`%||%` <- function(a, b) if (is.null(a) || length(a) == 0 || (length(a) == 1 && is.na(a))) b else a

# Kucuk gri aciklama satiri. GLOBAL tanimli olmali: hem build_ui hem server kullanir.
hint <- function(txt) div(class = "small text-muted mb-2", txt)

# ---------------------------------------------------------------------------
# YARDIMCILAR
# ---------------------------------------------------------------------------
geno_prefix <- function(path)
  sub("\\.(bed|bim|fam|geno|snp|ind|pheno|anno)$", "", path, ignore.case = TRUE)

# ---------------------------------------------------------------------------
# v6.1 ADIM 2b: "ETIKETI BIREYLERE AYIR"
# ---------------------------------------------------------------------------
# Ad = etiket + "_" + sample ID (kullanici karari). Diske yazilamayan (label_bad), setteki bir etiketle ya da
# birbiriyle cakisan ad label_fix_unique ile duzeltilir (Renamed = TRUE). Source = "split".
split_targets <- function(targets, labelmap, taken = character(0)) {
  ids <- character(0); lab <- character(0)
  for (t in targets) { m <- unique(as.character(labelmap[[t]] %||% character(0))); m <- m[!is.na(m) & nzchar(m)]; ids <- c(ids, m); lab <- c(lab, rep(t, length(m))) }
  if (!length(ids)) return(data.frame(SampleID = character(0), VirtualLabel = character(0), OriginalLabel = character(0), Source = character(0), Renamed = logical(0), stringsAsFactors = FALSE))
  nm <- paste0(lab, "_", ids); bad <- label_bad(nm) | nm %in% taken | duplicated(nm)
  if (any(bad)) nm[bad] <- unname(label_fix_unique(nm[bad], unique(c(taken, nm[!bad]))))
  data.frame(SampleID = ids, VirtualLabel = nm, OriginalLabel = lab, Source = rep("split", length(ids)), Renamed = bad, stringsAsFactors = FALSE)
}
# Kosunun sanal kurallari: kullanicinin kurallari + bolme kurallari (ayni birey icin bolme kurali kazanir).
split_vfam <- function(vfam, sp) {
  cols <- c("SampleID", "VirtualLabel", "OriginalLabel", "Source")
  rbind(vfam[!(vfam$SampleID %in% sp$SampleID), cols, drop = FALSE], sp[, cols, drop = FALSE])
}
SPLIT_EMPTY <- split_targets(character(0), list())

# v6.2 (K4): sanal etiket degisiminin SECIMLERE etkisi. Kutular: kimlik -> (sekme anahtari, kutu adi).
# v6.2 (K3): coklu secim kutulari (sag tik "Bireylere ayir" bunlarda). rot_target ve qge_leaf tekli.
K3_SINGLE <- c("rot_target", "qge_leaf")
K4_BOXES <- list(target = c("tab_model", "Target"), left = c("tab_model", "Left"), right = c("tab_model", "Right"),
  rot_target = c("tab_rotation", "Target"), rot_lr = c("tab_rotation", "leftright"), rot_rf = c("tab_rotation", "rightfix"),
  fst_pop1 = c("tab_fst", "pop1"), fst_pop2 = c("tab_fst", "pop2"), panel_pops = c("tab_panel", "pops"), qge_leaf = c("tab_qpgraph", "leaf"),
  f2_p1 = c("tab_fstats", "f2 pop1"), f2_p2 = c("tab_fstats", "f2 pop2"), f3_p1 = c("tab_fstats", "f3 pop1"), f3_p2 = c("tab_fstats", "f3 pop2"),
  f3_p3 = c("tab_fstats", "f3 pop3"), f4_p1 = c("tab_fstats", "f4 pop1"), f4_p2 = c("tab_fstats", "f4 pop2"), f4_p3 = c("tab_fstats", "f4 pop3"),
  f4_p4 = c("tab_fstats", "f4 pop4"), f4r_p1 = c("tab_fstats", "f4r pop1"), f4r_p2 = c("tab_fstats", "f4r pop2"), f4r_p3 = c("tab_fstats", "f4r pop3"),
  f4r_p4 = c("tab_fstats", "f4r pop4"), f4r_p5 = c("tab_fstats", "f4r pop5"), rset_pick = c("tab_sets", "Right"), lset_pick = c("tab_sets", "Left"))
# old_lm / new_lm: etiket -> sample ID (once / sonra), sel: kutu -> secili degerler. Secili her etiket icin tur:
# shrunk (birey eksildi), grown (birey eklendi), changed (ikisi), renamed (etiket yok; BUTUN bireyleri tek bir YENI
# etikette ve o etiket tam olarak bunlardan olusuyor), gone (dagildi ya da var olan baska etikete katildi).
# Doner: rows (Box, Label, Kind, Rem, Add, New) + rn (eski -> yeni ad). Etiket olmayan degerler (bireysel girdiler) atlanir.
vfam_effects <- function(old_lm, new_lm, sel) {
  ni <- unlist(new_lm, use.names = FALSE); look <- stats::setNames(rep(names(new_lm), lengths(new_lm)), ni)
  info <- list(); rn <- character(0)
  for (L in unique(as.character(unlist(sel, use.names = FALSE)))) {
    o <- old_lm[[L]]; if (!length(o)) next
    n <- new_lm[[L]]
    if (length(n) && setequal(o, n)) next
    if (length(n)) { rem <- length(setdiff(o, n)); add <- length(setdiff(n, o))
      info[[L]] <- list(kind = if (rem && add) "changed" else if (rem) "shrunk" else "grown", rem = rem, add = add, new = NA_character_)
    } else {
      tl <- unique(unname(look[o])); tl <- tl[!is.na(tl)]
      if (length(tl) == 1 && !(tl %in% names(old_lm)) && setequal(new_lm[[tl]], o)) { info[[L]] <- list(kind = "renamed", rem = 0L, add = 0L, new = tl); rn[L] <- tl }
      else info[[L]] <- list(kind = "gone", rem = length(o), add = 0L, new = NA_character_)
    }
  }
  rows <- list()
  for (b in names(sel)) for (L in intersect(as.character(sel[[b]]), names(info))) { z <- info[[L]]
    rows[[length(rows) + 1L]] <- data.frame(Box = b, Label = L, Kind = z$kind, Rem = as.integer(z$rem), Add = as.integer(z$add), New = z$new, stringsAsFactors = FALSE) }
  list(rows = if (length(rows)) do.call(rbind, rows) else data.frame(Box = character(0), Label = character(0), Kind = character(0), Rem = integer(0), Add = integer(0), New = character(0), stringsAsFactors = FALSE),
       rn = rn)
}
# v6.1 DUZELTME (notlar 8-9): Target degerindeki GRUP etiketlerini (labs icinde, kayitta olmayan) yerinde bireysel
# girdilere acar. reg = olusturulmus girdilerin kaydi (SampleID, VirtualLabel, OriginalLabel, Source, Renamed); ayni
# etiket + birey icin ad hep ayni (kayittan). Uyesi olmayan etiket grup kalir (empty). Doner: value, reg, empty, added.
split_expand <- function(v, labs, labelmap, reg = SPLIT_EMPTY, taken = character(0)) {
  v <- as.character(v %||% character(0)); grp <- unique(v[v %in% labs & !(v %in% reg$VirtualLabel)])
  if (!length(grp)) return(list(value = v, reg = reg, empty = character(0), added = 0L))
  out <- character(0); empty <- character(0); n0 <- nrow(reg)
  for (x in v) {
    if (!(x %in% grp)) { out <- c(out, x); next }
    m <- unique(as.character(labelmap[[x]] %||% character(0))); m <- m[!is.na(m) & nzchar(m)]
    if (!length(m)) { empty <- c(empty, x); out <- c(out, x); next }
    key <- paste(reg$OriginalLabel, reg$SampleID, sep = "\r"); new_ids <- m[!(paste(x, m, sep = "\r") %in% key)]
    if (length(new_ids)) reg <- rbind(reg, split_targets(x, stats::setNames(list(new_ids), x), unique(c(taken, reg$VirtualLabel))))
    nm <- reg$VirtualLabel[match(paste(x, m, sep = "\r"), paste(reg$OriginalLabel, reg$SampleID, sep = "\r"))]
    out <- c(out, nm)
  }
  list(value = out[!duplicated(out)], reg = reg, empty = empty, added = nrow(reg) - n0)
}
# Yuk tahmini. FALSE: extract_f2'nin bolmeden istedigi bellek ~ SNP x P^2 x 32 bayt (olcum: 10 pop, 1.856.583 SNP
# -> admixtools "5643 MB"; formul 5.665 MiB); havuz diski ~ P^2 x blok x 16 bayt (f2 + sayim; ~713 blok).
# TRUE: hedef basina genotip okumasi ~ 19,5 sn / GB (olcum: 14,43 GB .bed'de 280,8 sn).
SPLIT_SEC_PER_GB <- 156 / 14.43   # v6.5: olcum_v65 (14,43 GB .bed, dort tam gecis 106-205 sn, ortalama 156 sn)
split_load <- function(n_ind, n_lr, n_snp, geno_bytes, blocks = 713) {
  P <- n_ind + n_lr; snp <- if (isTRUE(is.finite(n_snp)) && n_snp > 0) n_snp else NA_real_
  list(P = P, ram = snp * P^2 * 32, disk = P^2 * blocks * 16,
       sec_t = if (isTRUE(is.finite(geno_bytes)) && geno_bytes > 0) geno_bytes / 1e9 * SPLIT_SEC_PER_GB else NA_real_)
}
fmt_bytes <- function(b) if (!isTRUE(is.finite(b))) "?" else if (b >= 1024^3) sprintf("%.1f GB", b / 1024^3) else sprintf("%.0f MB", max(b, 0) / 1024^2)

# ---------------------------------------------------------------------------
# v6.1 ADIM 2a (K17): COK SOZCUKLU ARAMA SIRALAMASI
# ---------------------------------------------------------------------------
# Shiny'nin sunucu tarafli secicisi eslesmeleri VERI SIRASIYLA ilk maxOptions kadar keser, istemci kalanlari
# siralar: "iran n" icin Iran_*_N etiketleri ilk 50'ye girmeyebiliyordu (olcum: Bolum 10). Puan (istemcideki
# qpsScore ile AYNI): her sozcuk icin etiketin bir bolumune (ayraclar _ . : - bosluk ve ->) tam esitse 3, bir
# bolumun basiysa 2, yalniz alt dizgiyse 1; ortalama; sozcukler yazildigi sirada geciyorsa +0,5; kisa ad +0,01/uzunluk.
# Bir sozcuk hic yoksa 0 (eslesmez). "ID  ->  etiket" satirlarinda (arama kutusu) ID kendi puanini, etiket kismindan
# gelen eslesme 1,5 eksigini alir: ayni etiketin kendisi uyelerinden once gelir.
QPS_SEARCH_B <- "[_.:\\s\u2192-]"
qps_rx_escape <- function(x) gsub("([][{}()+*^$|\\\\?.])", "\\\\\\1", x)
qps_search_score1 <- function(v, key) {
  sc <- numeric(length(v)); ok <- rep(TRUE, length(v)); last <- rep(-1L, length(v)); ord <- rep(TRUE, length(v))
  for (k in key) { p <- regexpr(k, v, fixed = TRUE); ok <- ok & p > 0; ord <- ord & p > last; last <- p; e <- qps_rx_escape(k)
    ex <- grepl(paste0("(^|", QPS_SEARCH_B, ")", e, "($|", QPS_SEARCH_B, ")"), v, perl = TRUE)
    pre <- grepl(paste0("(^|", QPS_SEARCH_B, ")", e), v, perl = TRUE)
    sc <- sc + ifelse(ex, 3, ifelse(pre, 2, 1)) }
  sc <- sc / length(key) + if (length(key) > 1) 0.5 * ord else 0
  sc <- sc + 0.01 / pmax(nchar(v), 1); sc[!ok] <- 0; sc
}
qps_search_score <- function(lab, key) {
  v <- tolower(as.character(lab)); key <- unique(tolower(key[!is.na(key) & nzchar(key)]))
  if (!length(key)) return(rep(1, length(v)))
  ar <- grepl("\u2192", v, fixed = TRUE); out <- numeric(length(v)); out[!ar] <- qps_search_score1(v[!ar], key)
  if (any(ar)) { sa <- qps_search_score1(v[ar], key); si <- qps_search_score1(sub("\\s*\u2192.*$", "", v[ar]), key)
    out[ar] <- pmax(si, ifelse(sa > 0, pmax(sa - 1.5, 0.05), 0)) }
  out
}
# shiny:::selectizeJSON'un yerine (ayni girdi/cikti): eslesenler puana gore siralanir, SONRA maxOptions kadar kesilir;
# secili degerler listede kalir. JSON jsonlite ile (shiny'nin bagimliligi).
qps_selectize_json <- function(data, req) {
  q <- shiny::parseQueryString(req$QUERY_STRING)
  fld <- gsub('[][" ]', "", strsplit(q$field %||% "label", ",", fixed = TRUE)[[1]]); fld <- intersect(fld[nzchar(fld)], names(data))
  if (!length(fld)) fld <- intersect("label", names(data))
  key <- unique(strsplit(tolower(q$query %||% ""), "\\s+")[[1]]); key <- key[nzchar(key)]
  mop <- suppressWarnings(as.numeric(q$maxop)); if (!length(mop) || !is.finite(mop)) mop <- 1000
  vfd <- q$value %||% "value"; sel <- attr(data, "selected_value", exact = TRUE)
  if (length(key)) { sc <- numeric(nrow(data)); for (f in fld) sc <- pmax(sc, qps_search_score(data[[f]], key))
    idx <- which(sc > 0); idx <- idx[order(-sc[idx], idx)] } else idx <- seq_len(nrow(data))
  idx <- utils::head(idx, mop)
  if (length(sel) && vfd %in% names(data)) { i <- stats::na.omit(match(sel, data[[vfd]])); if (length(i)) idx <- unique(c(idx, i)) }
  d <- data[idx, , drop = FALSE]; rownames(d) <- NULL
  shiny::httpResponse(200, "application/json", enc2utf8(as.character(jsonlite::toJSON(d, dataframe = "rows", na = "null"))))
}

