# OLCUM (2026-11-03, kullanicinin PC'si, R 4.5.1 + RStudio 2025.05.1, uygulama Chrome 156'da):
#   utils::choose.files tarayicinin ONUNDE acildi; Turkce karakterli varsayilan klasor ve donen yol dogru.
#   rstudioapi::selectFile RStudio penceresinin icinde, tarayicinin ARKASINDA kaldi -> kullanilmaz.
#   Surukle-birakta tarayici yalniz ad / boyut / degisim zamani verdi; disk yolu YOK, icerik okunabilir.
QPS_WIN   <- identical(.Platform$OS.type, "windows")
GENO_EXTS <- c("bed", "bim", "fam", "geno", "snp", "ind")
# v6.2 (K8): "labs" (etiket kaynagi) kaldirildi; harici etiket dosyalari AADR .anno da kabul eder.
PICK_SPEC <- list(geno = list(cap = "choose_geno", sfb = "geno", ext = GENO_EXTS),
                  ext  = list(cap = "ext_add_files", sfb = "extfam", ext = c("fam", "ind", "txt", "anno")),
                  pdm  = list(cap = "pdm_pick_cap", sfb = "pdm_sf", ext = c("qpadm", "txt", "tsv", "csv")),   # v6.3 test
                  xset = list(cap = "xs_pick_cap", sfb = "xs_sf", ext = c("bed", "bim", "fam", "txt", "csv", "tsv", "zip", "gz")))   # v6.4 test: ek setler + ham kitler
pick_filters <- function(ext, all_lab = "All files") {
  pat <- paste0("*.", ext, collapse = ";")
  rbind(c(paste0(paste(ext, collapse = " / "), " (", pat, ")"), pat), c(paste0(all_lab, " (*.*)"), "*.*"))
}
# Secici options(qps.chooser) ile verilebilir (sinama); yoksa Windows'ta utils::choose.files. Secici yoksa ya da
# hata verirse fallback = TRUE -> cagiran uygulama ici pencereye (gizli shinyFiles dugmesi) duser.
native_pick <- function(dir = NULL, caption = "", multi = FALSE, filters = NULL, file = NULL) {
  f <- getOption("qps.chooser")
  if (is.null(f) && QPS_WIN) f <- tryCatch(get("choose.files", envir = asNamespace("utils")), error = function(e) NULL)
  if (is.null(f)) return(list(paths = character(0), fallback = TRUE))
  d <- if (length(dir) == 1 && !is.na(dir) && nzchar(dir) && dir.exists(dir)) dir else path.expand("~")
  def <- paste0(gsub("/", "\\\\", sub("[/\\\\]+$", "", d)), "\\", if (length(file) == 1 && !is.na(file) && nzchar(file)) file else "*")
  p <- tryCatch(f(default = def, caption = caption, multi = multi, filters = filters %||% rbind(c("*.*", "*.*"))), error = function(e) e)
  if (inherits(p, "error")) return(list(paths = character(0), fallback = TRUE, err = conditionMessage(p)))
  p <- as.character(p %||% character(0)); p <- p[!is.na(p) & nzchar(p)]
  list(paths = enc2utf8(p), fallback = FALSE)
}
# v6.1 DUZELTME: Windows'ta dosya penceresi ARKA PLANDA. Olcumdeki D yolu (PowerShell OpenFileDialog, gorunmez TopMost
# sahip form; onde acildi, Turkce yol dogru) processx ile baslatilir, R BEKLEMEZ; secim QPS_OUT'a UTF-8 (BOM'suz) yazilir.
# Iptalde dosya olusmaz. Tum degerler ortam degiskeniyle gecer (betik ASCII). options(qps.dialog_cmd = function(env)
# list(cmd, args)) sinama kancasi (konteynerde PowerShell yok).
# v6.3 (S7): pencere arka plandaki bir surecten acildigi icin Windows onu ondeki pencerenin (tarayici) ARKASINDA
# birakabiliyordu (olcum M5: 3/3 gorunur ama kullanici goremedi; sahip formun TopMost'u etkisiz). ShowDialog'dan once
# arka is parcacigi (QpsTop) surecin gorunur #32770 penceresini bulup SetWindowPos(HWND_TOPMOST) ile en uste alir
# (olcum M6 "D": 0,75 sn'de bulundu, secim 8,2 sn); odak calinmaz. Derleme/arama basarisizsa pencere eskisi gibi acilir.
QPS_DLG_PS1 <- c("$ErrorActionPreference = 'Stop'", "Add-Type -AssemblyName System.Windows.Forms",
  "$o = New-Object System.Windows.Forms.Form -Property @{TopMost = $true; ShowInTaskbar = $false}",
  "$d = New-Object System.Windows.Forms.OpenFileDialog", "$d.Title = $env:QPS_TITLE", "$d.Multiselect = ($env:QPS_MULTI -eq '1')",
  "$d.Filter = $env:QPS_FILTER", "$d.FilterIndex = 1", "if ($env:QPS_DIR) { $d.InitialDirectory = $env:QPS_DIR }",
  "if ($env:QPS_FILE) { $d.FileName = $env:QPS_FILE }",
  "$cs = @\"", "using System; using System.Text; using System.Threading; using System.Diagnostics; using System.Runtime.InteropServices;", "public static class QpsTop {", "public delegate bool P(IntPtr h, IntPtr l);", "[DllImport(\"user32.dll\")] static extern bool EnumWindows(P f, IntPtr l);", "[DllImport(\"user32.dll\")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint p);", "[DllImport(\"user32.dll\")] static extern bool IsWindowVisible(IntPtr h);", "[DllImport(\"user32.dll\", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr h, StringBuilder s, int n);", "[DllImport(\"user32.dll\")] static extern bool SetWindowPos(IntPtr h, IntPtr a, int x, int y, int cx, int cy, uint f);", "public static void Start() {", "uint me = (uint)Process.GetCurrentProcess().Id;", "Thread t = new Thread(() => {", "for (int i = 0; i < 80; i++) {", "IntPtr hit = IntPtr.Zero;", "EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p != me || !IsWindowVisible(h)) return true; StringBuilder c = new StringBuilder(64); GetClassName(h, c, 64); if (c.ToString() == \"#32770\") { hit = h; return false; } return true; }, IntPtr.Zero);", "if (hit != IntPtr.Zero) { SetWindowPos(hit, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0040); return; }", "Thread.Sleep(250);", "}", "});", "t.IsBackground = true; t.Start();", "}", "}", "\"@", "try { Add-Type -TypeDefinition $cs -Language CSharp; [QpsTop]::Start() } catch { }",   # v6.3 (S7)
  "$r = $d.ShowDialog($o)",
  "if ($r -eq [System.Windows.Forms.DialogResult]::OK) { [System.IO.File]::WriteAllLines($env:QPS_OUT, [string[]]$d.FileNames, (New-Object System.Text.UTF8Encoding $false)) }",
  "$o.Dispose()", "exit 0")
# v6.2 (K5): toplu kosu tablosu panoya. Windows'ta PowerShell (STA) PNG'yi Clipboard.SetImage ile yazar (arka planda,
# R beklemez; kopya sureclerden bagimsiz kalir). Diger isletim sistemlerinde tarayici Clipboard API (istemci).
# options(qps.clip_cmd = function(env) list(cmd, args)) sinama kancasi; verilirse sunucu yolu kullanilir.
QPS_CLIP_PS1 <- c("$ErrorActionPreference = 'Stop'", "Add-Type -AssemblyName System.Windows.Forms", "Add-Type -AssemblyName System.Drawing",
  "$img = [System.Drawing.Image]::FromFile($env:QPS_FILE)", "[System.Windows.Forms.Clipboard]::SetImage($img)", "$img.Dispose()", "exit 0")
clip_mode <- function() if (QPS_WIN || !is.null(getOption("qps.clip_cmd"))) "server" else "browser"
clip_start <- function(file) {
  hook <- getOption("qps.clip_cmd"); errf <- tempfile("qps_clip_err_", fileext = ".txt")
  env <- c(QPS_FILE = enc2utf8(if (QPS_WIN) gsub("/", "\\", normalizePath(file, mustWork = FALSE), fixed = TRUE) else file))
  cmd <- if (!is.null(hook)) hook(env) else {
    ps1 <- file.path(tempdir(), "qps_clip.ps1"); writeLines(QPS_CLIP_PS1, ps1)
    list(cmd = "powershell", args = c("-NoProfile", "-STA", "-ExecutionPolicy", "Bypass", "-File", ps1)) }
  p <- tryCatch(processx::process$new(cmd$cmd, cmd$args, env = c("current", env), stdout = NULL, stderr = errf,
                                      windows_hide_window = TRUE, cleanup = TRUE), error = function(e) e)
  if (inherits(p, "error")) return(list(err = conditionMessage(p)))
  list(proc = p, errf = errf)
}
dialog_filter <- function(f) paste(apply(f, 1, function(r) paste0(gsub("|", "/", r[1], fixed = TRUE), "|", r[2])), collapse = "|")
native_dialog_start <- function(dir = NULL, caption = "", multi = FALSE, filters = NULL, file = NULL) {
  hook <- getOption("qps.dialog_cmd")
  if (is.null(hook) && !QPS_WIN) return(NULL)
  d <- if (length(dir) == 1 && !is.na(dir) && nzchar(dir) && dir.exists(dir)) dir else path.expand("~")
  out <- tempfile("qps_dlg_", fileext = ".txt"); errf <- tempfile("qps_dlg_err_", fileext = ".txt")
  env <- c(QPS_DIR = if (QPS_WIN) gsub("/", "\\", d, fixed = TRUE) else d, QPS_TITLE = enc2utf8(caption), QPS_MULTI = if (isTRUE(multi)) "1" else "0",
           QPS_FILTER = enc2utf8(dialog_filter(filters %||% rbind(c("*.*", "*.*")))),
           QPS_FILE = if (length(file) == 1 && !is.na(file) && nzchar(file)) enc2utf8(file) else "", QPS_OUT = out)
  cmd <- if (!is.null(hook)) hook(env) else {
    ps1 <- file.path(tempdir(), "qps_dialog.ps1"); writeLines(QPS_DLG_PS1, ps1)
    list(cmd = "powershell", args = c("-NoProfile", "-STA", "-ExecutionPolicy", "Bypass", "-File", ps1)) }
  p <- tryCatch(processx::process$new(cmd$cmd, cmd$args, env = c("current", env), stdout = NULL, stderr = errf,
                                      windows_hide_window = TRUE, cleanup = TRUE), error = function(e) e)
  if (inherits(p, "error")) return(list(err = conditionMessage(p)))
  list(proc = p, out = out, errf = errf)
}
native_dialog_result <- function(d) {
  st <- tryCatch(d$proc$get_exit_status(), error = function(e) NA_integer_)
  p <- if (file.exists(d$out)) readLines(d$out, encoding = "UTF-8", warn = FALSE) else character(0)
  e <- if (file.exists(d$errf)) paste(readLines(d$errf, warn = FALSE), collapse = " ") else ""
  unlink(c(d$out, d$errf)); p <- p[!is.na(p) & nzchar(p)]
  list(paths = enc2utf8(p), ok = isTRUE(as.integer(st) == 0L), err = trimws(e))
}
hist_push <- function(h, d, n = 10) {
  h <- c(d, h %||% character(0)); h <- h[!is.na(h) & nzchar(h)]
  utils::head(h[!duplicated(if (QPS_WIN) tolower(h) else h)], n)
}
# DEF_FILE'a v6.1'de eklenen alanlar; eski dosyada yoksa bos.
defs_extra <- function(d) list(dirs = as.list(d$dirs %||% list()), def_geno = d$def_geno %||% "", def_labs = d$def_labs %||% "",
                               def_rset = d$def_rset %||% "", def_lset = d$def_lset %||% "",
                               geno_hist = as.character(d$geno_hist %||% character(0)),
                               xsets = as.character(d$xsets %||% character(0)))   # v6.4 test: ek setlerin onekleri
def_name <- function(sets, nm) if (length(nm) == 1 && !is.na(nm) && nm %in% names(sets)) nm else names(sets)[1]
# Surukle-birak (set): tarayici disk yolunu vermez -> ad + boyut hatirlanan klasorlerde aranir. Kokler: son set
# klasoru, varsayilan setin klasoru, onceki setlerin klasorleri ve UST klasorleri. Her kokun kendisi ve BIR alt
# duzeyi taranir (yalniz file.exists + file.size; icerik okunmaz). Ayni ad + boyutta birden cok dosyada degisim
# zamani (tarayicinin lastModified'i, ms) 2 sn icinde olanlar one cikar.
geno_drop_roots <- function(defx) {
  r <- c(defx$dirs$geno %||% character(0), if (nzchar(defx$def_geno %||% "")) dirname(defx$def_geno), defx$geno_hist %||% character(0))
  r <- r[!is.na(r) & nzchar(r)]; r <- unique(c(r, dirname(r))); r <- r[dir.exists(r)]
  k <- normalizePath(r, "/", FALSE); r[!duplicated(if (QPS_WIN) tolower(k) else k)]
}
# v6.1 DUZELTME (saha): hatirlanan klasorlerde bulunamayan set icin GENIS arama. Kokler: program klasoru ve ust
# klasorleri (derinlik 3), surucu koku (2), kullanici klasorleri (Belgeler, Masaustu, Indirilenler, OneDrive; 3).
# Genislik oncelikli; f2cache, vfam_*, gizli, sistem klasorleri atlanir; en cok max_dirs klasor ve budget sn.
# Yalniz klasor listesi + file.exists/file.size (icerik okunmaz). Adaylar geno_drop_find ile (boyut, mtime) suzulur.
geno_drop_wide_roots <- function(wd = getwd(), home = path.expand("~"), prof = Sys.getenv(if (QPS_WIN) "USERPROFILE" else "HOME"),
                                 onedrive = Sys.getenv("OneDrive")) {
  a <- character(0); d <- normalizePath(wd, "/", FALSE)
  repeat { p <- dirname(d); if (identical(p, d)) break; a <- c(a, d); d <- p }
  h <- c(home, if (nzchar(prof)) file.path(prof, c("Desktop", "Downloads", "Documents")), if (nzchar(onedrive)) onedrive)
  r <- data.frame(dir = c(a, d, h), depth = c(rep(3L, length(a)), 2L, rep(3L, length(h))), stringsAsFactors = FALSE)
  r <- r[!is.na(r$dir) & nzchar(r$dir) & dir.exists(r$dir), , drop = FALSE]
  r[!duplicated(tolower(normalizePath(r$dir, "/", FALSE))), , drop = FALSE]
}
GENO_DROP_SKIP <- "^(f2cache|vfam_.*|qps_drop|\\..*|\\$.*|node_modules|AppData|System Volume Information|Windows|Program Files.*|ProgramData|Recovery|PerfLogs)$"
geno_drop_search <- function(name, size, roots, lm = NA, max_dirs = 4000, budget = 5) {
  if (is.null(roots) || !nrow(roots)) return(character(0))
  t0 <- Sys.time(); seen <- new.env(hash = TRUE); q <- roots$dir; dq <- roots$depth; hit <- character(0); n <- 0L
  while (length(q) && n < max_dirs && as.numeric(difftime(Sys.time(), t0, units = "secs")) < budget) {
    d <- q[1]; k <- dq[1]; q <- q[-1]; dq <- dq[-1]
    key <- tolower(normalizePath(d, "/", FALSE)); if (exists(key, envir = seen, inherits = FALSE)) next
    assign(key, TRUE, envir = seen); n <- n + 1L
    f <- file.path(d, name); if (file.exists(f) && isTRUE(file.size(f) == as.numeric(size))) hit <- c(hit, f)
    if (k > 0) { sub <- tryCatch(list.dirs(d, full.names = TRUE, recursive = FALSE), error = function(e) character(0))
      sub <- sub[!grepl(GENO_DROP_SKIP, basename(sub), ignore.case = TRUE)]; q <- c(q, sub); dq <- c(dq, rep(k - 1L, length(sub))) }
  }
  if (!length(hit)) return(character(0))
  geno_drop_find(name, size, unique(dirname(hit)), lm, max_sub = 0)
}
geno_drop_find <- function(name, size, roots, lm = NA, max_sub = 300) {
  cand <- character(0)
  for (r in roots) { sub <- c(r, utils::head(list.dirs(r, recursive = FALSE), max_sub)); p <- file.path(sub, name); cand <- c(cand, p[file.exists(p)]) }
  if (!length(cand)) return(character(0))
  k <- normalizePath(cand, "/", FALSE); cand <- cand[!duplicated(if (QPS_WIN) tolower(k) else k)]
  fs <- file.size(cand); cand <- cand[!is.na(fs) & fs == as.numeric(size)]
  if (length(cand) > 1 && length(lm) == 1 && is.finite(as.numeric(lm))) {
    dt <- abs(as.numeric(file.mtime(cand)) - as.numeric(lm) / 1000); if (any(dt < 2)) cand <- cand[dt < 2] }
  cand
}

read_pop_labels <- function(path) {
  ext <- tolower(tools::file_ext(path))
  if (ext == "anno") {
    df <- utils::read.delim(path, header = TRUE, stringsAsFactors = FALSE, quote = "", check.names = FALSE, comment.char = "")
    col <- grep("Group ?ID|Population|PopLabel|Group", names(df), ignore.case = TRUE)
    if (!length(col)) stop(tr("err_anno_group"))
    labs <- df[[col[1]]]
  } else {
    df <- utils::read.table(path, header = FALSE, stringsAsFactors = FALSE, fill = TRUE, comment.char = "", quote = "", check.names = FALSE)
    labs <- switch(ext, ind = df[[ncol(df)]], fam = df[[1]], stop(tr("err_label_ext"), ext))
  }
  sort(unique(trimws(as.character(labs))))
}

# Etiket -> sample ID eslesmesi (named list)
read_label_samples <- function(path) {
  ext <- tolower(tools::file_ext(path))
  if (ext == "anno") {
    df <- utils::read.delim(path, header = TRUE, stringsAsFactors = FALSE, quote = "", check.names = FALSE, comment.char = "")
    idc <- grep("Instance ?ID|Genetic ?ID|Version ?ID|^ID$", names(df), ignore.case = TRUE)[1]
    gc  <- grep("Group ?ID|Population|PopLabel|Group", names(df), ignore.case = TRUE)[1]
    if (is.na(idc) || is.na(gc)) return(list())
    id <- trimws(as.character(df[[idc]])); lab <- trimws(as.character(df[[gc]]))
  } else {
    df <- utils::read.table(path, header = FALSE, stringsAsFactors = FALSE, fill = TRUE, comment.char = "", quote = "", check.names = FALSE)
    if (ext == "ind") { id <- trimws(as.character(df[[1]])); lab <- trimws(as.character(df[[ncol(df)]])) }
    else if (ext == "fam") { lab <- trimws(as.character(df[[1]])); id <- trimws(as.character(df[[2]])) }
    else return(list())
  }
  split(id, lab)
}

# f2 onbellek anahtari.
# v5.4 NOTU: blgsize / adjust_pseudohaploid / auto_only anahtara EKLENDI. Bunlar
# extract_f2 sonucunu dogrudan degistirir; anahtarda olmazlarsa farkli ayarla
# yapilmis iki kosu AYNI klasore duser ve sessizce yanlis bloklar okunur.
# UYARI: anahtar degistigi icin v5.3 ile uretilmis f2_* klasorleri artik
# bulunamaz ve bir kez yeniden hesaplanir.
# v6.2 (Ek): comp verilirse (pop -> sample ID ozeti) anahtar ICERIKTEN: orijinal prefix + poplar + ozetler + ayarlar.
# Ayni icerikli poplar hangi sanal kural setiyle kurulursa kurulsun ayni klasore duser.
f2_cache_dir <- function(cache_base, prefix, pops, maxmiss, blgsize = 0.05, adjph = TRUE, auto_only = TRUE, vfam_key = "", orig = NULL, comp = NULL) {
  pp <- sort(unique(pops))
  key <- if (!is.null(comp) && !is.null(orig) && all(pp %in% names(comp)))
    digest::digest(list(orig = orig, pops = pp, comp = unname(comp[pp]), maxmiss = maxmiss, blgsize = blgsize, adjph = adjph, auto_only = auto_only), algo = "xxhash64")
  else digest::digest(list(prefix = normalizePath(prefix, mustWork = FALSE), pops = pp, maxmiss = maxmiss, blgsize = blgsize, adjph = adjph, auto_only = auto_only, vfam = vfam_key %||% ""), algo = "xxhash64")
  file.path(cache_base, paste0("f2_", key))
}

# v6.2 (Ek): pop icerigi ozeti. lm = etiket -> sample ID (sanal kurallar uygulanmis). Bir pop bos ya da lm bossa NULL
# (icerik anahtari kullanilmaz, eski anahtara dusulur).
pop_sig <- function(ids) digest::digest(sort(unique(as.character(ids))), algo = "xxhash64")
pool_comp <- function(lm, pops) {
  pops <- unique(as.character(pops))
  if (!length(pops) || is.null(lm) || !length(lm)) return(NULL)
  ids <- lapply(pops, function(p) lm[[p]])
  if (any(lengths(ids) == 0L)) return(NULL)
  stats::setNames(vapply(ids, pop_sig, ""), pops)
}
# Bir havuz bu istege uyar mi: ayarlar + poplari kapsama + (icerik ozetleri ayni) YA DA (eski anahtar: prefix + sanal ozet ayni).
pool_match <- function(m, prefix, vfam_key, orig, comp, pops, maxmiss, blgsize, adjph, auto_only) {
  if (!is.null(m) && !identical(xs_vsuf_of(m$vfam), xs_vsuf_of(vfam_key))) return(FALSE)   # v6.4 test (inceleme 9) + v6.4 (madde 2): ek set poplari birebir
  if (is.null(m) || !(isTRUE(m$maxmiss == maxmiss) && isTRUE(m$blgsize == blgsize) && isTRUE(m$adjph == adjph) &&
      isTRUE(m$auto_only == auto_only) && all(pops %in% m$pops))) return(FALSE)
  mc <- unlist(m$comp)
  if (!is.null(comp) && !is.null(orig) && length(mc) && identical(m$orig, orig) && all(pops %in% names(mc)) && all(pops %in% names(comp)) &&
      identical(unname(mc[pops]), unname(comp[pops]))) return(TRUE)
  identical(m$prefix, normalizePath(prefix, mustWork = FALSE)) && identical(m$vfam %||% "", vfam_key %||% "")
}

# Onbellek klasorune kendi yan dosyamiz. admixtools'un cache_metadata.json'i
# prefix'i KAYDETMEZ ve eski surumlerde hic yazilmaz; havuz aramasi (v5.5)
# bu dosyaya dayanacak.
pool_write_meta <- function(dir, prefix, pops, maxmiss, blgsize, adjph, auto_only, vfam_key, orig = NULL, comp = NULL) {
  m <- list(schema = 1L, prefix = normalizePath(prefix, mustWork = FALSE), pops = sort(unique(pops)), maxmiss = maxmiss, blgsize = blgsize, adjph = adjph, auto_only = auto_only, vfam = vfam_key %||% "", built = format(Sys.time(), "%Y-%m-%dT%H:%M:%S"))
  # v6.2 (Ek): orijinal prefix + pop basina icerik ozeti (eski surumler bu alanlari okumaz, zararsiz).
  if (!is.null(orig) && !is.null(comp) && all(m$pops %in% names(comp))) { m$orig <- orig; m$comp <- as.list(comp[m$pops]) }
  tryCatch(writeLines(jsonlite_or_dput(m), file.path(dir, "qps_pool.json"), useBytes = TRUE), error = function(e) invisible(NULL))
}

# jsonlite zorunlu bagimlilik degil; yoksa dput ile okunabilir bir metin yazilir.
jsonlite_or_dput <- function(m) {
  if (requireNamespace("jsonlite", quietly = TRUE)) return(as.character(jsonlite::toJSON(m, auto_unbox = TRUE)))
  paste(utils::capture.output(dput(m)), collapse = "")
}

pool_read_meta <- function(dir) {
  f <- file.path(dir, "qps_pool.json")
  if (!file.exists(f)) return(NULL)
  txt <- tryCatch(paste(readLines(f, warn = FALSE), collapse = ""), error = function(e) "")
  if (!nzchar(txt)) return(NULL)
  m <- if (requireNamespace("jsonlite", quietly = TRUE)) tryCatch(jsonlite::fromJSON(txt, simplifyVector = TRUE), error = function(e) NULL)
       else tryCatch(eval(parse(text = txt)), error = function(e) NULL)
  if (is.null(m)) return(NULL)
  m$dir <- dir; m
}

# Onbellek gecerli mi: admixtools'un is_precomp_dir olcutu + kendi bitis isaretimiz.
pool_ok <- function(dir) dir.exists(dir) && file.exists(file.path(dir, "block_lengths_f2.rds")) && file.exists(file.path(dir, ".f2_done"))

# Havuzun kac SNP ve kac blok tuttugu -- block_lengths_f2.rds'ten okunur.
pool_stats <- function(dir) {
  f <- file.path(dir, "block_lengths_f2.rds")
  if (!file.exists(f)) return(list(nsnp = NA_integer_, nblock = NA_integer_))
  bl <- tryCatch(readRDS(f), error = function(e) NULL)
  if (is.null(bl)) return(list(nsnp = NA_integer_, nblock = NA_integer_))
  list(nsnp = sum(bl), nblock = length(bl))
}

# v6.0 (K3): havuzda hedefin SNP sayisi. admixtools write_f2: <havuz>/<pop1>/<pop2>_f2.rds, sutunlar
# "f2" ve "counts"; counts = blokta iki popun da eksiksiz oldugu SNP ORANI (mats_to_ctarr ->
# block_arr_mean). Kendi ciftinde oran x blok uzunlugu toplami = hedefin eksiksiz SNP sayisi.
# Dosya/sutun yoksa ya da oran 0-1 disindaysa NA ("—").
pool_target_snps <- function(dir, pop) {
  if (is.null(dir) || is.null(pop) || !nzchar(dir)) return(NA_real_)
  f <- file.path(dir, pop, paste0(pop, "_f2.rds")); fb <- file.path(dir, "block_lengths_f2.rds")
  if (!file.exists(f) || !file.exists(fb)) return(NA_real_)
  tryCatch({
    x <- readRDS(f); b <- readRDS(fb)
    if (!("counts" %in% colnames(x)) || NROW(x) != length(b)) return(NA_real_)
    cn <- as.numeric(x[, "counts"])
    if (any(!is.finite(cn)) || any(cn < 0 | cn > 1 + 1e-9)) return(NA_real_)
    round(sum(cn * b))
  }, error = function(e) NA_real_)
}

# Diskteki tum gecerli havuzlar (kendi yan dosyamiz uzerinden).
pool_scan <- function(cache_base) {
  ds <- list.dirs(cache_base, recursive = FALSE)
  out <- lapply(ds, function(d) if (pool_ok(d)) pool_read_meta(d) else NULL)
  Filter(Negate(is.null), out)
}

# S3 KARARI -- UST KUME YENIDEN KULLANIMI.
# Istenen poplari KAPSAYAN ve tum extract_f2 parametreleri eslesen bir havuz
# varsa yeniden hesap YAPILMAZ. Birden cok aday varsa EN KUCUK ust kume secilir:
# panel ne kadar darsa maxmiss filtresi o kadar az SNP eler.
# DIKKAT: farkli pop setleriyle uretilmis klasorler ASLA BIRLESTIRILMEZ; her
# okuma tek bir tutarli klasorden yapilir (bkz. DEVIR NOTU Bolum 3[1]).
pool_find <- function(cache_base, prefix, pops, maxmiss, blgsize, adjph, auto_only, vfam_key = "", orig = NULL, comp = NULL) {
  cand <- Filter(function(m) pool_match(m, prefix, vfam_key, orig, comp, pops, maxmiss, blgsize, adjph, auto_only), pool_scan(cache_base))
  if (!length(cand)) return(NULL)
  cand[[which.min(vapply(cand, function(m) length(m$pops), integer(1)))]]
}

# Bir analiz icin kullanilacak f2 klasorunu belirle.
# Sira: (1) aktif panel kapsiyorsa panel, (2) diskte ust kume varsa o,
# (3) yoksa bu pop setine ozel yeni klasor.
# v6.2 (Ek): orig = orijinal prefix (normalize), lm = kosunun etiket -> sample ID eslemesi. Verilirse havuz icerikle eslesir;
# sonucta orig + comp doner (yeni havuzun yan dosyasina yazilir).
resolve_f2 <- function(cache_base, prefix, pops, maxmiss, blgsize, adjph, auto_only, vfam_key = "", panel = NULL, orig = NULL, lm = NULL) {
  comp <- if (!is.null(orig) && !is.null(lm)) pool_comp(lm, pops) else NULL
  if (!is.null(panel) && pool_ok(panel$dir %||% "") && pool_match(panel, prefix, vfam_key, orig, comp, pops, maxmiss, blgsize, adjph, auto_only))
    return(list(dir = panel$dir, need = FALSE, src = "panel", orig = orig, comp = comp))
  hit <- pool_find(cache_base, prefix, pops, maxmiss, blgsize, adjph, auto_only, vfam_key, orig, comp)
  if (!is.null(hit)) return(list(dir = hit$dir, need = FALSE, src = "superset", wider = length(setdiff(hit$pops, pops)) > 0, orig = orig, comp = comp))
  list(dir = f2_cache_dir(cache_base, prefix, pops, maxmiss, blgsize, adjph, auto_only, vfam_key, orig = orig, comp = comp), need = TRUE, src = "new", orig = orig, comp = comp)
}

# >>> ADNA ORTAK KOD (Adna Merge Studio v3.17; kaynak Adna_merge_studio_v3.17_by_mozy70.R md5 1e9223c8c6241a2a5e0fc6c3f6fb75ca; blok md5 3eb194b62768ed7168a3ee14abd84f6c)
# Bu blok gelistirme_v64/adna_gom.py ile Adna'nin kaynagindan BIREBIR alinir; burada degistirilmez. Tanimlar: FIRMA_SUFFIX, FIRMA_ADI, CHR_MAP, AADR_SUFFIX, yazdirilabilir, bom_temizle, temiz_utf8, kirp_b, kit_bas_satirlar, kit_format_tespit, kit_build_tespit, kit_ac, kit_ham_oku, kit_normalize, PAR1, PAR2, kit_cinsiyet, dolgu_esle, cekirdek_id.
# Kullanilmayan dallar: temiz_utf8(store = NULL) cagrilir (log_line/sayi gerekmez); kit_ham_oku VCF dali qpAdm Studio'da
# cagrilmaz (VCF kit reddedilir).
# --- FIRMA_SUFFIX
FIRMA_SUFFIX <- c(
  "23andme"    = ".23",
  "ancestry"   = ".AN",
  "myheritage" = ".MH",
  "ftdna"      = ".FT",
  "livingdna"  = ".LD",
  "tellmegen"  = ".TG",
  "selfdecode" = ".SD",
  "genomestudio" = ".GS",
  "geno2"      = ".G2",
  "decodeme"   = ".DC",
  "vcf"        = ".NB",
  "bilinmiyor" = ""
)
# --- FIRMA_ADI
FIRMA_ADI <- c(
  "23andme"    = "23andMe",
  "ancestry"   = "AncestryDNA",
  "myheritage" = "MyHeritage",
  "ftdna"      = "FamilyTreeDNA",
  "livingdna"  = "LivingDNA",
  "tellmegen"  = "tellmeGen",
  "selfdecode" = "SelfDecode",
  "genomestudio" = "GenomeStudio",
  "geno2"      = "Geno 2.0",
  "decodeme"   = "deCODEme",
  "vcf"        = "VCF",
  "bilinmiyor" = "Tespit edilemedi"
)
# --- CHR_MAP
CHR_MAP <- c("X" = "23", "x" = "23", "Y" = "24", "y" = "24",
             "XY" = "25", "xy" = "25", "PAR" = "25",
             "MT" = "26", "mt" = "26", "M" = "26", "m" = "26")
# --- AADR_SUFFIX
AADR_SUFFIX <- c(".AG", ".DG", ".SG", ".HO", ".TW", ".YW", ".IM",
                 ".AA", ".EC", ".WGC", ".REF", ".BY", ".SDG")
# --- yazdirilabilir
yazdirilabilir <- function(r) {
  i <- as.integer(r)
  paste(ifelse(i >= 32 & i <= 126,
               vapply(i, function(z) rawToChar(as.raw(z)), character(1)), "."),
        collapse = "")
}
# --- bom_temizle
bom_temizle <- function(x) {
  x <- sub("^\xef\xbb\xbf", "", x, useBytes = TRUE)
  sub("^\ufeff", "", x, useBytes = TRUE)
}
# --- temiz_utf8
temiz_utf8 <- function(x, ad = NULL, store = NULL) {
  if (!length(x)) return(x)
  bozuk <- is.na(iconv(x, from = "UTF-8", to = "UTF-8"))
  if (any(bozuk)) {
    ornek <- utils::head(which(bozuk), 3)
    if (!is.null(store))
      log_line(store, sprintf("%s: %s satirda gecersiz bayt bulundu ve temizlendi (ilk: %s)",
                              ad %||% "alan", sayi(sum(bozuk)),
                              paste(sprintf("satir %s -> '%s'", sayi(ornek),
                                            vapply(x[ornek], function(z)
                                              yazdirilabilir(charToRaw(z)), character(1))),
                                    collapse = "; ")), "UYARI")
    x[bozuk] <- iconv(x[bozuk], from = "latin1", to = "UTF-8", sub = "?")
    x[is.na(x)] <- "?"
  }
  x
}
# --- kirp_b
kirp_b   <- function(x) sub("[ \t\r]+$", "", sub("^[ \t\r]+", "", x, useBytes = TRUE), useBytes = TRUE)
# --- kit_bas_satirlar
kit_bas_satirlar <- function(yol, n = 120) {
  con <- file(yol, open = "r", encoding = "UTF-8")
  on.exit(close(con))
  bom_temizle(readLines(con, n = n, warn = FALSE, skipNul = TRUE))
}
# --- kit_format_tespit
kit_format_tespit <- function(bas) {
  b <- bas
  if (any(grepl("^##fileformat=VCF", b)))                       return("vcf")
  if (any(grepl("^##fileformat=MyHeritage", b, ignore.case = TRUE))) return("myheritage")
  if (any(grepl("MyHeritage", b, fixed = TRUE)))                return("myheritage")
  if (any(grepl("^#AncestryDNA raw data", b)))                  return("ancestry")
  if (any(grepl("AncestryDNA", b, fixed = TRUE)))               return("ancestry")
  if (any(grepl("Living ?DNA", b)))                             return("livingdna")
  if (any(grepl("tellmegen", b, ignore.case = TRUE)))           return("tellmegen")
  if (any(grepl("SelfDecode", b, ignore.case = TRUE)))          return("selfdecode")
  if (any(grepl("deCODEme", b, ignore.case = TRUE)))            return("decodeme")
  if (any(grepl("Geno ?2", b)))                                 return("geno2")
  if (any(grepl("GenomeStudio|SNP Name\\s", b)))                return("genomestudio")
  if (any(grepl("generated by 23andMe", b, fixed = TRUE)))      return("23andme")
  if (any(grepl("^RSID,CHROMOSOME,POSITION,RESULT", b)))        return("ftdna")
  # yapisal geri dusus
  b <- temiz_utf8(b)
  veri <- b[!grepl("^#", b) & nzchar(kirp_b(b))]
  veri <- veri[!grepl("^(RSID|rsid)", veri)]
  if (!length(veri)) return("bilinmiyor")
  s <- veri[1]
  if (grepl(",", s) && !grepl("\t", s)) return("ftdna")
  n <- length(strsplit(s, "\t")[[1]])
  if (n == 5) return("ancestry")
  if (n == 4) return("23andme")
  "bilinmiyor"
}
# --- kit_build_tespit
kit_build_tespit <- function(bas) {
  b <- paste(bas, collapse = " ")
  if (grepl("build ?38|GRCh38|hg38", b, ignore.case = TRUE)) return("b38")
  if (grepl("build ?37|GRCh37|hg19|build37|build 37\\.1", b, ignore.case = TRUE)) return("b37")
  "belirsiz"
}
# --- kit_ac
kit_ac <- function(yol, tmpdir) {
  alt <- tolower(tools::file_ext(yol))
  if (alt == "zip") {
    d <- file.path(tmpdir, paste0("unz_", basename(tools::file_path_sans_ext(yol))))
    dir.create(d, recursive = TRUE, showWarnings = FALSE)
    icerik <- utils::unzip(yol, exdir = d)
    icerik <- icerik[!grepl("__MACOSX", icerik)]
    if (!length(icerik)) stop("Zip icinde dosya bulunamadi: ", basename(yol))
    boy <- file.info(icerik)$size
    return(icerik[which.max(boy)])
  }
  if (alt == "gz") {
    hedef <- file.path(tmpdir, sub("\\.gz$", "", basename(yol)))
    con_in <- gzfile(yol, "rb"); con_out <- file(hedef, "wb")
    on.exit({ close(con_in); close(con_out) })
    repeat {
      b <- readBin(con_in, "raw", n = 1048576L)
      if (!length(b)) break
      writeBin(b, con_out)
    }
    return(hedef)
  }
  yol
}
# --- kit_ham_oku
kit_ham_oku <- function(yol, fmt, vcf_ayar = NULL) {
  # VCF, 2. sekmede diger bicimler gibi bir kit olarak kabul edilir: burada
  # ayni data.frame(rsid, chr, pos, gt) bicimine cevrilir ve o noktadan
  # sonra kit_normalize / kit_panel_esle / duplikat denetimi / birlestirme
  # hic degismeden calisir.
  if (fmt == "vcf") {
    if (is.null(vcf_ayar)) stop("VCF icin cevrim ayari verilmedi (10. sekmeyi kullanin).")
    return(do.call(vcf_kit_df, c(list(yol = yol), vcf_ayar)))
  }
  if (fmt %in% c("myheritage", "ftdna")) {
    x <- scan(yol, what = list("", "", "", ""), sep = ",", quote = "\"",
              comment.char = "#", quiet = TRUE, fill = TRUE, flush = TRUE,
              blank.lines.skip = TRUE)
    df <- data.frame(rsid = x[[1]], chr = x[[2]], pos = x[[3]], gt = x[[4]],
                     stringsAsFactors = FALSE)
  } else if (fmt == "ancestry") {
    x <- scan(yol, what = list("", "", "", "", ""), sep = "\t", quote = "",
              comment.char = "#", quiet = TRUE, fill = TRUE, flush = TRUE,
              blank.lines.skip = TRUE)
    df <- data.frame(rsid = x[[1]], chr = x[[2]], pos = x[[3]],
                     gt = paste0(x[[4]], x[[5]]), stringsAsFactors = FALSE)
  } else {
    x <- scan(yol, what = list("", "", "", ""), sep = "\t", quote = "",
              comment.char = "#", quiet = TRUE, fill = TRUE, flush = TRUE,
              blank.lines.skip = TRUE)
    df <- data.frame(rsid = x[[1]], chr = x[[2]], pos = x[[3]], gt = x[[4]],
                     stringsAsFactors = FALSE)
  }
  df$rsid <- temiz_utf8(bom_temizle(df$rsid))
  # yorumsuz basliklari at
  df <- df[!(tolower(df$rsid) %in% c("rsid", "rs id", "snp", "name")), , drop = FALSE]
  df <- df[nzchar(df$rsid), , drop = FALSE]
  df
}
# --- kit_normalize
kit_normalize <- function(df) {
  n_ham <- nrow(df)
  # kromozom
  ch <- kirp_b(temiz_utf8(df$chr))
  esle <- CHR_MAP[ch]
  ch[!is.na(esle)] <- esle[!is.na(esle)]
  df$chrn <- ch
  # pozisyon
  df$posn <- suppressWarnings(as.numeric(df$pos))
  # genotip
  g <- toupper(kirp_b(temiz_utf8(df$gt)))
  g <- gsub("[^A-Z0-9-]", "", g)
  df$gtn <- g

  gecersiz_pos <- is.na(df$posn) | df$posn <= 0 | df$chrn %in% c("0", "")
  n_unmapped <- sum(gecersiz_pos)
  df <- df[!gecersiz_pos, , drop = FALSE]

  # MT ve PAR satirlari (1240k panelinde karsiligi yok) -- filtreden ONCE sayilir
  n_mt  <- sum(df$chrn == "26")
  n_par <- sum(df$chrn == "25")

  is_nocall <- df$gtn %in% c("", "-", "--", "0", "00", "N", "NN", "__", "._")
  n_nocall <- sum(is_nocall)
  df <- df[!is_nocall, , drop = FALSE]

  is_indel <- grepl("[ID]", df$gtn)
  n_indel <- sum(is_indel)
  df <- df[!is_indel, , drop = FALSE]

  # kismi no-call ("A-", "-G") ve ACGT disi
  gecerli <- grepl("^[ACGT]{1,2}$", df$gtn)
  n_bozuk <- sum(!gecerli)
  df <- df[gecerli, , drop = FALSE]

  # duplike pozisyon -> ilkini tut
  anahtar <- paste0(df$chrn, ":", df$posn)
  dup <- duplicated(anahtar)
  n_dup <- sum(dup)
  df <- df[!dup, , drop = FALSE]
  anahtar <- anahtar[!dup]

  list(
    veri = data.frame(rsid = df$rsid, chr = df$chrn, pos = df$posn,
                      gt = df$gtn, anahtar = anahtar, stringsAsFactors = FALSE),
    qc = list(ham = n_ham, unmapped = n_unmapped, nocall = n_nocall,
              indel = n_indel, bozuk = n_bozuk, dup = n_dup,
              gecerli = nrow(df), mt = n_mt, par = n_par)
  )
}
# --- PAR1
PAR1 <- c(60001, 2699520)
# --- PAR2
PAR2 <- c(154931044, 155260560)
# --- kit_cinsiyet
kit_cinsiyet <- function(veri) {
  y <- sum(veri$chr == "24")
  xi <- veri$chr == "23"
  xpos <- veri$pos[xi]; xgt <- veri$gt[xi]
  par <- (xpos >= PAR1[1] & xpos <= PAR1[2]) | (xpos >= PAR2[1] & xpos <= PAR2[2])
  xgt <- xgt[!par]                      # yalnizca non-PAR X
  n_x <- length(xgt)
  # 23andMe erkek X'i tek karakter yazar; MyHeritage/Ancestry ciftler (AA)
  hap_oran <- if (n_x > 0) mean(nchar(xgt) == 1) else NA_real_
  x2 <- xgt[nchar(xgt) == 2]
  xhet <- if (length(x2) >= 200) mean(substr(x2, 1, 1) != substr(x2, 2, 2)) else NA_real_

  tahmin <- "0"
  if (!is.na(hap_oran) && hap_oran > 0.5) {
    tahmin <- "1"                                   # haploid yazim -> erkek
  } else if (!is.na(xhet)) {
    if (xhet < 0.05)      tahmin <- "1"
    else if (xhet > 0.15) tahmin <- "2"
  } else if (y >= 500) tahmin <- "1"

  gerekce <- sprintf("non-PAR X=%d, haploid yazim orani=%s, X het=%s, Y cagri=%d",
                     n_x,
                     if (is.na(hap_oran)) "-" else sprintf("%.2f", hap_oran),
                     if (is.na(xhet)) "-" else sprintf("%.3f", xhet), y)
  list(sex = tahmin, y = y, xhet = xhet, haploid = hap_oran, gerekce = gerekce)
}
# --- cekirdek_id
cekirdek_id <- function(iid) {
  x <- iid
  degisti <- TRUE
  while (degisti) {
    degisti <- FALSE
    for (s in AADR_SUFFIX) {
      hit <- endsWith(x, s)
      if (any(hit)) { x[hit] <- substr(x[hit], 1, nchar(x[hit]) - nchar(s)); degisti <- TRUE }
    }
  }
  x <- sub("_IL[0-9]+$", "", x)
  x <- sub("_(d|dup|published|merged)$", "", x)
  toupper(x)
}
# --- dolgu_esle
dolgu_esle <- function(p1, p2, g1, g2) {
  n <- length(g1); tur <- rep(1L, n)
  k1 <- g1 != "0"; k2 <- g2 != "0"; b1 <- p1 != "0"; b2 <- p2 != "0"
  tur[k1 & k2 & g1 == g2] <- -2L
  # g yuvasinin panelde gittigi yer: 1, 2 ya da 0 (panelde yok)
  s1 <- ifelse(k1 & b1 & g1 == p1, 1L, ifelse(k1 & b2 & g1 == p2, 2L, 0L))
  s2 <- ifelse(k2 & b1 & g2 == p1, 1L, ifelse(k2 & b2 & g2 == p2, 2L, 0L))
  ac <- tur == 1L
  # panelin iki alleli de bilinir
  i <- ac & b1 & b2
  tur[i & k1 & s1 == 0L] <- -1L; tur[i & k2 & s2 == 0L] <- -1L
  i <- i & tur == 1L
  tur[i & k1 & k2 & s1 == 2L & s2 == 1L] <- 2L
  tur[i & k1 & !k2 & s1 == 2L] <- 2L
  tur[i & !k1 & k2 & s2 == 1L] <- 2L
  # panelde allel(ler) "0": gelen yalniz panelin bilinen allelini tasiyabilir.
  # Yeni allel gelirse: bilinen allellerin birlesimi ikiyi asiyorsa PLINK
  # .missnp uretir (-1), asmiyorsa ciktinin .bim'ini doldurur (-3).
  i <- ac & !(b1 & b2)
  kot <- which(i & ((k1 & s1 == 0L) | (k2 & s2 == 0L)))
  if (length(kot)) {
    u <- vapply(kot, function(z) {
      a <- c(p1[z], p2[z], g1[z], g2[z]); length(unique(a[a != "0"]))
    }, 1L)
    tur[kot] <- ifelse(u > 2L, -1L, -3L)
  }
  i <- i & tur == 1L
  tur[i & k1 & s1 == 2L] <- 2L
  tur[i & k2 & s2 == 1L] <- 2L
  tur
}
