# --------------------------------------------------------------------------
# v6.4 test (adim 3): HAM KIT DONUSUMU -- her kit panele AYRI (karar 1; M2: kitler once birbirine birlestirilirse bir kitteki
# ucuncu allel partideki butun kitlerden dusuyordu). Okuma / bicim ve build tespiti / normalizasyon Adna'nin kendi kodu
# (yukaridaki blok). Esleme kromozom:konum anahtariyla (kit_panel_esle'nin kurali, sayisal kromozom kodu). Cagri yalniz iki
# kit alleli de panelin bilinen ("0" olmayan) allelleri arasindaysa kalir -- Adna'nin --23file + N1 (dolgu_esle) zincirinin
# sonucu: ters iplik, ucuncu allel ve panelde "0" iken yeni allel eksik yazilir; iplik cevrilmez; tek harfli cagri PLINK'in
# haploid yazimi gibi homozigot. Yalniz otozomlar (qpAdm auto_only). Build denetimi sablon sozlugu yerine panelin kendisiyle:
# rsID'si panelde olan satirlarin en az %90'i panelle ayni kromozom:konumdaysa uyumlu (en az 1000 satir; azsa baslik).
# Cikti: tek bireylik PLINK seti (.bim panelin bayt kopyasi, .fam FID = kit adi, IID = kit adi + firma soneki), yaninda
# <ad>_kit.txt (kaynak, bicim, build, sayilar, md5'ler).
# --------------------------------------------------------------------------
# v6.4 (madde 7): allel uyumsuzluk orani esikleri -- dogru build'li gercek kitler %0,0012 / %0,0026, yanlis build
# benzetimi %54,5-63,0 (gelistirme_v64/olcum_esik.txt).
RK_MISMATCH_YELLOW <- 0.01
RK_MISMATCH_RED <- 0.10
RK_EXT <- c("txt", "csv", "tsv", "zip", "gz", "vcf")   # vcf: yalniz birakmada taninip tek satirlik gerekceyle dusmesi icin (Adna ile cevrilir)
rk_ascii <- function(x) { x <- chartr("çğıöşüÇĞİÖŞÜâîûÂÎÛ", "cgiosuCGIOSUaiuAIU", x)
  y <- iconv(x, "UTF-8", "ASCII//TRANSLIT", sub = "_"); y[is.na(y)] <- gsub("[^ -~]", "_", x[is.na(y)]); y }
rk_chr <- function(chr) { ch <- sub("^chr", "", trimws(as.character(chr)), ignore.case = TRUE); m <- CHR_MAP[ch]; ch[!is.na(m)] <- unname(m[!is.na(m)]); ch }
rk_key <- function(chr, pos) paste0(rk_chr(chr), ":", format(suppressWarnings(as.numeric(pos)), scientific = FALSE, trim = TRUE))
# PLINK 2 bit kodu (A1'e gore): 0 = A1/A1, 2 = A1/A2, 3 = A2/A2, 1 = eksik. dolgu_esle'nin (N1) sonucuyla ayni karar.
rk_code <- function(gt, p1, p2) {
  a <- substr(gt, 1, 1); b <- ifelse(nchar(gt) >= 2, substr(gt, 2, 2), a)
  k1 <- p1 != "0"; k2 <- p2 != "0"; inn <- function(x) (k1 & x == p1) | (k2 & x == p2)
  d <- (k1 & a == p1) + (k1 & b == p1)
  ifelse(!(inn(a) & inn(b)), 1L, ifelse(d == 2, 0L, ifelse(d == 1, 2L, 3L)))
}
rk_read_side <- function(prefix) {
  f <- paste0(prefix, "_kit.txt"); if (!file.exists(f)) return(NULL)
  x <- readLines(f, warn = FALSE, encoding = "UTF-8"); x <- x[grepl("\t", x, fixed = TRUE) & !startsWith(x, "#")]
  kv <- strsplit(x, "\t", fixed = TRUE); stats::setNames(lapply(kv, function(z) paste(z[-1], collapse = "\t")), vapply(kv, `[`, "", 1))
}
# Kit adi: ham dosya adindan (.gz, son uzanti atilir; Turkce harfler ASCII); klasorde baska ham kitin ayni adi varsa _2, _3 ...
rk_name <- function(raw_name, dir, taken = character(0)) {
  b <- sub("\\.gz$", "", raw_name, ignore.case = TRUE); b <- sub("\\.[A-Za-z0-9]{2,4}$", "", b)
  b <- xs_safe_name(rk_ascii(b)); n <- b; i <- 2L
  while (n %in% taken || file.exists(file.path(dir, paste0(n, ".bed")))) { n <- paste0(b, "_", i); i <- i + 1L }
  n
}
# pan: list(prefix, snp (SNP/A1/A2/CHR/POS), key, auto, md5). Doner list(ok = TRUE, prefix, ...) ya da list(ok = FALSE, key, args).
rk_convert <- function(path, pan, outdir, name, raw_name = basename(path), raw_md5 = unname(tools::md5sum(path)), prog = NULL) {
  red <- function(key, ...) list(ok = FALSE, key = key, args = c(list(raw_name), list(...)))
  pg <- function(st) if (is.function(prog)) try(prog(st), silent = TRUE)   # v6.4 test (saha 1): "read" / "align" / "write"
  pg("read")
  tmp <- tempfile("qps_kit_"); dir.create(tmp, recursive = TRUE, showWarnings = FALSE); on.exit(unlink(tmp, recursive = TRUE), add = TRUE)
  f <- tryCatch(kit_ac(path, tmp), error = function(e) NULL); if (is.null(f) || !file.exists(f)) return(red("rk_red_open"))
  bas <- tryCatch(kit_bas_satirlar(f), error = function(e) character(0)); fmt <- kit_format_tespit(bas)
  if (identical(fmt, "vcf")) return(red("rk_red_vcf"))
  if (identical(fmt, "bilinmiyor")) return(red("rk_red_fmt"))
  bh <- kit_build_tespit(bas)
  nz <- tryCatch(kit_normalize(kit_ham_oku(f, fmt)), error = function(e) NULL)
  if (is.null(nz) || !nrow(nz$veri)) return(red("rk_red_fmt"))
  pg("align"); v <- nz$veri; kk <- rk_key(v$chr, v$pos)
  ri <- match(v$rsid, pan$snp$SNP); hv <- which(!is.na(ri) & grepl("^rs[0-9]+$", v$rsid))
  bo <- if (length(hv)) mean(kk[hv] == pan$key[ri[hv]]) else NA_real_
  if (length(hv) >= 1000L && bo < 0.9) return(red("rk_red_build", sprintf("%.1f%%", 100 * bo)))
  if (length(hv) < 1000L && identical(bh, "b38")) return(red("rk_red_b38"))
  idx <- match(kk, pan$key); use <- !is.na(idx); use[use] <- pan$auto[idx[use]]
  code <- rep(1L, nrow(pan$snp)); cc <- rk_code(v$gt[use], pan$snp$A1[idx[use]], pan$snp$A2[idx[use]]); code[idx[use]] <- cc
  ncall <- sum(code != 1L); if (!ncall) return(red("rk_red_nocall"))
  mrate <- sum(cc == 1L) / max(1L, sum(use))   # v6.4 (madde 7): eslesen konumlarda allel uyumsuzlugu
  if (mrate > RK_MISMATCH_RED) return(red("rk_red_mismatch", sprintf("%.1f%%", 100 * mrate), fs_fmt_n(sum(cc == 1L)), fs_fmt_n(sum(use))))
  bver <- length(hv) >= 1000L   # v6.4 (madde 6): build_check >= 0,9 (alti yukarida kirmizi); azsa dogrulanamadi
  sx <- tryCatch(as.character(kit_cinsiyet(v)$sex), error = function(e) "0"); if (!(sx %in% c("1", "2"))) sx <- "0"
  sfx <- unname(FIRMA_SUFFIX[fmt]); if (is.na(sfx)) sfx <- ""
  pg("write"); dir.create(outdir, recursive = TRUE, showWarnings = FALSE); pre <- file.path(outdir, name)
  tamam <- FALSE; on.exit(if (!tamam) unlink(paste0(pre, c(".bed", ".bim", ".fam", "_kit.txt"))), add = TRUE)   # inceleme 11: yarim donusum iz birakmaz
  con <- file(paste0(pre, ".bed"), "wb"); writeBin(as.raw(c(0x6c, 0x1b, 0x01)), con); writeBin(as.raw(code), con); close(con)
  if (!isTRUE(file.copy(paste0(pan$prefix, ".bim"), paste0(pre, ".bim"), overwrite = TRUE))) stop("panel .bim could not be copied")
  writeLines(sprintf("%s %s%s 0 0 %s -9", name, name, sfx, sx), paste0(pre, ".fam"))
  fa <- unname(FIRMA_ADI[fmt]); if (is.na(fa)) fa <- fmt
  side <- c("#QPS_KIT\t1", sprintf("program\t%s", QPS_VERSION), sprintf("date\t%s", format(Sys.time(), "%Y-%m-%d %H:%M:%S")),
            sprintf("raw_name\t%s", raw_name), sprintf("raw_md5\t%s", raw_md5), sprintf("format\t%s", fa), sprintf("format_code\t%s", fmt),
            sprintf("build_header\t%s", { b <- unname(c(b37 = "GRCh37", b38 = "GRCh38")[bh]); if (length(b) != 1L || is.na(b)) "unknown" else b }), sprintf("build_check\t%s", if (is.na(bo)) "NA" else sprintf("%.4f (%d rsID)", bo, length(hv))),
            sprintf("panel\t%s", pan$prefix), sprintf("panel_bim_md5\t%s", pan$md5), sprintf("rows_raw\t%d", nz$qc$ham), sprintf("rows_valid\t%d", nz$qc$gecerli),
            sprintf("matched_auto\t%d", sum(use)), sprintf("called_auto\t%d", ncall), sprintf("dropped_allele\t%d", sum(cc == 1L)),
            sprintf("build_verified\t%s", if (bver) "yes" else "no"), sprintf("allele_mismatch_rate\t%.6f", mrate), sprintf("duplicate_positions\t%d", as.integer(nz$qc$dup %||% 0L)),   # v6.4 (madde 6, 7, 10)
            sprintf("sex\t%s", sx), sprintf("iid\t%s%s", name, sfx), "rule\tAdna --23file + N1 (dolgu_esle): call kept only if both alleles are known panel alleles; autosomes only")
  writeLines(enc2utf8(side), paste0(pre, "_kit.txt"), useBytes = TRUE); tamam <- TRUE
  list(ok = TRUE, prefix = pre, name = name, fmt = fmt, build = bh, bo = bo, rows = nz$qc$ham, valid = nz$qc$gecerli, matched = sum(use),
       called = ncall, bad = sum(cc == 1L), sex = sx, iid = paste0(name, sfx), build_verified = bver, mrate = mrate, dup = as.integer(nz$qc$dup %||% 0L))
}
# Klasordeki donusturulmus kitler: ham md5 -> onek (ayni panel icin yeniden donusturme yok).
# v6.4 (madde 6, 7): yan dosyadan build dogrulamasi ve allel uyumsuzluk orani. Eski (v6.4 test) yan dosyalarinda alan yoksa
# build_check'teki rsID sayisi ve dropped_allele / matched_auto'dan.
rk_side_flags <- function(kv) { if (is.null(kv)) return(NULL)
  bv <- kv$build_verified %||% { n <- suppressWarnings(as.numeric(sub("^.*\\(([0-9]+) rsID\\).*$", "\\1", kv$build_check %||% ""))); if (isTRUE(n >= 1000)) "yes" else "no" }
  mm <- suppressWarnings(as.numeric(kv$dropped_allele %||% NA)); ma <- suppressWarnings(as.numeric(kv$matched_auto %||% NA))
  mr <- suppressWarnings(as.numeric(kv$allele_mismatch_rate %||% NA)); if (!is.finite(mr) && isTRUE(ma > 0)) mr <- mm / ma
  list(verified = identical(bv, "yes"), n_rsid = suppressWarnings(as.numeric(sub("^.*\\(([0-9]+) rsID\\).*$", "\\1", kv$build_check %||% ""))), rate = mr, bad = mm, matched = ma) }
rk_index <- function(dir) { f <- list.files(dir, "_kit\\.txt$", full.names = TRUE); if (!length(f)) return(list())
  p <- sub("_kit\\.txt$", "", f); m <- vapply(p, function(x) (rk_read_side(x)$raw_md5 %||% ""), "")
  ok <- nzchar(m) & file.exists(paste0(p, ".bed")) & file.exists(paste0(p, ".bim")) & file.exists(paste0(p, ".fam")); as.list(stats::setNames(p[ok], m[ok])) }
# T6: kit panelde de olabilir mi -- firma soneki (.AN/.MH/.23/.FT ...) atilarak Adna'nin cekirdek_id kuralinda ayni kimlik.
rk_dups <- function(iid, panel_ids) { st <- function(x) sub(paste0("(", paste(gsub(".", "\\.", setdiff(unname(FIRMA_SUFFIX), ""), fixed = TRUE), collapse = "|"), ")$"), "", x)
  ci <- cekirdek_id(st(iid)); panel_ids[cekirdek_id(st(panel_ids)) == ci] }

# --------------------------------------------------------------------------
# v6.4 test (adim 1): EK SETLER -- birlestirmesiz (sanal) modelleme. Talimat claude/qpAdm_Studio_v6.4_talimat.md; ana
# belge claude/qpAdm_Studio_v6.3_kararlari.md ("v6.4 kararlari", "Olcumler" M0/M1). Panel uyumlu PLINK setleri (Adna N1
# ciktisi, makale setleri) diske BIRLESTIRILMEDEN modele girer: her setin allel frekanslari ayri okunur, panel SNP sirasina
# hizalanir (ayni / ters -> 1 - p / uyumsuz -> duser), allsnps=FALSE'ta birlesik tablo extract_f2'nin varsayilan yolunun
# AYNI adimlariyla (discard_from_aftable -> cpp_is_polymorphic -> afs_to_f2_blocks) havuza yazilir (M0: ESDEGER).
# Panel etiketlerinin frekanslari kalici onbellekte (karar 5a): etiket basina plink_to_afs / packedancestrymap_to_afs'in
# KENDI ciktisi (bir popun sutunu oteki poplardan bagimsizdir; ploidi birey basina) -> onbellekten gelen sutun dogrudan
# okumayla birebir. Anahtar = panel imzasi (.bed boyut/zaman + SNP dosyasi md5 + birey sirasi) + etiketin birey kumesi
# + ploidi ayari.
# --------------------------------------------------------------------------
XS_COLS_PLINK <- c("CHR", "SNP", "cm", "POS", "A1", "A2")
XS_COLS_EIG   <- c("SNP", "CHR", "cm", "POS", "A1", "A2")
# admixtools'un SNP dosyasi ayristirmasiyla ayni (readr read_table2, col_types "ccddcc"); readr yoksa utils.
xs_rtab <- function(f, nam) {
  if (requireNamespace("readr", quietly = TRUE)) {
    fn <- if (exists("read_table2", envir = asNamespace("readr"), inherits = FALSE)) get("read_table2", envir = asNamespace("readr")) else readr::read_table
    return(as.data.frame(suppressWarnings(fn(f, col_names = nam, col_types = "ccddcc", progress = FALSE)), stringsAsFactors = FALSE))
  }
  d <- utils::read.table(f, header = FALSE, colClasses = c("character", "character", "numeric", "numeric", "character", "character"), comment.char = "", quote = "")
  stats::setNames(d, nam)
}
xs_read_snp <- function(prefix) {
  fs <- geno_fileset(prefix); if (is.null(fs)) stop("genotype files not found: ", prefix)
  x <- if (identical(fs$type, "plink")) xs_rtab(fs$files[["bim"]], XS_COLS_PLINK) else xs_rtab(fs$files[["snp"]], XS_COLS_EIG)
  data.frame(SNP = as.character(x$SNP), A1 = as.character(x$A1), A2 = as.character(x$A2), CHR = as.character(x$CHR), POS = as.numeric(x$POS), stringsAsFactors = FALSE)
}
# Setin birey kimlikleri dosya sirasiyla (.fam 2. sutun / .ind 1. sutun).
xs_read_ids <- function(prefix) {
  fs <- geno_fileset(prefix); if (is.null(fs)) return(character(0))
  d <- utils::read.table(fs$labfile, header = FALSE, colClasses = "character", fill = TRUE, comment.char = "", quote = "")
  trimws(if (identical(fs$type, "plink")) d[[2]] else d[[1]])
}
xs_read_fam <- function(prefix) {
  d <- utils::read.table(paste0(prefix, ".fam"), header = FALSE, colClasses = "character", fill = TRUE, comment.char = "", quote = "")
  data.frame(label = trimws(d[[1]]), id = trimws(d[[2]]), stringsAsFactors = FALSE)
}
# Allel hizasi (olcum M0/M1'deki dogrulanmis kural; talimat Ek B). k, p: SNP / A1 / A2 (ek set, panel). "0" ve "."
# eksik allel. same: ayni yon; flip: ters (frekans 1 - p); ok degilse SNP ek sette eksik sayilir.
xs_align <- function(k, p) {
  ix <- if (identical(k$SNP, p$SNP)) seq_len(nrow(k)) else match(k$SNP, p$SNP)
  z <- c("0", "."); a1 <- p$A1[ix]; a2 <- p$A2[ix]; h0 <- !is.na(ix)
  # v6.4 (madde 8): ayni SNP kimligi baska kromozomdaysa farkli varyant -- kullanilmaz (xs_bg_aftable'da ayni kural)
  nc <- function(x) { x <- toupper(sub("^chr", "", trimws(as.character(x)), ignore.case = TRUE)); x[x == "X"] <- "23"; x[x == "Y"] <- "24"; x[x == "XY"] <- "25"; x[x %in% c("M", "MT")] <- "26"; x }
  hc <- if (is.null(k$CHR) || is.null(p$CHR)) rep(FALSE, nrow(k)) else h0 & nc(k$CHR) != nc(p$CHR[ix]); hc[is.na(hc)] <- FALSE
  h <- h0 & !hc
  cm <- function(x, y) x == y | x %in% z | y %in% z   # "0" yalniz bilinmeyen allel icin joker (v6.4 test, inceleme 5)
  cf <- (!(k$A1 %in% z) & k$A1 == a2 & a1 != k$A1) | (!(k$A2 %in% z) & k$A2 == a1 & a2 != k$A2)
  same <- h & cm(k$A1, a1) & cm(k$A2, a2) & !cf; same[is.na(same)] <- FALSE
  flip <- h & !same & cm(k$A1, a2) & cm(k$A2, a1); flip[is.na(flip)] <- FALSE
  ok <- same | flip
  pd <- if (is.null(k$POS) || is.null(p$POS)) 0L else sum(h & k$POS != p$POS[ix], na.rm = TRUE)
  pl <- sum(ok & paste0(k$A1, k$A2) %in% c("AT", "TA", "CG", "GC"))
  ib <- identical(k$SNP, p$SNP) && identical(k$A1, p$A1) && identical(k$A2, p$A2) && identical(k$CHR, p$CHR) && identical(k$POS, p$POS)   # .bim panelinkiyle ayni (kit setleri)
  list(ix = ix, same = same, flip = flip, ok = ok,
       n = c(rows = nrow(k), common = sum(h0), same = sum(same), flip = sum(flip), bad = sum(h0 & !(same | flip)), absent = sum(!h0), chr = sum(hc), pos = pd, pal = pl, ident = as.integer(ib)))
}
# Ploidi (yalniz kart bilgisi): admixtools cpp_plink_ploidy ile ayni kural -- ilk ntest SNP'de heterozigot cagri (PLINK
# kodu 2 = ikili 10) varsa 2, yoksa 1 (pseudohaploid sayilir).
xs_ploidy <- function(bed, nsnp, nind, ntest = 1000L) {
  bps <- ceiling(nind / 4); n <- min(as.integer(ntest), nsnp)
  if (!file.exists(bed) || nind < 1 || n < 1) return(rep(NA_integer_, max(nind, 0)))
  con <- file(bed, "rb"); on.exit(close(con)); invisible(readBin(con, "raw", 3L))
  b <- readBin(con, "raw", bps * n); if (length(b) < bps * n) return(rep(NA_integer_, nind))
  v <- as.integer(b); het <- logical(4 * bps)
  for (s in 0:3) het[seq(s + 1, by = 4, length.out = bps)] <- rowSums(matrix(bitwAnd(bitwShiftR(v, 2L * s), 3L), nrow = bps) == 2L) > 0
  ifelse(het[seq_len(nind)], 2L, 1L)
}
xs_safe_name <- function(x) { x <- gsub("[^A-Za-z0-9_.-]+", "_", x); if (!nzchar(x)) "set" else x }
# Ek set denetimi (saf; sunucu ve sinamalar). pan = list(prefix, snp, ids, labels) ya da NULL (panel yok -> "wait");
# others = onceki kabul edilmis setler (etiket ve ic ID cakismasi icin). Doner: kart + kosu icin her sey --
# lm: son etiket -> ic ID; raw: ic ID -> .fam IID; mark: etiket -> set adi; why: list(list(key, args)) (cevirisi kartta).
# Etiket panelde ya da onceki bir sette varsa set adindan onek (karar 2(4); ayni bireyler olsa bile iki kopya ayri
# secilebilsin); IID panelde ya da onceki sette varsa ic ID "IID@set" (sample ID'ye dayali kurallar karismasin).
# Ek set dosyalarinin boyut + zaman damgasi (kosu basinda degisiklik denetimi; v6.4 test, inceleme 3).
# v6.4 (madde 11): dosyanin sabit konumlarindan n x len baytlik ornek; boyut + zaman damgasi korunarak yapilan icerik
# degisikligini de yakalar (tam md5 14 GB'lik panelde her koşuda okunamaz).
xs_bed_sample <- function(f, n = 32L, len = 65536L) { sz <- suppressWarnings(file.size(f)); if (!isTRUE(sz > 0)) return("")
  con <- file(f, "rb"); on.exit(close(con)); off <- unique(floor(seq(0, max(0, sz - len), length.out = n)))
  digest::digest(lapply(off, function(o) { seek(con, o); readBin(con, "raw", len) }), algo = "xxhash64") }
# v6.4 (madde 2): havuz anahtarinin ek set eki. Kullanilan setlerin imzasi + havuzdaki ek set poplarinin ad = icerik ozeti
# (lmk: pop -> sample ID + set isareti). Ayni ek -> ayni ek set poplari; pool_match eki iki tarafta birebir ister.
xs_vsuf <- function(sigs, xpops, lmk) { xk <- sort(vapply(as.character(xpops), function(p) paste0(p, "=", digest::digest(sort(as.character(lmk[[p]])), algo = "xxhash64")), ""))
  paste0("#x:", digest::digest(list(sort(as.character(sigs)), unname(xk)), algo = "xxhash64")) }
xs_vsuf_of <- function(v) { v <- v %||% ""; if (grepl("#x:", v, fixed = TRUE)) sub("^.*?(#x:.*)$", "\\1", v, perl = TRUE) else "" }
xs_stamp <- function(prefix) { f <- paste0(prefix, c(".bed", ".bim", ".fam")); paste(file.size(f), as.numeric(file.mtime(f)), collapse = "|") }
xs_check_set <- function(prefix, pan, others = list(), name = NULL) {
  prefix <- normalizePath(prefix, mustWork = FALSE); nm <- xs_safe_name(name %||% basename(prefix))
  x <- list(name = nm, prefix = prefix, status = "red", why = list(), n_ind = 0L, n_snp = 0L, al = NULL, ploidy = NULL,
            lm = list(), raw = character(0), mark = character(0), sig = "", t = Sys.time())
  red <- function(key, ...) { x$why <- list(list(key = key, args = list(...))); x }
  fs <- geno_fileset(prefix)
  if (is.null(fs)) return(red("xs_red_files"))
  if (!identical(fs$type, "plink")) return(red("xs_red_eig"))
  x$kit <- tryCatch(rk_read_side(prefix), error = function(e) NULL)   # v6.4 test (adim 3): programin donusturdugu kit
  if (!is.null(pan) && identical(normalizePath(pan$prefix, mustWork = FALSE), prefix)) return(red("xs_red_panel"))
  fam <- tryCatch(xs_read_fam(prefix), error = function(e) NULL); kb <- tryCatch(xs_read_snp(prefix), error = function(e) NULL)
  if (is.null(fam) || is.null(kb) || !nrow(fam) || !nrow(kb)) return(red("xs_red_files"))
  x$n_ind <- nrow(fam); x$n_snp <- nrow(kb)
  bsz <- file.size(fs$files[["bed"]])
  if (!isTRUE(bsz == 3 + as.numeric(nrow(kb)) * ceiling(nrow(fam) / 4))) return(red("xs_red_bedsize"))
  dup <- unique(fam$id[duplicated(fam$id)]); if (length(dup)) return(red("xs_red_dupiid", paste(utils::head(dup, 3), collapse = ", ")))
  x$sig <- digest::digest(list(unname(tools::md5sum(fs$files[["bim"]])), unname(tools::md5sum(fs$files[["fam"]])), bsz, as.numeric(file.mtime(fs$files[["bed"]])), xs_bed_sample(fs$files[["bed"]])), algo = "xxhash64")   # v6.4: + .bed ornegi
  x$stamp <- xs_stamp(prefix)
  if (is.null(pan)) { x$status <- "wait"; x$why <- list(list(key = "xs_st_wait", args = list())); return(x) }
  if (!is.null(x$kit) && length(pan$md5) == 1L && nzchar(x$kit$panel_bim_md5 %||% "") && !identical(x$kit$panel_bim_md5, pan$md5))   # karar 1: her kit kendi paneline
    return(red("rk_red_otherpanel", basename(x$kit$panel %||% "?"), x$kit$raw_name %||% "?"))
  kf <- rk_side_flags(x$kit)   # v6.4 (madde 6, 7)
  if (!is.null(kf) && isTRUE(kf$rate > RK_MISMATCH_RED)) return(red("rk_red_mismatch", x$kit$raw_name %||% basename(prefix), sprintf("%.1f%%", 100 * kf$rate), fs_fmt_n(kf$bad), fs_fmt_n(kf$matched)))
  al <- xs_align(kb, pan$snp); x$al <- al$n
  if (al$n[["same"]] + al$n[["flip"]] == 0) return(red("xs_red_nocommon"))
  pl <- tryCatch(xs_ploidy(fs$files[["bed"]], nrow(kb), nrow(fam)), error = function(e) rep(NA_integer_, nrow(fam)))
  x$ploidy <- c(dip = sum(pl == 2L, na.rm = TRUE), hap = sum(pl == 1L, na.rm = TRUE))
  taken <- unique(c(pan$labels, unlist(lapply(others, function(o) names(o$lm)), use.names = FALSE)))
  oid <- unique(c(pan$ids, unlist(lapply(others, function(o) names(o$raw)), use.names = FALSE)))
  labs <- unique(fam$label); fin <- stats::setNames(labs, labs); ren <- character(0)
  for (L in labs) if (L %in% taken) { f <- paste0(nm, "_", L); i <- 2L
    while (f %in% c(taken, unname(fin))) { f <- paste0(nm, "_", L, "_", i); i <- i + 1L }
    fin[[L]] <- f; ren <- c(ren, L) }
  iid <- ifelse(fam$id %in% oid, paste0(fam$id, "@", nm), fam$id)
  x$raw <- stats::setNames(fam$id, iid)
  fl <- unname(fin[fam$label]); x$lm <- lapply(split(iid, factor(fl, levels = unique(fl))), as.character)
  x$mark <- stats::setNames(rep(nm, length(x$lm)), names(x$lm))
  inp <- fam$id[fam$id %in% pan$ids]
  why <- list(list(key = "xs_st_ok", args = list(al$n[["same"]] + al$n[["flip"]], al$n[["flip"]])))
  if (al$n[["bad"]] - al$n[["chr"]] > 0) why <- c(why, list(list(key = "xs_st_drop", args = list(al$n[["bad"]] - al$n[["chr"]]))))   # v6.4: kromozom farki ayri satirda
  if (!isTRUE(al$n[["ident"]] == 1)) {   # v6.4 (madde 8): yalniz .bim'i panelden farkli setlerde
    if (al$n[["chr"]] > 0) why <- c(why, list(list(key = "xs_st_chr", args = list(al$n[["chr"]]))))
    if (al$n[["pos"]] > 0) why <- c(why, list(list(key = "xs_st_pos", args = list(al$n[["pos"]]))))
    if (al$n[["pal"]] > 0) why <- c(why, list(list(key = "xs_st_pal", args = list(al$n[["pal"]])))) }
  kyel <- FALSE
  if (!is.null(kf)) {   # v6.4 (madde 6, 7)
    if (!isTRUE(kf$verified)) { why <- c(why, list(list(key = "rk_st_build_unverified", args = list(if (is.finite(kf$n_rsid %||% NA)) fs_fmt_n(kf$n_rsid) else "0")))); kyel <- TRUE }
    if (isTRUE(kf$rate > RK_MISMATCH_YELLOW)) { why <- c(why, list(list(key = "rk_st_mismatch", args = list(sprintf("%.1f%%", 100 * kf$rate), fs_fmt_n(kf$bad), fs_fmt_n(kf$matched))))); kyel <- TRUE } }
  if (length(ren)) why <- c(why, list(list(key = "xs_st_ren", args = list(length(ren), paste(utils::head(unname(fin[ren]), 3), collapse = ", ")))))
  if (length(inp)) why <- c(why, list(list(key = "xs_st_inpanel", args = list(length(inp), paste(utils::head(inp, 3), collapse = ", ")))))
  if (al$n[["absent"]] > 0) why <- c(why, list(list(key = "xs_st_absent", args = list(al$n[["absent"]]))))
  why <- c(why, list(list(key = "xs_st_ploidy", args = list(x$ploidy[["dip"]], x$ploidy[["hap"]]))))
  x$why <- why; x$status <- if (al$n[["bad"]] > 0 || length(ren) || length(inp) || kyel) "yellow" else "green"
  x
}

# ARKA PLAN (callr) -- bu iki islevin govdesi KENDI KENDINE YETER: uygulamanin baska bir islevine basvurmaz (callr islevin
# ortamini .GlobalEnv yapar; cagiran environment(f) <- globalenv() ile gonderir). Yalniz base, admixtools, readr, digest.
# xi = list(panel, panel_type ("plink"/"eigenstrat"), panel_sig, pmap = pop -> panel IID, sets = list(list(name, prefix,
# sig, map = pop -> .fam IID))). Doner list(afs, counts, snpfile): satirlar panelin SNP sirasi, sutunlar 'pops' sirasi --
# admixtools okuyucusunun dondurdugu yapinin aynisi (olcum M0'daki cbind ile ayni degerler).
xs_bg_aftable <- function(xi, pops, adjph, cache_dir = NULL, cache_max = 8e9, counts = TRUE) {   # counts = FALSE: allsnps=TRUE (yalniz frekans)
  say <- function(...) cat(paste0(...), "\n", sep = "")
  rtab <- function(f, nam) { fn <- if (exists("read_table2", envir = asNamespace("readr"), inherits = FALSE)) get("read_table2", envir = asNamespace("readr")) else readr::read_table
    suppressWarnings(fn(f, col_names = nam, col_types = "ccddcc", progress = FALSE)) }
  pl <- identical(xi$panel_type, "plink")
  rdr <- if (pl) admixtools::plink_to_afs else admixtools::packedancestrymap_to_afs
  pm <- xi$pmap[intersect(pops, names(xi$pmap))]
  ck <- !is.null(cache_dir) && nzchar(cache_dir) && isTRUE(tryCatch({ dir.create(cache_dir, showWarnings = FALSE, recursive = TRUE); dir.exists(cache_dir) }, error = function(e) FALSE))
  # v6.4 (madde 4): anahtarda admixtools surumu + commit (okuyucunun davranisi degisirse eski frekanslar kullanilmaz)
  adx <- tryCatch({ d <- suppressWarnings(utils::packageDescription("admixtools")); paste(as.character(d$Version), if (is.null(d$RemoteSha)) "" else as.character(d$RemoteSha)) }, error = function(e) "")
  key <- function(p) digest::digest(list(v = 2L, sig = xi$panel_sig, ids = sort(as.character(pm[[p]])), adjph = isTRUE(adjph), adx = adx), algo = "xxhash64")
  ff <- if (ck && length(pm)) stats::setNames(file.path(cache_dir, paste0("afs_", vapply(names(pm), key, ""), ".rds")), names(pm)) else character(0)
  sf <- if (ck) file.path(cache_dir, paste0("snp_", digest::digest(list(xi$panel_sig, adx), algo = "xxhash64"), ".rds")) else ""
  put <- function(obj, f) tryCatch({ tmp <- paste0(f, ".tmp"); saveRDS(obj, tmp); file.rename(tmp, f) }, error = function(e) say("frequency cache: could not write (", conditionMessage(e), ")"))
  snp <- if (ck && file.exists(sf)) tryCatch(readRDS(sf), error = function(e) NULL) else NULL
  got <- list()
  if (!is.null(snp)) for (p in names(ff)) if (file.exists(ff[[p]])) {
    e <- tryCatch(readRDS(ff[[p]]), error = function(e) NULL)
    if (is.list(e) && length(e$afs) == nrow(snp) && length(e$counts) == nrow(snp)) { got[[p]] <- e; try(Sys.setFileTime(ff[[p]], Sys.time()), silent = TRUE) } }
  miss <- setdiff(names(pm), names(got))
  say("virtual merge: ", length(pm), " panel population(s) -- from frequency cache ", length(got), ", reading now ", length(miss))
  if (length(miss)) {
    say("QPS_XS_READ panel")   # v6.4 test (saha 1): ilerleme isareti
    a <- rdr(xi$panel, inds = unname(unlist(pm[miss])), pops = rep(miss, lengths(pm[miss])), adjust_pseudohaploid = adjph, verbose = TRUE)
    if (is.null(snp) || nrow(snp) != nrow(a$afs)) { snp <- a$snpfile; if (ck) put(snp, sf) }
    for (p in miss) { got[[p]] <- list(afs = unname(a$afs[, p]), counts = as.integer(a$counts[, p])); if (ck) put(got[[p]], ff[[p]]) }
    rm(a); invisible(gc())
  }
  if (is.null(snp)) { snp <- rtab(paste0(xi$panel, if (pl) ".bim" else ".snp"), if (pl) c("CHR", "SNP", "cm", "POS", "A1", "A2") else c("SNP", "CHR", "cm", "POS", "A1", "A2")); if (ck) put(snp, sf) }
  N <- nrow(snp)
  afs <- matrix(NA_real_, N, length(pops), dimnames = list(snp$SNP, pops)); cnt <- if (counts) matrix(0, N, length(pops), dimnames = list(snp$SNP, pops)) else NULL
  for (p in names(got)) { afs[, p] <- got[[p]]$afs; if (counts) cnt[, p] <- as.numeric(got[[p]]$counts) }
  got <- NULL; invisible(gc())
  # v6.4 (madde 5): panelde "0" alleli olan satirlar; ek setlerin hizalanmis allel yuvalari seyrek tabloya (xs_zero_fix)
  z0 <- which(snp$A1 %in% c("0", ".") | snp$A2 %in% c("0", ".")); zt <- list(); zc <- list()
  for (s in xi$sets) {
    kb <- rtab(paste0(s$prefix, ".bim"), c("CHR", "SNP", "cm", "POS", "A1", "A2"))
    ix <- if (identical(kb$SNP, snp$SNP)) seq_len(nrow(kb)) else match(kb$SNP, snp$SNP)
    z <- c("0", "."); a1 <- snp$A1[ix]; a2 <- snp$A2[ix]; h <- !is.na(ix)
    nc <- function(x) { x <- toupper(sub("^chr", "", trimws(as.character(x)), ignore.case = TRUE)); x[x == "X"] <- "23"; x[x == "Y"] <- "24"; x[x == "XY"] <- "25"; x[x %in% c("M", "MT")] <- "26"; x }   # v6.4 (madde 8): xs_align ile ayni
    hc <- h & nc(kb$CHR) != nc(snp$CHR[ix]); hc[is.na(hc)] <- FALSE; h <- h & !hc
    cm <- function(x, y) x == y | x %in% z | y %in% z   # xs_align ile ayni kural
    cf <- (!(kb$A1 %in% z) & kb$A1 == a2 & a1 != kb$A1) | (!(kb$A2 %in% z) & kb$A2 == a1 & a2 != kb$A2)
    same <- h & cm(kb$A1, a1) & cm(kb$A2, a2) & !cf; same[is.na(same)] <- FALSE
    flip <- h & !same & cm(kb$A1, a2) & cm(kb$A2, a1); flip[is.na(flip)] <- FALSE
    ok <- same | flip
    say("QPS_XS_READ set ", s$name)   # v6.4 test (saha 1)
    k <- admixtools::plink_to_afs(s$prefix, inds = unname(unlist(s$map)), pops = rep(names(s$map), lengths(s$map)), adjust_pseudohaploid = adjph, verbose = TRUE)
    if (nrow(k$afs) != nrow(kb)) stop("extra set ", s$name, ": allele frequency rows do not match its .bim")
    kaf <- k$afs; if (any(flip)) kaf[flip, ] <- 1 - kaf[flip, , drop = FALSE]
    cp <- intersect(colnames(kaf), pops)
    afs[ix[ok], cp] <- kaf[ok, cp, drop = FALSE]; if (counts) cnt[ix[ok], cp] <- k$counts[ok, cp, drop = FALSE]
    zc[[s$name]] <- cp
    if (length(z0)) { w <- which(ok & ix %in% z0)   # v6.4: degerler kb$A1'in (flip'te kb$A2'nin) frekansi -> yuva allelleri
      if (length(w)) zt[[length(zt) + 1L]] <- data.frame(row = ix[w], set = s$name, a1 = ifelse(flip[w], kb$A2[w], kb$A1[w]), a2 = ifelse(flip[w], kb$A1[w], kb$A2[w]), stringsAsFactors = FALSE) }
    say("extra set ", s$name, ": ", length(cp), " population(s) | SNPs same allele ", sum(same), ", flipped ", sum(flip), ", dropped (allele mismatch) ", sum(h & !ok), if (any(hc)) paste0(", dropped (other chromosome) ", sum(hc)) else "", ", not in panel ", sum(is.na(ix)))
    rm(k, kaf, kb); invisible(gc())
  }
  if (ck) tryCatch({   # kalici onbellek siniri: en eski kullanilanlar silinir (bu kosunun dosyalari korunur)
    fl <- list.files(cache_dir, "^(afs|snp)_.*\\.rds$", full.names = TRUE); inf <- file.info(fl); tot <- sum(inf$size, na.rm = TRUE)
    if (tot > cache_max) { o <- order(inf$mtime); keep <- normalizePath(c(unname(ff), sf), mustWork = FALSE)
      for (i in o) { if (tot <= 0.75 * cache_max) break; f <- fl[i]; if (normalizePath(f, mustWork = FALSE) %in% keep) next
        if (isTRUE(file.remove(f))) tot <- tot - inf$size[i] }
      say("frequency cache: trimmed to ", round(tot / 1e9, 2), " GB") }
  }, error = function(e) NULL)
  zero <- list(tab = if (length(zt)) do.call(rbind, zt) else NULL, cols = zc)
  if (!is.null(zero$tab)) say("allele reconciliation: ", nrow(zero$tab), " extra-set value row(s) on ", length(unique(zero$tab$row)), " panel SNP(s) with an unknown allele")
  say("QPS_XS_AF_DONE")   # v6.4 test (saha 1)
  list(afs = afs, counts = cnt, snpfile = snp, zero = zero)
}
# v6.4 (madde 5): "0" alleli -- (c) uzlasma kurali. Birim = verilen afs'in sutunlari (havuz ya da model). Kendi kendine
# yeter (arka plan): yalniz base. tab: row (panel satiri), set, a1/a2 (degerin yuvasi: deger = a1'in frekansi).
# Panelin bilinen allelleri K, birimde frekansi > 0 olan yeni alleller N: |K| + |N| <= 2 -> tamamlanir (0/0'da alfabetik
# ilk allelin frekansina cevrilir); > 2 -> yeni allel tasiyan poplar o satirda NA (counts 0). Sira bagimsiz.
xs_zero_fix <- function(afs, counts, snp, zero) {
  n <- c(rows = 0, newallele = 0, completed = 0, conflict = 0, masked = 0, reoriented = 0); out <- list(afs = afs, counts = counts, n = n); ro <- integer(0)
  tab <- zero$tab; if (is.null(tab) || !nrow(tab)) return(out)
  cols <- lapply(zero$cols, function(cc) intersect(as.character(cc), colnames(afs))); cols <- cols[lengths(cols) > 0]
  tab <- tab[tab$set %in% names(cols), , drop = FALSE]; if (!nrow(tab)) return(out)
  z <- c("0", "."); kn <- function(a) !is.na(a) & !(a %in% z)
  K1 <- snp$A1[tab$row]; K2 <- snp$A2[tab$row]
  p1 <- p2 <- logical(nrow(tab))
  for (st in names(cols)) { i <- which(tab$set == st); if (!length(i)) next
    V <- afs[tab$row[i], cols[[st]], drop = FALSE]; p1[i] <- rowSums(V > 0, na.rm = TRUE) > 0; p2[i] <- rowSums(V < 1, na.rm = TRUE) > 0 }
  new1 <- p1 & kn(tab$a1) & tab$a1 != ifelse(kn(K1), K1, "") & tab$a1 != ifelse(kn(K2), K2, "")
  new2 <- p2 & kn(tab$a2) & tab$a2 != ifelse(kn(K1), K1, "") & tab$a2 != ifelse(kn(K2), K2, "")
  nl <- unique(rbind(data.frame(row = tab$row[new1], al = tab$a1[new1], stringsAsFactors = FALSE), data.frame(row = tab$row[new2], al = tab$a2[new2], stringsAsFactors = FALSE)))
  rows <- sort(unique(tab$row)); nk <- kn(snp$A1[rows]) + kn(snp$A2[rows])
  nn <- if (nrow(nl)) as.integer(table(factor(nl$row, levels = rows))) else integer(length(rows))
  bad <- rows[nk + nn > 2]
  c1 <- if (nrow(nl)) vapply(split(nl$al, nl$row), function(a) sort(unique(a))[1], "") else character(0)
  ci <- function(st) match(cols[[st]], colnames(afs))
  for (st in names(cols)) { i <- which(tab$set == st); if (!length(i)) next; cc <- ci(st); R <- tab$row[i]
    V <- afs[R, cc, drop = FALSE]
    cf <- R %in% bad
    if (any(cf)) { M <- (matrix(new1[i], nrow(V), ncol(V)) & !is.na(V) & V > 0) | (matrix(new2[i], nrow(V), ncol(V)) & !is.na(V) & V < 1); M[!cf, ] <- FALSE
      if (any(M)) { w <- which(M, arr.ind = TRUE); afs[cbind(R[w[, 1]], cc[w[, 2]])] <- NA_real_; if (!is.null(counts)) counts[cbind(R[w[, 1]], cc[w[, 2]])] <- 0; n[["masked"]] <- n[["masked"]] + nrow(w) } }
    zz <- !cf & !kn(snp$A1[R]) & !kn(snp$A2[R]) & as.character(R) %in% names(c1)   # 0/0 satiri, celiski yok, en az bir allel var
    if (any(zz)) { j <- which(zz); cr <- unname(c1[as.character(R[j])]); a1 <- tab$a1[i][j]; a2 <- tab$a2[i][j]
      Vj <- afs[R[j], cc, drop = FALSE]
      NV <- ifelse(matrix(a1 == cr, length(j), ncol(Vj)), Vj, ifelse(matrix(a2 == cr, length(j), ncol(Vj)), 1 - Vj, 0 * Vj))
      ch <- which(!(a1 == cr)); ro <- c(ro, R[j][ch])
      afs[R[j], cc] <- NV } }
  # sayaclar (bagimsiz inceleme 5): satir sayilari -- panelde "0", yeni allel getiren, tamamlanan, celiskili, yonu cevrilen
  n[["rows"]] <- length(rows); n[["newallele"]] <- sum(nn > 0); n[["completed"]] <- sum(nn > 0 & nk + nn <= 2); n[["conflict"]] <- length(bad); n[["reoriented"]] <- length(unique(ro))
  list(afs = afs, counts = counts, n = n)
}
# allsnps=TRUE sanal f4 blok tablosu (olcum M1'deki vf4; talimat Ek B): f4blockdat_from_geno(allsnps = TRUE) dongusunun
# aynisi -- otozomal SNP'lerde get_block_lengths, blok blok cpp_aftable_to_dstatnum(at, p1..p4, 0, matrix(0), TRUE, FALSE),
# blok ortalamasi ve sayimi; est yalniz n > 0 iken. A: frekans matrisi (satir = snp, sutun = pop), snp: CHR/SNP/cm/POS.
# Kendi kendine yeter (arka plan): yalniz admixtools, tibble, tidyr, dplyr.
xs_vf4 <- function(A, snp, left, right, blgsize = 0.05, prog = FALSE, zero = NULL, zf = NULL) {   # v6.4: zero/zf -> model biriminde uzlasma   # prog: QPS_XSF4 i nb ilerleme satirlari (v6.4 test, saha 1)
  ns <- asNamespace("admixtools")
  pc <- tidyr::expand_grid(tibble::tibble(pop1 = left[1], pop2 = left[-1]), tibble::tibble(pop3 = right[1], pop4 = right[-1]))
  pops <- unique(c(pc$pop1, pc$pop2, pc$pop3, pc$pop4))
  s <- tibble::tibble(CHR = as.character(snp$CHR), SNP = as.character(snp$SNP), cm = as.numeric(snp$cm), POS = as.numeric(snp$POS))
  s$keep <- suppressWarnings(as.numeric(gsub("[a-zA-Z]+", "", s$CHR)) <= 22); s$keep[is.na(s$keep)] <- FALSE
  bl <- admixtools::get_block_lengths(s[which(s$keep), ], blgsize = blgsize, verbose = FALSE); nb <- length(bl)
  s$block <- NA_integer_; s$block[s$keep] <- rep(seq_len(nb), bl); s <- tidyr::fill(s, "block", .direction = "updown")
  si <- split(s$keep, s$block); en <- cumsum(rle(s$block)$lengths); st <- c(0, en[-length(en)])
  p1 <- match(pc$pop1, pops); p2 <- match(pc$pop2, pops); p3 <- match(pc$pop3, pops); p4 <- match(pc$pop4, pops)
  A <- A[, pops, drop = FALSE]; numer <- cnt <- matrix(NA, nb, nrow(pc))
  if (is.function(zf) && !is.null(zero$tab)) { zr <- zf(A, NULL, snp, zero); A <- zr$afs   # v6.4 (madde 5): birim = bu modelin poplari
    if (isTRUE(prog) && zr$n[["rows"]] > 0) cat(sprintf("allele reconciliation (model): %d panel SNP(s) with an unknown allele; %d bring a new allele: %d completed, %d conflicting (%d value(s) set missing); %d reoriented\n", as.integer(zr$n[["rows"]]), as.integer(zr$n[["newallele"]]), as.integer(zr$n[["completed"]]), as.integer(zr$n[["conflict"]]), as.integer(zr$n[["masked"]]), as.integer(zr$n[["reoriented"]]))) }
  for (i in seq_len(nb)) { at <- t(A[(st[i] + 1):en[i], , drop = FALSE][si[[i]], , drop = FALSE])
    num <- ns$cpp_aftable_to_dstatnum(at, p1, p2, p3, p4, 0, matrix(0), TRUE, FALSE)
    numer[i, ] <- unname(rowMeans(num$num, na.rm = TRUE)); cnt[i, ] <- c(num$cnt)
    if (isTRUE(prog) && (i %% 20L == 0L || i == nb)) cat("QPS_XSF4 ", i, " ", nb, "\n", sep = "") }
  out <- tidyr::expand_grid(pc, block = seq_len(nb)); out$est <- c(numer); out$n <- c(cnt); out$length <- bl[out$block]
  out$est <- dplyr::if_else(is.finite(out$est) & out$n > 0, out$est, NA_real_)
  out
}
# allsnps=TRUE sanal qpAdm: qpadm(prefix, allsnps = TRUE) ile ayni sira (left = c(target, left)), f4blocks[left, right[-1]];
# verbose iken f4 basina SNP tablosu qpadm'in bastigi bicimde (parse_f4_snp_table "SNP Used"i buradan okur).
xs_qpadm_true <- function(AF, snp, target, left, right, blgsize = 0.05, verbose = TRUE, vf4 = NULL, zero = NULL, zf = NULL) {
  L <- c(target, setdiff(left, target))
  fd <- vf4(AF, snp, L, right, blgsize, prog = verbose, zero = zero, zf = zf)
  if (verbose) {
    st <- as.data.frame(dplyr::summarize(dplyr::group_by(fd, pop1, pop2, pop3, pop4), n = sum(n), .groups = "drop"))   # qpadm'in kendi cagrisi gibi
    cat('"allsnps = TRUE" uses different SNPs for each f4-statistic\n  Number of SNPs used for each f4-statistic:\n'); print(st)
  }
  fb <- admixtools::f4blockdat_to_f4blocks(fd)[L[-1], right[-1], , drop = FALSE]
  admixtools::qpadm(NULL, NULL, NULL, target, f4blocks = fb, verbose = verbose)
}
# v6.5 ADIM 1: allsnps=TRUE TEK GENOTIP GECISI. admixtools 2f6957a f4blockdat_from_geno(allsnps = TRUE, auto_only = TRUE,
# blgsize = 0.05, poly_only = FALSE) dongusunun birebir kopyasi (olcum_v65 vpass): butun islerin dortluleri (popcombs)
# birlesik verilir, .bed bir kez okunur. allsnps = TRUE'da her dortlunun SNP'leri yalniz kendi dort popuna bagli, blok
# sinirlari yalniz .bim'e -> dortlu basina sonuc tek basina hesaplanmisla ayni. Ek: tpops hedeflerinin otozomal "frekansi
# tanimli" SNP sayisi ayni dongude (anygeno_to_aftable sayimiyla ayni tanim: en az bir cagrili genotip). Ilerleme
# satirlari qpadm'inkiyle ayni kalipta ("block i out of n"). Kendi kendine yeter: admixtools ad alani, readr, tidyr, dplyr.
qps_geno_pass <- function(pref, popcombs, tpops = character(0), blgsize = 0.05, prog = TRUE) {
  ns <- asNamespace("admixtools")
  if (prog) cat("Reading metadata...\n")
  pref <- normalizePath(pref, mustWork = FALSE); l <- ns$format_info(pref)
  indfile <- suppressWarnings(readr::read_table2(paste0(pref, l$indend), col_names = l$indnam, col_types = l$indtype, progress = FALSE))
  snpfile <- suppressWarnings(readr::read_table2(paste0(pref, l$snpend), col_names = l$snpnam, col_types = "ccddcc", progress = FALSE))
  cpp_read_geno <- l$cpp_read_geno; fl <- paste0(pref, l$genoend); nsnpall <- nrow(snpfile); nindall <- nrow(indfile)
  snpfile$keep <- as.numeric(gsub("[a-zA-Z]+", "", snpfile$CHR)) <= 22
  popcombs <- dplyr::distinct(popcombs[, c("pop1", "pop2", "pop3", "pop4")]); pc <- popcombs; modelvec <- 0
  pops <- unique(c(popcombs$pop1, popcombs$pop2, popcombs$pop3, popcombs$pop4))
  if (!all(pops %in% indfile$pop)) stop(paste0("Populations missing from indfile: ", paste0(setdiff(pops, indfile$pop), collapse = ", ")))
  if (any(duplicated(indfile$ind))) stop("Duplicate individual IDs are not allowed!")
  allinds <- indfile$ind; indfile <- dplyr::filter(indfile, pop %in% pops); indvec <- (allinds %in% indfile$ind) + 0; popvec <- match(indfile$pop, pops)
  p1 <- match(pc$pop1, pops); p2 <- match(pc$pop2, pops); p3 <- match(pc$pop3, pops); p4 <- match(pc$pop4, pops)
  if (prog) cat(sprintf("Computing block lengths for %d SNPs...\n", sum(snpfile$keep)))
  block_lengths <- ns$get_block_lengths(dplyr::filter(snpfile, keep), blgsize = blgsize); numblocks <- length(block_lengths)
  snpfile$block <- NA; snpfile$block[snpfile$keep] <- rep(1:length(block_lengths), block_lengths); snpfile <- tidyr::fill(snpfile, block, .direction = "updown")
  snpind <- split(snpfile$keep, snpfile$block); bl <- rle(snpfile$block)$lengths; start <- dplyr::lag(cumsum(bl), default = 0); end <- cumsum(bl)
  usesnps <- matrix(0); numer <- cnt <- matrix(NA, numblocks, nrow(pc))
  tpops <- intersect(unique(as.character(tpops)), pops); ti <- match(tpops, pops); tcnt <- stats::setNames(numeric(length(tpops)), tpops)
  for (i in 1:numblocks) {
    if (prog) cat(sprintf("Computing %d f4-statistics for block %d out of %d...\n", nrow(pc), i, numblocks))
    gmat <- cpp_read_geno(fl, nsnpall, nindall, indvec, start[i], end[i], T, F)[, snpind[[i]]]
    at <- ns$gmat_to_aftable(gmat, popvec)
    if (length(ti)) tcnt <- tcnt + rowSums(is.finite(at[ti, , drop = FALSE]))
    num <- ns$cpp_aftable_to_dstatnum(at, p1, p2, p3, p4, modelvec, usesnps, TRUE, FALSE)
    numer[i, ] <- unname(rowMeans(num$num, na.rm = TRUE)); cnt[i, ] <- c(num$cnt)
  }
  out <- tidyr::expand_grid(pc, block = 1:numblocks); out$est <- c(numer); out$n <- c(cnt)
  out <- dplyr::left_join(popcombs, out, by = paste0("pop", 1:4))
  out <- dplyr::mutate(out, length = block_lengths[block], est = dplyr::if_else(is.finite(est) & n > 0, est, NA_real_))
  list(fd = out, tsnp = tcnt, nb = numblocks)
}
# v6.5 ADIM 1: tek gecisin f4 tablosundan bir isin qpAdm'i -- qpadm(prefix, allsnps = TRUE) ile ayni sira (left = c(target,
# left)); o isin satirlari suzulur (f4blockdat_to_f4blocks blok uzunlugunu ve NA blok atmayi verilen satirlardan yapar),
# verbose iken SNP tablosu qpadm'in bastigi bicimde (parse_f4_snp_table). xs_qpadm_true'nun geno karsiligi.
qps_geno_fit <- function(fd, target, left, right, verbose = TRUE) {
  L <- setdiff(left, target)
  s <- fd[fd$pop1 == target & fd$pop2 %in% L & fd$pop3 == right[1] & fd$pop4 %in% right[-1], , drop = FALSE]
  if (verbose) {
    st <- as.data.frame(dplyr::summarize(dplyr::group_by(s, pop1, pop2, pop3, pop4), n = sum(n), .groups = "drop"))
    cat('"allsnps = TRUE" uses different SNPs for each f4-statistic\n  Number of SNPs used for each f4-statistic:\n'); print(st)
  }
  fb <- admixtools::f4blockdat_to_f4blocks(s)[L, right[-1], , drop = FALSE]
  admixtools::qpadm(NULL, NULL, NULL, target, f4blocks = fb, verbose = verbose)
}
# v6.5: arka plan icin dortlu tablosu (qpadm'in geno yolundaki popcombs'u: pop1 = target, pop2 = left, pop3 = right[1],
# pop4 = right[-1]) ve islev listesi (ortam globalenv; xs_bg_funs gibi).
qps_pcomb <- function(target, left, right) tidyr::expand_grid(tibble::tibble(pop1 = target, pop2 = setdiff(left, target)), tibble::tibble(pop3 = right[1], pop4 = right[-1]))
qps_gp_funs <- function() lapply(list(pass = qps_geno_pass, fit = qps_geno_fit, pcomb = qps_pcomb), function(f) { environment(f) <- globalenv(); f })
# allsnps=FALSE sanal havuz: extract_f2'nin varsayilan yolu (cols_per_chunk yok) -- discard_from_aftable (maxmiss birlesik
# tabloya; maxmiss = 0 -> havuz "panel ve kullanilan ek setlerin ortak SNP'leri"), cpp_is_polymorphic, afs_to_f2_blocks;
# uygulamanin extract_f2'ye vermedigi argumanlar extract_f2 varsayilanlariyla. Ic islevler ad alanindan (S1 / Ders 80).
xs_build_pool <- function(xi, outdir, pops, maxmiss, blgsize, adjph, auto_only, cache_dir = NULL, aft = NULL, zf = NULL) {   # v6.4: zf -> havuz biriminde uzlasma
  ns <- asNamespace("admixtools")
  fn <- c("discard_from_aftable", "cpp_is_polymorphic", "afs_to_f2_blocks")
  miss <- fn[!vapply(fn, function(f) exists(f, envir = ns, inherits = FALSE), logical(1))]
  if (length(miss)) stop("admixtools internal function(s) not found: ", paste(miss, collapse = ", "))
  afd <- aft(xi, pops, adjph, cache_dir)
  if (is.function(zf) && !is.null(afd$zero$tab)) { zr <- zf(afd$afs, afd$counts, afd$snpfile, afd$zero); afd$afs <- zr$afs; afd$counts <- zr$counts   # v6.4 (madde 5): birim = havuzun poplari
    if (zr$n[["rows"]] > 0) cat(sprintf("allele reconciliation (pool): %d panel SNP(s) with an unknown allele; %d bring a new allele: %d completed, %d conflicting (%d value(s) set missing); %d reoriented\n", as.integer(zr$n[["rows"]]), as.integer(zr$n[["newallele"]]), as.integer(zr$n[["completed"]]), as.integer(zr$n[["conflict"]]), as.integer(zr$n[["masked"]]), as.integer(zr$n[["reoriented"]]))) }
  afd$zero <- NULL
  afd <- ns$discard_from_aftable(afd, maxmiss = maxmiss, minmaf = 0, maxmaf = 0.5, minac2 = FALSE, outpop = NULL, auto_only = auto_only,
                                 poly_only = FALSE, transitions = TRUE, transversions = TRUE, keepsnps = NULL)
  afd$snpfile$poly <- as.logical(ns$cpp_is_polymorphic(afd$afs))
  if (sum(afd$snpfile$poly) == 0) stop("There are no informative SNPs!")
  cat(sprintf("%d SNPs remain after filtering. %d are polymorphic.\n", nrow(afd$afs), sum(afd$snpfile$poly)))
  dir.create(outdir, showWarnings = FALSE, recursive = TRUE)
  ns$afs_to_f2_blocks(afd, outdir = normalizePath(outdir, mustWork = FALSE), overwrite = TRUE, maxmem = 8000, poly_only = c("f2"),
                      pops1 = pops, pops2 = NULL, outpop = NULL, blgsize = blgsize, afprod = TRUE, fst = TRUE, apply_corr = TRUE,
                      n_cores = 1, verbose = TRUE)
  invisible(afd$snpfile)
}

# --------------------------------------------------------------------------
# f-ISTATISTIKLERI YARDIMCILARI (v5.5)
# --------------------------------------------------------------------------
# Kombinasyon sayisi. admixtools2'de fstat_get_popcombs maxcomb = 1e6 sinirini
# uygular ve asilirsa sure=TRUE ister; bu hata ARKA PLAN surecinde kullaniciya
# ULASMAZ, o yuzden sayiyi arayuzde hesaplamak ZORUNLU.
FS_MAXCOMB <- 1e6
fs_ncomb <- function(fnum, ns) { if (any(ns < 1)) return(0); prod(as.numeric(ns)) }

fs_fmt_n <- function(x) formatC(x, format = "d", big.mark = ",")

# f4 satir-satir giris: her satirda virgulle ayrilmis 4 pop.
parse_quads <- function(txt, labels) {
  if (is.null(txt) || !nzchar(trimws(txt))) return(list(df = NULL, bad = 0L))
  ln <- trimws(unlist(strsplit(txt, "[\r\n]+"))); ln <- ln[nzchar(ln)]
  rows <- list(); bad <- 0L
  for (l in ln) {
    p <- trimws(unlist(strsplit(l, "[,;\t]")))
    p <- p[nzchar(p)]
    if (length(p) != 4 || !all(p %in% labels)) { bad <- bad + 1L; next }
    rows[[length(rows) + 1]] <- data.frame(pop1 = p[1], pop2 = p[2], pop3 = p[3], pop4 = p[4], stringsAsFactors = FALSE)
  }
  list(df = if (length(rows)) do.call(rbind, rows) else NULL, bad = bad)
}

# f4-orani satir girisi: her satirda virgul/sekme ile BES pop.
# parse_quads ile ayni desen; tek fark sutun sayisi ve sutun adlari.
parse_quints <- function(txt, labels) {
  if (is.null(txt) || !nzchar(trimws(txt))) return(list(df = NULL, bad = 0L, dup = 0L))
  ln <- trimws(unlist(strsplit(txt, "[\r\n]+"))); ln <- ln[nzchar(ln)]
  ln <- ln[!grepl("^\\s*#", ln)]
  rows <- list(); bad <- 0L
  for (l in ln) {
    p <- trimws(unlist(strsplit(l, "[,;\t]"))); p <- p[nzchar(p)]
    if (length(p) != 5 || !all(p %in% labels)) { bad <- bad + 1L; next }
    rows[[length(rows) + 1]] <- data.frame(pop1 = p[1], pop2 = p[2], pop3 = p[3], pop4 = p[4], pop5 = p[5], stringsAsFactors = FALSE)
  }
  df <- if (length(rows)) do.call(rbind, rows) else NULL
  dup <- 0L
  if (!is.null(df)) { n0 <- nrow(df); df <- dedup_quints(df); dup <- n0 - nrow(df) }
  list(df = df, bad = bad, dup = dup)
}

# alpha = f4(1,2;3,4)/f4(1,2;5,4); pop1 <-> pop2 takasinda hem pay hem payda
# isaret degistirir, alpha AYNI kalir. Bu yuzden (A,B,...) ile (B,A,...) ayni
# istatistiktir ve biri elenir. pop3 <-> pop5 takasi alpha'yi TERSINE cevirir,
# ayri bir istatistiktir; elenmez.
dedup_quints <- function(df) {
  if (is.null(df) || !nrow(df)) return(df)
  a <- pmin(df$pop1, df$pop2); b <- pmax(df$pop1, df$pop2)
  key <- paste(a, b, df$pop3, df$pop4, df$pop5, sep = "\u0001")
  df[!duplicated(key), , drop = FALSE]
}

# Bes listeden kombinasyon matrisi. qpf4ratio'da ne comb ne unique_only ne de
# sure korumasi var; sayiyi ve elemeyi BIZ yapmak zorundayiz.
quints_from_lists <- function(p1, p2, p3, p4, p5) {
  if (!length(p1) || !length(p2) || !length(p3) || !length(p4) || !length(p5)) return(NULL)
  g <- expand.grid(pop1 = p1, pop2 = p2, pop3 = p3, pop4 = p4, pop5 = p5, stringsAsFactors = FALSE, KEEP.OUT.ATTRS = FALSE)
  g <- g[g$pop1 != g$pop2, , drop = FALSE]
  if (!nrow(g)) return(NULL)
  dedup_quints(g)
}

# cli/crayon renk kodlarini temizler. callr alt sureci hatasi ANA surecte
# rlang/cli ile bicimlendirildigi icin bildirime "[33m!" gibi ham kacislar
# sizabiliyordu (v5.8 ekran goruntusu).
strip_ansi <- function(x) gsub("\033\\[[0-9;]*[A-Za-z]", "", x, perl = TRUE)

# v6.0 (D1): konsol GORUNUMU. Log dosyasi ve ilerleme ayristiricilari HAM satirlari okur;
# ekranda ve RAW'da ayni turden ardisik ilerleme satirlarindan yalniz SONUNCUSU kalir
# (terminaldeki \r gorunumu). readLines CR'yi de satir sonu saydigi icin admixtools'un
# "block k out of N" ilerlemesi dosyada satir satir durur (konsolda 1..712 satir).
collapse_progress <- function(x) {
  if (length(x) < 2) return(x)
  k <- rep("", length(x))
  k[grepl("block\\s+[0-9]+\\s+out of", x)] <- "b"
  k[grepl("[0-9]+k SNPs read", x)] <- "s"
  k[grepl("(block|part|Chunk)\\s+[0-9]+\\s+of\\s+[0-9]+", x)] <- "p"
  x[!(nzchar(k) & k == c(k[-1], ""))]
}
# v6.0 (D1/D2/D8): ekrana ve RAW'a giden log. ANSI temizlenir, ilerleme sikistirilir, ic
# protokol satirlari (QPS_*) okunur Ingilizce satirlara cevrilir ya da atilir. Ilerleme
# ayristiricilari bunu DEGIL ham satirlari kullanir.
log_view <- function(x) {
  if (!length(x)) return(character(0))
  x <- collapse_progress(strip_ansi(x))
  x <- x[!grepl("^QPS_(MODE|STAGE|FS_STAGE|QG_STAGE|DONE|ROT_DONE|XS_READ|XS_AF_DONE|XSF4)( |$)", x)]   # v6.4 test (saha 1): XS_* ilerleme isaretleri
  x <- sub("^QPS_TARGET ([0-9]+) ([0-9]+) (.*)$", "--- target \\1/\\2: \\3", x)
  x <- sub("^QPS_ROT_TOTAL ([0-9]+).*$", "--- \\1 models to fit", x)
  x <- sub("^QPS_ROT_ERR ([0-9]+) (.*)$", "    model \\1 ERROR: \\2", x)
  x <- sub("^QPS_ROT ([0-9]+) ([0-9]+) ?(.*)$", "--- model \\1/\\2: \\3", x)
  x <- sub("^QPS_(STAGE_ERR|FS_ERR) ", "ERROR ", x)
  x <- sub("^QPS_TSNP_START ([0-9]+) (.*)$", "--- counting target SNPs (allsnps=TRUE, one genotype read): \\2", x)
  x <- sub("^QPS_PASS ([0-9]+) ([0-9]+).*$", "--- single genotype pass: \\1 model(s), \\2 f4-statistics (allsnps=TRUE)", x)   # v6.5
  x <- sub("^QPS_TSNP_PASS ([0-9]+) (.*)$", "--- target SNPs counted in the same genotype pass: \\2", x)   # v6.5
  x <- sub("^QPS_TSNP_TIME ([0-9.]+)$", "    target SNP read time: \\1 s", x)
  x <- sub("^QPS_TSNP_ERR ", "ERROR target SNPs: ", x)
  x <- sub("^QPS_TSNP ([0-9]+) (.*)$", "    target SNPs \\2: \\1", x)
  sub("^QPS_RCOND ", "RCOND ", x)
}
# v6.0 (K5): bitiste R oturumu gibi okunur dokum. tibble varsayilaninin aksine TUM satir ve
# sutunlar yazilir (genislik gecici acilir); p tam hassasiyetle.
result_transcript <- function(code, r) {
  op <- options(width = 10000); on.exit(options(op))
  w <- as.data.frame(r$weights); pd <- as.data.frame(r$popdrop)
  c(paste0("> ", code), "", "> results$weights", utils::capture.output(print(w, row.names = FALSE, digits = 4)), "",
    "> results$popdrop", utils::capture.output(print(pd, row.names = FALSE, digits = 4)), "",
    "> results$popdrop$p[1]", if (nrow(pd)) format(pd$p[1], digits = 15) else "NA", "")
}
# v6.0 (K9/K10): sure gosterimi (dilden bagimsiz mm:ss / h:mm:ss) ve ortak ilerleme cubugu.
fmt_dur <- function(s) {
  s <- max(0, round(as.numeric(s))); h <- s %/% 3600; m <- (s %% 3600) %/% 60; ss <- s %% 60
  if (h > 0) sprintf("%d:%02d:%02d", h, m, ss) else sprintf("%02d:%02d", m, ss)
}
el_str <- function(t0, t1 = NULL) if (is.null(t0)) NULL else fmt_dur(difftime(if (is.null(t1)) Sys.time() else t1, t0, units = "secs"))
prog_ui <- function(done, frac, msg, el = NULL, eta = NULL, eta_key = "prog_eta") {   # v6.4 ADIM 4: eta_key
  pct <- round((if (isTRUE(done)) 1 else (frac %||% 0)) * 100)
  extra <- paste0(if (!is.null(el)) paste0("  ·  ⏱ ", el) else "",
                  if (!isTRUE(done) && !is.null(eta)) paste0("  ·  ", sprintf(tr(eta_key), eta)) else "")
  txt <- if (isTRUE(done)) paste0(tr("msg_completed"), extra) else paste0(sprintf("%d%%  %s", pct, msg %||% ""), extra)
  div(class = "mt-2",
    div(class = "qps-prog-bg", div(class = paste("qps-prog-fill", if (isTRUE(done)) "done" else ""), style = sprintf("width:%d%%;", pct))),
    div(class = "qps-prog-txt", txt))
}
# v6.4 ADIM 4: gunlukteki son OLCULEBILIR sayac -- rotasyon modeli (QPS_ROT k N), f2 blogu (block k out of N; N yoksa ~713),
# SNP okuma (Nk SNPs read; yalniz toplam biliniyorsa). En son gecen asama secilir. Yoksa NULL.
prog_counter <- function(txt, total = NULL) {
  if (!length(txt)) return(NULL)
  ir <- grep("^QPS_ROT [0-9]+ [0-9]+", txt); ib <- grep("block\\s+[0-9]+\\s+out of", txt); is <- grep("[0-9]+k SNPs read", txt)
  last <- c(rot = if (length(ir)) max(ir) else 0L, blk = if (length(ib)) max(ib) else 0L, snp = if (length(is)) max(is) else 0L)
  if (all(last == 0L)) return(NULL); ph <- names(last)[which.max(last)]; ln <- txt[[last[[ph]]]]
  if (identical(ph, "rot")) { p <- strsplit(ln, " ", fixed = TRUE)[[1]]; return(list(ph = "rot", cur = suppressWarnings(as.numeric(p[2])), tot = suppressWarnings(as.numeric(p[3])))) }
  if (identical(ph, "blk")) { m <- regmatches(ln, gregexpr("block\\s+[0-9]+\\s+out of\\s*[0-9]*", ln))[[1]]; m <- m[length(m)]
    cur <- suppressWarnings(as.numeric(sub("^block\\s+([0-9]+).*$", "\\1", m))); tot <- suppressWarnings(as.numeric(sub("^.*out of\\s*", "", m)))
    if (!is.finite(tot)) tot <- max(713, cur); return(list(ph = "blk", cur = cur, tot = tot)) }
  if (is.null(total) || !isTRUE(is.finite(total) && total > 0)) return(NULL)
  ln <- txt[[max(is)]]; h <- regmatches(ln, gregexpr("[0-9]+k SNPs read", ln))[[1]]   # son satirin SON sayaci (ikinci okuma gecisinde geri gider -> eta_step bastan; bagimsiz inceleme 4)
  cur <- suppressWarnings(as.numeric(sub("k SNPs read", "", h[length(h)], fixed = TRUE))) * 1000
  if (!is.finite(cur)) return(NULL); list(ph = "snp", cur = cur, tot = total) }
# v6.4 ADIM 4: asama hiziyla kalan sure. st: onceki durum (ph, t0, c0, last) ya da NULL. Asama degisir ya da sayac geri
# giderse olcum bastan; en az min_secs ve 1 adim sonra.
eta_step <- function(st, pc, now = Sys.time(), min_secs = 5) {
  if (is.null(pc) || !isTRUE(is.finite(pc$cur)) || !isTRUE(is.finite(pc$tot))) return(list(st = NULL, eta = NULL))
  if (is.null(st) || !identical(st$ph, pc$ph) || pc$cur < st$last) return(list(st = list(ph = pc$ph, t0 = now, c0 = pc$cur, last = pc$cur), eta = NULL))
  st$last <- pc$cur; dk <- pc$cur - st$c0; el <- as.numeric(difftime(now, st$t0, units = "secs"))
  list(st = st, eta = if (dk > 0 && el >= min_secs && pc$tot > pc$cur) fmt_dur(el / dk * (pc$tot - pc$cur)) else NULL) }
# v6.0 (D6-b): rotasyon Flegontova filtresi. Tek kaynakli modelde nested model yoktur ve agirlik
# tam 1'dir (SE 0): bu iki kosul bos olarak SAGLANMIS sayilir. Cok kaynakli modelde popdrop
# yoksa (NA) model BASARISIZ kalir.
rot_nsrc <- function(d) if ("n_src" %in% names(d)) d$n_src else lengths(strsplit(as.character(d$sources), "  +  ", fixed = TRUE))
rot_keep <- function(d, pf, pn) {
  one <- rot_nsrc(d) == 1
  k <- d$p_full >= pf & (d$eaf_ok | one) & ((!is.na(d$p_max_nested) & d$p_max_nested < pn) | (is.na(d$p_max_nested) & one))
  k[is.na(k)] <- FALSE
  k
}
# v6.0 (D9/K18): FST ayarlarinin metni ve konsol kod satiri (dosya ciktisi -> sabit Ingilizce).
fst_param_str <- function(p) sprintf("adjust_pseudohaploid = %s | auto_only = %s | maxmiss = %s | blgsize = %s",
  isTRUE(p$adjph), isTRUE(p$autoonly), format(p$maxmiss %||% 0), format(p$blgsize %||% 0.05))
fst_code_line <- function(p) sprintf("fst(prefix, pop1 = c(%s), pop2 = c(%s), adjust_pseudohaploid = %s, auto_only = %s, maxmiss = %s, blgsize = %s)",
  paste0('"', p$pop1, '"', collapse = ", "), paste0('"', p$pop2, '"', collapse = ", "),
  isTRUE(p$adjph), isTRUE(p$autoonly), format(p$maxmiss %||% 0), format(p$blgsize %||% 0.05))
# v6.0 (K1): allsnps=TRUE'da admixtools (verbose) "Number of SNPs used for each f4-statistic"
# tablosunu (pop1 pop2 pop3 pop4 n) loga basar; satirlar L kaynak x (R-1). print(data.frame)
# genislik yetmezse sutun BLOKLARINA sarar (olculdu, 80 sutun: pop1 pop2 pop3 / pop4 n); bg surec
# genisligi 10000 yapar ama ayristirici iki bicimi de okur. Doner: n degerleri ya da NULL.
parse_f4_snp_table <- function(x) {
  if (!length(x)) return(NULL)
  x <- strip_ansi(x)
  h <- grep("Number of SNPs used for each f4-statistic", x, fixed = TRUE)
  if (!length(h) || h[length(h)] >= length(x)) return(NULL)
  x <- x[(h[length(h)] + 1):length(x)]
  cols <- c("pop1", "pop2", "pop3", "pop4", "n"); n <- numeric(0); rid <- integer(0); hdr <- FALSE; in_n <- FALSE
  for (ln in x) {
    tk <- strsplit(trimws(ln), "[[:space:]]+")[[1]]; tk <- tk[nzchar(tk)]
    if (!length(tk)) { if (hdr) break else next }
    if (all(tk %in% cols)) { hdr <- TRUE; in_n <- identical(tk[length(tk)], "n"); next }
    if (hdr && grepl("^[0-9]+$", tk[1]) && length(tk) >= 2) {
      if (in_n) { n <- c(n, suppressWarnings(as.numeric(tk[length(tk)]))); rid <- c(rid, as.integer(tk[1])) }
      next }
    break
  }
  ok <- is.finite(n)
  if (!any(ok) || anyDuplicated(rid[ok])) return(NULL)
  n[ok]
}
# v6.2 (K1): ham logu ISLERE bol (anahtar = is sirasi "k"): QPS_TARGET k isaretinden bir sonrakine, QPS_DONE k'ye ya da
# hedef SNP sayimina kadar. Sirali modelde ayni hedef birden cok iste gecer; ad yerine sira kullanilir.
log_job_segments <- function(x) {
  if (!length(x)) return(list())
  x <- strip_ansi(x); m <- grep("^QPS_TARGET [0-9]+ [0-9]+ ", x)
  if (!length(m)) return(list())
  e <- c(m[-1] - 1L, length(x)); st <- grep("^QPS_(TSNP_START|DONE) ", x); out <- list()
  for (i in seq_along(m)) {
    ei <- e[i]; tk <- st[st > m[i] & st <= ei]; if (length(tk)) ei <- tk[1] - 1L
    out[[sub("^QPS_TARGET ([0-9]+) .*$", "\\1", x[m[i]])]] <- if (ei > m[i]) x[(m[i] + 1L):ei] else character(0)
  }
  out
}
# v6.2 (K9): Left setinin sirasiz anahtari (ayni set iki kez eklenmez).
seq_key <- function(v) paste(sort(unique(as.character(v))), collapse = "\r")
# Ham logu hedeflere bol: her QPS_TARGET isaretinden bir sonrakine (son hedefte hedef SNP sayimina
# ya da sona) kadar. Ad -> satirlar.
log_target_segments <- function(x) {
  if (!length(x)) return(list())
  x <- strip_ansi(x); m <- grep("^QPS_TARGET [0-9]+ [0-9]+ ", x)
  if (!length(m)) return(list())
  e <- c(m[-1] - 1L, length(x)); ts <- grep("^QPS_TSNP_START ", x); out <- list()
  for (i in seq_along(m)) {
    ei <- e[i]; tk <- ts[ts > m[i] & ts <= ei]; if (length(tk)) ei <- tk[1] - 1L
    out[[sub("^QPS_TARGET [0-9]+ [0-9]+ ", "", x[m[i]])]] <- if (ei > m[i]) x[(m[i] + 1L):ei] else character(0)
  }
  out
}
# v6.0 (K4): SNP gosterimi. si = list(basis = "f4" | "pool" | "pool_le", used, used_min, used_max, n_f4, target)
fmt_int <- function(x) if (is.null(x) || !length(x) || !isTRUE(is.finite(x[1]))) "\u2014" else format(round(x[1]), big.mark = ",", scientific = FALSE, trim = TRUE)
snp_has <- function(si) !is.null(si) && isTRUE(is.finite(si$used %||% NA_real_))
snp_used_str <- function(si) if (!snp_has(si)) "\u2014" else paste0(if (identical(si$basis, "pool_le")) "\u2264 " else "", fmt_int(si$used))
snp_range_str <- function(si) if (!snp_has(si) || !identical(si$basis, "f4") || !isTRUE(is.finite(si$used_min %||% NA_real_))) "" else paste0(fmt_int(si$used_min), " \u2013 ", fmt_int(si$used_max))
snp_basis_tr <- function(b) switch(b %||% "", f4 = tr("snp_basis_f4"), pool = tr("snp_basis_pool"), pool_le = tr("snp_basis_pool_le"), "")
snp_basis_en <- function(b) switch(b %||% "", f4 = "allsnps=TRUE: mean of per-f4 SNP counts", pool = "f2 pool (maxmiss = 0)", pool_le = "f2 pool, upper bound (maxmiss > 0)", NA_character_)
snp_sub <- function(si) if (!snp_has(si)) NULL else paste0(snp_basis_tr(si$basis), if (nzchar(r <- snp_range_str(si))) paste0(" \u00b7 ", r) else "")
# v6.3 (S6): hedef SNP sayimi suruyorsa (si$pending) arayuzde tr("tsnp_counting"), dosya ciktilarinda "counting (not finished)".
snp_hdr <- function(si) paste0(tr("used_snps"), ": ", snp_used_str(si), if (nzchar(r <- snp_range_str(si))) paste0(" (", r, ")") else "", "   |   ", tr("target_snps"), ": ", if (isTRUE(si$pending)) tr("tsnp_counting") else fmt_int(si$target))
# dosya ciktisi (konsol, RAW) -> sabit Ingilizce
snp_line_en <- function(si) {
  r <- snp_range_str(si)
  sprintf("used = %s%s | basis = %s | target SNPs = %s", snp_used_str(si),
    if (nzchar(r)) sprintf(" (min-max %s, %d f4-statistics)", r, as.integer(si$n_f4 %||% 0L)) else "",
    if (snp_has(si)) snp_basis_en(si$basis) else "-", if (isTRUE(si$pending)) "counting (not finished)" else fmt_int(si$target))
}
snp_cols <- function(si) {
  g <- function(v) if (is.null(v) || !isTRUE(is.finite(v[1]))) NA_real_ else round(v[1])
  data.frame(Used_SNPs = g(si$used), Used_SNPs_min = g(si$used_min), Used_SNPs_max = g(si$used_max),
    SNP_basis = if (snp_has(si)) snp_basis_en(si$basis) else NA_character_, Target_SNPs = if (isTRUE(si$pending)) "counting (not finished)" else g(si$target), stringsAsFactors = FALSE)
}

# Genotip setindeki SNP sayisi (.bim ya da .snp satir sayisi). extract_f2
# okuma asamasinda "NNNNk SNPs read..." basar ama toplami ancak SONUNDA
# yazar; ilerleme paydasi icin toplami onceden biliyoruz. Satir sonu bayti
# sayilir; 2 milyon satirlik .bim icin birkac yuz milisaniye.
count_snps_file <- function(prefix) {
  if (is.null(prefix) || !nzchar(prefix)) return(NA_real_)
  f <- c(paste0(prefix, ".bim"), paste0(prefix, ".snp"))
  f <- f[file.exists(f)]
  if (!length(f)) return(NA_real_)
  con <- tryCatch(file(f[1], "rb"), error = function(e) NULL)
  if (is.null(con)) return(NA_real_)
  on.exit(close(con))
  n <- 0
  repeat { ch <- readBin(con, "raw", 1048576L); if (!length(ch)) break; n <- n + sum(ch == as.raw(10L)) }
  if (n > 0) n else NA_real_
}

# extract_f2 GERCEK ciktisina gore bant haritasi. v5.5-v5.7 ayristiricilari
# "block N out of M" kalibini ariyordu; extract_f2 bu kalibi HIC basmiyor,
# bu yuzden cubuk islem bitene kadar %5'te kaliyordu.
# Donus: list(frac, msg) ya da extract cikti satiri yoksa NULL.
parse_extract_progress <- function(txt, total = NULL) {
  if (!length(txt)) return(NULL)
  has <- function(p) any(grepl(p, txt, fixed = TRUE))
  if (has("Data written to"))              return(list(frac = 0.98, msg = tr("prog_writing")))
  if (has("Computing pairwise f2") || has("Computing without splitting") || has("Splitting into"))
                                           return(list(frac = 0.85, msg = tr("prog_f2_pairs")))
  if (has("Allele frequency matrix"))      return(list(frac = 0.72, msg = tr("prog_af_matrix")))
  if (has("remain after filtering"))       return(list(frac = 0.65, msg = tr("prog_filtering")))
  if (has("SNPs read in total"))           return(list(frac = 0.60, msg = tr("prog_filtering")))
  hits <- regmatches(txt, regexpr("[0-9]+k SNPs read", txt))
  if (!length(hits)) return(NULL)
  cur <- max(suppressWarnings(as.numeric(sub("k SNPs read", "", hits))), na.rm = TRUE) * 1000
  if (!is.finite(cur)) return(NULL)
  if (!is.null(total) && is.finite(total) && total > 0) {
    fr <- 0.05 + 0.50 * min(1, cur / total)
    return(list(frac = fr, msg = sprintf(tr("prog_snps_read"), format(cur, big.mark = ",", scientific = FALSE), format(total, big.mark = ",", scientific = FALSE))))
  }
  # Toplam bilinmiyorsa asimptotik rampa: yine de ilerliyor gorunsun.
  list(frac = 0.05 + 0.50 * (1 - exp(-cur / 1e6)), msg = sprintf(tr("prog_snps_read_nt"), format(cur, big.mark = ",", scientific = FALSE)))
}

# f-istatistigi ilerlemesi: hem blok sayaci hem asama isaretleri.
parse_fs_progress <- function(txt, total = NULL) {
  if (!length(txt)) return(list(frac = 0, msg = tr("prog_starting")))
  ex <- parse_extract_progress(txt, total); if (!is.null(ex)) return(ex)
  st <- ""; sm <- grep("^QPS_FS_STAGE ", txt)
  if (length(sm)) st <- sub("^QPS_FS_STAGE ", "", txt[sm[length(sm)]])
  hits <- unlist(regmatches(txt, gregexpr("block\\s+[0-9]+\\s+out of", txt)))
  nums <- suppressWarnings(as.numeric(gsub("\\D", "", hits))); nums <- nums[is.finite(nums)]
  if (length(nums)) { cur <- max(nums); tot <- max(713, cur)
    return(list(frac = min(0.98, cur / tot), msg = sprintf("block %d / ~%d", cur, tot))) }
  if (identical(st, "extract")) return(list(frac = 0.05, msg = tr("prog_f2_blocks")))
  if (identical(st, "read"))    return(list(frac = 0.50, msg = tr("prog_reading")))
  if (identical(st, "compute")) return(list(frac = 0.70, msg = tr("prog_computing")))
  # v5.8: f4-orani iki asamali -- once oran, sonra payda denetimi. Kullanici
  # islemin surdugunu gorsun diye her asama ayri yuzde ve ayri metin veriyor.
  if (identical(st, "ratio"))   return(list(frac = 0.45, msg = tr("f4r_stage_ratio")))
  if (identical(st, "denom"))   return(list(frac = 0.80, msg = tr("f4r_stage_denom")))
  list(frac = 0.02, msg = tr("prog_working"))
}

# --------------------------------------------------------------------------
# qpGRAPH YARDIMCILARI (v5.6)
# --------------------------------------------------------------------------
# Kenar tablosu metnini iki sutunlu data.frame'e cevirir.
# Kabul edilen ayraclar: virgul, noktali virgul, sekme, ok (->), bosluk.
parse_edges <- function(txt) {
  if (is.null(txt) || !nzchar(trimws(txt))) return(list(df = NULL, bad = 0L))
  ln <- trimws(unlist(strsplit(txt, "[\r\n]+"))); ln <- ln[nzchar(ln)]
  ln <- ln[!grepl("^\\s*#", ln)]
  rows <- list(); bad <- 0L
  for (l in ln) {
    s <- gsub("->", ",", l, fixed = TRUE)
    p <- trimws(unlist(strsplit(s, "[,;\t ]+"))); p <- p[nzchar(p)]
    if (length(p) != 2) { bad <- bad + 1L; next }
    rows[[length(rows) + 1]] <- data.frame(from = p[1], to = p[2], stringsAsFactors = FALSE)
  }
  df <- if (length(rows)) do.call(rbind, rows) else NULL
  if (!is.null(df)) df <- df[!duplicated(paste(df$from, df$to)), , drop = FALSE]
  list(df = df, bad = bad)
}

edges_to_text <- function(df) if (is.null(df) || !nrow(df)) "" else paste(sprintf("%s,%s", df$from, df$to), collapse = "\n")

# Graf topolojisinin kaba dogrulamasi. admixtools::is_valid() calisma zamaninda
# igraph ister; burada ARAYUZ icin bagimsiz, saf bir denetim yapiyoruz:
#   - tek kok (hic gelen kenari olmayan tam bir dugum)
#   - her dugume gelen kenar sayisi 1 (normal) ya da 2 (karisim)
#   - dongu yok (topolojik siralama tamamlanabiliyor)
#   - yapraklar: giden kenari olmayan dugumler
graph_check <- function(df) {
  bad <- function(msg) list(ok = FALSE, msg = msg, leaves = character(0), nadmix = 0L, nedge = 0L, roots = character(0))
  if (is.null(df) || !nrow(df)) return(bad("empty"))
  nodes <- unique(c(df$from, df$to))
  indeg <- vapply(nodes, function(n) sum(df$to == n), integer(1))
  outdeg <- vapply(nodes, function(n) sum(df$from == n), integer(1))
  roots <- nodes[indeg == 0]
  leaves <- sort(nodes[outdeg == 0])
  nadmix <- sum(indeg == 2)
  if (length(roots) != 1) return(bad("root"))
  if (any(indeg > 2)) return(bad("indeg"))
  if (!length(leaves)) return(bad("leaf"))
  # dongu denetimi: Kahn topolojik siralama
  rem <- df; ind <- indeg; ord <- 0L; q <- roots
  while (length(q)) {
    n <- q[1]; q <- q[-1]; ord <- ord + 1L
    ch <- rem$to[rem$from == n]
    rem <- rem[rem$from != n, , drop = FALSE]
    for (c in ch) { ind[[c]] <- ind[[c]] - 1L; if (ind[[c]] == 0L) q <- c(q, c) }
  }
  if (ord != length(nodes)) return(bad("cycle"))
  list(ok = TRUE, msg = "ok", leaves = leaves, nadmix = as.integer(nadmix), nedge = nrow(df), roots = roots)
}

# Ornek iskelet: dort yapraktan tek karisim olayli bir graf.
# Amac topoloji onermek DEGIL, kenar tablosu bicimini gostermek.
example_graph_edges <- function(leaves) {
  if (length(leaves) < 4) return(NULL)
  L <- leaves[1:4]
  data.frame(
    from = c("R", "R", "N1", "N1", "N2", "N2", "N3", "A", "N4", "A"),
    to   = c(L[1], "N1", "N2", "N3", L[2], "N4", "A", L[3], "A", L[4]),
    stringsAsFactors = FALSE)
}

# --------------------------------------------------------------------------
# GRAF DUZENLEYICI YARDIMCILARI (v5.8). Hepsi kenar data.frame'i (from, to)
# alir ve list(df, changed, msg) dondurur; msg bir ceviri anahtaridir.
# Duzenleyici YALNIZCA bu kenar tablosunu degistirir; uyum motoru, denetim ve
# .graph/.dot ice aktarma oldugu gibi kalir.
# --------------------------------------------------------------------------
qge_res <- function(df, changed, msg = "") list(df = df, changed = changed, msg = msg)
qge_empty <- function() data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
qge_has <- function(df, a, b) !is.null(df) && nrow(df) > 0 && any(df$from == a & df$to == b)

# Kullanilmayan ilk ic dugum adi: N1, N2, ...
qge_new_name <- function(df, prefix = "N") {
  used <- if (is.null(df)) character(0) else unique(c(df$from, df$to))
  i <- 1L
  while (paste0(prefix, i) %in% used) i <- i + 1L
  paste0(prefix, i)
}

# A->B kenarini A->N->B yapar. Karisim eklemenin ilk adimi budur.
qge_insert <- function(df, a, b, nm) {
  if (!qge_has(df, a, b)) return(qge_res(df, FALSE, "qge_no_edge"))
  k <- which(df$from == a & df$to == b)[1]
  out <- rbind(df[-k, , drop = FALSE], data.frame(from = c(a, nm), to = c(nm, b), stringsAsFactors = FALSE))
  rownames(out) <- NULL
  qge_res(out, TRUE)
}

qge_add <- function(df, a, b) {
  if (identical(a, b)) return(qge_res(df, FALSE, "qge_self"))
  if (qge_has(df, a, b)) return(qge_res(df, FALSE, "qge_edge_exists"))
  out <- rbind(if (is.null(df)) qge_empty() else df, data.frame(from = a, to = b, stringsAsFactors = FALSE))
  rownames(out) <- NULL
  qge_res(out, TRUE)
}

qge_del_edge <- function(df, a, b) {
  if (!qge_has(df, a, b)) return(qge_res(df, FALSE, "qge_no_edge"))
  out <- df[!(df$from == a & df$to == b), , drop = FALSE]; rownames(out) <- NULL
  qge_res(out, TRUE)
}

qge_del_node <- function(df, a) {
  if (is.null(df) || !nrow(df) || !any(df$from == a | df$to == a)) return(qge_res(df, FALSE, "qge_no_edge"))
  out <- df[df$from != a & df$to != a, , drop = FALSE]; rownames(out) <- NULL
  qge_res(out, TRUE)
}

# Yaprak ekleme: ebeveyn verilmezse grafin koku; graf bossa "R" koku olusur.
qge_add_leaf <- function(df, parent, leaf) {
  if (!is.null(df) && nrow(df) && leaf %in% c(df$from, df$to)) return(qge_res(df, FALSE, "qge_leaf_exists"))
  if (is.null(parent) || !nzchar(parent)) {
    roots <- if (is.null(df) || !nrow(df)) character(0) else setdiff(unique(df$from), df$to)
    parent <- if (length(roots)) roots[1] else "R"
  }
  qge_add(df, parent, leaf)
}

# Katmanli yerlesim: derinlik = koktan en uzun yol; YAPRAKLAR EN ALT SATIRDA.
# x: her katmanda ebeveynlerin ortalama x'ine gore sirali (kesisme azalir).
# Dongu varsa gevseme dugum sayisi kadar turla sinirli; sonsuz donmez.
qge_layout <- function(df) {
  if (is.null(df) || !nrow(df)) return(NULL)
  nodes <- unique(c(df$from, df$to))
  indeg <- vapply(nodes, function(n) sum(df$to == n), integer(1))
  outdeg <- vapply(nodes, function(n) sum(df$from == n), integer(1))
  depth <- stats::setNames(rep(0L, length(nodes)), nodes)
  for (it in seq_along(nodes)) {
    ch <- FALSE
    for (i in seq_len(nrow(df))) { d <- depth[[df$from[i]]] + 1L; if (d > depth[[df$to[i]]]) { depth[[df$to[i]]] <- d; ch <- TRUE } }
    if (!ch) break
  }
  leaf <- outdeg == 0
  if (any(leaf)) depth[leaf] <- max(depth)
  x <- stats::setNames(rep(NA_real_, length(nodes)), nodes)
  for (d in sort(unique(depth))) {
    lv <- names(depth)[depth == d]
    key <- vapply(lv, function(n) { px <- x[df$from[df$to == n]]; px <- px[is.finite(px)]; if (length(px)) mean(px) else 0 }, numeric(1))
    lv <- lv[order(key, lv)]
    x[lv] <- seq_along(lv) - (length(lv) + 1) / 2
  }
  type <- ifelse(indeg == 0, "root", ifelse(indeg >= 2, "admix", ifelse(outdeg == 0, "leaf", "inner")))
  data.frame(node = nodes, x = unname(x[nodes]), y = -unname(depth[nodes]), type = unname(type), stringsAsFactors = FALSE)
}

# qpgraph ilerlemesi: numstart dongusu tek tek raporlanmadigi icin asama tabanli.
parse_qg_progress <- function(txt, total = NULL) {
  if (!length(txt)) return(list(frac = 0, msg = tr("prog_starting")))
  ex <- parse_extract_progress(txt, total); if (!is.null(ex)) return(list(frac = ex$frac * 0.6, msg = ex$msg))
  st <- ""; sm <- grep("^QPS_QG_STAGE ", txt)
  if (length(sm)) st <- sub("^QPS_QG_STAGE ", "", txt[sm[length(sm)]])
  hits <- unlist(regmatches(txt, gregexpr("block\\s+[0-9]+\\s+out of", txt)))
  nums <- suppressWarnings(as.numeric(gsub("\\D", "", hits))); nums <- nums[is.finite(nums)]
  if (length(nums)) { cur <- max(nums); tot <- max(713, cur)
    return(list(frac = min(0.60, 0.05 + 0.55 * cur / tot), msg = sprintf("block %d / ~%d", cur, tot))) }
  if (identical(st, "read"))   return(list(frac = 0.35, msg = tr("prog_reading")))
  if (identical(st, "fit"))    return(list(frac = 0.70, msg = tr("prog_computing")))
  if (identical(st, "fstats")) return(list(frac = 0.88, msg = tr("prog_computing")))
  if (identical(st, "pvalue")) return(list(frac = 0.94, msg = tr("prog_computing")))
  list(frac = 0.02, msg = tr("prog_working"))
}

# qpGraph Excel ciktisi. Sayfalar ve sutunlar SABIT INGILIZCE (D2 kurali).
write_qpgraph_excel <- function(fit, file, meta = NULL) {
  wb <- openxlsx::createWorkbook()
  hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#E9ECEF", border = "TopBottom")
  bad <- openxlsx::createStyle(fontColour = "#B00020", bgFill = "#FDE7E9")
  add <- function(nm, d, zcol = NULL) {
    if (is.null(d) || !NROW(d)) return(invisible(NULL))
    d <- as.data.frame(d)
    openxlsx::addWorksheet(wb, nm); openxlsx::writeData(wb, nm, d, headerStyle = hdr)
    if (!is.null(zcol) && zcol %in% names(d))
      openxlsx::conditionalFormatting(wb, nm, cols = which(names(d) == zcol), rows = 2:(nrow(d) + 1), rule = "ABS(A2)>3", style = bad)
    openxlsx::setColWidths(wb, nm, cols = 1:ncol(d), widths = "auto")
  }
  if (!is.null(meta) && length(meta)) {
    openxlsx::addWorksheet(wb, "Summary")
    md <- data.frame(Field = names(meta), Value = vapply(meta, function(v) paste(as.character(v), collapse = ", "), character(1)), stringsAsFactors = FALSE)
    openxlsx::writeData(wb, "Summary", md, headerStyle = hdr); openxlsx::setColWidths(wb, "Summary", cols = 1:2, widths = "auto")
  }
  add("Edges", fit$edges)
  add("f3_fit", fit$f3, "z")
  add("f4_residuals", fit$f4, "z")
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

# f-istatistigi Excel ciktisi. Sayfa adi ve sutunlar SABIT INGILIZCE (D2 kurali).
write_fstat_excel <- function(df, file, kind = "fstat", meta = NULL) {
  wb <- openxlsx::createWorkbook()
  hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#E9ECEF", border = "TopBottom")
  sh <- switch(kind, f2 = "f2", f3 = "f3", f4 = "f4", f4r = "f4_ratio", "fstat")
  openxlsx::addWorksheet(wb, sh)
  openxlsx::writeData(wb, sh, df, headerStyle = hdr)
  openxlsx::setColWidths(wb, sh, cols = 1:max(1, ncol(df)), widths = "auto")
  if (!is.null(meta) && length(meta)) {
    openxlsx::addWorksheet(wb, "Settings")
    md <- data.frame(Field = names(meta), Value = vapply(meta, function(v) paste(as.character(v), collapse = ", "), character(1)), stringsAsFactors = FALSE)
    openxlsx::writeData(wb, "Settings", md, headerStyle = hdr)
    openxlsx::setColWidths(wb, "Settings", cols = 1:2, widths = "auto")
  }
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

qpadm_fullmodel <- function(res, left) {
  full_pat <- paste(rep(0L, length(left)), collapse = "")
  pd <- as.data.frame(res$popdrop); row <- pd[pd$pat == full_pat, , drop = FALSE]
  g <- function(c) if (nrow(row) && c %in% names(row)) row[[c]][1] else NA
  list(p = g("p"), dof = g("dof"), chisq = g("chisq"), feasible = g("feasible"))
}

fmt <- function(x) { if (is.null(x) || length(x) == 0) return("NA"); if (all(is.na(x))) return("NA")
  if (is.numeric(x)) format(x, digits = 4) else as.character(x) }

# Yapistirlan pop metnini 3 formatta cozer: a,b | "a","b" | right=c("a","b")
parse_pops <- function(txt) {
  if (is.null(txt) || !nzchar(trimws(txt))) return(character(0))
  s <- sub("^\\s*(right|left)\\s*=\\s*", "", txt, ignore.case = TRUE)
  s <- gsub("c\\s*\\(", "", s, ignore.case = TRUE); s <- gsub("[()\"']", "", s)
  toks <- trimws(unlist(strsplit(s, "[,;\r\n\t ]+"))); toks[nzchar(toks)]
}

copy_fmt <- function(pops) if (length(pops)) paste0('"', paste(pops, collapse = '","'), '"') else ""

# Etiket -> ID tablosu (Excel/arayuz icin)
# NOT: sutun adlari BILEREK Ingilizce -- bu tablo Excel ve RAW .txt ciktilarina gider.
ids_table <- function(labelmap, labs, missing = tr("not_in_file")) {   # v6.3 test2: dosya ciktilari missing = "(not in file)"
  if (!length(labs)) return(data.frame(Label = character(0), SampleIDs = character(0)))
  data.frame(Label = labs,
             SampleIDs = vapply(labs, function(l) { ids <- labelmap[[l]]
               if (length(ids)) paste(ids, collapse = ", ") else missing }, character(1)),
             stringsAsFactors = FALSE)
}

# Tek "ara ve seç" kutusu icin secenekler: etiket satirlari + her sample ID icin
# ayri aranabilir satir. Deger benzersiz (etiket\u0001id), ekleme sirasinda etikete cozulur.
build_s3_choices <- function(labels, labelmap) {
  if (!length(labels)) return(character(0))
  vals  <- labels; disp <- labels
  # v6.4 test: ek set etiketleri "\u25c7 set" isaretiyle (deger degismez; isaret yalniz gosterimde)
  xm <- attr(labelmap, "xmark", exact = TRUE); xmk <- function(l) if (length(xm)) ifelse(l %in% names(xm), paste0("  \u25c7 ", xm[l]), "") else ""
  if (length(xm)) disp <- paste0(disp, xmk(disp))
  if (length(labelmap)) {
    ids  <- unlist(labelmap, use.names = FALSE)
    labs <- rep(names(labelmap), lengths(labelmap))
    keep <- nzchar(ids) & labs %in% labels
    if (any(keep)) { vals <- c(vals, paste0(labs[keep], "\u0001", ids[keep]))
      disp <- c(disp, paste0(ids[keep], "  \u2192  ", labs[keep], xmk(labs[keep]))) }
  }
  stats::setNames(vals, disp)
}
s3_decode <- function(x) unique(sub("\u0001.*$", "", x))
# v6.2 (K3): secim kutularinin secenekleri: etiketler + aranabilir sample ID satirlari (deger "etiket\u0001ID"; secilince
# sunucu yalniz o bireyi bireysel girdiye cevirir) + kayitli bireysel girdiler (secili olanlar gorunsun).
box_choices <- function(labs, labelmap, extra = character(0)) {
  ch <- build_s3_choices(labs, labelmap); e <- setdiff(as.character(extra), ch)
  c(ch, stats::setNames(e, e))
}
make_donut <- function(res, right, snp = NULL) {   # v6.1: snp = kosunun SNP bilgisi (basliga "SNP Used")
  if (!requireNamespace("ggpubr", quietly = TRUE) || !requireNamespace("patchwork", quietly = TRUE))
    stop(tr("err_need_ggpubr"))
  df <- as.data.frame(res$weights); df$left <- factor(df$left, levels = rev(df$left))
  df$W <- round(df$weight * 100, 2); df$S <- round(df$se * 100, 2); df$Z <- round(df$z, 2)
  my_cols <- scales::hue_pal()(nrow(df))
  p1 <- ggplot(df, aes(x = "", y = W, fill = left)) +
    geom_bar(stat = "identity", width = 1, color = "#333333") + coord_polar("y", start = 0) +
    scale_fill_manual(values = setNames(my_cols, rev(df$left))) +
    theme_void() + theme(legend.position = "none", text = element_text(family = "Arial"))
  tab <- data.frame(Color = "", Population = as.character(rev(df$left)),
                    "Weight(%)" = rev(df$W), "SE(%)" = rev(df$S), "Z-Score" = rev(df$Z), check.names = FALSE)
  t1 <- ggpubr::ggtexttable(tab, rows = NULL, theme = ggpubr::ttheme("light"))
  for (i in seq_len(nrow(tab))) t1 <- ggpubr::table_cell_bg(t1, row = i + 1, column = 1, fill = my_cols[i])
  r_str <- paste(strwrap(paste("Right Pops:", paste(right, collapse = ", ")), 110), collapse = "\n")
  pd <- as.data.frame(res$popdrop)
  tit <- paste0("Target: ", df$target[1], "\nP-Value: ", round(pd$p[1], 3), " | Chi-Squared: ", round(pd$chisq[1], 2),
                if (snp_has(snp)) paste0(" | SNP Used: ", snp_used_str(snp)) else "")
  (p1 | t1) + patchwork::plot_annotation(title = tit, caption = r_str,
    theme = theme(plot.title = element_text(hjust = .5, face = "bold", size = 15, family = "Arial"),
                  plot.caption = element_text(hjust = .5, size = 9, family = "Arial"),
                  plot.background = element_rect(fill = "white", color = "gray50", linewidth = 1)))
}

# v6.1 ADIM 3 (istek 6): TOPLU KOSU TABLOSU. bt_frame: toplu kaydin (rv$batches[[b]]) sonuclarindan matrisler.
# bt_color: Left sutunu j icin ton, agirliga gore koyuluk (0..1 kirpilir; ekran ve PNG ayni renk). bt_order: siralama
# (sutun "target" / "L<j>" / "p" / "chisq" / "feasible"; NA hep sonda). bt_plot: PNG icin ayni tablo (ggplot).
bt_frame <- function(b) {
  if (identical(b$kind, "seq")) return(NULL)   # v6.2 (K9): sirali modelde Left sabit degil
  res <- b$batch %||% list(); left <- as.character(b$left %||% character(0)); tg <- names(res)
  if (!length(tg) || !length(left)) return(NULL)
  W <- S <- Z <- matrix(NA_real_, length(tg), length(left), dimnames = list(tg, left))
  p <- chisq <- rep(NA_real_, length(tg)); fe <- rep(NA, length(tg)); err <- rep("", length(tg))
  for (i in seq_along(tg)) { x <- res[[i]]
    if (is.null(x$res)) { err[i] <- as.character(x$error %||% "error"); next }
    w <- as.data.frame(x$res$weights); k <- match(left, as.character(w$left))
    W[i, ] <- as.numeric(w$weight[k]); S[i, ] <- as.numeric(w$se[k]); Z[i, ] <- as.numeric(w$z[k])
    p[i] <- as.numeric(x$p %||% NA); chisq[i] <- as.numeric(x$chisq %||% NA); fe[i] <- as.logical(x$feasible %||% NA) }
  list(target = tg, left = left, W = W, S = S, Z = Z, p = p, chisq = chisq, feasible = fe, err = err)
}
# v6.5 ADIM 3 (madde 6): Biriken modellerden secilenleri Toplu kosu tablosunda birlikte gostermek. Uygunluk: Right ve Left
# etiket adlariyla VE her etiketin arkasindaki sample ID'lerle ayni (sira onemsiz; ayni bireyler farkli adla birlesmez),
# ayni allsnps modu, FALSE'ta ayni maxmiss. Ilk secili model referanstir; ilk uyumsuzluk tek satirlik gerekce olur.
# Etiket -> ID eslemesi her kaydin toplu kaydindan (kosu anindaki esleme).
bts_ids <- function(r, batches, l) { b <- if (!is.null(r$batch)) batches[[r$batch]] else NULL; sort(unique(as.character(b$labelmap[[l]] %||% character(0)))) }
bt_sel_check <- function(runs, batches) {
  if (length(runs) < 2) return(list(ok = FALSE, why = tr("bts_need2")))
  a <- runs[[1]]; na <- sprintf("%02d", as.integer(a$meta$no %||% 0L))
  for (r in runs[-1]) { pre <- sprintf("%s / %02d \u2014 ", na, as.integer(r$meta$no %||% 0L))
    if (!identical(as.character(a$meta$mode), as.character(r$meta$mode))) return(list(ok = FALSE, why = paste0(pre, sprintf(tr("bts_mode"), a$meta$mode, r$meta$mode))))
    if (identical(as.character(a$meta$mode), "FALSE") && !isTRUE(all.equal(as.numeric(a$meta$maxmiss %||% NA), as.numeric(r$meta$maxmiss %||% NA))))
      return(list(ok = FALSE, why = paste0(pre, sprintf(tr("bts_maxmiss"), format(a$meta$maxmiss %||% NA), format(r$meta$maxmiss %||% NA)))))
    for (rl in c("right", "left")) { x <- unique(as.character(a[[rl]])); y <- unique(as.character(r[[rl]]))
      if (!setequal(x, y)) return(list(ok = FALSE, why = paste0(pre, sprintf(tr(if (rl == "right") "bts_right" else "bts_left"), paste(utils::head(c(setdiff(x, y), setdiff(y, x)), 4), collapse = ", "))))) }
    for (l in unique(c(as.character(a$right), as.character(a$left)))) { ia <- bts_ids(a, batches, l); ib <- bts_ids(r, batches, l)
      if (!identical(ia, ib)) return(list(ok = FALSE, why = paste0(pre, if (length(ia) != length(ib)) sprintf(tr("bts_ids"), l, length(ia), length(ib)) else sprintf(tr("bts_ids_n"), l, length(ia))))) } }
  list(ok = TRUE)
}
# Secilen kayitlardan toplu kayit (bt_frame / write_batch_excel bicimi). Satir adi hedef (ya da hedef · model); ayni ad
# birden cok kez geciyorsa kosu numarasiyla ("05 · xxbabam"). Kopyadaki weights$target da satir adini alir (Excel).
bt_sel_batch <- function(runs, batches) {
  base <- vapply(runs, function(r) if (is.null(r$meta$model)) as.character(r$meta$target) else paste0(r$meta$target, " \u00b7 ", r$meta$model), "")
  lab <- ifelse(base %in% base[duplicated(base)], sprintf("%02d \u00b7 %s", vapply(runs, function(r) as.integer(r$meta$no %||% 0L), 1L), base), base)
  a <- runs[[1]]; lm <- list()
  for (r in runs) { b <- if (!is.null(r$batch)) batches[[r$batch]] else NULL; for (l in setdiff(names(b$labelmap), names(lm))) lm[[l]] <- b$labelmap[[l]] }
  bt <- stats::setNames(lapply(seq_along(runs), function(i) { r <- runs[[i]]; w <- r$res$weights; if (!is.null(w)) { w <- as.data.frame(w); w$target <- lab[i]; r$res$weights <- w }
    list(target = lab[i], model = NULL, left = r$left, res = r$res, p = r$meta$p, dof = r$meta$dof, chisq = r$meta$chisq, feasible = r$meta$feasible, rcond = r$rcond %||% character(0), snp = r$snp) }), unname(lab))
  list(batch = bt, right = as.character(a$right), left = as.character(a$left), kind = "sel", sets = NULL, rcond = character(0), log = character(0), vfam = NULL,
       labelmap = lm, meta = list(mode = a$meta$mode, maxmiss = a$meta$maxmiss, time = format(Sys.time(), "%Y-%m-%d %H:%M:%S"), n = length(runs), keys = names(runs)))
}
bt_color <- function(w, j, n) {
  h <- (210 + (j - 1) * 360 / max(n, 1)) %% 360; v <- pmin(pmax(suppressWarnings(as.numeric(w)), 0), 1); v[is.na(v)] <- 0
  l <- 94 - 52 * v; list(bg = grDevices::hcl(h, 25 + 45 * v, l), fg = ifelse(l < 62, "#ffffff", "#1f2328"))
}
bt_order <- function(f, col = NULL, dir = "desc") {
  n <- length(f$target); if (is.null(col) || length(col) != 1 || !nzchar(col)) return(seq_len(n))
  v <- if (identical(col, "target")) f$target else if (identical(col, "p")) f$p else if (identical(col, "chisq")) f$chisq
       else if (identical(col, "feasible")) as.numeric(f$feasible)
       else if (grepl("^L[0-9]+$", col) && as.integer(sub("^L", "", col)) <= length(f$left)) f$W[, as.integer(sub("^L", "", col))] else return(seq_len(n))
  o <- order(v, decreasing = identical(dir, "desc"), method = "radix", na.last = NA); c(o, setdiff(seq_len(n), o))
}
bt_layout <- function(f) {   # sutun genislikleri (birim) ve PNG piksel boyutu: 1 birim = 75 px yatay, 1 satir = 58 px (res 150)
  nl <- length(f$left); wd <- c(max(1.6, (9.6 * max(nchar(f$target), 6) + 20) / 75), rep(2, nl), 1.1, 1.1, 1.3)
  nr <- length(f$target); top <- nr + 0.55 + (9.5 * max(nchar(c(f$left, "feasible"))) + 24) / 58
  list(wd = wd, xc = cumsum(wd) - wd / 2, nr = nr, top = top,
       px = c(as.integer(ceiling(sum(wd) * 75 + 50)), as.integer(ceiling((top - 0.45) * 58 + 50))))
}
bt_plot <- function(f, ord = seq_along(f$target)) {
  L <- bt_layout(f); nl <- length(f$left); cells <- list()
  add <- function(k, y, fill, fg, a, b = "") cells[[length(cells) + 1]] <<- data.frame(x = L$xc[k], y = y, w = L$wd[k], fill = fill, fg = fg, a = a, b = b, stringsAsFactors = FALSE)
  for (ri in seq_along(ord)) { i <- ord[ri]; y <- L$nr - ri + 1
    add(1, y, "#ffffff", "#1f2328", f$target[i])
    for (j in seq_len(nl)) { wv <- f$W[i, j]; cl <- bt_color(wv, j, nl); fg <- if (isTRUE(wv < 0)) "#c62828" else cl$fg
      if (is.na(wv)) add(j + 1, y, cl$bg, fg, if (nzchar(f$err[i])) "ERROR" else "—")
      else add(j + 1, y, cl$bg, fg, sprintf("%.3f", wv), sprintf("se %.3f · z %.2f", f$S[i, j], f$Z[i, j])) }
    add(nl + 2, y, "#ffffff", "#1f2328", fmt(f$p[i])); add(nl + 3, y, "#ffffff", "#1f2328", fmt(f$chisq[i]))
    add(nl + 4, y, "#ffffff", "#1f2328", if (is.na(f$feasible[i])) "NA" else as.character(f$feasible[i])) }
  d <- do.call(rbind, cells); d$ya <- d$y + ifelse(nzchar(d$b), 0.14, 0); d$yb <- d$y - 0.2; d$ff <- ifelse(nzchar(d$b), "bold", "plain")
  hd <- data.frame(x = L$xc, lab = c("Target", f$left, "p", "chisq", "feasible"), stringsAsFactors = FALSE)
  ggplot2::ggplot(d) + ggplot2::geom_tile(ggplot2::aes(x = x, y = y, width = w, height = 0.96), fill = d$fill, colour = "#c9ccd1") +
    ggplot2::geom_text(ggplot2::aes(x = x, y = ya, label = a, fontface = ff), colour = d$fg, size = 3.1) +
    ggplot2::geom_text(ggplot2::aes(x = x, y = yb, label = b), colour = d$fg, size = 2.3) +
    ggplot2::geom_text(data = hd, ggplot2::aes(x = x, y = L$nr + 0.55, label = lab), angle = 90, hjust = 0, size = 3.1, fontface = "bold") +
    ggplot2::scale_x_continuous(limits = c(0, sum(L$wd)), expand = c(0, 0)) +
    ggplot2::scale_y_continuous(limits = c(0.45, L$top), expand = c(0, 0)) +
    ggplot2::coord_cartesian(clip = "off") + ggplot2::theme_void() +
    ggplot2::theme(plot.background = ggplot2::element_rect(fill = "white", colour = NA), plot.margin = ggplot2::margin(12, 12, 12, 12))
}
bt_png_size <- function(f) bt_layout(f)$px

save_png <- function(plot, file, w, h) {
  if (requireNamespace("ragg", quietly = TRUE)) ragg::agg_png(file, width = w, height = h, units = "px", res = 150, background = "white")
  else grDevices::png(file, width = w, height = h, res = 150, type = "cairo", bg = "white")
  on.exit(grDevices::dev.off()); print(plot)
}

# Ilerleme: payda kirpildigi icin pay/713 (monoton). QPS_TARGET marker -> target k/N.
parse_progress <- function(txt, total = NULL) {
  if (!length(txt)) return(list(frac = 0, msg = tr("prog_starting"), rcond = character(0)))
  rc <- collect_rcond(txt); txt0 <- txt

  # Hedef bilgisi (toplu kosuda kacinci target)
  tinfo <- ""; tfrac_base <- 0; tspan <- 1
  tmark <- grep("^QPS_TARGET ", txt)
  if (length(tmark)) {
    p <- strsplit(txt[tmark[length(tmark)]], " ")[[1]]
    k <- suppressWarnings(as.integer(p[2])); n <- suppressWarnings(as.integer(p[3]))
    tinfo <- sprintf(tr("prog_target_kn"), p[2], p[3], paste(p[-(1:3)], collapse = " "))
    if (is.finite(k) && is.finite(n) && n > 0) { tfrac_base <- (k - 1) / n; tspan <- 1 / n }
    txt <- txt[(tmark[length(tmark)] + 1):length(txt)]
  }

  # v6.0 (K3): allsnps=TRUE'da son hedeften sonra hedef SNP sayimi (tek genotip okumasi)
  ts <- grep("^QPS_TSNP_START ", txt)
  if (length(ts)) {
    seg <- txt[ts[length(ts)]:length(txt)]
    h <- regmatches(seg, regexpr("[0-9]+k SNPs read", seg))
    cur <- if (length(h)) suppressWarnings(max(as.numeric(sub("k SNPs read", "", h)), na.rm = TRUE)) * 1000 else NA_real_
    det <- if (!is.finite(cur)) "" else if (!is.null(total) && is.finite(total) && total > 0)
      sprintf(tr("prog_snps_read"), format(cur, big.mark = ",", scientific = FALSE), format(total, big.mark = ",", scientific = FALSE))
      else sprintf(tr("prog_snps_read_nt"), format(cur, big.mark = ",", scientific = FALSE))
    return(list(frac = 0.99, msg = paste0(tr("prog_tsnp"), if (nzchar(det)) paste0(" \u2014 ", det) else ""), rcond = rc))
  }

  # v6.5 ADIM 1: tek genotip gecisi (allsnps=TRUE, ek setsiz). Gecis %3-90 (blok sayaci; kalan sure "bu asama icin"),
  # ardindan is basina qpAdm uyumu %90-99 (saniyeler). QPS_PASS n_is n_dortlu gecisten once basilir.
  pm <- grep("^QPS_PASS [0-9]+ ", txt0)
  if (length(pm) && !any(grepl("^QPS_STAGE_ERR single pass", txt0))) {   # gecis hata verdiyse eski yolun ilerlemesi
    pn <- suppressWarnings(as.integer(strsplit(txt0[pm[1]], " ")[[1]][2])); if (!is.finite(pn)) pn <- 1L
    if (!length(tmark)) {
      seg <- txt0[pm[1]:length(txt0)]; hb <- regmatches(seg, regexpr("block\\s+[0-9]+\\s+out of\\s+[0-9]+", seg))
      if (length(hb)) { m <- hb[length(hb)]; cur <- suppressWarnings(as.numeric(sub("^block\\s+([0-9]+).*$", "\\1", m))); tot <- suppressWarnings(as.numeric(sub("^.*out of\\s+", "", m)))
        if (!is.finite(tot) || tot <= 0) tot <- max(713, cur)
        return(list(frac = min(0.90, 0.03 + 0.87 * min(1, cur / tot)), msg = sprintf(tr("prog_pass"), pn, cur, tot), rcond = rc, blk = cur, tot = tot, phase = TRUE)) }
      return(list(frac = 0.02, msg = sprintf(tr("prog_pass_start"), pn), rcond = rc))
    }
    return(list(frac = min(0.99, 0.90 + 0.09 * tfrac_base), msg = paste0(tinfo, tr("stg_fit")), rcond = rc))
  }

  # v6.4 test (saha 1): ek setli allsnps=TRUE sanal yol. Frekans tablosu bir kez (panel okuma %2-70, ek set okuma %70-78),
  # sonra hedef basina f4 bloklari ve qpAdm (%78-99). Toplam SNP admixtools'un "has .. and M SNPs" satirindan.
  xa <- grep("^QPS_STAGE sanal frekans tablosu kuruluyor", txt0)
  if (length(xa)) {
    if (!any(grepl("^QPS_XS_AF_DONE", txt0))) {
      seg <- txt0[xa[length(xa)]:length(txt0)]; rd <- grep("^QPS_XS_READ ", seg)
      wh <- if (length(rd)) sub("^QPS_XS_READ ", "", seg[rd[length(rd)]]) else "panel"
      if (length(rd)) seg <- seg[rd[length(rd)]:length(seg)]
      h <- regmatches(seg, regexpr("[0-9]+k SNPs read", seg))
      cur <- if (length(h)) suppressWarnings(max(as.numeric(sub("k SNPs read", "", h)), na.rm = TRUE)) * 1000 else 0
      tl <- regmatches(seg, regexpr("and [0-9]+ SNPs", seg)); tot <- if (length(tl)) suppressWarnings(as.numeric(gsub("\\D", "", tl[length(tl)]))) else NA_real_
      if (!isTRUE(tot > 0)) tot <- if (!is.null(total) && isTRUE(total > 0)) total else NA_real_
      if (any(grepl("SNPs read in total", seg, fixed = TRUE)) && isTRUE(tot > 0)) cur <- tot
      f <- if (isTRUE(tot > 0) && is.finite(cur)) min(1, cur / tot) else 0
      isp <- identical(wh, "panel")
      fr <- if (isp) 0.02 + 0.68 * f else 0.70 + 0.08 * f
      det <- if (isTRUE(cur > 0) && isTRUE(tot > 0)) sprintf(tr("prog_snps_read"), format(cur, big.mark = ",", scientific = FALSE), format(tot, big.mark = ",", scientific = FALSE)) else ""
      what <- if (isp) tr("prog_xs_panel") else sprintf(tr("prog_xs_set"), sub("^set ", "", wh))
      return(list(frac = min(0.78, fr), msg = paste0(tr("stg_xs_af"), " \u2014 ", what, if (nzchar(det)) paste0(" \u2014 ", det) else ""), rcond = rc))
    }
    fm <- grep("^QPS_XSF4 ", txt); inner <- 0.02; xmsg <- tr("stg_qpadm")
    if (length(fm)) { p4 <- strsplit(txt[fm[length(fm)]], " ")[[1]]; bi <- suppressWarnings(as.integer(p4[2])); bn <- suppressWarnings(as.integer(p4[3]))
      if (isTRUE(bn > 0) && is.finite(bi)) { inner <- 0.85 * min(1, bi / bn); xmsg <- sprintf(tr("prog_xs_f4"), bi, bn) } }
    if (any(grepl("Computing admixture weights", txt, fixed = TRUE))) { inner <- 0.92; xmsg <- tr("stg_qpadm") }
    fr <- 0.78 + 0.21 * (if (length(tmark)) tfrac_base + tspan * inner else inner)
    return(list(frac = min(0.99, fr), msg = paste0(tinfo, xmsg), rcond = rc))
  }

  # Asama isaretleri (allsnps=FALSE'da ilerleme %0'da takilmasin diye)
  stage <- ""; smark <- grep("^QPS_STAGE ", txt)
  if (length(smark)) stage <- sub("^QPS_STAGE ", "", txt[smark[length(smark)]])

  # v5.8: extract_f2 "block N out of M" BASMAZ; bu asamada gercek ciktiya
  # gore bant haritasi kullan (0.08 -> 0.50 araligi, "f2 okunuyor" asamasina kadar).
  if (grepl("extract_f2 calisiyor", stage, fixed = TRUE)) {
    ex <- parse_extract_progress(txt, total)
    if (!is.null(ex)) { inner <- 0.08 + 0.42 * ex$frac; fr <- if (length(tmark)) tfrac_base + tspan * inner else inner
      return(list(frac = min(1, fr), msg = paste0(tinfo, ex$msg), rcond = rc)) }
  }

  # extract_f2 blok ilerlemesi (varsa en guvenilir sinyal)
  # allsnps=TRUE'da asil is qpadm icindeki blok dongusudur -> qpadm tabani DUSUK olmali,
  # yoksa ibre once %75 gosterip blok satirlari gelince geri duser.
  allsnps_true <- any(grepl("^QPS_MODE TRUE", txt0))
  sfrac <- if (allsnps_true)
    c("f2 onbellegi kontrol ediliyor" = 0.02, "extract_f2 calisiyor" = 0.03,
      "f2 okunuyor (onceden hesaplanmis)" = 0.04, "qpadm calisiyor" = 0.05,
      "Sanal etiketler uygulaniyor" = 0.01)
  else
    c("f2 onbellegi kontrol ediliyor" = 0.05, "extract_f2 calisiyor" = 0.08,
      "f2 okunuyor (onceden hesaplanmis)" = 0.50, "qpadm calisiyor" = 0.60,
      "Sanal etiketler uygulaniyor" = 0.03)
  hits <- unlist(regmatches(txt, gregexpr("block\\s+[0-9]+\\s+out of", txt)))
  nums <- suppressWarnings(as.numeric(gsub("\\D", "", hits))); nums <- nums[is.finite(nums)]
  if (length(nums)) { cur <- max(nums); tot <- max(713, cur)
    stage_now <- ""; sm <- grep("^QPS_STAGE ", txt)
    if (length(sm)) stage_now <- sub("^QPS_STAGE ", "", txt[sm[length(sm)]])
    base <- 0.05
    if (nzchar(stage_now)) { kk <- names(sfrac)[vapply(names(sfrac), function(k) grepl(k, stage_now, fixed = TRUE), logical(1))]
      if (length(kk)) base <- sfrac[[kk[1]]] }
    inner <- base + (0.98 - base) * min(1, cur / tot)   # asamadan yukari dogru, geri gitmez
    fr <- if (length(tmark)) tfrac_base + tspan * inner else inner
    return(list(frac = min(1, fr), msg = sprintf("%sblock %d / ~%d", tinfo, cur, tot), rcond = rc, blk = cur, tot = tot)) }

  # Asamaya gore kaba yuzde (takilma hissini onler)
  if (nzchar(stage)) {
    key <- names(sfrac)[vapply(names(sfrac), function(k) grepl(k, stage, fixed = TRUE), logical(1))]
    base <- if (length(key)) sfrac[[key[1]]] else 0.5
    fr <- if (length(tmark)) tfrac_base + tspan * base else base
    sk <- c("f2 onbellegi kontrol ediliyor" = "stg_f2_check", "extract_f2 calisiyor" = "stg_extract",   # v6.1 ADIM 3
            "f2 okunuyor (onceden hesaplanmis)" = "stg_f2_read", "qpadm calisiyor" = "stg_qpadm",
            "sanal frekans tablosu kuruluyor" = "stg_xs_af")   # v6.4 test
    sk <- sk[vapply(names(sk), function(k) grepl(k, stage, fixed = TRUE), logical(1))]
    sm <- if (length(sk)) tr(sk[[1]]) else stage; if (!length(sm) || !nzchar(sm)) sm <- stage
    return(list(frac = min(0.98, fr), msg = paste0(tinfo, sm), rcond = rc))
  }
  if (any(grepl("block lengths", txt))) return(list(frac = max(0.05, tfrac_base), msg = paste0(tinfo, tr("prog_blocklen")), rcond = rc))
  if (any(grepl("Reading", txt)))      return(list(frac = max(0.03, tfrac_base), msg = paste0(tinfo, tr("prog_reading")), rcond = rc))
  list(frac = max(0.02, tfrac_base), msg = paste0(tinfo, tr("prog_working")), rcond = rc)
}

# --- Excel: her model AYRI sayfa (ozet + weights + right etiketleri + popdrop + sample ID listeleri)
write_qpadm_excel <- function(runs, file, labelmap) {
  wb  <- openxlsx::createWorkbook()
  hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#E9ECEF", border = "TopBottom")
  ttl <- openxlsx::createStyle(textDecoration = "bold", fontSize = 12)
  neg <- openxlsx::createStyle(fontColour = "#B00020", bgFill = "#FDE7E9"); used <- character(0)
  wtitle <- function(sheet, text, row) {
    openxlsx::writeData(wb, sheet, text, startCol = 1, startRow = row)
    openxlsx::addStyle(wb, sheet, ttl, rows = row, cols = 1)
  }
  for (nm in names(runs)) {
    r <- runs[[nm]]; res <- r$res; meta <- r$meta
    sheet <- substr(gsub("[^A-Za-z0-9_]+", "_", nm), 1, 31)
    if (sheet %in% used) sheet <- substr(paste0(sheet, "_", length(used)), 1, 31)
    used <- c(used, sheet); openxlsx::addWorksheet(wb, sheet)
    wtitle(sheet, "qpAdm -- model summary", 1)
    rcl <- r$rcond %||% character(0)
    sc <- snp_cols(r$snp); scs <- function(v) if (is.na(v)) "NA" else format(v, scientific = FALSE)
    metadf <- data.frame(Field = c("Target", "allsnps", "p-value", "dof", "chisq", "feasible", "maxmiss",
                                   "Used SNPs", "Used SNPs min", "Used SNPs max", "SNP basis", "Target SNPs", "Time", "rcond"),
      Value = c(if (is.null(meta$model)) meta$target else paste0(meta$target, " (", meta$model, ")"), meta$mode, fmt(meta$p), fmt(meta$dof), fmt(meta$chisq), as.character(meta$feasible), as.character(meta$maxmiss),
                scs(sc$Used_SNPs), scs(sc$Used_SNPs_min), scs(sc$Used_SNPs_max), if (is.na(sc$SNP_basis)) "NA" else sc$SNP_basis, scs(sc$Target_SNPs),
                meta$time, if (length(rcl)) sprintf("rcond / matrix warnings (%d)", length(rcl)) else "none"), stringsAsFactors = FALSE)
    metadf <- rbind(metadf, data.frame(Field = "admixtools", Value = paste0(qps_adx_str(), qps_adx_note()), stringsAsFactors = FALSE))   # v6.4 (madde 3)
    pm <- meta$pdm   # v6.3 test: on tanimli model notu
    if (!is.null(pm)) metadf <- rbind(metadf, data.frame(Field = c("Predefined model", "Model notes", "Reference"),
      Value = c(paste0(pm$model, if (nzchar(pm$file %||% "")) paste0(" (", pm$file, ")") else "", if (isTRUE(pm$edited)) " [edited]" else ""),
                paste(c(vapply(pm$iss %||% list(), pdm_issue_en, ""), pm$notes, if (isTRUE(pm$super)) "f2 pool built with a wider panel than requested", if ((pm$rules_n %||% 0) > 0) sprintf("%d sample(s) relabeled for this run", pm$rules_n),
                        if (isTRUE((pm$group_n %||% 1) > 1) && identical(meta$mode, "FALSE")) sprintf("shared f2 pool (%d models, %d pops)", pm$group_n, pm$pool_n %||% 0L)), collapse = "; "),
                pdm_ref_en(tryCatch(pdm_ref_compare(pm$ref, meta$target, meta$mode, meta$p, res$weights), error = function(e) NULL))), stringsAsFactors = FALSE))
    metadf <- metadf[!(metadf$Field == "Reference" & !nzchar(as.character(metadf$Value))), , drop = FALSE]   # v6.3 test2 (S3)
    openxlsx::writeData(wb, sheet, metadf, startRow = 2, startCol = 1, headerStyle = hdr)
    rr <- 2 + nrow(metadf) + 2
    w <- as.data.frame(res$weights)
    wtitle(sheet, "Weights (weight | se | z)", rr - 1)
    openxlsx::writeData(wb, sheet, w, startRow = rr, startCol = 1, headerStyle = hdr)
    if ("weight" %in% names(w) && nrow(w))
      openxlsx::conditionalFormatting(wb, sheet, cols = which(names(w) == "weight"), rows = (rr + 1):(rr + nrow(w)), rule = "<0", style = neg)
    rr <- rr + nrow(w) + 3
    wtitle(sheet, "Right set labels", rr - 1)
    openxlsx::writeData(wb, sheet, data.frame(Right = r$right), startRow = rr, startCol = 1, headerStyle = hdr)
    rr <- rr + length(r$right) + 3
    pd <- as.data.frame(res$popdrop)
    wtitle(sheet, "Nested models (popdrop)", rr - 1)
    openxlsx::writeData(wb, sheet, pd, startRow = rr, startCol = 1, headerStyle = hdr)
    if ("p" %in% names(pd) && nrow(pd))
      openxlsx::conditionalFormatting(wb, sheet, cols = which(names(pd) == "p"), rows = (rr + 1):(rr + nrow(pd)), rule = "<0.05", style = neg)
    rr <- rr + nrow(pd) + 3
    wtitle(sheet, "Right labels -> sample IDs", rr - 1)
    lmr <- r$labelmap %||% list(); lmr <- c(lmr, (labelmap %||% list())[setdiff(names(labelmap %||% list()), names(lmr))])   # v6.3 test2 (S2): kosunun (toplu kaydin) eslemesi; kayitta olmayan etiket oturumdan
    rt <- ids_table(lmr, r$right, missing = "(not in file)")
    openxlsx::writeData(wb, sheet, rt, startRow = rr, startCol = 1, headerStyle = hdr); rr <- rr + nrow(rt) + 2
    wtitle(sheet, "Left labels -> sample IDs", rr - 1)
    lt <- ids_table(lmr, r$left, missing = "(not in file)")
    openxlsx::writeData(wb, sheet, lt, startRow = rr, startCol = 1, headerStyle = hdr)
    rr <- rr + nrow(lt) + 3
    wtitle(sheet, "rcond / matrix warnings (from console)", rr - 1)
    rcdf <- data.frame(Warning = if (length(rcl)) rcl else "no warnings", stringsAsFactors = FALSE)
    openxlsx::writeData(wb, sheet, rcdf, startRow = rr, startCol = 1, headerStyle = hdr)
    # v6.3 test2 (S4): B sutunu etiket -> sample ID listelerine gore degil, sayfanin oteki hucrelerine gore; en fazla 60.
    # ID listeleri tek satirda kalir, sagdaki bos hucrelere tasar.
    nc <- max(ncol(pd), 4); bv <- c(as.character(metadf$Value), names(w)[2], if (ncol(w) >= 2) format(w[[2]]) else character(0), names(pd)[2], if (ncol(pd) >= 2) format(pd[[2]]) else character(0), "SampleIDs")
    bw <- min(60, max(10, nchar(bv[!is.na(bv)], type = "width")) + 2)
    openxlsx::setColWidths(wb, sheet, cols = 1:nc, widths = c("auto", bw, rep("auto", nc - 2)))
  }
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

# --- Toplu Excel: Summary / Weights / Popdrop (+ etiket-sample sayfasi)
# v6.2 (K9): kind = "seq" (sirali model) -> Summary / Weights / Popdrop'ta her satir bir model; agirliklar "kaynak: agirlik +- SE",
# nested modeller "-dusen kaynak(lar): p, feasible" metni.
write_batch_excel <- function(batch, right, left, labelmap, file, rcond_lines = character(0), kind = "batch") {
  seqm <- identical(kind, "seq")
  ok <- Filter(function(x) !is.null(x$res), batch)
  f4d <- function(v) formatC(as.numeric(v), format = "f", digits = 4)
  if (seqm) {
    weights_all <- if (length(ok)) do.call(rbind, lapply(ok, function(x) { w <- as.data.frame(x$res$weights)
      data.frame(model = x$model %||% "", target = x$target, weights = paste(sprintf("%s: %s \u00b1 %s", as.character(w$left), f4d(w$weight), f4d(w$se)), collapse = "; "), stringsAsFactors = FALSE) })) else data.frame()
    popdrop_all <- if (length(ok)) do.call(rbind, lapply(ok, function(x) { pd <- as.data.frame(x$res$popdrop); lf <- as.character(x$left %||% character(0))
      full <- grepl("^0+$", as.character(pd$pat))
      nest <- vapply(which(!full), function(i) { d <- lf[strsplit(as.character(pd$pat[i]), "")[[1]] == "1"]
        sprintf("-%s: p = %s, feasible = %s", paste(d, collapse = "/"), fmt(pd$p[i]), as.character(pd$feasible[i] %||% NA)) }, character(1))
      data.frame(model = x$model %||% "", target = x$target, p_full = if (any(full)) pd$p[full][1] else NA_real_,
                 feasible_full = if (any(full)) as.character(pd$feasible[full][1]) else NA_character_, nested = paste(nest, collapse = " | "), stringsAsFactors = FALSE) })) else data.frame()
  } else {
  weights_all <- if (length(ok)) do.call(rbind, lapply(ok, function(x) as.data.frame(x$res$weights))) else data.frame()
  popdrop_all <- if (length(ok)) do.call(rbind, lapply(ok, function(x) { pd <- as.data.frame(x$res$popdrop); pd$target <- x$target; pd })) else data.frame()
  }
  summary_all <- if (seqm) do.call(rbind, lapply(batch, function(x) {
    rcx <- x$rcond %||% character(0); rcs <- if (length(rcx)) paste(utils::head(rcx, 3), collapse = " | ") else "none"
    src <- paste(x$left %||% character(0), collapse = ", ")
    d <- if (is.null(x$res)) data.frame(model = x$model %||% "", target = x$target, left = src, p_full = NA_real_, chisq = NA_real_, dof = NA_real_, feasible = NA_character_,
                                        min_weight = NA_real_, max_z = NA_real_, status = "ERROR", rcond = rcs, stringsAsFactors = FALSE)
    else { w <- x$res$weights; data.frame(model = x$model %||% "", target = x$target, left = src, p_full = x$res$popdrop$p[1], chisq = as.numeric(x$chisq %||% NA),
      dof = as.numeric(x$dof %||% NA), feasible = as.character(x$feasible %||% NA), min_weight = min(w$weight), max_z = max(abs(w$z)), status = "OK", rcond = rcs, stringsAsFactors = FALSE) }
    cbind(d, snp_cols(x$snp)) })) else do.call(rbind, lapply(batch, function(x) {
    rcx <- x$rcond %||% character(0)
    rcs <- if (length(rcx)) paste(utils::head(rcx, 3), collapse = " | ") else "none"
    d <- if (is.null(x$res)) data.frame(target = x$target, p_full = NA, min_weight = NA, max_z = NA, status = "ERROR", rcond = rcs)
    else { w <- x$res$weights; data.frame(target = x$target, p_full = x$res$popdrop$p[1],
      min_weight = min(w$weight), max_z = max(abs(w$z)), status = "OK", rcond = rcs) }
    cbind(d, snp_cols(x$snp)) }))
  if (NROW(summary_all)) summary_all$admixtools <- qps_adx_str()   # v6.4 (madde 3)
  wb <- openxlsx::createWorkbook()
  openxlsx::addWorksheet(wb, "Summary"); openxlsx::writeData(wb, "Summary", summary_all)
  openxlsx::addWorksheet(wb, "Weights"); openxlsx::writeData(wb, "Weights", weights_all)
  openxlsx::addWorksheet(wb, "Popdrop"); openxlsx::writeData(wb, "Popdrop", popdrop_all)
  openxlsx::addWorksheet(wb, "RightLeft_Samples")
  ttl <- openxlsx::createStyle(textDecoration = "bold")
  openxlsx::writeData(wb, "RightLeft_Samples", "Right set labels", 1, 1); openxlsx::addStyle(wb, "RightLeft_Samples", ttl, 1, 1)
  openxlsx::writeData(wb, "RightLeft_Samples", data.frame(Right = right), startRow = 2, startCol = 1)
  r2 <- 2 + length(right) + 2
  openxlsx::writeData(wb, "RightLeft_Samples", "Right labels -> sample IDs", r2 - 1, 1); openxlsx::addStyle(wb, "RightLeft_Samples", ttl, r2 - 1, 1)
  rt <- ids_table(labelmap %||% list(), right, missing = "(not in file)"); openxlsx::writeData(wb, "RightLeft_Samples", rt, startRow = r2, startCol = 1)
  r3 <- r2 + nrow(rt) + 2
  openxlsx::writeData(wb, "RightLeft_Samples", "Left labels -> sample IDs", r3 - 1, 1); openxlsx::addStyle(wb, "RightLeft_Samples", ttl, r3 - 1, 1)
  lt <- ids_table(labelmap %||% list(), left, missing = "(not in file)"); openxlsx::writeData(wb, "RightLeft_Samples", lt, startRow = r3, startCol = 1)
  openxlsx::addWorksheet(wb, "rcond_Warnings")
  perr <- do.call(rbind, lapply(batch, function(x) { rcx <- x$rcond %||% character(0)
    if (!length(rcx)) return(NULL); data.frame(target = if (is.null(x$model)) x$target else paste(x$model, x$target), warning = rcx, stringsAsFactors = FALSE) }))
  allr <- if (length(rcond_lines)) data.frame(target = "(global console)", warning = rcond_lines, stringsAsFactors = FALSE) else NULL
  rcall <- rbind(perr, allr)
  openxlsx::writeData(wb, "rcond_Warnings", if (!is.null(rcall) && nrow(rcall)) rcall else data.frame(Info = "no warnings"))
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

# ---------------------------------------------------------------------------
# FST + ROTASYON YARDIMCILARI
# ---------------------------------------------------------------------------
# FST ilerleme: geno'dan blok blok hesaplar; block N -> pay/~713 (monoton).
parse_fst_progress <- function(txt) {
  if (!length(txt)) return(list(frac = 0, msg = tr("prog_starting")))
  hits <- unlist(regmatches(txt, gregexpr("block\\s+[0-9]+\\s+out of", txt)))
  nums <- suppressWarnings(as.numeric(gsub("\\D", "", hits))); nums <- nums[is.finite(nums)]
  if (length(nums)) { cur <- max(nums); tot <- max(713, cur)
    return(list(frac = min(1, cur / tot), msg = sprintf("block %d / ~%d", cur, tot))) }
  if (any(grepl("Reading", txt))) return(list(frac = 0, msg = tr("prog_reading")))
  list(frac = 0, msg = tr("prog_computing"))
}

# Rotasyon ilerleme: QPS_ROT k N -> k/N
parse_rot_progress <- function(txt, total = NULL) {
  if (!length(txt)) return(list(frac = 0, msg = tr("prog_starting")))
  tot <- NA; tm <- grep("^QPS_ROT_TOTAL ", txt)
  if (length(tm)) tot <- suppressWarnings(as.integer(strsplit(txt[tm[length(tm)]], " ")[[1]][2]))
  # v6.5 ADIM 2: tek genotip gecisi (allsnps=TRUE, ek setsiz) %3-90, ardindan model uyumlari %90-100
  pm <- grep("^QPS_PASS [0-9]+ ", txt)
  if (length(pm) && !any(grepl("^QPS_STAGE_ERR single pass", txt))) {   # gecis hata verdiyse eski yolun ilerlemesi
    pn <- suppressWarnings(as.integer(strsplit(txt[pm[1]], " ")[[1]][2])); if (!is.finite(pn)) pn <- 1L; rm <- grep("^QPS_ROT ", txt)
    if (!length(rm)) { seg <- txt[pm[1]:length(txt)]; hb <- regmatches(seg, regexpr("block\\s+[0-9]+\\s+out of\\s+[0-9]+", seg))
      if (length(hb)) { m <- hb[length(hb)]; cur <- suppressWarnings(as.numeric(sub("^block\\s+([0-9]+).*$", "\\1", m))); tot <- suppressWarnings(as.numeric(sub("^.*out of\\s+", "", m)))
        if (!is.finite(tot) || tot <= 0) tot <- max(713, cur)
        return(list(frac = min(0.90, 0.03 + 0.87 * min(1, cur / tot)), msg = sprintf(tr("prog_pass"), pn, cur, tot))) }
      return(list(frac = 0.02, msg = sprintf(tr("prog_pass_start"), pn))) }
    p <- strsplit(txt[rm[length(rm)]], " ")[[1]]; k <- suppressWarnings(as.integer(p[2])); n <- suppressWarnings(as.integer(p[3]))
    if (is.finite(k) && is.finite(n) && n > 0) return(list(frac = min(1, 0.90 + 0.10 * k / n), msg = paste0(tr("stg_fit"), " \u2014 ", sprintf(tr("prog_model_kn"), k, n), if (length(p) > 3) paste0(" \u2014 ", paste(p[-(1:3)], collapse = " ")) else "")))
  }
  # v5.8: f2 bu kosuda cikarildiysa cubugun ilk %25'i extract_f2'ye ayrilir.
  ex <- parse_extract_progress(txt, total)
  base <- if (is.null(ex)) 0 else 0.25
  rm <- grep("^QPS_ROT ", txt)
  if (length(rm)) { p <- strsplit(txt[rm[length(rm)]], " ")[[1]]
    k <- suppressWarnings(as.integer(p[2])); n <- suppressWarnings(as.integer(p[3]))
    if (is.finite(k) && is.finite(n) && n > 0) return(list(frac = min(1, base + (1 - base) * k / n), msg = paste0(sprintf(tr("prog_model_kn"), k, n), if (length(p) > 3) paste0(" \u2014 ", paste(p[-(1:3)], collapse = " ")) else ""))) }
  if (!is.null(ex)) return(list(frac = 0.25 * ex$frac, msg = ex$msg))
  if (is.finite(tot)) return(list(frac = 0, msg = sprintf(tr("prog_models_ready"), tot)))
  hits <- unlist(regmatches(txt, gregexpr("block\\s+[0-9]+\\s+out of", txt)))
  if (length(hits)) return(list(frac = 0, msg = tr("prog_f2_blocks")))
  list(frac = 0, msg = tr("prog_preparing"))
}

# FST sonucunu Excel'e yaz (tek sayfa: pop1 | pop2 | est | se)
write_fst_excel <- function(df, file, params = NULL) {
  wb <- openxlsx::createWorkbook(); openxlsx::addWorksheet(wb, "FST")
  hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#E9ECEF", border = "TopBottom")
  openxlsx::writeData(wb, "FST", df, headerStyle = hdr)
  openxlsx::setColWidths(wb, "FST", cols = 1:ncol(df), widths = "auto")
  # v6.0 (D9): tablonun hangi ayarlarla uretildigi (sabit Ingilizce)
  if (!is.null(params)) {
    openxlsx::addWorksheet(wb, "Parameters")
    pdf <- data.frame(Parameter = c("adjust_pseudohaploid", "auto_only", "maxmiss", "blgsize", "pop1", "pop2", "genotype_prefix", "run_time"),
      Value = c(as.character(isTRUE(params$adjph)), as.character(isTRUE(params$autoonly)), format(params$maxmiss %||% 0), format(params$blgsize %||% 0.05),
                paste(params$pop1, collapse = ", "), paste(params$pop2, collapse = ", "), params$prefix %||% "", params$time %||% ""), stringsAsFactors = FALSE)
    openxlsx::writeData(wb, "Parameters", pdf, headerStyle = hdr)
    openxlsx::setColWidths(wb, "Parameters", cols = 1:2, widths = "auto")
  }
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

# Rotasyon: geçerli + başarısız modelleri Excel'e (iki sayfa)
write_rot_excel <- function(valid, failed, file) {
  wb <- openxlsx::createWorkbook()
  hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#E9ECEF", border = "TopBottom")
  openxlsx::addWorksheet(wb, "Valid_models")
  openxlsx::writeData(wb, "Valid_models", if (nrow(valid)) valid else data.frame(Info = "no valid model"), headerStyle = hdr)
  openxlsx::addWorksheet(wb, "Failed")
  openxlsx::writeData(wb, "Failed", if (nrow(failed)) failed else data.frame(Info = "no record"), headerStyle = hdr)
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
}

# Rotasyon: geçerli + başarısız tek CSV (durum sütunlu)
write_rot_csv <- function(valid, failed, file) {
  a <- if (nrow(valid)) cbind(status = "valid", valid) else NULL
  bcols <- intersect(names(failed), c("model_index", "sources", "p_full", "proportions", "se_values", "p_min_nested", "fail_reason"))
  b <- if (nrow(failed)) cbind(status = "failed", failed[, bcols, drop = FALSE]) else NULL
  out <- if (!is.null(a) && !is.null(b)) dplyr_bind(a, b) else if (!is.null(a)) a else if (!is.null(b)) b else data.frame(Info = "no record")
  utils::write.csv(out, file, row.names = FALSE, fileEncoding = "UTF-8")
}
# rbind ile hizalama (farklı sütunları NA ile birleştirir)
dplyr_bind <- function(a, b) {
  allc <- union(names(a), names(b))
  for (c in setdiff(allc, names(a))) a[[c]] <- NA
  for (c in setdiff(allc, names(b))) b[[c]] <- NA
  rbind(a[allc], b[allc])
}

# Rotasyon akademik yığın-bar + istatistik tablosu (arkadaşın scripti uyarlaması)
make_rotation_plot <- function(valid, target, font_family = "Arial") {
  if (!requireNamespace("cowplot", quietly = TRUE))
    stop(tr("err_need_cowplot"))
  fam <- font_family
  if (.Platform$OS.type == "windows") { try({ grDevices::windowsFonts(rotfont = grDevices::windowsFont(font_family)); fam <- "rotfont" }, silent = TRUE) }
  n_models <- nrow(valid)
  vv <- valid; vv$Model_Name <- factor(paste0("Model ", vv$model_index), levels = rev(paste0("Model ", vv$model_index)))
  rows <- lapply(seq_len(nrow(vv)), function(i) {
    src <- trimws(strsplit(vv$sources[i], "\\+")[[1]])
    prp <- suppressWarnings(as.numeric(gsub("%", "", strsplit(vv$proportions[i], "\\+")[[1]])))
    data.frame(Model_Name = vv$Model_Name[i], Source = src, Proportion = prp, stringsAsFactors = FALSE)
  })
  pd <- do.call(rbind, rows)
  pops <- unique(pd$Source); cols <- scales::hue_pal()(length(pops)); names(cols) <- pops
  bar_w <- max(0.45, min(0.70, 0.70 - 0.03 * n_models)); fsz <- max(3.0, min(4.0, 4.0 - 0.12 * n_models))
  p_bar <- ggplot(pd, aes(x = Proportion, y = Model_Name, fill = Source)) +
    geom_vline(xintercept = c(25, 50, 75), color = "grey85", linewidth = 0.4) +
    geom_bar(stat = "identity", color = "white", linewidth = 0.5, width = bar_w) +
    geom_text(data = pd[pd$Proportion > 5, , drop = FALSE], aes(label = paste0(Proportion, "%")),
              position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = fsz, family = fam) +
    scale_fill_manual(values = cols) +
    scale_x_continuous(limits = c(0, 100), expand = c(0, 0), breaks = c(0, 25, 50, 75, 100), labels = c("0%", "25%", "50%", "75%", "100%")) +
    labs(x = "Admixture Proportion (%)", y = NULL, fill = "Source Population",
         title = paste0("qpAdm Rotation Models \u2014 ", target),
         subtitle = "Models passing Flegontova et al. (2025) criteria  |  p \u2265 threshold  \u2022  EAF \u2208 (0,1)  \u2022  all nested rejected") +
    theme_classic(base_family = fam, base_size = 11) +
    theme(plot.title = element_text(face = "bold", size = 13, color = "#1a1a2e", margin = margin(b = 4)),
          plot.subtitle = element_text(size = 8.5, color = "#555577", margin = margin(b = 14)),
          axis.text.y = element_text(face = "bold", size = 9.5, color = "#1a1a2e"),
          axis.text.x = element_text(size = 8.5, color = "#444444"),
          panel.grid = element_blank(), panel.background = element_rect(fill = "#fafafa", color = NA),
          plot.background = element_rect(fill = "white", color = NA),
          legend.position = "bottom", legend.direction = "vertical",
          legend.title = element_text(face = "bold", size = 8.5), legend.text = element_text(size = 8)) +
    guides(fill = guide_legend(ncol = 1))
  td <- vv; td$se_fmt <- paste0("\u00b1", td$se_values); td$p_full_fmt <- sprintf("%.4f", td$p_full)
  td$p_min_fmt <- formatC(td$p_min_nested, format = "e", digits = 2)
  p_tab <- ggplot(td, aes(y = Model_Name)) +
    geom_text(aes(x = 1, label = se_fmt), hjust = 0, size = 3.2, family = fam, color = "#333333") +
    geom_text(aes(x = 3, label = p_full_fmt), hjust = 0.5, size = 3.2, family = fam, color = "#333333") +
    geom_text(aes(x = 4.2, label = p_min_fmt), hjust = 0, size = 3.2, family = fam, color = "#333333") +
    annotate("text", x = 1, y = n_models + 0.9, label = "SE", fontface = "bold", hjust = 0, size = 3.4, family = fam, color = "#1a1a2e") +
    annotate("text", x = 3, y = n_models + 0.9, label = "p (full)", fontface = "bold", hjust = 0.5, size = 3.4, family = fam, color = "#1a1a2e") +
    annotate("text", x = 4.2, y = n_models + 0.9, label = "p (nested min)", fontface = "bold", hjust = 0, size = 3.4, family = fam, color = "#1a1a2e") +
    scale_x_continuous(limits = c(0.9, 5.2)) + theme_void() +
    theme(plot.background = element_rect(fill = "white", color = NA))
  cowplot::plot_grid(p_bar, p_tab, rel_widths = c(3.2, 1), align = "h", axis = "tb")
}

# ---------------------------------------------------------------------------
# SANAL .fam / .ind DUZENLEYICI (VIRTUAL LABELS)
# ---------------------------------------------------------------------------
# Mantik: orijinal dosyalara ASLA dokunulmaz. Gecici bir klasorde YENI bir
# etiket dosyasi (.fam veya .ind) yazilir; buyuk genotip dosyalari (.bed/.bim
# veya .geno/.snp) KOPYALANMAZ, hard link ile baglanir (link olmazsa kopyalanir).
# Sonuc: qpadm()/fst() gercekten sanal etiketleri gorur; disk maliyeti ~0.

# v5.9: SIRADAN BAGIMSIZ. Eskiden data.frame satir adlariyla birlikte ozetleniyordu;
# satir adlari kuralin EKLENME sirasini tasidigi icin ayni sanal set (orn. once elle
# kural sonra harici dosya / tersi; disa aktarilip yeniden yuklenen dosya) farkli
# ozet -> yeni vfam klasoru ve FARKLI f2 havuz anahtari uretiyordu.
vfam_hash <- function(vfam) if (is.null(vfam) || !nrow(vfam)) "" else {
  o <- order(vfam$SampleID, vfam$VirtualLabel)
  digest::digest(paste(as.character(vfam$SampleID[o]), as.character(vfam$VirtualLabel[o]), sep = "\t"), algo = "xxhash64") }

# Genotip setinin turunu ve dosyalarini bul
geno_fileset <- function(prefix) {
  plink <- c(bed = paste0(prefix, ".bed"), bim = paste0(prefix, ".bim"), fam = paste0(prefix, ".fam"))
  eig   <- c(geno = paste0(prefix, ".geno"), snp = paste0(prefix, ".snp"), ind = paste0(prefix, ".ind"))
  if (all(file.exists(plink))) return(list(type = "plink", files = plink, labfile = plink[["fam"]]))
  if (all(file.exists(eig)))   return(list(type = "eigenstrat", files = eig, labfile = eig[["ind"]]))
  NULL
}

# v6.3 test2 (S5): AADR v66 .geno dosyalari TGENO (birey basina kayit) bicimindedir; admixtools onu paketli GENO sanip
# hatasiz ama yanlis okur. Ayni onekle PLINK seti varsa geno_fileset onu sectigi icin denetim yapilmaz.
geno_is_tgeno <- function(prefix) {
  fs <- geno_fileset(prefix); if (is.null(fs) || !identical(fs$type, "eigenstrat")) return(FALSE)
  h <- tryCatch(readBin(fs$files[["geno"]], "raw", 5L), error = function(e) raw(0))
  length(h) == 5L && identical(rawToChar(h), "TGENO")
}

# Buyuk genotip dosyalari ASLA KOPYALANMAZ.
# Sira: hard link -> sembolik link -> (izin verilmisse) kopya -> hata.
# Kopyalama VARSAYILAN OLARAK KAPALIDIR: 12 GB'lik .bed dosyalarinin sessizce
# cogaltilmasi diski doldurur. Kullanici bilerek acmadikca kopya olusturulmaz.
link_only <- function(from, to, allow_copy = FALSE) {
  if (file.exists(to)) return("mevcut")
  if (isTRUE(suppressWarnings(tryCatch(file.link(from, to), error = function(e) FALSE)))) return("hardlink")
  if (isTRUE(suppressWarnings(tryCatch(file.symlink(from, to), error = function(e) FALSE)))) return("symlink")
  if (isTRUE(allow_copy)) {
    if (isTRUE(suppressWarnings(tryCatch(file.copy(from, to), error = function(e) FALSE)))) return("kopya")
  }
  ""
}

# Sanal etiket klasoru icin EN IYI konumu sec: genotip dosyasiyla AYNI klasor
# (ayni disk bolumu = hard link calisir). Yazilamiyorsa f2cache'e duser.
vfam_base_dir <- function(prefix, fallback) {
  yan <- file.path(dirname(prefix), ".qpadm_vfam")
  ok <- tryCatch({ dir.create(yan, showWarnings = FALSE, recursive = TRUE); dir.exists(yan) }, error = function(e) FALSE)
  if (isTRUE(ok)) {
    t <- file.path(yan, ".yazma_testi"); yz <- tryCatch({ writeLines("x", t); file.remove(t); TRUE }, error = function(e) FALSE)
    if (isTRUE(yz)) return(yan)
  }
  file.path(fallback, "vfam")
}

# Klasor boyutu (GB) -- onbellek temizligi icin
dir_size_gb <- function(path) {
  if (!dir.exists(path)) return(0)
  f <- list.files(path, recursive = TRUE, full.names = TRUE, all.files = TRUE, no.. = TRUE)
  if (!length(f)) return(0)
  # Hard link/symlink olanlar diskte YER KAPLAMAZ ama file.size yine de gosterir;
  # kullaniciya gercek durumu ayirt edebilmesi icin ayrica link sayisi veriyoruz.
  round(sum(file.size(f), na.rm = TRUE) / 1024^3, 2)
}

# vfam: data.frame(SampleID, VirtualLabel). Yeni prefix dondurur (veya orijinali).
build_vfam_prefix <- function(prefix, vfam, base_dir, allow_copy = FALSE) {
  if (is.null(vfam) || !nrow(vfam)) return(prefix)
  fs <- geno_fileset(prefix)
  if (is.null(fs)) stop(tr("err_geno_missing"))
  # v5.9: klasor adi kurallarin ozeti + setin etiket dosyasi parmak izi. Set .fam'i
  # degisirse eski klasordeki data.fam (eski etiketlerle kurulmus) yeniden kullanilmaz.
  h <- digest::digest(paste0(vfam_hash(vfam), "#", labfile_fp(prefix)), algo = "xxhash64")
  dir <- file.path(base_dir, paste0("vfam_", h)); dir.create(dir, showWarnings = FALSE, recursive = TRUE)
  newpref <- file.path(dir, "data")
  done <- file.path(dir, ".vfam_done")
  if (file.exists(done)) return(newpref)

  buyuk <- if (fs$type == "plink") c("bed", "bim") else c("geno", "snp")
  yontem <- character(0)
  for (e in buyuk) {
    r <- link_only(fs$files[[e]], paste0(newpref, ".", e), allow_copy = allow_copy)
    if (!nzchar(r)) {
      unlink(dir, recursive = TRUE)   # yarim kalan klasoru birak
      stop(paste0(sprintf(tr("err_vfam_link"), e), "\n\n", sprintf(tr("err_link_src_dst"), fs$files[[e]], dir)))
    }
    yontem <- c(yontem, r)
  }

  if (fs$type == "plink") {
    fam <- utils::read.table(fs$files[["fam"]], header = FALSE, stringsAsFactors = FALSE,
                             fill = TRUE, comment.char = "", quote = "", check.names = FALSE)
    idx <- match(trimws(as.character(fam[[2]])), vfam$SampleID); hit <- !is.na(idx)
    if (any(hit)) fam[[1]][hit] <- vfam$VirtualLabel[idx[hit]]
    utils::write.table(fam, paste0(newpref, ".fam"), quote = FALSE, row.names = FALSE, col.names = FALSE)
  } else {
    ind <- utils::read.table(fs$files[["ind"]], header = FALSE, stringsAsFactors = FALSE,
                             fill = TRUE, comment.char = "", quote = "", check.names = FALSE)
    idx <- match(trimws(as.character(ind[[1]])), vfam$SampleID); hit <- !is.na(idx)
    if (any(hit)) ind[[ncol(ind)]][hit] <- vfam$VirtualLabel[idx[hit]]
    utils::write.table(ind, paste0(newpref, ".ind"), quote = FALSE, row.names = FALSE, col.names = FALSE)
  }
  writeLines(c(format(Sys.time()), paste("yontem:", paste(unique(yontem), collapse = ", "))), done)
  attr(newpref, "yontem") <- paste(unique(yontem), collapse = ", ")
  newpref
}

# Sanal etiketler uygulandiktan sonraki etiket listesi (dosya okumadan, bellekte)
vfam_apply_labels <- function(labelmap, vfam) {
  if (is.null(vfam) || !nrow(vfam)) return(labelmap)
  m <- labelmap
  # once bireyleri eski gruplarindan cikar
  m <- lapply(m, function(ids) setdiff(ids, vfam$SampleID))
  m <- m[lengths(m) > 0]
  # sonra sanal gruplara ekle
  for (g in unique(vfam$VirtualLabel)) m[[g]] <- unique(c(m[[g]], vfam$SampleID[vfam$VirtualLabel == g]))
  m
}


# ---------------------------------------------------------------------------
# v5.9: SANAL ETIKET DISA AKTARIMI -- saf yardimcilar (shiny gerekmez)
# ---------------------------------------------------------------------------
# Cinsiyet/fenotip kaynagi: genotip setinin etiket dosyasi (.fam/.ind; sanal .fam de bundan kuruluyor).
# v6.2 (K8): ayri etiket kaynagi yok; labfile = setin kendi dosyasi (set yoksa NULL).
# .anno ve iki sutunlu .txt bu bilgiyi tasimaz -> NULL.
vfx_sex_source <- function(prefix, labfile) {
  if (!is.null(prefix)) { fs <- geno_fileset(prefix); if (!is.null(fs)) return(unname(fs$labfile)) }
  if (!is.null(labfile) && tolower(tools::file_ext(labfile)) %in% c("fam", "ind") && file.exists(labfile)) return(labfile)
  NULL
}

# Kaynaktan sample ID -> cinsiyet/fenotip tablosu.
#   .fam: FID IID PID MID SEX PHENO -> has_sex + has_pheno (ham degerler KORUNUR)
#   .ind: ID SEX LABEL              -> yalnizca has_sex
vfx_read_source <- function(path) {
  if (is.null(path) || !file.exists(path)) return(NULL)
  ext <- tolower(tools::file_ext(path))
  df <- utils::read.table(path, header = FALSE, stringsAsFactors = FALSE, fill = TRUE, comment.char = "", quote = "", check.names = FALSE, colClasses = "character")
  if (ext == "fam" && ncol(df) >= 5) {
    sx <- trimws(df[[5]])
    return(list(type = "fam", path = path, has_sex = TRUE, has_pheno = ncol(df) >= 6,
      df = data.frame(SampleID = trimws(df[[2]]), PID = trimws(df[[3]]), MID = trimws(df[[4]]), SexFam = sx,
        SexInd = ifelse(sx == "1", "M", ifelse(sx == "2", "F", "U")), Pheno = if (ncol(df) >= 6) trimws(df[[6]]) else "-9", stringsAsFactors = FALSE)))
  }
  if (ext == "ind" && ncol(df) >= 3) {
    sx <- toupper(trimws(df[[2]])); sx[!sx %in% c("M", "F")] <- "U"
    return(list(type = "ind", path = path, has_sex = TRUE, has_pheno = FALSE,
      df = data.frame(SampleID = trimws(df[[1]]), PID = "0", MID = "0", SexFam = ifelse(sx == "M", "1", ifelse(sx == "F", "2", "0")),
        SexInd = sx, Pheno = "-9", stringsAsFactors = FALSE)))
  }
  NULL
}

# Secilebilir bicimler: txt her zaman; ind cinsiyet varsa; fam cinsiyet + fenotip varsa.
vfx_formats <- function(st) c("txt", if (isTRUE(st$has_sex) && isTRUE(st$has_pheno)) "fam", if (isTRUE(st$has_sex)) "ind")

# Disa aktarilacak satirlar. labs: secilen sanal etiketler (sira korunur);
# etiket icinde kaynak dosyadaki birey sirasi. found = kaynakta bulundu mu.
vfx_build <- function(vfam, labs, st = NULL) {
  if (is.null(vfam) || !nrow(vfam) || !length(labs)) return(NULL)
  d <- vfam[vfam$VirtualLabel %in% labs, c("SampleID", "VirtualLabel"), drop = FALSE]
  d <- d[!duplicated(d$SampleID), , drop = FALSE]
  if (!nrow(d)) return(NULL)
  ref <- if (is.null(st)) data.frame(SampleID = character(0), PID = character(0), MID = character(0), SexFam = character(0), SexInd = character(0), Pheno = character(0), stringsAsFactors = FALSE) else st$df
  i <- match(d$SampleID, ref$SampleID); f <- !is.na(i)
  pick <- function(col, miss) { v <- rep(miss, length(i)); v[f] <- ref[[col]][i[f]]; v[is.na(v) | !nzchar(v)] <- miss; v }
  out <- data.frame(SampleID = d$SampleID, Label = d$VirtualLabel, PID = pick("PID", "0"), MID = pick("MID", "0"),
    SexFam = pick("SexFam", "0"), SexInd = pick("SexInd", "U"), Pheno = pick("Pheno", "-9"), found = f,
    HasSex = f & isTRUE(st$has_sex), HasPheno = f & isTRUE(st$has_pheno), stringsAsFactors = FALSE)
  out <- out[order(match(out$Label, labs), ifelse(f, i, .Machine$integer.max)), , drop = FALSE]
  rownames(out) <- NULL
  out
}

# Karar 11 (birey duzeyi): secili bireylerden BIRINDE bile bilgi yoksa o bicim
# KAPANIR; eksik koduyla (0/-9/U) doldurulmaz. x NULL ise dosya duzeyi kapi.
vfx_allowed <- function(x, st = NULL) {
  if (is.null(x) || !nrow(x)) return(vfx_formats(st))
  c("txt", if (all(x$HasSex & x$HasPheno)) "fam", if (all(x$HasSex)) "ind")
}

# Satirlar. txt: SampleID<TAB>Label (baslik yok; read_external_labels ID sutununu
# bilinen ID'lerle eslesmeye bakarak kendisi bulur). fam: PLINK bosluk ayracli.
# ind: EIGENSTRAT bosluk ayracli (ID SEX LABEL).
vfx_lines <- function(x, fmt) switch(fmt,
    txt = paste(x$SampleID, x$Label, sep = "\t"),
    fam = paste(x$Label, x$SampleID, x$PID, x$MID, x$SexFam, x$Pheno),
    ind = sprintf("%-20s %s %s", x$SampleID, x$SexInd, x$Label),
    stop("vfx_lines: bilinmeyen bicim ", fmt))
vfx_write <- function(x, fmt, file) { ln <- vfx_lines(x, fmt); writeLines(ln, file); invisible(length(ln)) }

# v6.2 (K7): Gelismis duzenleyicide "Secilenleri kaydet". cur = adv_cur() (SampleID, Guncel; sol liste sirasi),
# sel = secili ID'ler, src = kaynak satirlari (SampleID, PID, MID, SexFam, SexInd, Pheno, HasSex, HasPheno; ilk eslesme).
# Cikti vfx_lines ile ayni sutunlar; vfx_allowed bicim kapisi (bir bireyde bile bilgi yoksa .fam/.ind kapanir).
adv_sel_rows <- function(cur, sel, src = NULL) {
  if (is.null(cur) || !nrow(cur) || !length(sel)) return(NULL)
  d <- cur[cur$SampleID %in% sel & !duplicated(cur$SampleID), c("SampleID", "Guncel"), drop = FALSE]
  if (!nrow(d)) return(NULL)
  if (is.null(src) || !nrow(src)) src <- data.frame(SampleID = character(0), PID = character(0), MID = character(0), SexFam = character(0),
    SexInd = character(0), Pheno = character(0), HasSex = logical(0), HasPheno = logical(0), stringsAsFactors = FALSE)
  i <- match(d$SampleID, src$SampleID); f <- !is.na(i)
  pick <- function(col, miss) { v <- rep(miss, nrow(d)); v[f] <- src[[col]][i[f]]; v[is.na(v) | !nzchar(v)] <- miss; v }
  flag <- function(col) { v <- rep(FALSE, nrow(d)); v[f] <- as.logical(src[[col]][i[f]]); v & !is.na(v) }
  data.frame(SampleID = d$SampleID, Label = d$Guncel, PID = pick("PID", "0"), MID = pick("MID", "0"), SexFam = pick("SexFam", "0"),
    SexInd = pick("SexInd", "U"), Pheno = pick("Pheno", "-9"), found = f, HasSex = flag("HasSex"), HasPheno = flag("HasPheno"), stringsAsFactors = FALSE)
}
# Kaynak satirlari: verilen .fam/.ind dosyalari ONCELIK sirasiyla; ayni ID'de ilk dosya gecer.
adv_sel_source <- function(paths) {
  out <- NULL
  for (p in paths) { s <- tryCatch(vfx_read_source(p), error = function(e) NULL); if (is.null(s)) next
    d <- s$df; d$HasSex <- isTRUE(s$has_sex); d$HasPheno <- isTRUE(s$has_pheno)
    out <- if (is.null(out)) d else rbind(out, d[!d$SampleID %in% out$SampleID, , drop = FALSE]) }
  if (!is.null(out)) out <- out[!duplicated(out$SampleID), , drop = FALSE]
  out
}
# Dosya adi: bossa varsayilan; uzanti (fam/ind/txt) atilir, diske yazilamayan karakterler "_" olur, bicim uzantisi eklenir.
adv_sel_fname <- function(name, def, fmt) {
  x <- trimws(as.character(name %||% "")); if (!nzchar(x)) x <- def
  x <- sub("\\.(fam|ind|txt)$", "", x, ignore.case = TRUE); x <- gsub("[\\\\/:*?\"<>|]+", "_", x); x <- sub("[. ]+$", "", x)
  if (!nzchar(x)) x <- "selected"
  paste0(x, ".", fmt)
}

vfx_filename <- function(prefix, fmt, now = Sys.time())
  sprintf("%s_virtual_labels_%s.%s", if (is.null(prefix)) "qpadm" else basename(prefix), format(now, "%Y%m%d_%H%M%S"), fmt)

# ---------------------------------------------------------------------------
# v5.9 ADIM 1: ETIKET ADI KURALI, PARMAK IZI, GUVENLI YAZIM
# ---------------------------------------------------------------------------
# admixtools havuzu <havuz>/<pop1>/<pop2>_f2.rds olarak yazar; klasoru
# dir.create ile OZYINELEMESIZ acar. '/' ya da '\' iceren bir pop adi yolu
# boler ve havuz kurulumu dosya yazma hatasiyla duser. Windows'ta : * ? " < > |
# dosya adinda gecersiz, sonda nokta/bosluk kirpilir.
LABEL_BAD_SHOW <- "\\ / : * ? \" < > |"
label_bad <- function(x) { x <- as.character(x); !nzchar(x) | grepl("[[:space:]\\\\/:*?\"<>|]", x) | grepl("[. ]$", x) }
label_fix <- function(x) { y <- gsub("[[:space:]\\\\/:*?\"<>|]+", "_", as.character(x)); y <- sub("[. ]+$", "", y); y[!nzchar(y)] <- "X"; y }
# Onerilen adlar baska bir etiketle CAKISMASIN (sessiz grup birlesmesi olmasin).
label_fix_unique <- function(bad, taken) {
  out <- character(length(bad))
  for (i in seq_along(bad)) { b <- label_fix(bad[i]); s <- b; k <- 2L
    while (s %in% taken) { s <- paste0(b, "_", k); k <- k + 1L }
    out[i] <- s; taken <- c(taken, s) }
  stats::setNames(out, bad)
}

QPS_VERSION <- "qpAdm Studio v6.5"
# v6.4 (madde 3): kurulu admixtools'un surumu ve commit'i (remotes::install_github RemoteSha yazar). Sonuclar 2f6957a ile
# dogrulandi (olcumler M0-M4); baska commit'te ciktilara tek satir not.
QPS_ADX_REF <- "2f6957a"
QPS_ADX <- local({ d <- tryCatch(suppressWarnings(utils::packageDescription("admixtools")), error = function(e) NULL)
  v <- if (is.list(d) && !is.null(d$Version)) as.character(d$Version) else NA_character_
  sh <- if (is.list(d)) as.character(d$RemoteSha %||% d$GithubSHA1 %||% NA_character_) else NA_character_
  list(version = v, sha = sh, ok = isTRUE(startsWith(sh %||% "", QPS_ADX_REF))) })
qps_adx_str <- function(a = QPS_ADX) sprintf("%s (commit %s)", a$version %||% "not installed", if (is.na(a$sha %||% NA)) "unknown" else substr(a$sha, 1, 7))
# v6.4 ADIM 3: port secimi ve calisan kopyanin bulunmasi
QPS_PORT_PREF <- 7654L; QPS_PORT_RANGE <- 7654:7699; QPS_GRACE <- 10
qps_port_path <- function() file.path(getwd(), "qps_port.txt")
qps_port_busy <- function(port) { s <- tryCatch(suppressWarnings(socketConnection("127.0.0.1", port = port, open = "r+", blocking = TRUE, timeout = 1)), error = function(e) NULL); if (is.null(s)) return(FALSE); close(s); TRUE }
qps_http_is_qps <- function(port, timeout = 2) { op <- options(timeout = timeout); on.exit(options(op), add = TRUE)
  x <- tryCatch({ con <- url(sprintf("http://127.0.0.1:%d/", as.integer(port))); on.exit(try(close(con), silent = TRUE), add = TRUE); suppressWarnings(readLines(con, n = 400L, warn = FALSE)) }, error = function(e) character(0))
  any(grepl("name=\"qps-app\"", x, fixed = TRUE)) }
qps_port_read <- function(f = qps_port_path()) { if (!file.exists(f)) return(NA_integer_); x <- tryCatch(readLines(f, n = 1L, warn = FALSE), error = function(e) ""); suppressWarnings(as.integer(strsplit(x %||% "", "\t", fixed = TRUE)[[1]][1])) }
# Calisan qpAdm Studio'nun portu (yan dosya ya da tercih edilen port; HTTP isaretiyle dogrulanir) ya da NA.
qps_running_port <- function(pref = QPS_PORT_PREF) { for (p in unique(stats::na.omit(c(qps_port_read(), pref)))) if (qps_port_busy(p) && qps_http_is_qps(p)) return(as.integer(p)); NA_integer_ }
qps_pick_port <- function(pref = suppressWarnings(as.integer(Sys.getenv("QPS_PORT", as.character(QPS_PORT_PREF))))) {
  if (is.na(pref)) pref <- QPS_PORT_PREF
  r <- qps_running_port(pref)
  # bagimsiz inceleme 3: calisan kopyanin portu DONDURULMEZ (runApp "address already in use" ile duser, onStop da port
  # dosyasini silerdi). .bat calisan kopyayi kendisi bulur; buraya RStudio'dan acik runApp ile gelinir -> ikinci kopya bos portta.
  for (p in unique(c(pref, QPS_PORT_RANGE))) if (!qps_port_busy(p)) {
    if (!is.na(r)) message(sprintf("qpAdm Studio is already running: http://127.0.0.1:%d -- this copy uses port %d", r, p))
    else if (p != pref) message(sprintf("port %d is used by another program; qpAdm Studio uses port %d", pref, p))
    return(as.integer(p)) }
  pref }
# Port dosyasi yalniz onu yazan surecce silinir (2. sutun PID; bagimsiz inceleme 3).
qps_port_unlink <- function(f = qps_port_path()) { if (!file.exists(f)) return(invisible()); x <- tryCatch(strsplit(readLines(f, n = 1L, warn = FALSE), "\t", fixed = TRUE)[[1]], error = function(e) character(0))
  if (length(x) >= 2L && identical(suppressWarnings(as.integer(x[2])), as.integer(Sys.getpid()))) try(unlink(f), silent = TRUE); invisible() }
# Kapanis: programin KENDI isleri -- kayit defterindeki surecler (QPS_PROCS): callr isleri ("job") ve PowerShell pencereleri
# / pano ("aux") -- agaclariyla oldurulur, sonra stopApp. Isletim sisteminin surec tablosu TARANMAZ: v6.4'un ilk teslimi ps
# ile tariyordu; Windows'ta ps_children -> ps_ppid_map her surec icin ayri CreateToolhelp32Snapshot alir (O(N^2)), 2 sn'de
# bir calisan "is suruyor" denetimiyle R ana is parcacigi kilitlendi: sayfa dolmadi, "Programi kapat" islenmedi (saha,
# 2026-11-09). Bagimsiz inceleme 1 (tarayici R'in alt sureci olabilir) de boylece cozulur: yalniz programin baslattigi
# surecler. kind = "job": yalniz isler (onay / sekme uyarisi). Sinamada durdurmaz.
QPS_LIFE <- new.env(); QPS_LIFE$n <- 0L; QPS_LIFE$gen <- 0L; QPS_LIFE$test <- FALSE; QPS_LIFE$stopped <- FALSE
QPS_PROCS <- new.env(); QPS_PROCS$l <- list()
qps_alive <- function(p) isTRUE(tryCatch(p$is_alive(), error = function(e) FALSE))
qps_reg <- function(p, kind = "job") { if (inherits(p, "process")) QPS_PROCS$l <- c(Filter(function(x) qps_alive(x$p), QPS_PROCS$l), list(list(p = p, kind = kind))); p }
qps_r_bg <- function(...) qps_reg(callr::r_bg(...))   # programin butun arka plan islerini baslatan tek yer
qps_children <- function(kind = c("job", "all")) { kind <- match.arg(kind)
  lapply(Filter(function(x) (kind == "all" || identical(x$kind, "job")) && qps_alive(x$p), QPS_PROCS$l), function(x) x$p) }
qps_kill_tree <- function(p) { if (inherits(tryCatch(p$kill_tree(), error = function(e) e), "error")) try(p$kill(), silent = TRUE); invisible() }
qps_stop_all <- function() { for (p in qps_children("all")) qps_kill_tree(p); qps_port_unlink()
  QPS_LIFE$stopped <- TRUE; if (isTRUE(QPS_LIFE$test)) return(invisible(FALSE)); try(shiny::stopApp(), silent = TRUE); invisible(TRUE) }
qps_autostop <- function() identical(Sys.getenv("QPS_LAUNCHER"), "bat")
qps_adx_note <- function(a = QPS_ADX) if (isTRUE(a$ok)) "" else sprintf("  [note: qpAdm Studio results were validated with admixtools commit %s]", QPS_ADX_REF)
