pdm_starter_label <- function() paste(vapply(PDM_STARTER, function(p) if (nzchar(p$dataset)) sprintf("%s (%s)", p$name, p$dataset) else p$name, ""), collapse = ", ")
PDM_FMT  <- 1L
PDM_ROLES <- c("target", "left", "right")
pdm_unq <- function(x) { x <- trimws(x); q <- nchar(x) >= 2 & substr(x, 1, 1) == "\"" & substr(x, nchar(x), nchar(x)) == "\""; x[q] <- gsub("\"\"", "\"", substr(x[q], 2, nchar(x[q]) - 1)); trimws(x) }
pdm_split <- function(line, sep) pdm_unq(strsplit(line, sep, fixed = TRUE)[[1]])
pdm_sep <- function(lines) {
  h <- lines[grepl("^\\s*\"?model\"?\\s*[\t;,]", lines, ignore.case = TRUE)][1]
  probe <- if (!is.na(h)) h else paste(lines, collapse = "\n")
  if (grepl("\t", probe, fixed = TRUE)) "\t" else if (grepl(";", probe, fixed = TRUE)) ";" else if (grepl(",", probe, fixed = TRUE)) "," else "\t"
}
pdm_bool3 <- function(x) { x <- toupper(trimws(as.character(x %||% ""))); if (x %in% c("TRUE", "T", "1", "YES", "EVET")) "TRUE" else if (x %in% c("FALSE", "F", "0", "NO", "HAYIR")) "FALSE" else if (x %in% c("BOTH", "IKISI", "\u0130K\u0130S\u0130", "TRUE/FALSE", "TRUE,FALSE", "TRUE;FALSE")) "BOTH" else NA_character_ }
pdm_num <- function(x) { v <- suppressWarnings(as.numeric(gsub(",", ".", trimws(as.character(x)), fixed = TRUE))); if (length(v) && is.finite(v[1])) v[1] else NA_real_ }
pdm_empty_pops <- function() data.frame(role = character(0), label = character(0), sample_id = character(0), master_id = character(0), stringsAsFactors = FALSE)
pdm_empty_ref <- function() data.frame(target = character(0), allsnps = character(0), key = character(0), value = character(0), se = character(0), stringsAsFactors = FALSE)
pdm_new_model <- function(name, pops = pdm_empty_pops(), allsnps = NA_character_, params = list(), ref = pdm_empty_ref(), src = "", note = "") {
  list(name = as.character(name), pops = pops, allsnps = allsnps, params = params, ref = ref, src = as.character(src), note = as.character(note))
}
pdm_new_coll <- function() list(meta = list(name = "", dataset = "", author = "", description = ""), models = list())

# Baslik takma adlari (Excel / baska programlardan gelen sutun adlari); bilinmeyen sutun oldugu gibi kalir (yok sayilir).
pdm_hdr_alias <- function(f) { h <- gsub("[^a-z0-9]", "", tolower(trimws(f)))
  m <- c(model = "model", modelname = "model", modelid = "model", role = "role", rol = "role", label = "label", group = "label", groupid = "label", pop = "label", population = "label", etiket = "label",
         sampleid = "sample_id", sample = "sample_id", iid = "sample_id", geneticid = "sample_id", id = "sample_id", ornekid = "sample_id", masterid = "master_id")
  ifelse(h %in% names(m), unname(m[h]), tolower(trimws(f))) }
# Metinden koleksiyon. src = dosya adi koku (adsiz model icin). Hata: stop(kod) -- kodlar tr() anahtari olarak cevrilir.
pdm_read_text <- function(txt, src = "model") {
  txt <- paste(txt, collapse = "\n"); txt <- sub("^\ufeff", "", txt)
  lines <- strsplit(gsub("\r\n?", "\n", txt), "\n", fixed = TRUE)[[1]]
  lines <- lines[nzchar(trimws(lines))]
  if (!length(lines)) stop("pdm_err_empty")
  sep <- pdm_sep(lines)
  meta <- list(name = "", dataset = "", author = "", description = "")
  mm <- list(); refs <- list(); rows <- list(); hdr <- NULL; order <- character(0); unnamed <- 0L
  add_order <- function(nm) if (!(nm %in% order)) order <<- c(order, nm)
  for (ln in lines) {
    f <- pdm_split(ln, sep)
    if (!length(f)) next
    if (startsWith(f[1], "#")) {
      k <- tolower(trimws(sub("^#+", "", f[1])))
      if (k %in% c("name", "dataset", "author", "description") && length(f) >= 2) meta[[k]] <- f[2]
      else if (k == "model" && length(f) >= 4 && nzchar(f[2])) { add_order(f[2]); mm[[f[2]]][[tolower(f[3])]] <- f[4] }
      else if (k == "ref" && length(f) >= 6 && nzchar(f[2])) refs[[length(refs) + 1]] <- data.frame(model = f[2], target = f[3], allsnps = pdm_bool3(f[4]) %||% "", key = f[5], value = f[6], se = if (length(f) >= 7) f[7] else "", stringsAsFactors = FALSE)
      next
    }
    if (is.null(hdr)) {
      h <- pdm_hdr_alias(f)
      if (all(c("role", "label") %in% h)) { hdr <- h; next }
      stop("pdm_err_header")
    }
    g <- function(col) { i <- match(col, hdr); if (is.na(i) || i > length(f)) "" else f[i] }
    role <- tolower(g("role")); if (role %in% c("source", "sources", "kaynak")) role <- "left"; if (role %in% c("outgroup", "outgroups")) role <- "right"; if (role == "hedef") role <- "target"
    if (!(role %in% PDM_ROLES) || !nzchar(g("label"))) next
    nm <- g("model"); if (!nzchar(nm)) nm <- "\u0001"
    add_order(nm)
    rows[[length(rows) + 1]] <- data.frame(model = nm, role = role, label = g("label"), sample_id = g("sample_id"), master_id = g("master_id"), stringsAsFactors = FALSE)
  }
  if (is.null(hdr) && !length(rows)) stop("pdm_err_header")
  if (!length(rows)) stop("pdm_err_nomodel")
  rows <- do.call(rbind, rows); ref <- if (length(refs)) do.call(rbind, refs) else NULL
  models <- list()
  for (nm in order) {
    p <- rows[rows$model == nm, c("role", "label", "sample_id", "master_id"), drop = FALSE]
    if (!nrow(p)) next
    p <- p[!duplicated(paste(p$role, p$label, p$sample_id, sep = "\r")), , drop = FALSE]; rownames(p) <- NULL
    disp <- if (identical(nm, "\u0001")) { unnamed <- unnamed + 1L; if (unnamed == 1L) src else paste0(src, "_", unnamed) } else nm
    md <- mm[[nm]] %||% list()
    prm <- list(); for (k in c("maxmiss", "blgsize")) if (!is.null(md[[k]]) && is.finite(pdm_num(md[[k]]))) prm[[k]] <- pdm_num(md[[k]])
    r <- if (!is.null(ref)) ref[ref$model == nm, c("target", "allsnps", "key", "value", "se"), drop = FALSE] else pdm_empty_ref(); rownames(r) <- NULL
    models[[length(models) + 1]] <- pdm_new_model(disp, p, pdm_bool3(md$allsnps), prm, r, src, md$note %||% "")
  }
  if (!length(models)) stop("pdm_err_nomodel")
  list(meta = meta, models = models)
}
# Ham bayt -> UTF-8 metin. Excel "Unicode metin" = UTF-16 (BOM'lu); Turkce Windows'ta "sekmeyle ayrilmis metin" CP1254.
pdm_decode <- function(raw) {
  b2 <- if (length(raw) >= 2) as.integer(raw[1:2]) else c(0L, 0L)
  if (identical(b2, c(255L, 254L)) || identical(b2, c(254L, 255L))) {
    enc <- if (b2[1] == 255L) "UTF-16LE" else "UTF-16BE"; x <- iconv(list(raw[-(1:2)]), enc, "UTF-8")
    if (is.na(x)) stop("pdm_err_binary"); return(x) }
  if (any(raw == as.raw(0))) stop("pdm_err_binary")
  txt <- rawToChar(raw); Encoding(txt) <- "UTF-8"; if (validUTF8(txt)) return(txt)
  for (enc in c("CP1254", "WINDOWS-1254", "latin1")) { x <- tryCatch(iconv(rawToChar(raw), enc, "UTF-8"), error = function(e) NA_character_); if (!is.na(x)) return(x) }
  stop("pdm_err_binary")
}
pdm_read_file <- function(path, name = basename(path)) {
  raw <- readBin(path, "raw", file.info(path)$size)
  if (length(raw) > 20 * 1024^2) stop("pdm_err_big")
  txt <- pdm_decode(raw)
  pdm_read_text(txt, src = pdm_src_name(name))
}
# v6.3 test2 (karar 2): dosya adindan model adi koku: "x.qpAdm.txt" / "x.qpadm" / "x.txt" -> "x".
pdm_src_name <- function(nm) sub("\\.qpadm(\\.(txt|tsv|csv))?$|\\.(txt|tsv|csv)$", "", nm, ignore.case = TRUE)
# v6.3 test2 (karar 2): icerikten tur tespiti. Uygulamalar dosyayi yeniden adlandirabilir ("model (1).txt"); bicim satiri
# (#qpadm) ya da ilk yorum disi satirda model/role/label basligi varsa on tanimli model dosyasidir.
pdm_sniff <- function(path) {
  sz <- suppressWarnings(file.info(path)$size); if (!isTRUE(sz > 0)) return(FALSE)
  raw <- tryCatch(readBin(path, "raw", min(65536, sz)), error = function(e) raw(0)); if (!length(raw)) return(FALSE)
  txt <- tryCatch(pdm_decode(raw), error = function(e) ""); if (!length(txt) || is.na(txt[1])) return(FALSE)
  ln <- trimws(strsplit(gsub("\r\n?", "\n", sub("^\ufeff", "", txt[1])), "\n", fixed = TRUE)[[1]]); ln <- utils::head(ln[nzchar(ln)], 50)
  if (any(grepl("^\"?#qpadm\"?([\t;, ]|$)", ln, ignore.case = TRUE))) return(TRUE)
  h <- ln[!startsWith(ln, "#") & !startsWith(ln, "\"#")][1]; if (is.na(h)) return(FALSE)
  all(c("role", "label") %in% pdm_hdr_alias(pdm_split(h, pdm_sep(h))))
}

# Yazim. ids = yazilacak model sirasi (varsayilan hepsi).
pdm_esc <- function(x) { x <- gsub("[\t\r\n]+", " ", as.character(x %||% "")); x }
pdm_write_text <- function(coll, ids = seq_along(coll$models), program = "qpAdm Studio") {
  m <- coll$meta; out <- c(paste0("#qpadm\t", PDM_FMT), paste0("#program\t", pdm_esc(program)), paste0("#created\t", format(Sys.Date())))
  for (k in c("name", "dataset", "author", "description")) if (nzchar(m[[k]] %||% "")) out <- c(out, paste0("#", k, "\t", pdm_esc(m[[k]])))
  ms <- coll$models[ids]
  for (x in ms) {
    if (!is.na(x$allsnps %||% NA)) out <- c(out, paste("#model", pdm_esc(x$name), "allsnps", x$allsnps, sep = "\t"))
    for (k in names(x$params)) out <- c(out, paste("#model", pdm_esc(x$name), k, format(x$params[[k]]), sep = "\t"))
    if (nzchar(x$note %||% "")) out <- c(out, paste("#model", pdm_esc(x$name), "note", pdm_esc(x$note), sep = "\t"))
    r <- x$ref; if (!is.null(r) && nrow(r)) out <- c(out, paste("#ref", pdm_esc(x$name), pdm_esc(r$target), r$allsnps, pdm_esc(r$key), pdm_esc(r$value), pdm_esc(r$se), sep = "\t"))
  }
  has_master <- any(vapply(ms, function(x) any(nzchar(x$pops$master_id %||% "")), logical(1)))
  out <- c(out, paste(c("model", "role", "label", "sample_id", if (has_master) "master_id"), collapse = "\t"))
  for (x in ms) {
    p <- x$pops; if (!nrow(p)) next
    p <- p[order(match(p$role, PDM_ROLES)), , drop = FALSE]
    out <- c(out, paste(pdm_esc(x$name), p$role, pdm_esc(p$label), pdm_esc(p$sample_id), if (has_master) pdm_esc(p$master_id %||% "") else NULL, sep = "\t"))
  }
  paste0(paste(sub("\t+$", "", out), collapse = "\n"), "\n")
}

# Icerik imzasi: ayni model iki kez yuklenmez (ad farki onemsiz).
pdm_sig <- function(x) { p <- x$pops; prm <- x$params %||% list(); if (length(prm)) prm <- prm[order(names(prm))] else prm <- list(); digest::digest(list(sort(paste(p$role, p$label, p$sample_id, sep = "\r")), x$allsnps %||% NA, prm), algo = "xxhash64") }
# Birlestirme: b'nin modelleri a'ya eklenir; ayni imza atlanir; ad cakisirsa "ad (2)". Doner: list(coll, added, skipped)
pdm_merge <- function(a, b) {
  if (is.null(a) || !length(a$models)) { a <- a %||% pdm_new_coll(); for (k in names(b$meta)) if (!nzchar(a$meta[[k]] %||% "") && nzchar(b$meta[[k]] %||% "")) a$meta[[k]] <- b$meta[[k]] }
  else for (k in c("dataset")) if (!nzchar(a$meta[[k]] %||% "") && nzchar(b$meta[[k]] %||% "")) a$meta[[k]] <- b$meta[[k]]
  sigs <- vapply(a$models, pdm_sig, ""); nms <- vapply(a$models, function(x) x$name, "")
  added <- 0L; skipped <- 0L
  for (x in b$models) {
    s <- pdm_sig(x); if (s %in% sigs) { skipped <- skipped + 1L; next }
    nm <- x$name; k <- 2L; while (nm %in% nms) { nm <- paste0(x$name, " (", k, ")"); k <- k + 1L }
    x$name <- nm; a$models[[length(a$models) + 1]] <- x; sigs <- c(sigs, s); nms <- c(nms, nm); added <- added + 1L
  }
  list(coll = a, added = added, skipped = skipped)
}

# AADR .anno: Genetic ID, Master ID, otozomal SNP sayisi. Sutun adlari surume gore degisir.
pdm_anno_read <- function(path) {
  df <- tryCatch(utils::read.delim(path, header = TRUE, stringsAsFactors = FALSE, quote = "", check.names = FALSE, comment.char = "", colClasses = "character", na.strings = character(0)), error = function(e) NULL)
  if (is.null(df) || !nrow(df)) return(NULL)
  nm <- names(df); f <- function(pats) { for (p in pats) { i <- grep(p, nm, ignore.case = TRUE); if (length(i)) return(i[1]) }; NA_integer_ }
  id <- f(c("^Genetic ?ID", "^Instance ?ID", "^Version ?ID", "Genetic ?ID")); ms <- f(c("^Master ?ID", "Master ?ID"))
  sn <- f(c("SNPs? hit on autosomal targets", "autosomal SNPs", "SNPs hit", "^SNPs"))
  if (is.na(id) || is.na(ms)) return(NULL)
  snp <- if (is.na(sn)) rep(NA_real_, nrow(df)) else suppressWarnings(as.numeric(gsub("[^0-9.]", "", df[[sn]])))
  data.frame(id = trimws(df[[id]]), master = trimws(df[[ms]]), snps = snp, stringsAsFactors = FALSE)
}
# Aday .anno yollari: once genotip onekinin yanindaki <onek>.anno, sonra ayni klasorde TEK .anno, sonra verilen ek yollar.
pdm_find_anno <- function(prefix, extra = character(0)) {
  c1 <- if (!is.null(prefix) && nzchar(prefix)) paste0(prefix, ".anno") else character(0)
  c2 <- if (!is.null(prefix) && nzchar(prefix) && dir.exists(dirname(prefix))) { a <- list.files(dirname(prefix), "\\.anno$", full.names = TRUE, ignore.case = TRUE); if (length(a) == 1) a else character(0) } else character(0)
  cand <- unique(c(c1, c2, extra[grepl("\\.anno$", extra, ignore.case = TRUE)]))
  cand[file.exists(cand)]
}

# Bir modelin veri setine gore cozumu.
#   ids_all : veri setindeki sample ID'ler; lab_of : adlandirilmis vektor sample ID -> GECERLI etiket (kullanicinin sanal etiketleri dahil)
#   anno    : pdm_anno_read() sonucu ya da NULL; targets_user : dosyada Target yoksa Model kutusundaki hedefler (etiket)
# Doner: pops (rol, etiket, durum), rules (sanal kurallar: SampleID / VirtualLabel / OriginalLabel / Source = "qpadm"),
#        labels (target/left/right; calistirilacak adlar), status ("green"/"yellow"/"red"), issues (list(code, n, what)).
pdm_resolve <- function(x, ids_all, lab_of, anno = NULL, taken = character(0)) {
  p <- x$pops; issues <- list(); iss <- function(code, n = NA, what = "") issues[[length(issues) + 1]] <<- list(code = code, n = n, what = paste(what, collapse = ", "))
  ids_all <- as.character(ids_all); lab_of <- lab_of[!duplicated(names(lab_of))]
  pr <- match(p$role, PDM_ROLES)
  # etiket bazli satirlar (sample_id bos): etiketin gecerli bireyleri
  lb <- which(!nzchar(p$sample_id))
  if (length(lb)) {
    ex <- do.call(rbind, lapply(lb, function(i) { s <- names(lab_of)[lab_of == p$label[i]]; if (!length(s)) data.frame(role = p$role[i], label = p$label[i], sample_id = "", master_id = "", stringsAsFactors = FALSE) else data.frame(role = p$role[i], label = p$label[i], sample_id = s, master_id = "", stringsAsFactors = FALSE) }))
    p <- rbind(p[-lb, , drop = FALSE], ex); pr <- match(p$role, PDM_ROLES)
  }
  p$found <- p$sample_id %in% ids_all & nzchar(p$sample_id); p$mapped <- ""
  # .anno ile Master ID eslemesi (yalniz .anno varsa)
  if (!is.null(anno) && nrow(anno) && any(!p$found & nzchar(p$sample_id))) {
    used <- p$sample_id[p$found]
    an <- anno[anno$id %in% ids_all, , drop = FALSE]
    for (i in which(!p$found & nzchar(p$sample_id))) {
      m <- p$master_id[i]; if (!nzchar(m)) m <- anno$master[match(p$sample_id[i], anno$id)]; if (is.na(m) || !nzchar(m)) m <- sub("\\.[^.]+$", "", p$sample_id[i])
      c <- an[an$master == m & !(an$id %in% used), , drop = FALSE]
      if (nrow(c)) { c <- c[order(-ifelse(is.na(c$snps), -1, c$snps)), , drop = FALSE]; p$mapped[i] <- c$id[1]; used <- c(used, c$id[1]) }
    }
    mp <- nzchar(p$mapped); if (any(mp)) { iss("anno", sum(mp), paste0(p$sample_id[mp], " -> ", p$mapped[mp])); p$sample_id[mp] <- p$mapped[mp]; p$found[mp] <- TRUE }
  }
  miss <- !p$found & nzchar(p$sample_id)
  if (any(miss)) iss("missing", sum(miss), unique(p$sample_id[miss]))
  # ayni birey iki popda: target > left > right; ayni rolde ilk gelen kalir
  o <- order(match(p$role, PDM_ROLES), seq_len(nrow(p)))
  q <- p[o, , drop = FALSE]; dup <- q$found & duplicated(q$sample_id) & nzchar(q$sample_id)
  if (any(dup)) { iss("dup", sum(dup), unique(q$sample_id[dup])); q$found[dup] <- FALSE }
  p <- q[q$found, , drop = FALSE]
  labs <- function(r) unique(x$pops$label[x$pops$role == r])
  have <- function(r) unique(p$label[p$role == r])
  tl <- labs("target"); ll <- labs("left"); rl <- labs("right")
  red <- FALSE
  if (length(intersect(tl, c(ll, rl))) || length(intersect(ll, rl))) { iss("role_clash", NA, unique(c(intersect(tl, c(ll, rl)), intersect(ll, rl)))); red <- TRUE }
  le <- setdiff(ll, have("left")); if (length(le)) { iss("left_empty", length(le), le); red <- TRUE }
  re <- setdiff(rl, have("right")); if (length(re)) iss("right_dropped", length(re), re)
  te <- setdiff(tl, have("target")); if (length(te)) { if (length(te) == length(tl)) { iss("target_empty", length(te), te); red <- TRUE } else iss("target_dropped", length(te), te) }
  nl <- length(have("left")); nr <- length(have("right"))
  if (!length(ll)) { iss("no_left"); red <- TRUE }
  if (!length(rl)) { iss("no_right"); red <- TRUE }
  else if (nl && nr < nl + 1) { iss("rank", nr, nl); red <- TRUE }
  # sanal kurallar: etiket adi gecersizse duzeltilir; etiketin bilesimi ayniysa kural yok
  all_l <- unique(p$label); taken <- unique(c(taken, unique(lab_of)))
  eff <- stats::setNames(all_l, all_l); bad <- label_bad(all_l)
  if (any(bad)) { eff[bad] <- label_fix_unique(all_l[bad], unique(c(setdiff(taken, all_l[bad]), all_l[!bad]))); iss("renamed", sum(bad), paste0(all_l[bad], " -> ", eff[bad])) }
  rules <- list(); model_ids <- unique(p$sample_id)
  for (L in all_l) {
    S <- unique(p$sample_id[p$label == L]); E <- eff[[L]]; D <- names(lab_of)[lab_of == E]
    if (setequal(S, D)) next
    mv <- S[lab_of[S] != E | is.na(lab_of[S])]
    if (length(mv)) rules[[length(rules) + 1]] <- data.frame(SampleID = mv, VirtualLabel = E, OriginalLabel = unname(ifelse(is.na(lab_of[mv]), "", lab_of[mv])), Source = "qpadm", stringsAsFactors = FALSE)
    out <- setdiff(D, model_ids)
    if (length(out)) { X <- unname(label_fix_unique(paste0(E, "_qpx"), unique(c(taken, eff)))); taken <- c(taken, X); rules[[length(rules) + 1]] <- data.frame(SampleID = out, VirtualLabel = X, OriginalLabel = E, Source = "qpadm_out", stringsAsFactors = FALSE) }
  }
  rules <- if (length(rules)) do.call(rbind, rules) else data.frame(SampleID = character(0), VirtualLabel = character(0), OriginalLabel = character(0), Source = character(0), stringsAsFactors = FALSE)
  e <- function(r) unname(eff[intersect(labs(r), have(r))])
  status <- if (red) "red" else if (any(vapply(issues, function(z) z$code %in% c("anno", "missing", "dup", "right_dropped", "target_dropped"), logical(1)))) "yellow" else "green"
  comp <- lapply(stats::setNames(all_l, unname(eff[all_l])), function(L) sort(unique(p$sample_id[p$label == L])))
  list(pops = p, rules = rules, labels = list(target = e("target"), left = e("left"), right = e("right")), status = status, issues = issues, comp = comp,
       n = c(target = length(e("target")), left = length(e("left")), right = length(e("right"))))
}

# Kural birlestirme: ayni birey iki farkli ada gidiyorsa NULL (cakisma).
pdm_rules_merge <- function(a, b) {
  r <- rbind(a, b); if (!nrow(r)) return(r)
  r <- r[!duplicated(paste(r$SampleID, r$VirtualLabel, sep = "\r")), , drop = FALSE]
  if (any(duplicated(r$SampleID))) return(NULL)
  rownames(r) <- NULL; r
}
# Birlesik kurallar altinda her modelin her popu tam istenen bireylerden mi olusuyor?
pdm_rules_ok <- function(rules, res_list, lab_of) {
  lo <- lab_of; if (nrow(rules)) { k <- rules$SampleID %in% names(lo); lo[rules$SampleID[k]] <- rules$VirtualLabel[k] }
  for (r in res_list) for (E in names(r$comp)) if (!setequal(names(lo)[lo == E], r$comp[[E]])) return(FALSE)
  TRUE
}
# \u00d61 TEK HAVUZ: kirmizi olmayan modeller (rs: ad -> cozum) uyumlu kural kumelerine gore gruplanir. Ayni gruptaki modeller
# AYNI sanal set (birlesik kurallar) ile kosar -> ayni vfam onegi ve (allsnps=FALSE) tek f2 havuzu (birlesik pop listesi).
pdm_group <- function(rs, lab_of) {
  groups <- list()
  for (k in names(rs)) { r <- rs[[k]]; placed <- FALSE
    for (g in seq_along(groups)) { R <- pdm_rules_merge(groups[[g]]$rules, r$rules); if (is.null(R)) next
      if (pdm_rules_ok(R, c(groups[[g]]$res, list(r)), lab_of)) { groups[[g]]$rules <- R; groups[[g]]$idx <- c(groups[[g]]$idx, k); groups[[g]]$res <- c(groups[[g]]$res, list(r)); placed <- TRUE; break } }
    if (!placed) groups[[length(groups) + 1]] <- list(idx = k, rules = r$rules, res = list(r)) }
  lapply(groups, function(g) list(idx = g$idx, rules = g$rules, pops = unique(unlist(lapply(g$res, function(r) unlist(r$labels, use.names = FALSE)), use.names = FALSE))))
}

# \u00d65 referans sonuc karsilastirmasi. ref: modelin #ref satirlari; md: "TRUE"/"FALSE"; res: qpadm sonucu (weights: left, weight, se).
# Doner NULL (referans yok) ya da list(same, dw (en buyuk |fark|), p_ref, p_cur, rows (etiket, ref, cur)).
pdm_ref_compare <- function(ref, target, md, p_cur, weights) {
  if (is.null(ref) || !nrow(ref)) return(NULL)
  r <- ref[(ref$target %in% c(target, "", "*")) & (ref$allsnps %in% c(md, "", NA)), , drop = FALSE]
  if (!nrow(r)) return(NULL)
  if (any(r$target == target)) r <- r[r$target == target, , drop = FALSE]
  if (any(r$allsnps %in% md)) r <- r[r$allsnps %in% md, , drop = FALSE]
  p_ref <- pdm_num(r$value[r$key == "p"][1] %||% NA)
  wr <- r[startsWith(r$key, "w:"), , drop = FALSE]
  w <- as.data.frame(weights %||% data.frame()); cur <- if (nrow(w) && all(c("left", "weight") %in% names(w))) stats::setNames(as.numeric(w$weight), as.character(w$left)) else numeric(0)
  rows <- data.frame(label = sub("^w:", "", wr$key), ref = vapply(wr$value, pdm_num, 0), stringsAsFactors = FALSE)
  rows$cur <- unname(cur[rows$label])
  if (!nrow(rows) && !is.finite(p_ref)) return(NULL)
  dw <- if (nrow(rows)) suppressWarnings(max(abs(rows$ref - rows$cur), na.rm = TRUE)) else NA_real_; if (!is.finite(dw)) dw <- NA_real_
  pc <- suppressWarnings(as.numeric(p_cur)); dp <- if (is.finite(p_ref) && isTRUE(is.finite(pc))) abs(p_ref - pc) else NA_real_
  same <- isTRUE(!is.na(dw) && dw < 0.001 || is.na(dw)) && isTRUE(is.na(dp) || dp < max(0.001, 0.01 * abs(p_ref))) && !(is.na(dw) && is.na(dp)) && all(!is.na(rows$cur))
  list(same = same, dw = dw, p_ref = p_ref, p_cur = pc, rows = rows)
}
pdm_ref_en <- function(cmp) if (is.null(cmp)) "" else if (isTRUE(cmp$same)) "reference: same" else
  paste0("reference: differs", if (!is.na(cmp$dw)) sprintf(" (max weight difference %.1f points)", 100 * cmp$dw) else "",
         if (is.finite(cmp$p_ref)) sprintf("; p ref = %s, now = %s", format(signif(cmp$p_ref, 3)), format(signif(cmp$p_cur, 3))) else "")
# Bir sonuctan referans satirlari (Model > "On tanimli modellere ekle" -> "son sonucu referans olarak ekle").
pdm_ref_rows <- function(target, md, p, chisq, dof, feasible, weights, dataset = "", pool = "", nsnp = NA) {
  w <- as.data.frame(weights %||% data.frame()); k <- c("p", "chisq", "dof", "feasible"); v <- c(format(p), format(chisq), format(dof), as.character(feasible))
  out <- data.frame(target = target, allsnps = md, key = k, value = v, se = "", stringsAsFactors = FALSE)
  if (nrow(w) && all(c("left", "weight") %in% names(w))) out <- rbind(out, data.frame(target = target, allsnps = md, key = paste0("w:", w$left), value = format(w$weight), se = if ("se" %in% names(w)) format(w$se) else "", stringsAsFactors = FALSE))
  ex <- c(dataset = dataset, pool = pool, nsnp = if (is.finite(nsnp)) format(round(nsnp)) else ""); ex <- ex[nzchar(ex)]
  if (length(ex)) out <- rbind(out, data.frame(target = target, allsnps = md, key = names(ex), value = unname(ex), se = "", stringsAsFactors = FALSE))
  out
}

# \u00d610 ozet: satir = (model, allsnps, target). Excel: Matrix (target x model, p) + Models.
write_pdm_excel <- function(sm, file) {
  wb <- openxlsx::createWorkbook(); hdr <- openxlsx::createStyle(textDecoration = "bold", fgFill = "#DDEBF7")
  col <- paste0(sm$model, " [", sm$allsnps, "]")
  mt <- stats::reshape(data.frame(target = sm$target, model = col, p = sm$p, stringsAsFactors = FALSE), idvar = "target", timevar = "model", direction = "wide")
  names(mt) <- sub("^p\\.", "", names(mt))
  openxlsx::addWorksheet(wb, "Matrix"); openxlsx::writeData(wb, "Matrix", "p-value (target x model)", startRow = 1)
  openxlsx::writeData(wb, "Matrix", mt, startRow = 2, headerStyle = hdr)
  openxlsx::addWorksheet(wb, "Models"); openxlsx::writeData(wb, "Models", sm[, intersect(c("model", "allsnps", "target", "p", "chisq", "dof", "feasible", "weights", "reference", "notes", "file"), names(sm)), drop = FALSE], headerStyle = hdr)
  openxlsx::setColWidths(wb, "Models", cols = 1:11, widths = "auto")
  openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
  invisible(file)
}

# Onerilen veri seti listesi (dosya olustururken secim kolayligi; dosyadaki deger listede olmasa da gosterilir).
PDM_DATASETS <- c("", "AADR v66.p1 1240K", "AADR v66.p1 HO (1240K+HO)", "AADR v66.p1 2M", "AADR v66.0 1240K", "AADR v66.0 HO (1240K+HO)", "AADR v66.0 2M", "AADR v62.0 1240K", "AADR v62.0 HO (1240K+HO)", "AADR v54.1.p1 1240K", "AADR v54.1.p1 HO (1240K+HO)", "AADR v54.1 1240K", "AADR v54.1 HO (1240K+HO)", "AADR v52.2 1240K", "AADR v52.2 HO (1240K+HO)", "AADR v50.0.p1 1240K", "AADR v50.0.p1 HO (1240K+HO)", "AADR v50.0 1240K", "AADR v50.0 HO (1240K+HO)", "AADR v44.3 1240K", "AADR v44.3 HO (1240K+HO)", "AADR v42.4 1240K", "AADR v42.4 HO (1240K+HO)", "AADR v37.2 1240K", "AADR v37.2 HO (1240K+HO)")

# Durum notu (Ingilizce; Excel/RAW icin). Ekranda tr() ile pdm_iss_<kod> anahtarlari kullanilir.
pdm_issue_en <- function(z) switch(z$code,
  anno = sprintf("%d sample(s) matched by AADR Master ID (.anno): %s", z$n, z$what),
  missing = sprintf("%d sample ID(s) not found in the dataset: %s", z$n, z$what),
  dup = sprintf("%d sample(s) listed in two populations; kept in target > left > right: %s", z$n, z$what),
  role_clash = sprintf("same label in two roles: %s", z$what),
  left_empty = sprintf("no samples found for left population(s): %s", z$what),
  right_dropped = sprintf("right population(s) with no samples dropped: %s", z$what),
  target_empty = sprintf("no samples found for target(s): %s", z$what),
  target_dropped = sprintf("target(s) with no samples dropped: %s", z$what),
  no_left = "model has no left populations", no_right = "model has no right populations",
  rank = sprintf("right populations (%s) must be at least left (%s) + 1", z$n, z$what),
  renamed = sprintf("label(s) renamed to valid names: %s", z$what), z$code)

# Model Model-kutusundaki (gecerli) secimden: etiket -> sample ID'ler. targets bossa Target yazilmaz.
pdm_from_selection <- function(name, targets, left, right, labelmap, allsnps = NA_character_, params = list(), anno = NULL) {
  mk <- function(role, labs) { labs <- unique(as.character(labs)); if (!length(labs)) return(NULL)
    do.call(rbind, lapply(labs, function(l) { s <- labelmap[[l]] %||% character(0); data.frame(role = role, label = l, sample_id = if (length(s)) s else "", master_id = if (!is.null(anno) && length(s)) { v <- anno$master[match(s, anno$id)]; ifelse(is.na(v), "", v) } else "", stringsAsFactors = FALSE) })) }
  p <- rbind(mk("target", targets), mk("left", left), mk("right", right)); if (is.null(p)) p <- pdm_empty_pops()
  pdm_new_model(name, p, allsnps, params)
}
# Dinamik kurulan ceviri anahtarlari (tr(paste0("pdm_st_", durum)), tr(paste0("pdm_iss_", kod))); dead_keys denetimi icin.
PDM_DYN_KEYS <- c("pdm_st_green", "pdm_st_yellow", "pdm_st_red", "pdm_iss_anno", "pdm_iss_missing", "pdm_iss_dup", "pdm_iss_role_clash", "pdm_iss_left_empty",
  "pdm_iss_right_dropped", "pdm_iss_target_empty", "pdm_iss_target_dropped", "pdm_iss_no_left", "pdm_iss_no_right", "pdm_iss_rank", "pdm_iss_renamed", "pdm_iss_error")

# Setin etiket dosyasinin parmak izi (md5). Boyut + mtime ile onbellekli.
.QPS_FP <- new.env(parent = emptyenv())
labfile_fp <- function(prefix) {
  if (is.null(prefix)) return("")
  fs <- geno_fileset(prefix); if (is.null(fs)) return("")
  f <- unname(fs$labfile); inf <- file.info(f)
  k <- paste(normalizePath(f, mustWork = FALSE), inf$size, as.numeric(inf$mtime))
  v <- .QPS_FP[[k]]; if (!is.null(v)) return(v)
  v <- tryCatch(digest::digest(file = f, algo = "md5"), error = function(e) "")
  assign(k, v, envir = .QPS_FP); v
}

# v6.0 (K3): allsnps=TRUE'da hedef SNP sayisi onbellegi. Anahtar: genotip dosyasi (yol + boyut +
# mtime) + etiket dosyasi md5 + hedefin birey listesi (etiket adindan bagimsiz; sanal etiketle de
# ayni bireyler ayni anahtar) + auto_only. Deger: list(n, target, time, secs).
tsnp_cache_file <- function() file.path(CACHE_BASE, "qps_target_snps.rds")
tsnp_cache_read <- function() { f <- tsnp_cache_file(); if (!file.exists(f)) return(list()); tryCatch(readRDS(f), error = function(e) list()) }
tsnp_cache_put <- function(vals) {
  if (!length(vals)) return(invisible(NULL))
  m <- tsnp_cache_read(); for (k in names(vals)) m[[k]] <- vals[[k]]
  tryCatch(saveRDS(m, tsnp_cache_file()), error = function(e) NULL); invisible(NULL)
}
tsnp_key <- function(prefix, ids, auto_only = TRUE) {
  fs <- if (is.null(prefix)) NULL else geno_fileset(prefix); if (is.null(fs)) return(NA_character_)
  g <- unname(fs$files[1]); inf <- file.info(g)
  digest::digest(list(normalizePath(g, mustWork = FALSE), inf$size, as.numeric(inf$mtime), labfile_fp(prefix),
    sort(unique(as.character(ids))), isTRUE(auto_only)), algo = "md5")
}

# Dosyayi once gecici ada yazar, sonra yerine koyar. Hedef varsa: backup = TRUE
# ise <ad>.bak_<zaman> olarak birakilir; degilse eski dosya ancak yeni dosya
# yerine oturduktan sonra silinir. Her adimda basarisizlik eski hale doner.
# eol: NULL = platformun metin kipi (eski davranis); "\n" / "\r\n" = ikili kipte
# AYNEN o satir sonu (tam kopya kaynagin satir sonunu korur).
write_lines_safe <- function(lines, path, backup = FALSE, stamp = format(Sys.time(), "%Y%m%d_%H%M%S"), eol = NULL) {
  tmp <- paste0(path, ".qps_tmp")
  if (is.null(eol)) writeLines(lines, tmp) else { con <- file(tmp, "wb"); tryCatch(writeLines(lines, con, sep = eol, useBytes = TRUE), finally = close(con)) }
  bk <- NULL; old <- NULL
  if (file.exists(path)) {
    if (isTRUE(backup)) {
      bk <- paste0(path, ".bak_", stamp); while (file.exists(bk)) bk <- paste0(bk, "_2")
      if (!isTRUE(file.rename(path, bk))) { unlink(tmp); stop(sprintf(tr("err_backup"), bk), call. = FALSE) }
    } else {
      old <- paste0(path, ".qps_old"); unlink(old)
      if (!isTRUE(file.rename(path, old))) { unlink(tmp); stop(sprintf(tr("err_write"), path), call. = FALSE) }
    }
  }
  if (!isTRUE(file.rename(tmp, path))) {
    if (!is.null(bk)) file.rename(bk, path)
    if (!is.null(old)) file.rename(old, path)
    unlink(tmp); stop(sprintf(tr("err_write"), path), call. = FALSE)
  }
  if (!is.null(old)) unlink(old)
  invisible(list(path = path, backup = bk))
}

# Gelismis duzenleyici: setin etiket dosyasi DOSYA SIRASIYLA (sample ID, etiket).
adv_read_set <- function(path) {
  ext <- tolower(tools::file_ext(path))
  df <- utils::read.table(path, header = FALSE, stringsAsFactors = FALSE, fill = TRUE, comment.char = "", quote = "", check.names = FALSE, colClasses = "character")
  if (ext == "fam" && ncol(df) >= 2) return(data.frame(SampleID = trimws(df[[2]]), Label = trimws(df[[1]]), stringsAsFactors = FALSE))
  if (ext == "ind" && ncol(df) >= 2) return(data.frame(SampleID = trimws(df[[1]]), Label = trimws(df[[ncol(df)]]), stringsAsFactors = FALSE))
  NULL
}

# ---------------------------------------------------------------------------
# v5.9 ADIM 2-3: GELISMIS DUZENLEYICI -- saf yardimcilar
# ---------------------------------------------------------------------------
# Dosyanin satir sonu. Tam kopya kaynagin satir sonuyla yazilir.
detect_eol <- function(path) {
  con <- file(path, "rb"); on.exit(close(con))
  b <- readBin(con, "raw", 65536L)
  if (any(b == as.raw(13L))) "\r\n" else "\n"
}
# Ham satirlar (CR atilir, bos satirlar korunur).
read_raw_lines <- function(path) {
  con <- file(path, "rb"); on.exit(close(con))
  sub("\r$", "", readLines(con, warn = FALSE))
}
# Satirdaki ID ve etiket alanlari. fam: etiket = 1. sutun, ID = 2. sutun;
# ind: ID = 1. sutun, etiket = son sutun. Iki sutundan az olan satirda NA.
lab_line_fields <- function(lines, ext) {
  tok <- strsplit(trimws(lines), "[[:space:]]+")
  idc <- if (identical(ext, "fam")) 2L else 1L
  list(id = vapply(tok, function(t) if (length(t) >= 2) t[idc] else NA_character_, ""),
       lab = vapply(tok, function(t) if (length(t) >= 2) t[if (identical(ext, "fam")) 1L else length(t)] else NA_character_, ""))
}
# TAM KOPYA: satirlarda YALNIZCA etiket alanini degistirir. Satir sirasi, diger
# sutunlar, ayraclar ve bos satirlar aynen kalir. newlab: SampleID -> etiket.
# Sonuc yeniden ayristirilir; ID dizisi kaynakla AYNI degilse ya da etiket alani
# istenen etiket degilse (bosluklu etiket sutun kaydirir) yazim durur.
adv_relabel_lines <- function(lines, ext, newlab) {
  f <- lab_line_fields(lines, ext)
  i <- which(!is.na(f$id) & f$id %in% names(newlab))
  out <- lines; nch <- 0L
  if (length(i)) {
    nl <- unname(newlab[f$id[i]]); l <- lines[i]
    m <- if (identical(ext, "fam")) regexpr("[^[:space:]]+", l) else regexpr("[^[:space:]]+(?=[[:space:]]*$)", l, perl = TRUE)
    st <- as.integer(m); ln <- attr(m, "match.length")
    out[i] <- paste0(substr(l, 1L, st - 1L), nl, substr(l, st + ln, nchar(l)))
    nch <- sum(f$lab[i] != nl)
  }
  g <- lab_line_fields(out, ext)
  if (!identical(g$id, f$id) || (length(i) && !identical(g$lab[i], nl))) stop(tr("err_adv_ids"), call. = FALSE)
  attr(out, "n_changed") <- nch
  out
}
# Bekleyen degisiklikleri temel tabloya uygular. base: SampleID, Guncel,
# Orijinal, St; edit: SampleID -> etiket. Temeldekiyle ayni olan kayit etkisizdir.
adv_apply_edits <- function(base, edit) {
  if (is.null(base) || !length(edit)) return(base)
  i <- match(names(edit), base$SampleID); ok <- !is.na(i)
  i <- i[ok]; v <- unname(edit[ok]); ch <- base$Guncel[i] != v
  base$Guncel[i[ch]] <- v[ch]; base$St[i[ch]] <- "p"
  base
}

# Adna merge studio v3.14 duplikat kurallari (cekirdek_id + alt_dizi_mi +
# benzer_ciftler) -- bagimsiz modda YALNIZCA bilgi listesi icin.
ADV_SUFFIX <- c(".AG", ".DG", ".SG", ".HO", ".TW", ".YW", ".IM", ".AA", ".EC", ".WGC", ".REF", ".BY", ".SDG")
adv_core_id <- function(iid) {
  x <- iid; degisti <- TRUE
  while (degisti) { degisti <- FALSE
    for (s in ADV_SUFFIX) { hit <- endsWith(x, s); if (any(hit)) { x[hit] <- substr(x[hit], 1, nchar(x[hit]) - nchar(s)); degisti <- TRUE } } }
  x <- sub("_IL[0-9]+$", "", x); x <- sub("_(d|dup|published|merged)$", "", x)
  toupper(x)
}
# Kisa ID uzunun ALT DIZISI mi (yalnizca karakter eklenmis/cikarilmis; en cok 3).
adv_subseq <- function(x, y) {
  x <- toupper(x); y <- toupper(y)
  if (nchar(x) > nchar(y)) { t <- x; x <- y; y <- t }
  if (nchar(y) - nchar(x) > 3L) return(FALSE)
  xs <- strsplit(x, "")[[1]]; ys <- strsplit(y, "")[[1]]; i <- 1L
  for (ch in ys) { if (i > length(xs)) break; if (identical(ch, xs[i])) i <- i + 1L }
  i > length(xs)
}
adv_similar_pairs <- function(a, b, esik = 2L, azami_aday = 5000L, azami_kova = 400L) {
  kova <- function(x) paste0(substr(x, 1, 3), "|", substr(x, pmax(1, nchar(x) - 2), nchar(x)))
  ka <- kova(toupper(a)); kb <- kova(toupper(b)); out <- list(); n <- 0L
  for (k in intersect(unique(ka), unique(kb))) {
    ia <- which(ka == k); ib <- which(kb == k)
    if (length(ia) * length(ib) > azami_kova^2) next
    d <- utils::adist(toupper(a[ia]), toupper(b[ib]))
    for (r in seq_along(ia)) for (c in seq_along(ib)) if (d[r, c] <= esik && adv_subseq(a[ia[r]], b[ib[c]])) {
      n <- n + 1L; if (n > azami_aday) break; out[[n]] <- c(ia[r], ib[c]) }
    if (n > azami_aday) break
  }
  if (!length(out)) return(NULL)
  m <- do.call(rbind, out); data.frame(i = m[, 1], j = m[, 2])
}

# Bagimsiz mod birlestirme. files: adlandirilmis liste (dosya kimligi ->
# list(df = data.frame(SampleID, Label, Line), ...)); ord: oncelik sirasi;
# ovr: SampleID -> dosya kimligi (satir bazinda secim). Ayni ID + ayni etiket
# sessizce teklenir; ayni ID + farkli etiket CAKISMA; ayni dosyada ayni ID
# birden cok kez = dosya ici mukerrer (cakismalar listesinde). Kazanan: en
# oncelikli dosyadaki ilk satir (satir secimi varsa o dosyanin ilk satiri).
advi_merge <- function(files, ord, ovr = character(0)) {
  ord <- ord[ord %in% names(files)]; if (!length(ord)) return(NULL)
  a <- do.call(rbind, lapply(seq_along(ord), function(p) { d <- files[[ord[p]]]$df
    data.frame(SampleID = d$SampleID, Label = d$Label, Line = d$Line, F = rep(ord[p], nrow(d)), P = rep(p, nrow(d)), stringsAsFactors = FALSE) }))
  a <- a[order(a$P, a$Line), , drop = FALSE]
  win <- a[!duplicated(a$SampleID), c("SampleID", "Label", "F", "P"), drop = FALSE]
  ovr <- ovr[names(ovr) %in% win$SampleID & ovr %in% ord]
  if (length(ovr)) {
    j <- match(paste(names(ovr), ovr, sep = "\r"), paste(a$SampleID, a$F, sep = "\r")); ok <- !is.na(j)
    wi <- match(names(ovr)[ok], win$SampleID)
    win$Label[wi] <- a$Label[j[ok]]; win$F[wi] <- a$F[j[ok]]; win$P[wi] <- a$P[j[ok]]
    ovr <- ovr[ok]
  }
  u <- a[!duplicated(a[, c("SampleID", "Label")]), , drop = FALSE]
  nl <- table(u$SampleID); cid <- names(nl)[nl > 1]
  did <- unique(a$SampleID[duplicated(a[, c("F", "SampleID")])])
  ids <- win$SampleID[win$SampleID %in% c(cid, did)]
  conf <- NULL
  if (length(ids)) {
    # Secenek metni: etiket [#dosya sirasi, ...] | ... (vektorel; 27 bin cakismada da hizli)
    aa <- a[a$SampleID %in% ids, , drop = FALSE]
    aa <- aa[order(match(aa$SampleID, ids), aa$P, aa$Line), , drop = FALSE]
    aa <- aa[!duplicated(aa[, c("SampleID", "Label", "P")]), , drop = FALSE]
    k <- paste(aa$SampleID, aa$Label, sep = "\r"); fk <- !duplicated(k)
    pl <- vapply(split(paste0("#", aa$P), factor(k, levels = unique(k))), paste, "", collapse = ", ")
    opts <- vapply(split(paste0(aa$Label[fk], " [", pl, "]"), factor(aa$SampleID[fk], levels = ids)), paste, "", collapse = " | ")
    typ <- ifelse(ids %in% cid & ids %in% did, "label+dup", ifelse(ids %in% cid, "label", "dup"))
    w <- win[match(ids, win$SampleID), ]
    conf <- data.frame(SampleID = ids, Type = typ, Options = unname(opts), Chosen = w$Label, Src = w$P, Ovr = ids %in% names(ovr), stringsAsFactors = FALSE)
  }
  rownames(win) <- NULL
  list(rows = win, conf = conf, cid = cid, did = did, ovr = ovr, n = nrow(win))
}
# Bilgi listesi: dosya ciftleri arasinda KESIN eslesmeyen ama ayni birey
# olabilecek ID'ler (cekirdek ID ya da benzer yazim). Bir dosyada zaten
# bulunan ID'ler karsilastirmaya girmez. Cok buyuk eslesmeyen kumelerde bulanik
# tarama atlanir (merge studio: cekirdek eslesmesi 2000'i asarsa da atlanir).
advi_similar <- function(files, ord, max_fuzzy = 3000L) {
  ord <- ord[ord %in% names(files)]
  if (length(ord) < 2) return(list(df = NULL, skipped = 0L))
  ids <- lapply(files[ord], function(f) unique(f$df$SampleID))
  lab1 <- lapply(files[ord], function(f) { d <- f$df; k <- !duplicated(d$SampleID); stats::setNames(d$Label[k], d$SampleID[k]) })
  out <- list(); skipped <- 0L
  for (x in seq_along(ord)) for (y in seq_along(ord)) if (x < y) {
    A <- setdiff(ids[[x]], ids[[y]]); B <- setdiff(ids[[y]], ids[[x]])
    if (!length(A) || !length(B)) next
    m <- merge(data.frame(a = A, k = adv_core_id(A), stringsAsFactors = FALSE), data.frame(b = B, k = adv_core_id(B), stringsAsFactors = FALSE), by = "k")
    pr <- data.frame(T = rep("core", nrow(m)), a = m$a, b = m$b, stringsAsFactors = FALSE)
    if (nrow(m) <= 2000L) {
      if (min(length(A), length(B)) <= max_fuzzy) {
        bz <- adv_similar_pairs(A, B)
        if (!is.null(bz)) { fz <- data.frame(T = "fuzzy", a = A[bz$i], b = B[bz$j], stringsAsFactors = FALSE)
          pr <- rbind(pr, fz[!paste(fz$a, fz$b) %in% paste(pr$a, pr$b), , drop = FALSE]) }
      } else skipped <- skipped + 1L
    }
    if (nrow(pr)) out[[length(out) + 1L]] <- data.frame(Type = pr$T, ID1 = pr$a, F1 = ord[x], L1 = unname(lab1[[x]][pr$a]),
      ID2 = pr$b, F2 = ord[y], L2 = unname(lab1[[y]][pr$b]), stringsAsFactors = FALSE)
  }
  list(df = if (length(out)) do.call(rbind, out) else NULL, skipped = skipped)
}

# v6.0 ADIM 3 (Ç1-a): bagimsiz mod ile Veri sekmesinin ORTAK bilesenleri. Motor advi_merge();
# cakisma tablosu ve oncelik penceresi ayni fonksiyonlardan kurulur. nm: oncelik SIRASINDAKI dosya
# adlari (c0$Src konum). orig: list(ids, lab = adlandirilmis etiket, name) -> "Orijinal etiket kalsin".
merge_conf_frame <- function(c0, nm, orig = NULL) {
  tp <- c(label = tr("advi_type_label"), dup = tr("advi_type_dup"))
  typ <- vapply(strsplit(c0$Type, "+", fixed = TRUE), function(x) paste(tp[x], collapse = " + "), "")
  d <- data.frame(SampleID = c0$SampleID, Type = typ, Options = c0$Options, Chosen = c0$Chosen, Src = unname(nm[c0$Src]),
                  Ovr = ifelse(c0$Ovr, "\u2713", ""), stringsAsFactors = FALSE)
  if (!is.null(orig) && length(orig$ids)) {
    h <- d$SampleID %in% orig$ids
    if (any(h)) { d$Chosen[h] <- unname(orig$lab[d$SampleID[h]]); d$Src[h] <- orig$name; d$Ovr[h] <- "\u2713" }
  }
  d
}
merge_conf_dt <- function(d) datatable(d, rownames = FALSE, filter = "top", selection = "multiple", options = list(pageLength = 25, scrollX = TRUE),
  colnames = c(tr("adv_col_id"), tr("advi_col_type"), tr("advi_cc_opts"), tr("advi_cc_chosen"), tr("advi_cc_src"), tr("advi_cc_ovr")))
merge_pref_modal <- function(radio, ok, ord, labs, body) showModal(modalDialog(title = tr("advi_pref_title"), easyClose = TRUE, p(body),
  radioButtons(radio, NULL, choices = stats::setNames(ord, unname(labs[ord])), selected = ord[1]),
  footer = tagList(modalButton(tr("ow_cancel")), actionButton(ok, tr("advi_pref_ok"), class = "btn-primary"))))

# v6.0 ADIM 3: Veri sekmesi coklu harici dosya. files: kimlik -> list(path, name, ext, df(SampleID,
# Label, Line), md5, on). ETKIN dosyalar oncelik sirasiyla advi_merge'e girer (ayni ID + ayni etiket
# sessiz teklenir; farkli etiket / dosya ici mukerrer = cakisma). ovr: SampleID -> dosya kimligi ya da
# EXT_ORIG ("Orijinal etiket kalsin": birey setteki etiketinde kalir -> SAME, kural olmaz).
EXT_ORIG <- "__orig__"
ext_merge <- function(files, ord, ovr, labelmap) {
  on <- ord[vapply(ord, function(k) isTRUE(files[[k]]$on), logical(1))]
  if (!length(on)) return(NULL)
  r <- advi_merge(files, on, ovr[ovr != EXT_ORIG])
  m <- data.frame(SampleID = r$rows$SampleID, Label = r$rows$Label, File = r$rows$F, stringsAsFactors = FALSE)
  known <- unlist(labelmap, use.names = FALSE); olab <- rep(names(labelmap), lengths(labelmap))
  h <- m$SampleID %in% names(ovr)[ovr == EXT_ORIG] & m$SampleID %in% known
  if (any(h)) { m$Label[h] <- olab[match(m$SampleID[h], known)]; m$File[h] <- EXT_ORIG }
  list(res = r, map = m, orig_ids = m$SampleID[h], on = on)
}
# (Ç7-a) bilgi: etiketi DEGISEN bireylerde (CONFLICT) yeni ad birden cok dosyadan geliyor (tek grup
# olur) ya da setteki bir etiketle ayni (o grubun kalan bireyleriyle birlesir). rep satirlari map ile ayni sirada.
ext_info <- function(map, rep, labelmap) {
  nil <- list(multi = character(0), existing = character(0))
  if (is.null(map) || is.null(rep) || !nrow(rep)) return(nil)
  ch <- rep$Status == "CONFLICT" & map$File != EXT_ORIG
  if (!any(ch)) return(nil)
  L <- rep$ExternalLabel[ch]; nf <- tapply(map$File[ch], L, function(v) length(unique(v)))
  list(multi = sort(names(nf)[nf > 1]), existing = sort(unique(L[L %in% names(labelmap)])))
}
# Dosya listesi (oncelik sirasinda) ve dosya ciktilari icin etiketler -- SABIT INGILIZCE.
ext_files_frame <- function(files, ord) {
  if (!length(ord)) return(NULL)
  f <- files[ord]
  data.frame(No = seq_along(ord), Name = vapply(f, function(z) z$name, ""),
             Path = vapply(f, function(z) if (isTRUE(z$drop)) "(dropped in browser; no disk path)" else z$path, ""),
             Md5 = vapply(f, function(z) z$md5 %||% "", ""), Active = vapply(f, function(z) isTRUE(z$on), logical(1)),
             Rows = vapply(f, function(z) nrow(z$df), integer(1)), stringsAsFactors = FALSE)
}
ext_file_tag <- function(id, ord) ifelse(id == EXT_ORIG, "orig", paste0("#", match(id, ord)))
ext_conf_en <- function(x, files, ord, labelmap) {
  c0 <- if (is.null(x)) NULL else x$res$conf
  if (is.null(c0) || !nrow(c0)) return(NULL)
  src <- x$on[c0$Src]; nm <- vapply(files[src], function(z) z$name, "")
  d <- data.frame(SampleID = c0$SampleID, Type = c0$Type, Chosen = c0$Chosen, Source = paste(ext_file_tag(src, ord), nm),
                  Override = ifelse(c0$Ovr, "yes", ""), Options = c0$Options, stringsAsFactors = FALSE)
  h <- d$SampleID %in% x$orig_ids
  if (any(h)) { known <- unlist(labelmap, use.names = FALSE); olab <- rep(names(labelmap), lengths(labelmap))
    d$Chosen[h] <- olab[match(d$SampleID[h], known)]; d$Source[h] <- "original label (kept)"; d$Override[h] <- "yes" }
  d
}

# ---------------------------------------------------------------------------
# v5.9: GRAFIK / MODEL ESLESMESI -- saf yardimcilar
# ---------------------------------------------------------------------------
# meta$stamp v5.9'da eklendi; eski kayitlarda yalnizca meta$time (SS:DD:ss) var.
run_stamp <- function(meta) meta$stamp %||% gsub(":", "", meta$time %||% "000000")
run_choice_label <- function(meta) sprintf("%02d \u00b7 %s%s \u00b7 allsnps=%s \u00b7 p=%s \u00b7 %s", as.integer(meta$no), meta$target,
  if (is.null(meta$model)) "" else paste0(" \u00b7 ", meta$model), meta$mode, fmt(meta$p), meta$time %||% "")
graph_png_name <- function(meta) sprintf("qpadm_%02d_%s%s_%s_%s.png", as.integer(meta$no), gsub("[^A-Za-z0-9]+", "_", meta$target),
  if (is.null(meta$model)) "" else paste0("_", gsub("[^A-Za-z0-9]+", "_", meta$model)), if (identical(meta$mode, "TRUE")) "T" else "F", run_stamp(meta))
run_choices <- function(runs) {
  if (!length(runs)) return(character(0))
  k <- rev(names(runs))
  stats::setNames(k, vapply(k, function(x) run_choice_label(runs[[x]]$meta), character(1)))
}


# ---------------------------------------------------------------------------
# HARICI SANAL .fam/.ind/.txt ETIKET DOSYASI
# ---------------------------------------------------------------------------
# Amac: bir makalenin etiketlerini, orijinal .fam/.ind'e HIC dokunmadan,
# sample ID esleme yoluyla modelde kullanmak.
# Kabul edilen bicimler (sekme VEYA bosluk ayracli, baslik satiri olsun/olmasin):
#   .fam  -> V1 = etiket (FID), V2 = sample ID
#   .ind  -> V1 = sample ID, son sutun = etiket
#   .txt  -> iki sutun; hangisinin ID hangisinin etiket oldugu, bilinen sample
#            ID kumesiyle eslesme sayisina bakilarak OTOMATIK belirlenir.
# v5.9: tum satirlari (mukerrerler dahil, dosya sirasiyla, Line = satir no) okuyan
# cekirdek. Sutunlar METIN okunur: "0012" gibi ID'ler sayiya donusmez, "NA"
# etiketi eksik deger sayilmaz.
# v6.2 (K8): AADR .anno -- baslikli, sekme ayracli. ID sutunu Genetic ID (eski surumlerde Instance/Version ID),
# etiket sutunu Group ID. Line = dosyadaki satir no (baslik 1. satir).
anno_cols <- function(nm) {
  f <- function(pats) { for (p in pats) { i <- grep(p, nm, ignore.case = TRUE); if (length(i)) return(i[1]) }; NA_integer_ }
  id <- f(c("^Genetic ?ID", "^Instance ?ID", "^Version ?ID", "^ID$", "Genetic ?ID", "Instance ?ID"))
  lab <- f(c("^Group ?ID", "^Group ?Label", "Population|PopLabel", "Group"))
  if (is.na(id) || is.na(lab) || id == lab) NULL else list(id = id, lab = lab)
}
read_label_rows <- function(path, known_ids = character(0)) {
  ext <- tolower(tools::file_ext(path))
  if (ext == "anno") {
    df <- utils::read.delim(path, header = TRUE, stringsAsFactors = FALSE, quote = "", check.names = FALSE, comment.char = "",
                            colClasses = "character", na.strings = character(0))
    if (!ncol(df) || !nrow(df)) stop(tr("err_file_empty"))
    cc <- anno_cols(names(df)); if (is.null(cc)) stop(tr("err_anno_group"))
    out <- data.frame(SampleID = trimws(as.character(df[[cc$id]])), Label = trimws(as.character(df[[cc$lab]])),
                      Line = seq_len(nrow(df)) + 1L, stringsAsFactors = FALSE)
    out <- out[nzchar(out$SampleID) & nzchar(out$Label), , drop = FALSE]; rownames(out) <- NULL
    if (!nrow(out)) stop(tr("err_no_valid_row"))
    return(out)
  }
  df <- utils::read.table(path, header = FALSE, stringsAsFactors = FALSE, fill = TRUE,
                          comment.char = "", quote = "", check.names = FALSE,
                          sep = "", strip.white = TRUE, colClasses = "character", na.strings = character(0))
  if (!ncol(df) || !nrow(df)) stop(tr("err_file_empty"))
  # Baslik satiri varsa at (ilk satir bilinen ID icermiyorsa ve tipik basliksa)
  if (nrow(df) > 1) {
    h <- tolower(trimws(as.character(unlist(df[1, ]))))
    if (any(h %in% c("id", "sample", "sampleid", "sample_id", "iid", "fid",
                     "label", "group", "groupid", "pop", "population", "etiket")))
      df <- df[-1, , drop = FALSE]
  }
  pick <- function(id_col, lab_col) data.frame(
    SampleID = trimws(as.character(df[[id_col]])),
    Label    = trimws(as.character(df[[lab_col]])), Line = seq_len(nrow(df)), stringsAsFactors = FALSE)

  out <- if (ext == "fam" && ncol(df) >= 2) pick(2, 1)
    else if (ext == "ind" && ncol(df) >= 2) pick(1, ncol(df))
    else {
      if (ncol(df) < 2) stop(tr("err_two_cols"))
      # .txt: sutunlari bilinen ID kumesiyle karsilastirip otomatik karar ver
      c1 <- trimws(as.character(df[[1]])); c2 <- trimws(as.character(df[[2]]))
      n1 <- if (length(known_ids)) sum(c1 %in% known_ids) else 0
      n2 <- if (length(known_ids)) sum(c2 %in% known_ids) else 0
      if (n2 > n1) pick(2, 1)
      else if (n1 > n2) pick(1, 2)
      else {
        # Karar verilemedi: ID sutunu genelde daha COK benzersiz deger icerir
        if (length(unique(c2)) > length(unique(c1))) pick(2, 1) else pick(1, 2)
      }
    }
  out <- out[nzchar(out$SampleID) & nzchar(out$Label), , drop = FALSE]
  rownames(out) <- NULL
  if (!nrow(out)) stop(tr("err_no_valid_row"))
  out
}

# Harici etiket esleme: ayni ID birden cok kez geciyorsa ILKI kullanilir.
read_external_labels <- function(path, known_ids = character(0)) {
  out <- read_label_rows(path, known_ids)
  out <- out[!duplicated(out$SampleID), c("SampleID", "Label"), drop = FALSE]
  rownames(out) <- NULL
  out
}

# Harici dosya ile orijinal veri setinin karsilastirmasi
# Status sutunu SABIT KOD tutar: "CONFLICT" / "SAME" / "MISSING". Karsilastirmalar
# cevrilmis metne DEGIL bu kodlara bakar (Ders 19). Kodlar yalnizca overlap.txt
# dosyasina yazilir (sabit Ingilizce); ekranda gosterilmedigi icin ceviri
# koprusune gerek yok -- v5.8'de hic cagrilmayan ext_status_label() kaldirildi.
ext_overlap_report <- function(ext_map, labelmap) {
  known <- unlist(labelmap, use.names = FALSE)
  orig_lab <- rep(names(labelmap), lengths(labelmap))
  idx <- match(ext_map$SampleID, known)
  matched <- !is.na(idx)
  df <- data.frame(SampleID = ext_map$SampleID, ExternalLabel = ext_map$Label, OriginalLabel = ifelse(matched, orig_lab[idx], NA_character_), stringsAsFactors = FALSE)
  df$Status <- ifelse(!matched, "MISSING", ifelse(df$ExternalLabel == df$OriginalLabel, "SAME", "CONFLICT"))
  df
}

# Dosya ciktisi -> SABIT INGILIZCE (arayuz dilinden bagimsiz).
# v6.0 ADIM 3 (Ç8): files = ext_files_frame() (oncelik, etkin, md5), conf = ext_conf_en() (dosyalar
# arasi cakismalar). rep$File varsa tabloya kaynak dosya sutunu eklenir (#sira / orig).
write_overlap_txt <- function(rep, file, prefix = "", extfile = "", files = NULL, conf = NULL) {
  n_c <- sum(rep$Status == "CONFLICT"); n_s <- sum(rep$Status == "SAME"); n_m <- sum(rep$Status == "MISSING")
  fl <- if (is.null(files) || !nrow(files)) character(0) else c("External files (priority order; only ACTIVE files are merged):",
    sprintf("  #%d [%s] %s  (%d rows)  md5=%s", files$No, ifelse(files$Active, "active", "off   "), files$Name, files$Rows, files$Md5),
    paste0("        ", files$Path), "")
  L <- c(strrep("=", 78), "qpAdm Studio -- EXTERNAL VIRTUAL LABEL / OVERLAP REPORT (overlap.txt)",
         paste0("Time          : ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")),
         paste0("Genotype      : ", prefix), paste0("External file : ", extfile), strrep("=", 78), "", fl,
         sprintf("Total rows : %d", nrow(rep)),
         sprintf("  CONFLICT (original label will be replaced)   : %d", n_c),
         sprintf("  SAME     (label already identical)           : %d", n_s),
         sprintf("  MISSING  (not in dataset -- UNUSABLE)        : %d", n_m), "",
         "NOTE: your original .fam/.ind file is NEVER modified. Virtual labels are",
         "      applied only in a temporary copy.", "", strrep("-", 78),
         sprintf("%-28s %-26s %-26s %s", "SAMPLE_ID", "EXTERNAL_LABEL", "ORIGINAL_LABEL", "STATUS"),
         strrep("-", 78))
  ord <- order(match(rep$Status, c("CONFLICT", "MISSING", "SAME")), rep$SampleID)
  hf <- !is.null(rep$File)
  if (hf) L[length(L) - 1L] <- paste(L[length(L) - 1L], " FILE")
  for (i in ord) L <- c(L, paste0(sprintf("%-28s %-26s %-26s %s", rep$SampleID[i], rep$ExternalLabel[i], rep$OriginalLabel[i] %||% "-", rep$Status[i]),
                                  if (hf) paste0("  ", rep$File[i]) else ""))
  if (!is.null(conf) && nrow(conf)) {
    L <- c(L, "", strrep("-", 78), sprintf("BETWEEN-FILE CONFLICTS: %d sample IDs (label = different labels across files; dup = repeated in one file)", nrow(conf)),
           "Chosen = global priority unless a row choice (Override = yes) was made.", strrep("-", 78),
           sprintf("%-28s %-10s %-26s %-30s %-8s %s", "SAMPLE_ID", "TYPE", "CHOSEN", "SOURCE", "OVERRIDE", "OPTIONS [file #]"), strrep("-", 78),
           sprintf("%-28s %-10s %-26s %-30s %-8s %s", conf$SampleID, conf$Type, conf$Chosen, conf$Source, conf$Override, conf$Options))
  }
  writeLines(L, file, useBytes = TRUE)
}

# ---------------------------------------------------------------------------
# rcond / matris uyarilarini metne cevir
# ---------------------------------------------------------------------------
RCOND_PAT <- "rcond|ill-condition|singular|reciprocal condition|computationally singular|matris"

collect_rcond <- function(txt) {
  if (!length(txt)) return(character(0))
  hits <- txt[grepl(RCOND_PAT, txt, ignore.case = TRUE)]
  unique(trimws(hits))
}

# ---------------------------------------------------------------------------
# RAW (txt) CIKTI -- secimlerden koda, sonuclardan popdrop ve rcond'a kadar
# ---------------------------------------------------------------------------
qpadm_code_line <- function(target, left, right, allsnps) {
  paste0("qpadm(data, ",
    "left=c(", paste0('"', left, '"', collapse = ", "), "), ",
    "right=c(", paste0('"', right, '"', collapse = ", "), "), ",
    'target="', target, '", allsnps=', allsnps, ")")
}

# Dosya ciktisi -> SABIT INGILIZCE (arayuz dilinden bagimsiz). Bir raporu baska
# bir dilde uretilmis raporla karsilastirabilmek ve arsivlenen basliklarin
# degismemesi icin bu bolum CEVRILMEZ.
build_raw_report <- function(batch, right, left, meta, labelmap, rcond_lines, console_txt, vfam, ext = NULL, sets = NULL, running = NULL) {
  L <- character(0)
  add <- function(...) L <<- c(L, paste0(...))
  hr <- function() add(strrep("=", 78))
  hr(); add("qpAdm Studio -- RAW OUTPUT"); add("Time: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"))
  add("Program: ", QPS_VERSION, "   |   admixtools: ", qps_adx_str(), qps_adx_note())   # v6.4 (madde 3)
  if (length(sets)) add("Sequential models: ", length(sets), " Left sets (same target and right)")   # v6.2 (K9)
  if (!is.null(meta$stopped)) add("STOPPED BY USER: ", meta$stopped, " models finished")   # v6.2 (K1)
  if (!is.null(running)) add("RUN IN PROGRESS: ", running$done, "/", running$total, " models finished when this file was written")   # v6.5 ADIM 3 (madde 5)
  if (!is.null(pm <- meta$pdm)) {   # v6.3 test
    add("PREDEFINED MODEL: ", pm$model, if (nzchar(pm$file %||% "")) paste0("  (file: ", pm$file, ")") else "", if (isTRUE(pm$edited)) "  [edited in the boxes]" else "")
    for (z in pm$iss %||% list()) add("  note: ", pdm_issue_en(z))
    for (z in pm$notes %||% character(0)) add("  note: ", z)
    if (isTRUE(pm$super)) add("  note: f2 pool built with a wider panel than requested")
    if ((pm$rules_n %||% 0) > 0) add("  ", pm$rules_n, " sample(s) relabeled for this run (sample-ID based model)")
    if (isTRUE((pm$group_n %||% 1) > 1) && identical(meta$mode, "FALSE")) add("  shared f2 pool: ", pm$group_n, " models, ", pm$pool_n %||% 0L, " pops")
    for (x in batch) if (!is.null(x$res)) { r <- pdm_ref_en(tryCatch(pdm_ref_compare(pm$ref, x$target, meta$mode, x$p, x$res$weights), error = function(e) NULL)); if (nzchar(r)) add("  ", x$target, ": ", r) } }
  hr(); add("")

  add("## 1. SELECTIONS"); add("")
  add("Target(s): ", paste(unique(vapply(batch, function(x) x$target, character(1))), collapse = ", "))
  if (length(sets)) { add(""); for (k in names(sets)) add("left ", k, " = c(", paste0('"', sets[[k]], '"', collapse = ", "), ")") }
  else { add(""); add("left  = c(", paste0('"', left, '"', collapse = ", "), ")") }
  add(""); add("right = c(", paste0('"', right, '"', collapse = ", "), ")")
  add(""); add("allsnps = ", meta$mode %||% "?", "   |   maxmiss = ", meta$maxmiss %||% "?")
  add("")
  if (!is.null(vfam) && nrow(vfam)) {
    add("## 1b. VIRTUAL LABELS (original file not modified)"); add("")
    for (g in unique(vfam$VirtualLabel)) add("  ", g, "  <=  ", paste(vfam$SampleID[vfam$VirtualLabel == g], collapse = ", "))
    add("")
  }
  # v6.0 ADIM 3 (Ç8): kosu anindaki harici etiket dosyalari (oncelik, etkin, md5) + satir secimi sayisi
  if (!is.null(ext) && !is.null(ext$files) && nrow(ext$files)) {
    add("## 1c. EXTERNAL LABEL FILES (priority order, as at run time)"); add("")
    for (i in seq_len(nrow(ext$files))) { add(sprintf("  #%d [%s] %s  md5=%s", ext$files$No[i], if (ext$files$Active[i]) "active" else "off", ext$files$Name[i], ext$files$Md5[i]))
      add("      ", ext$files$Path[i]) }
    add(sprintf("  Row choices: %d (another file: %d, keep original label: %d)", (ext$n_ovr %||% 0L) + (ext$n_orig %||% 0L), ext$n_ovr %||% 0L, ext$n_orig %||% 0L)); add("")
  }

  add("## 2. RUN CODE"); add("")
  for (x in batch) add("  ", qpadm_code_line(x$target, x$left %||% left, right, meta$mode %||% "FALSE"))
  add("")

  add("## 3. RESULTS"); add("")
  for (x in batch) {
    add(strrep("-", 70)); add("TARGET: ", x$target, if (!is.null(x$model)) paste0("   |   MODEL: ", x$model, "   |   left: ", paste(x$left, collapse = ", ")) else "")
    rcx <- x$rcond %||% character(0)   # v6.5 ADIM 3 (madde 5): hedef basina rcond / matris uyarilari
    rca <- function() if (length(rcx)) { add("  rcond / matrix warnings (", length(rcx), "):"); for (z in rcx) add("    ", z) } else add("  rcond / matrix warnings: none")
    if (is.null(x$res)) { add("  ERROR: ", x$error %||% "unknown"); rca(); add(""); next }
    add(sprintf("  p = %s | dof = %s | chisq = %s | feasible = %s", fmt(x$p), fmt(x$dof), fmt(x$chisq), as.character(x$feasible)))
    add("  SNPs: ", snp_line_en(x$snp)); rca()
    add(""); add("  Weights (weight | se | z):")
    w <- as.data.frame(x$res$weights)
    for (i in seq_len(nrow(w))) add(sprintf("    %-45s %8.4f %8.4f %8.3f", as.character(w$left[i]), w$weight[i], w$se[i], w$z[i]))
    add(""); add("  Nested models (popdrop):")
    pd <- as.data.frame(x$res$popdrop)
    hdr <- paste(names(pd), collapse = "\t"); add("    ", hdr)
    for (i in seq_len(nrow(pd))) add("    ", paste(vapply(pd[i, ], function(v) as.character(v), character(1)), collapse = "\t"))
    add("")
  }

  add("## 4. rcond / MATRIX WARNINGS"); add("")
  if (!is.null(running)) add("  (run in progress: warnings so far; the complete list is written when the run finishes)")
  if (length(rcond_lines)) for (r in rcond_lines) add("  ", r) else add("  (no warnings)")
  add("")

  add("## 5. LABEL -> SAMPLE ID"); add("")
  it <- ids_table(labelmap %||% list(), unique(c(vapply(batch, function(x) x$target, character(1)), left, right)), missing = "(not in file)")
  for (i in seq_len(nrow(it))) add("  ", it$Label[i], "  =>  ", it$SampleIDs[i])
  add("")

  add("## 6. CONSOLE OUTPUT (raw)"); add("")
  if (!is.null(running)) add("  (run in progress: console output so far; the complete output is written when the run finishes)")
  if (length(console_txt)) L <- c(L, console_txt) else add("  (empty)")
  L
}

