load_defaults <- function() {
  d <- if (file.exists(DEF_FILE)) tryCatch(readRDS(DEF_FILE), error = function(e) NULL) else NULL
  if (is.list(d) && is.list(d$right) && is.list(d$left) && length(names(d$right))) return(d)
  list(right = DEFAULT_RIGHT_SETS, left = DEFAULT_LEFT_SETS, png_res = "1280x800")
}
