# Aktif dil (reactive olmayan basit global; sunucu her oturumda ayarlar)
.QPS_LANG <- new.env(parent = emptyenv()); .QPS_LANG$code <- "tr"
set_lang <- function(code) { if (code %in% LANGS) .QPS_LANG$code <- code; invisible(code) }
cur_lang <- function() .QPS_LANG$code %||% "tr"
# Ceviri: eksikse Ingilizce, o da yoksa anahtar
tr <- function(key, lang = cur_lang()) {
  v <- I18N[[key]]
  if (is.null(v)) return(key)
  out <- v[[lang]]
  if (is.null(out) || is.na(out) || !nzchar(out)) out <- v[["en"]]
  if (is.null(out) || is.na(out)) key else out
}
is_rtl <- function(lang = cur_lang()) lang %in% RTL_LANGS


# NOT: bg/fg BILEREK sabitlenmedi. Sabitlenirse acik moda gecince bslib
# data-bs-theme=light yapar ama zemin koyu kalir -> koyu zemin + koyu yazi
# (ornegin "Left" etiketinin gorunmemesi) olur. Varsayilan koyu mod,
# input_dark_mode(mode = "dark") ile ayarlanir.
app_theme <- bs_theme(
  version = 5, preset = "flatly",
  primary = "#0d9488", secondary = "#1e293b",
  success = "#10b981", info = "#3b82f6",
  warning = "#f59e0b", danger = "#ef4444"
)
# NOT: font_google() bilerek KULLANILMADI -- internet yoksa acilista hata/gecikme yapar.

qps_css <- tags$head(
  # Inter fonta INTERNET varsa kullanilir; yoksa sistem fontuna DUSER (offline calisir).
  tags$link(href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap", rel = "stylesheet"),
  tags$style(HTML("
    :root{--qps-primary:#3b82f6;--qps-success:#10b981;--qps-danger:#ef4444;--qps-warn:#f59e0b;
          --qps-bg:#f1f5f9;--qps-card:#ffffff;--qps-border:#cbd5e1;--qps-text:#0f172a;--qps-muted:#475569;
          --qps-inset:#f1f5f9;--qps-accent:#0d9488;}
    [data-bs-theme='dark']{--qps-bg:#0b1220;--qps-card:#1b2740;--qps-border:#3b4d69;--qps-text:#f8fafc;--qps-muted:#b6c2d4;--qps-inset:#0f1a2e;--qps-accent:#5eead4;}
    body{font-family:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:var(--qps-bg);color:var(--qps-text);}
    .card{background:var(--qps-card)!important;border:1px solid var(--qps-border)!important;border-radius:12px!important;
          box-shadow:0 1px 3px rgba(0,0,0,.08)!important;}
    .card-header{background:transparent!important;border-bottom:1px solid var(--qps-border)!important;
                 font-weight:600;letter-spacing:.01em;}
    .navbar{box-shadow:0 1px 3px rgba(0,0,0,.12);}
    /* --- chip / tag sistemi --- */
    .qps-chips{display:flex;flex-wrap:wrap;gap:6px;margin:.35rem 0 .1rem 0;}
    .qps-chip{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;
              font-size:12px;font-weight:500;line-height:1.5;border:1px solid transparent;}
    .qps-chip-t{background:rgba(59,130,246,.12);color:#2563eb;border-color:rgba(59,130,246,.3);}
    .qps-chip-l{background:rgba(16,185,129,.12);color:#059669;border-color:rgba(16,185,129,.3);}
    .qps-chip-r{background:rgba(100,116,139,.14);color:#475569;border-color:rgba(100,116,139,.3);}
    [data-bs-theme='dark'] .qps-chip-t{color:#93c5fd;} [data-bs-theme='dark'] .qps-chip-l{color:#6ee7b7;}
    [data-bs-theme='dark'] .qps-chip-r{color:#cbd5e1;}
    .qps-chip-empty{font-size:12px;color:var(--qps-muted);font-style:italic;}
    .qps-count{font-size:11px;color:var(--qps-muted);font-weight:600;text-transform:uppercase;letter-spacing:.04em;}
    .qps-formula{background:rgba(16,185,129,.08);border-left:3px solid #10b981;padding:.4rem .6rem;margin:.4rem 0;border-radius:4px;}
    /* --- gradient ilerleme cubugu --- */
    .qps-prog-bg{height:24px;border-radius:999px;overflow:hidden;background:rgba(100,116,139,.18);}
    .qps-prog-fill{height:100%;border-radius:999px;transition:width .35s ease;
                   background:linear-gradient(90deg,#f59e0b,#fbbf24);}
    .qps-prog-fill.done{background:linear-gradient(90deg,#10b981,#34d399);}
    .qps-prog-txt{font-size:12px;color:var(--qps-muted);margin-top:5px;}
    /* --- sol border'li stat kartlari --- */
    .qps-stats{display:flex;gap:10px;flex-wrap:wrap;}
    .qps-stat{flex:1;min-width:104px;background:var(--qps-card);border:1px solid var(--qps-border);
              border-left-width:4px;border-radius:10px;padding:8px 12px;}
    .qps-stat .lbl{font-size:11px;color:var(--qps-muted);text-transform:uppercase;letter-spacing:.05em;line-height:1.2;}
    .qps-stat .val{font-size:20px;font-weight:650;line-height:1.25;font-variant-numeric:tabular-nums;}
    .qps-stat .sub{font-size:11px;color:var(--qps-muted);line-height:1.25;margin-top:2px;font-variant-numeric:tabular-nums;}
    .qps-b-blue{border-left-color:#3b82f6;} .qps-b-slate{border-left-color:#64748b;}
    .qps-b-amber{border-left-color:#f59e0b;} .qps-b-green{border-left-color:#10b981;}
    .qps-b-red{border-left-color:#ef4444;}
    /* --- sayisal tablolar --- */
    table.dataTable{font-variant-numeric:tabular-nums;}
    /* --- bildirimleri modern toast gorunumune yaklastir --- */
    #shiny-notification-panel{width:380px;bottom:18px;right:18px;}
    .shiny-notification{border-radius:10px;border:1px solid var(--qps-border);
                        box-shadow:0 6px 20px rgba(0,0,0,.16);padding:12px 34px 12px 14px;opacity:1;}
    .shiny-notification-message{background:var(--qps-card);color:var(--qps-text);border-left:4px solid #3b82f6;}
    .shiny-notification-warning{background:var(--qps-card);color:var(--qps-text);border-left:4px solid #f59e0b;}
    .shiny-notification-error{background:var(--qps-card);color:var(--qps-text);border-left:4px solid #ef4444;}
    /* ---- GORUNURLUK: cikti kutulari (prefix / etiket yolu) ---- */
    pre.shiny-text-output, .shiny-text-output{background:var(--qps-inset)!important;color:var(--qps-text)!important;
      border:1px solid var(--qps-border)!important;border-radius:8px;padding:8px 10px;min-height:38px;
      font-family:'Consolas','Courier New',monospace;font-size:12.5px;white-space:pre-wrap;word-break:break-all;}
    code{background:var(--qps-inset);color:var(--qps-accent);padding:2px 7px;border-radius:6px;
         border:1px solid var(--qps-border);font-size:12.5px;}
    .text-muted{color:var(--qps-muted)!important;}
    .card-header{color:var(--qps-text)!important;font-size:15px;}
    body,.form-label,label,p,li,td,th{color:var(--qps-text);}
    /* ---- GORUNURLUK: outline dugmeler (Konsolu temizle vb.) ---- */
    .btn-outline-secondary{color:var(--qps-text)!important;border-color:var(--qps-border)!important;
                           background:var(--qps-inset)!important;}
    .btn-outline-secondary:hover{background:#334155!important;color:#fff!important;}
    .btn-outline-primary{color:#5eead4!important;border-color:#5eead4!important;background:transparent!important;}
    .btn-outline-primary:hover{background:#0d9488!important;color:#fff!important;}
    .btn-outline-danger{color:#fca5a5!important;border-color:#ef4444!important;background:transparent!important;}
    .btn-outline-danger:hover{background:#ef4444!important;color:#fff!important;}
    /* ---- Klasor secme dugmesi belirgin olsun ---- */
    .qps-dirbtn .btn, .btn.shinyDirectories, button.shinyDirectories{
      border:1px solid var(--qps-accent)!important;background:var(--qps-inset)!important;
      color:var(--qps-text)!important;border-radius:8px;padding:5px 12px;font-weight:500;}
    .qps-dirbtn .btn:hover, button.shinyDirectories:hover{background:#0d9488!important;color:#fff!important;}
    /* ---- Tablolar: sayfaya sigsin ---- */
    table.dataTable{width:100%!important;font-size:12px;}
    table.dataTable td,table.dataTable th{padding:4px 6px!important;white-space:nowrap;
      text-overflow:ellipsis;overflow:hidden;max-width:220px;}
    table.dataTable th{font-size:11.5px;}
    .dataTables_wrapper{color:var(--qps-text);font-size:12px;}
    .dataTables_wrapper .dataTables_filter input,.dataTables_wrapper .dataTables_length select{
      background:var(--qps-inset);color:var(--qps-text);border:1px solid var(--qps-border);border-radius:6px;}
    /* DT: yazi/zemin zitligi -- her tabloda */
    table.dataTable{background:var(--qps-card)!important;color:var(--qps-text)!important;}
    table.dataTable thead th{background:var(--qps-inset)!important;color:var(--qps-text)!important;
      border-bottom:2px solid var(--qps-accent)!important;font-weight:700;}
    table.dataTable tbody td{background:var(--qps-card)!important;color:var(--qps-text)!important;
      border-top:1px solid var(--qps-border)!important;}
    table.dataTable tbody tr.odd td{background:var(--qps-inset)!important;}
    table.dataTable tbody tr:hover td{background:#24406b!important;color:#ffffff!important;}
    [data-bs-theme='light'] table.dataTable tbody tr:hover td{background:#dbeafe!important;color:#0f172a!important;}
    /* DT ust filtre kutulari ve arama */
    table.dataTable thead .form-control,.dataTables_wrapper input[type='search'],
    .dataTables_wrapper .dataTables_filter input,.dataTables_wrapper select{
      background:var(--qps-inset)!important;color:var(--qps-text)!important;border:1px solid var(--qps-border)!important;}
    table.dataTable thead td .form-control::placeholder{color:var(--qps-muted)!important;}
    .dataTables_wrapper .dataTables_info,.dataTables_wrapper .dataTables_length,
    .dataTables_wrapper .dataTables_filter,.dataTables_wrapper .dataTables_paginate{color:var(--qps-text)!important;}
    .dataTables_wrapper .paginate_button{color:var(--qps-text)!important;}
    .dataTables_wrapper .paginate_button.current{background:var(--qps-accent)!important;color:#04231f!important;border-radius:6px;}
    /* feasible / mantiksal degerler */
    .qps-true{color:#10b981!important;font-weight:700;}
    .qps-false{color:#ef4444!important;font-weight:700;}
    /* --- konsol: KOYU zemin + ACIK yesil yazi (kontrast) --- */
    .qps-console{background:#0b1020;border:1px solid #24304d;border-radius:10px;padding:10px;height:420px;overflow:auto;}
    .qps-console pre{background:transparent!important;border:0!important;color:#7CFFB2!important;
                     font-family:'Consolas','Courier New',monospace;font-size:12.5px;line-height:1.45;
                     white-space:pre-wrap;word-break:break-word;margin:0;}
    [data-bs-theme='light'] .qps-console{background:#0b1020;}
    /* sanal etiket rozetleri */
    /* varsayilan/indirme dugmeleri de gorunur olsun */
    .btn-default,.shiny-download-link{background:var(--qps-inset)!important;color:var(--qps-text)!important;
      border:1px solid var(--qps-border)!important;border-radius:8px;}
    .btn-default:hover,.shiny-download-link:hover{background:#334155!important;color:#fff!important;}
    .btn-success .shiny-download-link,.btn-success{color:#fff!important;}
    a.btn.btn-success,a.shiny-download-link.btn-success{background:#10b981!important;border-color:#10b981!important;color:#fff!important;}
    a.shiny-download-link.btn-outline-secondary{background:var(--qps-inset)!important;color:var(--qps-text)!important;}
    /* --- dil secim baglantilari --- */
    .qps-quit:hover,.qps-quit:focus{background:#c0392b;color:#fff!important;border-radius:8px;}
    .qps-langgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px;}
    .qps-lang{display:block;padding:9px 14px;border-radius:10px;text-decoration:none!important;
      background:var(--qps-inset);color:var(--qps-text)!important;border:1px solid var(--qps-border);
      font-size:14px;font-weight:500;transition:.15s;}
    .qps-lang:hover{background:#0d9488;color:#fff!important;border-color:#0d9488;}
    .qps-lang.active{background:#0d9488;color:#fff!important;border-color:#0d9488;font-weight:700;}
    /* --- radyo/checkbox yazilari (Left / Right): HER IKI TEMADA da acikca sabit --- */
    .form-check-label,.form-check-label span,.radio label,.radio span,.checkbox label,
    .shiny-options-group label,.shiny-options-group span,.shiny-input-radiogroup label,
    .shiny-input-radiogroup span,.form-check-input+span,.control-label{
      opacity:1!important;font-weight:500;}
    [data-bs-theme='dark'] .form-check-label,[data-bs-theme='dark'] .form-check-label span,
    [data-bs-theme='dark'] .shiny-options-group label,[data-bs-theme='dark'] .shiny-options-group span,
    [data-bs-theme='dark'] .shiny-input-radiogroup label,[data-bs-theme='dark'] .shiny-input-radiogroup span,
    [data-bs-theme='dark'] .radio label,[data-bs-theme='dark'] .control-label{color:#f8fafc!important;}
    [data-bs-theme='light'] .form-check-label,[data-bs-theme='light'] .form-check-label span,
    [data-bs-theme='light'] .shiny-options-group label,[data-bs-theme='light'] .shiny-options-group span,
    [data-bs-theme='light'] .shiny-input-radiogroup label,[data-bs-theme='light'] .shiny-input-radiogroup span,
    [data-bs-theme='light'] .radio label,[data-bs-theme='light'] .control-label{color:#0f172a!important;}
    /* radyo secenekleri arasi bosluk (inline) */
    .shiny-options-group .form-check{margin-right:18px;display:inline-flex;align-items:center;gap:6px;}
    .shiny-options-group .form-check{margin-right:14px;}
    .form-check-input{background-color:var(--qps-inset);border-color:var(--qps-border);}
    .form-check-input:checked{background-color:#0d9488;border-color:#0d9488;}
    /* --- calistir dugmeleri: TRUE turuncu, FALSE yesil --- */
    #run_true.btn-warning{background:#f59e0b!important;border-color:#f59e0b!important;color:#1a1a1a!important;font-weight:600;}
    #run_true.btn-warning:hover{background:#d97706!important;border-color:#d97706!important;color:#fff!important;}
    #run_false.btn-success{background:#10b981!important;border-color:#10b981!important;color:#08251b!important;font-weight:600;}
    #run_false.btn-success:hover{background:#059669!important;border-color:#059669!important;color:#fff!important;}
    .qps-vbadge{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;font-size:12px;
                background:rgba(245,158,11,.15);color:#b45309;border:1px solid rgba(245,158,11,.35);margin:2px 4px 2px 0;}
    [data-bs-theme='dark'] .qps-vbadge{color:#fcd34d;}
    .qps-kv{font-size:13px;} .qps-kv b{color:var(--qps-muted);font-weight:600;}
  ")))

qps_head <- tags$head(tags$meta(name = "qps-app", content = QPS_VERSION), tags$script(HTML("
    function qpsDim(){Shiny.setInputValue('win_w',window.innerWidth,{priority:'event'});Shiny.setInputValue('dpr',window.devicePixelRatio,{priority:'event'});}
    $(document).on('shiny:connected',qpsDim);$(window).on('resize',qpsDim);
    function qpsVals(id){var el=document.getElementById(id);if(el&&el.selectize){return el.selectize.items.slice();}var v=el?$(el).val():null;return v?[].concat(v):[];}
    function qpsFallback(txt){var ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.top='0';ta.style.left='0';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();var ok=false;try{ok=document.execCommand('copy');}catch(e){ok=false;}document.body.removeChild(ta);return ok;}
    function qpsCopy(id){var vals=qpsVals(id);var txt=vals.join('\\n');var report=function(ok){Shiny.setInputValue('qps_copy',{id:id,n:vals.length,ok:ok,t:Date.now()},{priority:'event'});};if(vals.length===0){report(true);return;}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(function(){report(true);},function(){report(qpsFallback(txt));});}else{report(qpsFallback(txt));}}
    $(document).on('click','#copy_left',function(e){e.preventDefault();qpsCopy('left');});
    $(document).on('click','#copy_right',function(e){e.preventDefault();qpsCopy('right');});
    function qpsCopyList(id,vals){var txt=vals.join('\\n');var report=function(ok){Shiny.setInputValue('qps_copy',{id:id,n:vals.length,ok:ok,t:Date.now()},{priority:'event'});};if(vals.length===0){report(true);return;}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(function(){report(true);},function(){report(qpsFallback(txt));});}else{report(qpsFallback(txt));}}
    $(document).on('click','.qps-copy-vals',function(e){e.preventDefault();var t=String($(this).attr('data-vals')||'');qpsCopyList($(this).attr('data-id'),t?t.split('\\n'):[]);});
    $(document).on('click','.qps-qadd',function(e){e.preventDefault();Shiny.setInputValue('quick_add',{lab:$(this).attr('data-lab'),to:$(this).attr('data-to'),n:Math.random()},{priority:'event'});});
    $(document).on('shiny:value',function(e){if(e.name!=='console_logs')return;var b=document.getElementById('console_out');if(!b)return;var atEnd=(b.scrollHeight-b.scrollTop-b.clientHeight)<40;if(atEnd)setTimeout(function(){b.scrollTop=b.scrollHeight;},0);});
    $(document).on('shown.bs.tab',function(){var b=document.getElementById('console_out');if(b&&$(b).is(':visible'))b.scrollTop=b.scrollHeight;});
  ")))


qps_adv_js <- tags$head(tags$style(HTML("
  .qps-adv-lab{cursor:pointer;border-bottom:1px dashed currentColor;white-space:nowrap;}
  .qps-adv-lab::before{content:'\\25CB';margin-right:5px;opacity:.7;}
  .qps-adv-lab[data-st=part]::before{content:'\\25D0';color:#f59e0b;opacity:1;}
  .qps-adv-lab[data-st=all]::before{content:'\\25CF';color:#10b981;opacity:1;}
  .qps-adv-x{cursor:pointer;color:#ef4444;font-weight:700;padding:0 6px;}
  .qps-adv-st{font-weight:700;}
  .qps-adv-st-p{color:#f59e0b;} .qps-adv-st-v{color:#3b82f6;} .qps-adv-st-c{color:#ef4444;}
  #adv_left input.qps-adv-cb{transform:scale(1.15);cursor:pointer;}
")), tags$script(HTML("
  window.qpsAdv={sel:new Set(),ls:{},api:null,t0:0,
    esc:function(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\\x22/g,'&quot;').replace(/'/g,'&#39;');},
    q:String.fromCharCode(34),
    rTxt:function(d,t){return t==='display'?qpsAdv.esc(d):d;},
    rCb:function(d,t,r){if(t!=='display')return '';var q=qpsAdv.q;return '<input type='+q+'checkbox'+q+' class='+q+'qps-adv-cb'+q+' data-id='+q+qpsAdv.esc(r[1])+q+(qpsAdv.sel.has(r[1])?' checked':'')+'>';},
    rLab:function(d,t){if(t!=='display')return d;var q=qpsAdv.q;return '<span class='+q+'qps-adv-lab'+q+' data-lab='+q+qpsAdv.esc(d)+q+' data-st='+q+qpsAdv.state(d)+q+'>'+qpsAdv.esc(d)+'</span>';},
    rSt:function(d,t){if(t!=='display')return d;if(!d)return '';var q=qpsAdv.q,g={p:'\\u270E',v:'V',c:'\\u26A0'};return '<span class='+q+'qps-adv-st qps-adv-st-'+qpsAdv.esc(d)+q+'>'+(g[d]||qpsAdv.esc(d))+'</span>';},
    rX:function(d,t,r){if(t!=='display')return '';var q=qpsAdv.q;return '<span class='+q+'qps-adv-x'+q+' data-id='+q+qpsAdv.esc(r[1])+q+'>&times;</span>';},
    state:function(l){var s=this.ls&&Object.prototype.hasOwnProperty.call(this.ls,l)?this.ls[l]:'';return s==='all'||s==='part'?s:'none';},
    sync:function(){var s=this;$('#adv_left input.qps-adv-cb').each(function(){this.checked=s.sel.has($(this).attr('data-id'));});$('#adv_left span.qps-adv-lab').each(function(){$(this).attr('data-st',s.state($(this).attr('data-lab')));});},
    attach:function(api){this.api=api;api.on('draw',function(){qpsAdv.sync();});Shiny.setInputValue('adv_ready',Date.now(),{priority:'event'});},
    attachRight:function(api){api.on('draw',function(){qpsAdv.drawn();});},
    drawn:function(){if(!this.t0)return;var ms=Math.round(performance.now()-this.t0);this.t0=0;var el=$('#adv_timing');el.text((el.attr('data-fmt')||'%d ms').replace('%d',ms));},
    apply:function(m){this.sel=new Set(m.ids||[]);this.ls=(m.ls&&!Array.isArray(m.ls))?m.ls:{};this.sync();},
    click:function(m){this.t0=performance.now();m.n=Math.random();Shiny.setInputValue('adv_click',m,{priority:'event'});}
  };
  $(document).on('change','#adv_left input.qps-adv-cb',function(){qpsAdv.click({t:'id',v:$(this).attr('data-id'),on:this.checked});});
  $(document).on('click','#adv_left span.qps-adv-lab',function(){qpsAdv.click({t:'lab',v:$(this).attr('data-lab')});});
  $(document).on('click','#adv_right span.qps-adv-x',function(){qpsAdv.click({t:'id',v:$(this).attr('data-id'),on:false});});
  $(document).on('shiny:connected',function(){Shiny.addCustomMessageHandler('qps_adv_sel',function(m){qpsAdv.apply(m||{});});});
")))

PASTE_EX <- "Pop1,Pop2   |   \"Pop1\",\"Pop2\"   |   right=c(\"Pop1\",\"Pop2\")"

# ---------------------------------------------------------------------------
# UI, secili dile gore YENIDEN kurulur (build_ui). Tum ID'ler sabittir.
# ---------------------------------------------------------------------------
# shinyFiles dugmelerinin varlik blogunu atan sarmalayicilar.
# NOT: shinyFilesButton/shinyDirButton tagList(head_blogu, dugme) dondurur.
# Blogu atmazsak arayuz her yeniden kuruldugunda script tekrar yuklenir ve
# secim penceresi birden fazla kez acilir.
sfb <- function(...) { t <- shinyFilesButton(...); t[[length(t)]] }
sdb <- function(...) { t <- shinyDirButton(...);  t[[length(t)]] }

build_ui <- function(lang = "tr") {
