    # ---------------------------------------------------------------- VERİ
    nav_panel(
      title = tr("tab_data"), value = "data", icon = icon("database"),
      layout_sidebar(
        sidebar = sidebar(title = tr("file_select"), width = 350,
          # v6.1 ADIM 1: Windows'ta yerel dosya penceresi (son klasorde). Pencere yoksa gizli shinyFiles dugmesi.
