            uiOutput("rot_progress_ui"), tags$hr(),
            radioButtons("rot_export_fmt", tr("export_format"), c("Excel" = "xlsx", "CSV" = "csv"), inline = TRUE),
            downloadButton("rot_export", tr("export_valid_failed"), class = "btn-success w-100")))
      ),
      layout_columns(col_widths = c(6, 6),
        card(full_screen = TRUE,
          card_header(div(class = "d-flex gap-2 align-items-center flex-wrap", uiOutput("rot_toggle_ui"))),
          card_body(DTOutput("rot_table")))),
      card(full_screen = TRUE, card_header(tr("rot_chart")),
        card_body(
          div(class = "d-flex gap-2 align-items-center flex-wrap mb-2",
            actionButton("rot_plot", tr("make_graph"), class = "btn-primary btn-sm", icon = icon("chart-column")),
            selectInput("rot_font", NULL, c("Arial", "Calibri", "Georgia", "Times New Roman"), "Arial", width = "160px"),
            dirbtn("rot_dir"),
            actionButton("rot_save_png", tr("save_png"), class = "btn-success btn-sm", icon = icon("download"))),
          div(class = "small text-muted", textOutput("rot_dir_path")),
