  $(document).on('drop','.qps-drop',function(e){e.preventDefault();$(this).removeClass('qps-drop-on');var dt=e.originalEvent.dataTransfer;if(!dt||!dt.files||!dt.files.length)return;
    var kd=$(this).attr('data-kind');if(kd==='geno'||kd==='xset'){var n=[],s=[],m=[],pp=[],dk=new DataTransfer(),gk=0;for(var i=0;i<dt.files.length;i++){var f=dt.files[i];if(kd==='xset'&&!/\\.(bed|bim|fam)$/i.test(f.name)){dk.items.add(f);gk++;continue;}n.push(f.name);s.push(f.size);m.push(f.lastModified);pp.push(f.path||'');}if(n.length)Shiny.setInputValue(kd==='geno'?'geno_drop':'xs_drop',{name:n,size:s,lm:m,p:pp,t:Date.now()},{priority:'event'});if(gk){var kn=[];for(var j=0;j<dk.files.length;j++)kn.push(dk.files[j].name);Shiny.setInputValue('xs_kit_busy',{n:kn,t:Date.now()},{priority:'event'});var ki=document.getElementById('xs_kit_drop');if(ki){ki.files=dk.files;$(ki).trigger('change');}}}
    else{var inp=document.getElementById($(this).attr('data-kind')==='pdm'?'pdm_drop':'ext_drop');if(!inp)return;inp.files=dt.files;$(inp).trigger('change');}});
  $(document).on('keydown','#pdm_tbl td input',function(e){if(e.keyCode===13){e.preventDefault();this.blur();}});
")))

