  /* v6.1 ADIM 2a (K17): arama puani -- R'deki qps_search_score ile AYNI kural. */
  window.qpsScore=function(q){var B='[_.:\\\\s\\\\u2192-]';var esc=function(t){return t.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&');};
    var ks=String(q||'').toLowerCase().trim().split(/\\s+/).filter(function(k,i,a){return k.length&&a.indexOf(k)===i;});
    var rx=ks.map(function(k){var e=esc(k);return {k:k,ex:new RegExp('(^|'+B+')'+e+'($|'+B+')'),pre:new RegExp('(^|'+B+')'+e)};});
    var one=function(v){var sc=0,last=-1,ord=true;for(var i=0;i<rx.length;i++){var p=v.indexOf(rx[i].k);if(p<0)return 0;if(p<=last)ord=false;last=p;sc+=rx[i].ex.test(v)?3:(rx[i].pre.test(v)?2:1);}sc=sc/rx.length;if(rx.length>1&&ord)sc+=0.5;return sc+0.01/Math.max(v.length,1);};
