      if(!it){var box=e.target.closest&&e.target.closest('.selectize-control.multi .selectize-input');if(!box)return;var s0=inst(box);if(!s0||s0.isLocked)return;
        st={s:s0,it:null,rect:true,x:e.clientX,y:e.clientY,ctrl:(e.ctrlKey||e.metaKey),shift:e.shiftKey,was:false,before:s0.$activeItems.slice(),mode:null,tgt:null};return;}
      var s=inst(it);if(!s||s.isLocked)return;
      st={s:s,it:it,x:e.clientX,y:e.clientY,ctrl:(e.ctrlKey||e.metaKey),shift:e.shiftKey,was:$(it).hasClass('active'),before:s.$activeItems.slice(),mode:null,tgt:null};},true);
    document.addEventListener('mousemove',function(e){if(!st)return;if(!(e.buttons&1)){st=null;rubOff();return;}
      if(st.rect){if(!st.mode){if(Math.abs(e.clientX-st.x)+Math.abs(e.clientY-st.y)<5)return;st.mode='rect';st.s.close();rub=document.createElement('div');rub.className='qps-rubber';document.body.appendChild(rub);}
        var x1=Math.min(st.x,e.clientX),y1=Math.min(st.y,e.clientY),x2=Math.max(st.x,e.clientX),y2=Math.max(st.y,e.clientY);
        rub.style.left=x1+'px';rub.style.top=y1+'px';rub.style.width=(x2-x1)+'px';rub.style.height=(y2-y1)+'px';
        var b=st.ctrl?st.before.slice():[];hits(items(st.s),x1,y1,x2,y2).forEach(function(x){if(b.indexOf(x)<0)b.push(x);});setAct(st.s,b);st.s.close();e.preventDefault();return;}
      if(!st.mode){if(Math.abs(e.clientX-st.x)+Math.abs(e.clientY-st.y)<5)return;st.mode=(st.was&&!st.ctrl&&!st.shift)?'move':'sweep';if(st.mode==='move'){setAct(st.s,st.before);$(st.before).addClass('qps-sel-drag');}}
      var el=document.elementFromPoint(e.clientX,e.clientY),all=items(st.s),it=el&&el.closest?el.closest('.item'):null;if(it&&all.indexOf(it)<0)it=null;
      if(st.mode==='sweep'){if(!it)return;var a=all.indexOf(st.it),b=all.indexOf(it),lo=Math.min(a,b),hi=Math.max(a,b),base=st.ctrl?st.before.slice():[];all.slice(lo,hi+1).forEach(function(x){if(base.indexOf(x)<0)base.push(x);});setAct(st.s,base);e.preventDefault();return;}
