      else if(st.shift&&st.before.length){var a=all.indexOf(st.before[st.before.length-1]),c=all.indexOf(it),lo=Math.min(a,c),hi=Math.max(a,c),b2=st.before.slice();all.slice(lo,hi+1).forEach(function(x){if(b2.indexOf(x)<0)b2.push(x);});setAct(s,b2);stop();}
