    function ctxClose(){if(CTX){CTX.remove();CTX=null;}}
    window.qpsCtxClose=ctxClose;
    document.addEventListener('contextmenu',function(e){var it=e.target.closest&&e.target.closest(SEL);if(!it)return;var s=inst(it);if(!s||s.isLocked)return;e.preventDefault();e.stopPropagation();ctxClose();
      var all=items(s),act=s.$activeItems||[],use=(act.indexOf(it)>=0&&act.length)?act.slice():[it];use.sort(function(a,b){return all.indexOf(a)-all.indexOf(b);});
      var vals=use.map(function(x){return x.getAttribute('data-value');}),id=s.$input.attr('id');
