      var grp=vals.filter(function(v){return !IND[v];});
      if(SPLIT.indexOf(id)>=0&&grp.length)add('split',function(){Shiny.setInputValue('qps_sel_split',{id:id,v:grp,n:Math.random()},{priority:'event'});});
      document.body.appendChild(m);var w=m.offsetWidth,h=m.offsetHeight;m.style.left=Math.max(0,Math.min(e.clientX,window.innerWidth-w-4))+'px';m.style.top=Math.max(0,Math.min(e.clientY,window.innerHeight-h-4))+'px';CTX=m;},true);
    document.addEventListener('mousedown',function(e){if(CTX&&!CTX.contains(e.target))ctxClose();},true);
