    info <- input$qps_copy; if (is.null(info)) return()
    nm <- if (identical(info$id, "left")) "Left" else if (identical(info$id, "right")) "Right" else if (identical(info$id, "pdm")) tr("pdm_title") else k4_box_name(info$id %||% "")   # v6.2 (K2) + v6.3 test
    if (isTRUE(info$n == 0)) { showNotification(sprintf(tr("msg_copy_empty"), nm), type = "warning"); return() }
    if (isTRUE(info$ok)) showNotification(sprintf(tr("msg_copy_ok"), nm, info$n), type = "message")
    else showNotification(sprintf(tr("msg_copy_fail"), nm), type = "error", duration = 8)
  })

  # v6.2 (K2): sag tik menusunun metinleri (dil degisince), bireylere ayrilabilen kutular ve bireysel girdiler.
  observe({ lang_rv(); session$sendCustomMessage("qps_ctx_cfg", list(lab = list(copy = tr("ctx_copy"), remove = tr("ctx_remove"), split = tr("ctx_split")), split = as.list(setdiff(names(K4_BOXES), K3_SINGLE)))) })
  observe({ e <- rv$split_ent %||% SPLIT_EMPTY; session$sendCustomMessage("qps_ctx_cfg", list(ind = as.list(e$VirtualLabel))) })
  # Menuden "Bireylere ayir": yalniz tiklanan etiket(ler) kutuda yerinde bireysel girdilere acilir (anahtar gerekmez).
  observeEvent(input$qps_sel_split, safe_run({
    m <- input$qps_sel_split; id <- as.character(m$id %||% ""); vals <- as.character(unlist(m$v))
    if (!id %in% setdiff(names(K4_BOXES), K3_SINGLE)) return()   # v6.2 (K3): butun coklu kutular
    grp <- setdiff(intersect(vals, rv$labels), split_reg()$VirtualLabel)
    if (!length(grp)) { showNotification(tr("msg_split_none"), type = "warning"); return() }
    r <- split_expand(isolate(input[[id]]) %||% character(0), grp, rv$labelmap, split_reg(), unique(c(rv$labels, split_reg()$VirtualLabel)))
    rv$split_ent <- r$reg
    updateSelectizeInput(session, id, choices = rv$labels, selected = r$value, server = TRUE)
    nw <- utils::tail(r$reg, r$added); rn <- nw$VirtualLabel[nw$Renamed]
    if (length(rn)) showNotification(sprintf(tr("split_renamed"), length(rn), paste(utils::head(rn, 3), collapse = ", ")), type = "warning", duration = 10)
  }, tr("ctx_split")))

  # v6.0 (K15): "Tumunu degistir" mevcut listeyi yapistirilanla DEGISTIRIR; canli sayac
  output$paste_count <- renderText({
    lang_rv(); toks <- parse_pops(input$paste_text %||% "")
    if (!length(toks)) return("")
    sprintf(tr("paste_count"), length(toks), sum(toks %in% c(rv$labels, split_reg()$VirtualLabel)))
  })
  paste_apply <- function(replace) {
    toks <- parse_pops(input$paste_text)
    if (!length(toks)) { showNotification(tr("msg_paste_fail"), type = "warning"); return() }
    sv <- sel_check(toks); present <- sv$ok; missing <- sv$miss; tgt <- input$paste_target
    cur <- if (tgt == "left") input$left else input$right
    set_sel(tgt, if (isTRUE(replace)) present else union(cur, present))
    msg <- sprintf(tr("msg_paste_added"), length(present))
    if (length(missing)) msg <- paste0(msg, sprintf(tr("msg_paste_missing"), paste(head(missing, 8), collapse = ", ")))
    showNotification(msg, type = if (length(missing)) "warning" else "message", duration = 8)
  }
  observeEvent(input$paste_add, paste_apply(FALSE))
  observeEvent(input$paste_replace, paste_apply(TRUE))

  # v6.0 (K14): Veri sekmesi etiket tablosundan Hizli ekle (+Target / +Left / +Right).
  # Model sekmesine hic girilmediyse ilk girisin kutuyu bosaltmamasi icin pop_done isaretlenir.
  observeEvent(input$quick_add, {
    q <- input$quick_add; lab <- as.character(q$lab %||% ""); to <- as.character(q$to %||% "")
    if (!to %in% c("target", "left", "right") || !lab %in% rv$labels) return()
    set_sel(to, union(input[[to]], lab)); pop_done(union(pop_done(), to))
    showNotification(sprintf(tr("msg_quick_added"), lab, switch(to, target = "Target", left = "Left", right = "Right")), type = "message", duration = 4)
  })

  # ---- Ara ve seç: etiket + sample ID (tek kutu, ind+fam) ----
  # v6.2 (K3): ID satiri yalniz o bireyi (bireysel girdi), etiket satiri etiketi ekler.
  observeEvent(input$s3_target, { sel <- sel_valid(input$s3_pick)
    if (length(sel)) updateSelectizeInput(session, "target", choices = rv$labels, selected = union(input$target, sel), server = TRUE) })
  observeEvent(input$s3_left,  { sel <- sel_valid(input$s3_pick)
    if (length(sel)) set_sel("left",  union(input$left, sel)) })
  observeEvent(input$s3_right, { sel <- sel_valid(input$s3_pick)
    if (length(sel)) set_sel("right", union(input$right, sel)) })

  # ---- Set yonetimi ----
  observeEvent(input$rset_edit, { s <- rv$right_sets[[input$rset_edit]] %||% character(0)
    updateTextInput(session, "rset_name", value = input$rset_edit)
    sv <- sel_check(s); updateSelectizeInput(session, "rset_pick", choices = rv$labels, selected = sv$ok, server = TRUE)
    updateTextAreaInput(session, "rset_content", value = paste(sv$miss, collapse = "\n")) })
  observeEvent(input$lset_edit, { s <- rv$left_sets[[input$lset_edit]] %||% character(0)
    updateTextInput(session, "lset_name", value = input$lset_edit)
    sv <- sel_check(s); updateSelectizeInput(session, "lset_pick", choices = rv$labels, selected = sv$ok, server = TRUE)
    updateTextAreaInput(session, "lset_content", value = paste(sv$miss, collapse = "\n")) })

  observeEvent(input$rset_save, {
    old <- input$rset_edit; newname <- trimws(input$rset_name); if (!nzchar(newname)) newname <- old
    sets <- rv$right_sets; content <- union(input$rset_pick %||% character(0), parse_pops(input$rset_content))
    if (!identical(newname, old)) sets[[old]] <- NULL
    sets[[newname]] <- content; rv$right_sets <- sets; save_defaults(); refresh_sets()
    updateSelectInput(session, "rset_edit", selected = newname); showNotification(tr("msg_rset_saved"), type = "message")
  })
  observeEvent(input$lset_save, {
    old <- input$lset_edit; newname <- trimws(input$lset_name); if (!nzchar(newname)) newname <- old
    sets <- rv$left_sets; content <- union(input$lset_pick %||% character(0), parse_pops(input$lset_content))
    if (!identical(newname, old)) sets[[old]] <- NULL
    sets[[newname]] <- content; rv$left_sets <- sets; save_defaults(); refresh_sets()
    updateSelectInput(session, "lset_edit", selected = newname); showNotification(tr("msg_lset_saved"), type = "message")
  })
  observeEvent(input$rset_addnew, { sets <- rv$right_sets; n <- length(sets) + 1; nm <- sprintf("Right seti %d", n)
    while (nm %in% names(sets)) { n <- n + 1; nm <- sprintf("Right seti %d", n) }
    sets[[nm]] <- character(0); rv$right_sets <- sets; save_defaults(); refresh_sets()
    updateSelectInput(session, "rset_edit", selected = nm); showNotification(tr("msg_rset_added"), type = "message") })
  observeEvent(input$lset_addnew, { sets <- rv$left_sets; n <- length(sets) + 1; nm <- sprintf("Left seti %d", n)
    while (nm %in% names(sets)) { n <- n + 1; nm <- sprintf("Left seti %d", n) }
    sets[[nm]] <- character(0); rv$left_sets <- sets; save_defaults(); refresh_sets()
    updateSelectInput(session, "lset_edit", selected = nm); showNotification(tr("msg_lset_added"), type = "message") })

  # ---- Calistir (tek/toplu) ----
  # v6.1 ADIM 2b: bolme acikken once yuk uyarisi (split_confirm), "Devam et" -> launch_run(mode, confirmed = TRUE).
  split_pend <- reactiveVal(NULL)
  split_prefix <- function(vf) tryCatch({
      bd <- vfam_base_dir(rv$prefix, CACHE_BASE)
      build_vfam_prefix(rv$prefix, vf, bd, allow_copy = isTRUE(input$vfam_allow_copy))
    }, error = function(e) { showNotification(paste0(tr("msg_vfam_build_fail"), ": ", conditionMessage(e)), type = "error", duration = NULL); NULL })
  split_confirm <- function(mode, sp, left, right, nt_all = nrow(sp)) {
    fs <- geno_fileset(rv$prefix); gb <- if (is.null(fs)) NA_real_ else file.size(unname(fs$files[1]))
    ld <- split_load(nt_all, length(unique(c(left, right))), rv$snp_total, gb)
    nt <- length(unique(sp$OriginalLabel)); n <- nrow(sp)
    body <- if (identical(mode, "allsnps_true"))
      sprintf(tr("split_true"), if (is.na(ld$sec_t)) "?" else fmt_dur(ld$sec_t))   # v6.5: tek gecis
    else sprintf(tr("split_false"), ld$P, fmt_bytes(ld$ram), fmt_bytes(ld$disk))
    rn <- sp$VirtualLabel[sp$Renamed]
    split_pend(list(mode = mode))
    showModal(modalDialog(title = tr("split_title"), easyClose = FALSE,
      p(tags$strong(sprintf(tr("split_body"), nt, n, nt_all))), p(body),
      if (length(rn)) p(class = "text-warning", sprintf(tr("split_renamed"), length(rn), paste(utils::head(rn, 3), collapse = ", "))),
      p(class = "small text-muted", tr("split_stop")),
      footer = tagList(modalButton(tr("ow_cancel")), actionButton("split_go", tr("split_go"), class = "btn-warning"))))
  }
  observeEvent(input$split_go, { m <- split_pend(); split_pend(NULL); removeModal()
    if (!is.null(m)) safe_run(launch_run(m$mode, confirmed = TRUE), if (identical(m$mode, "allsnps_true")) "qpAdm (allsnps=TRUE)" else "qpAdm (allsnps=FALSE)") })
  # v6.1 DUZELTME (notlar 8-9): anahtar acikken Target'taki ve eklenen grup etiketleri kutuda bireysel girdilere acilir.
  split_apply <- function(v) {
    if (any(grepl("\u0001", v %||% character(0), fixed = TRUE))) return(invisible(FALSE))   # v6.2 (K3): once ind_resolve
    r <- split_expand(v, rv$labels, rv$labelmap, split_reg(), unique(c(rv$labels, isolate(input$left), isolate(input$right))))
    if (identical(r$value, as.character(v %||% character(0)))) return(invisible(FALSE))
    rv$split_ent <- r$reg
    updateSelectizeInput(session, "target", choices = tgt_choices(rv$labels), selected = r$value, server = TRUE)
    nw <- utils::tail(r$reg, r$added); rn <- nw$VirtualLabel[nw$Renamed]
    if (length(rn)) showNotification(sprintf(tr("split_renamed"), length(rn), paste(utils::head(rn, 3), collapse = ", ")), type = "warning", duration = 10)
    invisible(TRUE)
  }
  observeEvent(input$target, { if (isTRUE(input$split_ind)) split_apply(input$target) }, ignoreNULL = FALSE)
  observeEvent(input$split_ind, { if (isTRUE(input$split_ind)) split_apply(isolate(input$target)) }, ignoreInit = TRUE)
  output$split_info <- renderText({ lang_rv(); v <- input$target %||% character(0); e <- rv$split_ent %||% SPLIT_EMPTY
    k <- v[v %in% e$VirtualLabel]; if (!length(k)) return("")
    sprintf(tr("split_info"), length(unique(e$OriginalLabel[e$VirtualLabel %in% k])), length(k), length(v)) })

  # ---- v6.2 (K9): Sirali model ----
  # Ayni Target ve Right; listedeki Left setleri sirayla (set basina bir model, anahtar M01, M02, ...). Liste oturum
  # boyunca kalir (anahtar kapaninca silinmez). Kip acikken Target tek secimli (yeni secim oncekinin yerine gecer) ve
  # "Etiketi bireylere ayir" pasif; birden cok target secili iken anahtar pasif.
  k9 <- new.env(parent = emptyenv()); k9$prev <- character(0)
  seq_keys <- function() vapply(rv$seq_sets %||% list(), seq_key, character(1))
  observe({ lang_rv(); v <- input$target; on <- isTRUE(input$seq_on)
    session$sendCustomMessage("qps_k9_dis", list(seq = !on && length(v) > 1, split = on)) })
  observeEvent(input$seq_on, {
    if (!isTRUE(input$seq_on)) return()
    if (length(input$target) > 1) { update_switch("seq_on", value = FALSE); showNotification(tr("k9_multi"), type = "warning", duration = 6); return() }
    if (isTRUE(input$split_ind)) { update_switch("split_ind", value = FALSE); showNotification(tr("k9_split_off"), type = "warning", duration = 6) }
    v <- as.character(input$left %||% character(0))
    if (length(v) && !length(rv$seq_sets) && !any(grepl("\u0001", v, fixed = TRUE))) rv$seq_sets <- list(v)
  }, ignoreInit = TRUE)
  observeEvent(input$target, {
    v <- as.character(input$target %||% character(0)); prev <- k9$prev; k9$prev <- v
    if (!isTRUE(input$seq_on) || length(v) <= 1 || any(grepl("\u0001", v, fixed = TRUE))) return()
    nw <- setdiff(v, prev); keep <- if (length(nw)) nw[length(nw)] else v[length(v)]
    k9$prev <- keep; set_sel("target", keep)
  }, ignoreNULL = FALSE)
  observeEvent(input$split_ind, { if (isTRUE(input$split_ind) && isTRUE(input$seq_on)) {
    update_switch("split_ind", value = FALSE); showNotification(tr("k9_split_off"), type = "warning", duration = 6) } }, ignoreInit = TRUE)
  output$seq_info <- renderText({ lang_rv(); if (!isTRUE(input$seq_on)) return(""); sprintf(tr("k9_info"), length(rv$seq_sets %||% list())) })
  observeEvent(input$seq_add, {
    v <- as.character(input$left %||% character(0)); if (any(grepl("\u0001", v, fixed = TRUE))) v <- sel_valid(v)
    if (!length(v)) { showNotification(tr("k9_add_empty"), type = "error", duration = 5); return() }
    if (seq_key(v) %in% seq_keys()) { showNotification(tr("k9_dup"), type = "warning", duration = 5); return() }
    rv$seq_sets <- c(rv$seq_sets %||% list(), list(v)); n <- length(rv$seq_sets)
    showNotification(sprintf(tr("k9_added"), n, length(v)), type = "message", duration = 3)
    ov <- intersect(v, input$right %||% character(0))
    if (length(ov)) showNotification(sprintf(tr("k9_ov_right"), n, paste(ov, collapse = ", ")), type = "warning", duration = 10)
  })
  observeEvent(input$seq_act, { a <- as.character(input$seq_act$a %||% ""); i <- suppressWarnings(as.integer(input$seq_act$i)); s <- rv$seq_sets %||% list()
    if (length(i) != 1 || is.na(i) || i < 1 || i > length(s)) return()
    if (identical(a, "load")) set_sel("left", s[[i]])
    else if (identical(a, "del")) rv$seq_sets <- s[-i]
    else if (identical(a, "up") && i > 1) { s[c(i - 1, i)] <- s[c(i, i - 1)]; rv$seq_sets <- s }
    else if (identical(a, "down") && i < length(s)) { s[c(i, i + 1)] <- s[c(i + 1, i)]; rv$seq_sets <- s }
  })
  output$seq_list_ui <- renderUI({ lang_rv(); s <- rv$seq_sets %||% list()
    if (!length(s)) return(div(class = "small text-muted", tr("k9_empty")))
    cur <- seq_key(input$left %||% character(0))
    btn <- function(a, i, ic, ttl, dis = FALSE) tags$button(type = "button", class = "btn btn-sm btn-outline-secondary py-0 px-1", title = ttl,
      disabled = if (dis) NA else NULL, `data-a` = a, `data-i` = i,
      onclick = sprintf("Shiny.setInputValue('seq_act',{a:'%s',i:%d,n:Math.random()},{priority:'event'})", a, i), icon(ic))
    tags$ol(class = "ps-4 mb-0", id = "qps_seq_list", lapply(seq_along(s), function(i) tags$li(class = "mb-1", style = if (identical(seq_key(s[[i]]), cur)) "font-weight:600;" else NULL,
      div(class = "d-flex align-items-start gap-1",
        div(class = "flex-grow-1 small", tags$b(sprintf("M%02d", i)), sprintf(" (%d): ", length(s[[i]])), paste(s[[i]], collapse = ", ")),
        btn("load", i, "upload", tr("k9_load")), btn("up", i, "arrow-up", tr("k9_up"), i == 1),
        btn("down", i, "arrow-down", tr("k9_down"), i == length(s)), btn("del", i, "trash", tr("k9_del"))))))
  })
  output$seq_note <- renderUI({ lang_rv(); if (!isTRUE(input$seq_on)) return(NULL); s <- rv$seq_sets %||% list(); v <- input$left %||% character(0)
    tagList(div(class = "small mt-1 fw-bold", sprintf(tr("k9_run_n"), length(s))),
      if (length(v) && !(seq_key(v) %in% seq_keys())) div(class = "small text-warning", icon("triangle-exclamation"), " ", tr("k9_note")))
  })
  seq_confirm <- function(mode, nmod, pops) {
    fs <- geno_fileset(rv$prefix); gb <- if (is.null(fs)) NA_real_ else file.size(unname(fs$files[1]))
    ld <- split_load(0, length(pops), rv$snp_total, gb)
    body <- if (identical(mode, "allsnps_true"))
      sprintf(tr("k9_load_true"), if (is.na(ld$sec_t)) "?" else fmt_dur(ld$sec_t))   # v6.5: tek gecis
    else sprintf(tr("k9_load_false"), ld$P, fmt_bytes(ld$ram), fmt_bytes(ld$disk))
    split_pend(list(mode = mode))
    showModal(modalDialog(title = tr("k9_load_title"), easyClose = FALSE,
      p(tags$strong(sprintf(tr("k9_load_body"), nmod, length(pops)))), p(body), p(class = "small text-muted", tr("split_stop")),
      footer = tagList(modalButton(tr("ow_cancel")), actionButton("split_go", tr("split_go"), class = "btn-warning"))))
  }

  # ---- v6.2 (K1): biten modeller sirayla ----
  # Arka plan sureci her isi bitirince sonucunu <resdir>/<k>.rds'e (gecici addan yeniden adlandirarak; yarim dosya
  # okunmaz) yazar ve "QPS_DONE k" basar; gozlemci yeni sonuclari ekler (fin_add). Ilk basarili sonuc gosterilir ve
  # Sonuclar'a gecilir; sonrakiler listeye/tabloya eklenir, ekran atlamaz. Durdur ya da hata: diskteki bitmis sonuclar
  # okunur ve korunur (k1_partial). Isler: list(key, t, left, model, tag); toplu kosuda hedef basina (key = hedef),
  # sirali modelde Left seti basina (key = M01, M02, ...). allsnps=TRUE'da hedef SNP sayimi kosu sonunda yapildigi
  # icin o deger bitiste tamamlanir (finalize).
  k1 <- new.env(parent = emptyenv()); k1$closed <- TRUE
  k1_init <- function(jobs, kind = "batch", sets = NULL, resdir = NULL, tcache = list()) {
    k1$jobs <- jobs; k1$seen <- rep(FALSE, length(jobs)); k1$nm <- rep(NA_character_, length(jobs)); k1$bid <- NULL
    k1$opened <- FALSE; k1$closed <- FALSE; k1$resdir <- resdir; k1$kind <- kind; k1$sets <- sets
    k1$pst <- NULL; k1$ptgt <- list(); k1$tcache <- tcache; k1$tsv <- NULL; k1$tdone <- FALSE   # v6.3 (S6)
    rv$k1_n <- list(done = 0L, total = length(jobs), running = TRUE)
  }
  k1_read_log <- function() if (!is.null(rv$logf) && file.exists(rv$logf)) tryCatch(readLines(rv$logf, warn = FALSE), error = function(e) character(0)) else character(0)
  k1_snp <- function(k, t, md, raw_lg) {
    pend <- rv$pending
    if (identical(md, "TRUE")) {
      nn <- parse_f4_snp_table(log_job_segments(raw_lg)[[as.character(k)]] %||% character(0)); kk <- pend$tsnp_keys[[t]] %||% NA_character_
      tv <- if (!is.na(kk) && !is.null(k1$tcache[[kk]])) k1$tcache[[kk]]$n else if (is.null(k1$tsv)) NA_real_ else unname(k1$tsv[t])
      if (!isTRUE(is.finite(tv)) && length(raw_lg)) { tl <- grep("^QPS_TSNP [0-9]+ ", raw_lg, value = TRUE)   # v6.5: tek geciste sayildi
        if (length(tl)) { nm <- sub("^QPS_TSNP [0-9]+ ", "", tl); if (t %in% nm) tv <- as.numeric(sub("^QPS_TSNP ([0-9]+) .*$", "\\1", tl[match(t, nm)])) } }
      si <- list(basis = "f4", used = if (length(nn)) mean(nn) else NA_real_, used_min = if (length(nn)) min(nn) else NA_real_,
           used_max = if (length(nn)) max(nn) else NA_real_, n_f4 = length(nn), target = as.numeric(tv %||% NA_real_))
      # v6.3 (S6): hedef bu kosuda sayilacak ve sayim henuz bitmedi
      if (!isTRUE(k1$tdone) && t %in% (pend$tsnp_need %||% character(0)) && !isTRUE(is.finite(si$target))) si$pending <- TRUE
      si
    } else {
      if (is.null(k1$pst)) k1$pst <- if (!is.null(pend$f2dir)) pool_stats(pend$f2dir) else list(nsnp = NA_real_)
      if (is.null(k1$ptgt[[t]])) k1$ptgt[[t]] <- pool_target_snps(pend$f2dir, t)
      list(basis = if (isTRUE((pend$maxmiss %||% 0) > 0)) "pool_le" else "pool", used = as.numeric(k1$pst$nsnp %||% NA_real_),
           used_min = NA_real_, used_max = NA_real_, n_f4 = NA_integer_, target = k1$ptgt[[t]])
    }
  }
  fin_add <- function(k, r, raw_lg) {
    pend <- rv$pending; jb <- k1$jobs[[k]]; t <- jb$t; now <- Sys.time()
    md <- if (identical(pend$mode, "allsnps_true")) "TRUE" else "FALSE"
    # v6.0 (D3-b): her toplu kosu kendi kaydini tutar (sonuclar, secimler, rcond, sikistirilmis log, o anki sanal
    # etiketler ve etiket eslemesi). v6.2 (K1): kayit ilk sonucla acilir, sonuclar geldikce eklenir.
    if (is.null(k1$bid) || is.null(rv$batches[[k1$bid]])) {
      k1$bid <- local({ n <- suppressWarnings(as.integer(sub("^b", "", names(rv$batches)))); sprintf("b%03d", max(c(0L, n), na.rm = TRUE) + 1L) })   # v6.3 test
      lm <- pend$lm %||% c(rv$labelmap %||% list(), pend$split$map); labs_b <- unique(c(vapply(k1$jobs, function(j) j$t, character(1)), unlist(lapply(k1$jobs, function(j) j$left)), pend$left, pend$right))   # v6.3 test2 (S2): + butun islerin Left'leri
      rv$batches[[k1$bid]] <- list(batch = list(), right = pend$right, left = pend$left, kind = k1$kind, sets = k1$sets, rcond = character(0), log = character(0),
        vfam = pend$vfam %||% rv$vfam, labelmap = lm[intersect(labs_b, names(lm))], ext = pend$ext,
        meta = list(mode = md, maxmiss = pend$maxmiss, prefix = pend$prefix, time = format(now, "%Y-%m-%d %H:%M:%S"), n = length(k1$jobs), pdm = pend$pdm))
    }
    bid <- k1$bid; k1$seen[k] <- TRUE
    if (inherits(r, "error")) {
      x <- list(target = t, model = jb$model, left = jb$left, res = NULL, error = conditionMessage(r),
                rcond = rv$rcond[grepl(sprintf("[%s]", jb$tag), rv$rcond, fixed = TRUE)])
    } else {
      s <- qpadm_fullmodel(r, jb$left); rc_t <- attr(r, "qps_rcond") %||% character(0); si <- k1_snp(k, t, md, raw_lg)
      # v6.3 (S8): admixtools'un C++ uyarilari ("solve(): system is singular ...") R kosulu degil; o isin konsol satirlari da
      rc_c <- collect_rcond(log_job_segments(raw_lg)[[as.character(k)]] %||% character(0)); rc_t <- unique(c(rc_t, rc_c[!grepl("^QPS_", rc_c)]))
      x <- list(target = t, model = jb$model, left = jb$left, res = r, p = s$p, dof = s$dof, chisq = s$chisq, feasible = s$feasible, rcond = rc_t, snp = si)
      # v6.0 (K5): R oturumu gibi okunur dokum (tum satir/sutun)
      console_add(tryCatch(result_transcript(qpadm_code_line(t, jb$left, pend$right, md), r), error = function(e) paste("transcript ERROR:", conditionMessage(e))))
      console_add(sprintf("SNPs [%s]: %s", jb$tag, snp_line_en(si)), "")
      idx <- max(c(0L, vapply(rv$runs, function(z) as.integer(z$meta$no %||% 0L), 1L))) + 1L   # v6.3 test
      nm <- if (is.null(jb$model)) sprintf("%02d_%s_%s", idx, t, if (md == "TRUE") "T" else "F") else sprintf("%02d_%s_%s_%s", idx, t, jb$model, if (md == "TRUE") "T" else "F")
      rv$runs[[nm]] <- list(res = r, right = pend$right, left = jb$left, rcond = rc_t, batch = bid, snp = si, meta = list(
        no = idx, target = t, model = jb$model, mode = md,
        p = s$p, feasible = s$feasible, chisq = s$chisq, dof = s$dof, maxmiss = pend$maxmiss,
        time = format(now, "%H:%M:%S"), stamp = format(now, "%Y%m%d_%H%M%S"), pdm = pend$pdm))
      k1$nm[k] <- nm
    }
    b <- rv$batches[[bid]]; b$batch[[jb$key]] <- x; rv$batches[[bid]] <- b
    rv$k1_n <- list(done = sum(k1$seen), total = length(k1$jobs), running = !isTRUE(k1$closed))
    # yalniz ilk sonuc kendiliginden acilir; sonrakiler ekrani degistirmez
    if (!is.na(k1$nm[k]) && !isTRUE(k1$opened)) { k1$opened <- TRUE; rv$bt_sel <- NULL; rv$graph_pick <- k1$nm[k]; nav_select("main_nav", "results") }   # v6.5: yeni kosu -> tablo kosunun
    invisible(NULL)
  }
  fin_close <- function(raw_lg, stopped = FALSE) {
    k1$closed <- TRUE; n <- rv$k1_n; if (!is.null(n)) { n$running <- FALSE; rv$k1_n <- n }
    pend <- rv$pending; bid <- k1$bid; if (is.null(bid) || is.null(rv$batches[[bid]])) return(invisible(NULL))
    b <- rv$batches[[bid]]; b$rcond <- rv$rcond; b$log <- tryCatch(log_view(raw_lg), error = function(e) character(0))
    if (isTRUE(stopped)) b$meta$stopped <- sprintf("%d/%d", sum(k1$seen), length(k1$jobs))
    rv$batches[[bid]] <- b
    rv$batch <- b$batch; rv$right <- pend$right; rv$left <- pend$left
    okk <- Filter(function(x) !is.null(x$res), b$batch)
    rv$res <- if (length(okk)) okk[[length(okk)]]$res else NULL
    rv$mode <- if (length(b$batch) > 1) "batch" else "single"
    invisible(NULL)
  }
  k1_poll <- function(txt) {
    if (is.null(k1$jobs) || isTRUE(k1$closed) || is.null(k1$resdir)) return(invisible(0L))
    dn <- suppressWarnings(as.integer(sub("^QPS_DONE ([0-9]+).*$", "\\1", txt[grepl("^QPS_DONE [0-9]+", txt)])))
    new <- sort(setdiff(dn[is.finite(dn) & dn >= 1 & dn <= length(k1$jobs)], which(k1$seen)))
    if (!length(new)) return(invisible(0L))
    flush_pool_meta()   # havuz ilk sonuctan once hazirdir
    for (k in new) { r <- tryCatch(readRDS(file.path(k1$resdir, sprintf("%04d.rds", k))), error = function(e) NULL)
      if (!is.null(r)) fin_add(k, r, txt) }
    invisible(length(new))
  }
  # Durdur / hata: diskte bitmis sonuclar okunur, kayit kapatilir. Doner: korunan (basarili) model sayisi.
  # v6.3 (S6): Durdur/hata -- hedef SNP sayimi yapilmayacak; eklenmis kayitlardaki "sayiliyor" isareti kalkar.
  k1_unpend <- function() {
    k1$tdone <- TRUE; nms <- k1$nm[!is.na(k1$nm)]; rr <- rv$runs; ch <- FALSE
    for (nm in nms) if (isTRUE(rr[[nm]]$snp$pending)) { rr[[nm]]$snp$pending <- NULL; ch <- TRUE }
    if (ch) rv$runs <- rr
    if (!is.null(k1$bid) && !is.null(b <- rv$batches[[k1$bid]])) { cb <- FALSE
      for (key in names(b$batch)) if (isTRUE(b$batch[[key]]$snp$pending)) { b$batch[[key]]$snp$pending <- NULL; cb <- TRUE }
      if (cb) rv$batches[[k1$bid]] <- b }
    invisible(NULL)
  }
  k1_partial <- function(stopped = TRUE) {
    if (is.null(k1$jobs) || isTRUE(k1$closed)) return(0L)
    k1$tdone <- TRUE   # v6.3 (S6)
    raw_lg <- k1_read_log()
    if (!is.null(k1$resdir) && dir.exists(k1$resdir)) {
      fs <- list.files(k1$resdir, "^[0-9]+\\.rds$"); ks <- sort(suppressWarnings(as.integer(sub("\\.rds$", "", fs))))
      for (k in ks[is.finite(ks) & ks >= 1 & ks <= length(k1$jobs)]) if (!k1$seen[k]) {
        r <- tryCatch(readRDS(file.path(k1$resdir, sprintf("%04d.rds", k))), error = function(e) NULL)
        if (!is.null(r)) fin_add(k, r, raw_lg) }
    }
    k1_unpend()   # v6.3 (S6)
    flush_pool_meta(); fin_close(raw_lg, stopped = stopped)
    sum(!is.na(k1$nm))
  }
  output$k1_live <- renderUI({ lang_rv(); n <- rv$k1_n
    if (is.null(n) || !isTRUE(n$running) || (n$total %||% 0) < 2 || is.null(rv$proc)) return(NULL)
    div(class = "small fw-bold text-primary mb-1", icon("spinner", class = "fa-spin"), " ", sprintf(tr("k1_live"), n$done, n$total)) })

  # v6.3 test: ov = on tanimli model isi: list(target, left, right) kutular yerine (boxes = TRUE ise kutular), rules (kosuya
  # ozel sanal kurallar), model (ad), params (maxmiss/blgsize), pdm (not meta), pool_pops (O1 birlesik havuz), nav.
  # ov yoksa ve on tanimli kip aciksa etkin modelin kurallari elle kosuya da uygulanir (pdm_manual_ov).
  launch_run <- function(mode, confirmed = FALSE, ov = NULL) {
    ov <- ov %||% pdm_manual_ov(); useb <- is.null(ov) || isTRUE(ov$boxes)
    seqm <- isTRUE(input$seq_on) && useb   # v6.2 (K9)
    if (is.null(rv$prefix)) { showNotification(tr("msg_pick_geno"), type = "warning"); return() }   # v6.4 test (saha 1): req() bos hata yaziyordu
    if (useb && (!length(input$target) || !length(input$right) || (!seqm && !length(input$left)))) { showNotification(tr("msg_need_tlr"), type = "warning"); return() }
    if (!is.null(rv$proc) && rv$proc$is_alive()) { showNotification(tr("msg_running"), type = "warning"); return() }
    targets <- if (useb) input$target else ov$target; right <- if (useb) input$right else ov$right
    sets <- if (seqm) rv$seq_sets %||% list() else list(if (useb) input$left else ov$left)
    if (seqm && !length(sets)) { showNotification(tr("k9_no_sets"), type = "error", duration = NULL); return() }
    if (seqm && length(targets) != 1) { showNotification(tr("k9_one_target"), type = "error", duration = NULL); return() }
    lall <- unique(unlist(sets, use.names = FALSE))
    if (seqm) { miss <- setdiff(lall, tgt_choices(rv$labels))
      if (length(miss)) { showNotification(sprintf(tr("k9_missing"), paste(miss, collapse = ", ")), type = "error", duration = NULL); return() } }
    # v6.2 (K3): bireysel girdiler BUTUN kutularda; birey kendi grubundan cikar (grup onsuz kosar, bos kalan grup duser),
    # ayni birey iki rolde -> kosu yok. Kosunun sanal seti = kullanicinin kurallari + kullanilan girdiler (ic$vfam).
    # v6.2 (K9): sirali modelde Left rolu = setlerin birlesimi; dusen etiketler her setten cikar.
    ic <- ind_check(list(Target = targets, Left = lall, Right = right), notify = !isTRUE(confirmed)); if (is.null(ic)) return()
    drop <- setdiff(lall, ic$roles$Left); sets <- lapply(sets, function(x) setdiff(x, drop))
    targets <- ic$roles$Target; right <- ic$roles$Right; lall <- ic$roles$Left; left <- if (seqm) lall else sets[[1]]
    emp <- c("Target", "Left", "Right")[c(!length(targets), !length(lall), !length(right))]
    if (length(emp)) { showNotification(sprintf(tr("k3_role_empty"), paste(emp, collapse = ", ")), type = "error", duration = NULL); return() }
    if (seqm && any(!lengths(sets))) { showNotification(sprintf(tr("k9_set_empty"), paste(sprintf("M%02d", which(!lengths(sets))), collapse = ", ")), type = "error", duration = NULL); return() }
    ent <- ic$sp %||% SPLIT_EMPTY; sp <- ent[ent$VirtualLabel %in% targets, , drop = FALSE]; if (!nrow(sp)) sp <- NULL
    if (any(targets %in% c(lall, right))) { showNotification(tr("msg_target_in_lr"), type = "error"); return() }
    for (i in seq_along(sets)) { si <- sets[[i]]; pre <- if (seqm) sprintf(tr("k9_set_n"), i) else ""
      dup <- intersect(si, right)
      if (length(dup)) { showNotification(paste0(pre, sprintf(tr("msg_dup_left_right"), paste(dup, collapse = ", "))), type = "error", duration = NULL); return() }
      # v6.0 (D4): rank testi en az Left + 1 Right ister
      if (length(right) <= length(si)) { showNotification(paste0(pre, sprintf(tr("msg_right_le_left"), length(right), length(si))), type = "error", duration = NULL); return() } }
    # v6.1 ADIM 2b / DUZELTME: bireysel girdilerin kurallari yalniz bu kosunun sanal setine girer (rv$vfam degismez).
    run_vfam <- ic$vfam
    if (!is.null(ov$rules) && nrow(ov$rules)) { run_vfam <- split_vfam(run_vfam, ov$rules); ic$vfam <- run_vfam; ic$pdm <- TRUE }   # v6.3 test
    pops <- unique(c(targets, lall, right))
    if (seqm && !isTRUE(confirmed)) { seq_confirm(mode, length(sets), pops); return() }
    if (!seqm && !is.null(sp) && !isTRUE(confirmed)) { split_confirm(mode, sp, left, right, length(targets)); return() }
    pfx <- run_prefix(ic); if (is.null(pfx)) return()
    vkey <- run_vkey(ic)
    rlm <- vfam_apply_labels(rv$base_labelmap, run_vfam)   # v6.2 (K3): kosudaki pop icerikleri
    # v5.5: S3 -- aktif panel ya da diskteki bir UST KUME kapsiyorsa yeniden
    # hesap yapilmaz; her okuma TEK ve tutarli bir klasorden yapilir.
    pa <- panel_args()
    for (k in intersect(names(ov$params), c("maxmiss", "blgsize"))) if (isTRUE(is.finite(ov$params[[k]]))) pa[[k]] <- ov$params[[k]]   # v6.3 test
    ppops <- if (identical(mode, "allsnps_true")) pops else unique(c(pops, intersect(ov$pool_pops, names(vfam_apply_labels(rv$base_labelmap, run_vfam)))))   # v6.3 test (O1)
    # v6.4 test (adim 1): ek set bireyi iceren model -> sanal havuz (allsnps=FALSE); anahtar set bilesimiyle (T3)
    xc <- xs_ctx(ppops, run_vfam); if (isFALSE(xc)) return()
    cx <- pool_ctx(run_vfam)
    if (!is.null(xc)) { vkey <- paste0(vkey, xc$vsuf); cx$lm <- xc$lm_key; rlm <- xc$lm }
    fr <- resolve_f2(CACHE_BASE, pfx, ppops, pa$maxmiss, pa$blgsize, pa$adjph, pa$auto_only, vkey, active_panel(), cx$orig, cx$lm)
    f2dir <- fr$dir; need <- isTRUE(fr$need) && !pool_ok(f2dir)
    if (need && !identical(mode, "allsnps_true") && !pops_disk_ok(ppops)) return()
    if (identical(fr$src, "superset") && isTRUE(fr$wider)) { if (is.null(ov$pdm)) showNotification(tr("panel_super_note"), type = "message", duration = 10) else ov$pdm$super <- TRUE }   # v6.3 test: kuyrukta not sonuca yazilir
    logf <- tempfile(fileext = ".log")
    md <- if (identical(mode, "allsnps_true")) "TRUE" else "FALSE"
    # v6.0 (K3): allsnps=TRUE'da onbellekte olmayan hedeflerin SNP sayisi bg'de son hedeften sonra TEK okumayla.
    tids <- function(t) (if (!is.null(xc)) xc$lm_key[[t]]) %||% rlm[[t]] %||% t   # v6.4 test: ek set hedefinde set imzasi da anahtarda
    tkeys <- if (identical(mode, "allsnps_true")) stats::setNames(lapply(targets, function(t) tsnp_key(rv$prefix, tids(t))), targets) else list()
    tcache <- if (length(tkeys)) tsnp_cache_read() else list()
    tneed <- if (length(tkeys)) targets[vapply(tkeys, function(k) is.na(k) || is.null(tcache[[k]]), logical(1))] else character(0)
    jobs <- if (seqm) lapply(seq_along(sets), function(i) list(key = sprintf("M%02d", i), t = targets, left = sets[[i]], model = sprintf("M%02d", i), tag = sprintf("%s M%02d", targets, i)))
            else lapply(targets, function(t) list(key = t, t = t, left = left, model = ov$model, tag = if (is.null(ov$model)) t else paste(t, ov$model)))
    resdir <- tempfile("qps_res_"); dir.create(resdir, recursive = TRUE, showWarnings = FALSE)
    k1_init(jobs, kind = if (seqm) "seq" else "batch", sets = if (seqm) stats::setNames(sets, vapply(jobs, function(j) j$key, character(1))) else NULL,
            resdir = resdir, tcache = tcache)
    if (!is.null(ov) && !isTRUE(ov$nav %||% TRUE)) k1$opened <- TRUE   # v6.3 test: kuyrukta yalniz ilk is Sonuclar'a gecer
    rv$logf <- logf; rv$done <- FALSE; rv$progress <- 0; rv$progmsg <- tr("msg_starting"); rv$rcond <- character(0)
    rv$pending <- list(targets = targets, left = left, right = right, mode = mode, maxmiss = pa$maxmiss, prefix = pfx, vfam = run_vfam,
                       f2dir = if (identical(mode, "allsnps_true")) NULL else f2dir, tsnp_keys = tkeys, tsnp_need = tneed, ext = ext_snapshot(),
                       split = if (is.null(sp)) NULL else list(n = nrow(sp), from = unique(sp$OriginalLabel), map = stats::setNames(as.list(sp$SampleID), sp$VirtualLabel)),
                       lm = rlm[intersect(pops, names(rlm))], kind = if (seqm) "seq" else "batch", pdm = ov$pdm)
    rv$t_start <- Sys.time(); rv$t_end <- NULL; rv$eta <- NULL; rv$blk_t0 <- NULL; rv$blk_k0 <- NULL; rv$blk_last <- 0
    console_add("", strrep("-", 60),
      sprintf("[%s] qpAdm started (allsnps=%s)%s", format(Sys.time(), "%H:%M:%S"), md, if (seqm) sprintf(", sequential models: %d", length(jobs)) else ""),
      sprintf("  prefix : %s", pfx),
      sprintf("  admixtools: %s%s", qps_adx_str(), qps_adx_note()),   # v6.4 (madde 3)
      if (!is.null(ov$pdm)) sprintf("  model  : %s (predefined%s; %d sample(s) relabeled for this run)", ov$pdm$model, if (isTRUE(ov$pdm$edited)) ", edited" else "", ov$pdm$rules_n %||% 0L),
      if (length(setdiff(ppops, pops))) sprintf("  f2 pool: %d pops (shared by %d predefined models)", length(ppops), ov$pdm$group_n %||% 1L),
      if (!is.null(sp)) sprintf("  split  : %s -> %d individual targets (label_sampleID)", paste(unique(sp$OriginalLabel), collapse = ", "), nrow(sp)),
      if (length(setdiff(ic$sp$VirtualLabel, sp$VirtualLabel))) sprintf("  indiv. : %s (left/right, label_sampleID)", paste(setdiff(ic$sp$VirtualLabel, sp$VirtualLabel), collapse = ", ")),
      sprintf("  target : %s", paste(targets, collapse = ", ")),
      if (seqm) vapply(jobs, function(j) sprintf("  left %s: %s", j$key, paste(j$left, collapse = ", ")), character(1)) else sprintf("  left   : %s", paste(left, collapse = ", ")),
      sprintf("  right  : %s", paste(right, collapse = ", ")))
    if (!is.null(xc)) console_add(xs_console(xc))   # v6.4 test
    for (jb in jobs) console_add(paste0("  code: ", qpadm_code_line(jb$t, jb$left, right, md)))
    # DIKKAT: arka plan surecinde tr()/I18N YOKTUR. Cevrilmis hata metinleri
    # REAKTIF BAGLAMDA (burada) duz veriye cevrilip argüman olarak gonderilir.
    msgs <- list(f2_head = tr("err_extract_f2_head"), f2_maxmiss = tr("err_extract_f2_maxmiss"), f2_log = tr("err_extract_f2_log"), f2_precomp = tr("err_f2_precomp"))
    rv$proc <- qps_r_bg(
      func = function(mode, prefix, f2dir, need, pops, jobs, right, maxmiss, blgsize, adjph, auto_only, msgs, tsnp_need, resdir, pool_pops = pops, xinfo = NULL, xfun = NULL, xcache = NULL, gp = NULL) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat(sprintf("QPS_MODE %s\n", if (identical(mode, "allsnps_true")) "TRUE" else "FALSE"))
        f2 <- NULL
        if (!identical(mode, "allsnps_true")) {
          cat("QPS_STAGE f2 onbellegi kontrol ediliyor\n")
          if (need) {
            cat("QPS_STAGE extract_f2 calisiyor (blok blok)\n")
            # v6.4 test: ek set -> sanal birlestirme (xs_build_pool; extract_f2'nin ayni adimlari)
            ok <- tryCatch({ if (is.null(xinfo)) extract_f2(prefix, f2dir, pops = pool_pops, maxmiss = maxmiss, blgsize = blgsize, adjust_pseudohaploid = adjph, auto_only = auto_only, overwrite = TRUE, verbose = TRUE)
                             else xfun$pool(xinfo, f2dir, pool_pops, maxmiss, blgsize, adjph, auto_only, xcache, xfun$aft, xfun$zfix); TRUE },
              error = function(e) { cat(sprintf("QPS_STAGE_ERR extract_f2: %s\n", conditionMessage(e))); FALSE })
            if (!ok) stop(paste0(msgs$f2_head, if (isTRUE(maxmiss == 0)) msgs$f2_maxmiss else msgs$f2_log))
            writeLines(format(Sys.time()), file.path(f2dir, ".f2_done"))
          }
          cat("QPS_STAGE f2 okunuyor (onceden hesaplanmis)\n")
          f2 <- tryCatch(f2_from_precomp(f2dir, pops = pops, afprod = TRUE, verbose = FALSE),
            error = function(e) stop(paste0(msgs$f2_precomp, conditionMessage(e))))
        }
        N <- length(jobs); out <- list()
        # v6.4 test (adim 2): ek setli allsnps=TRUE -- frekans matrisi bir kez (panel SNP sirasi, ploidi duzeltmesiz)
        AFx <- NULL
        if (identical(mode, "allsnps_true") && !is.null(xinfo)) { cat("QPS_STAGE sanal frekans tablosu kuruluyor\n"); AFx <- xfun$aft(xinfo, pops, FALSE, xcache, counts = FALSE) }
        # v6.5 ADIM 1: ek setsiz allsnps=TRUE -- butun islerin dortluleri tek genotip gecisinde; hedef SNP sayimi ayni geciste.
        # Gecis hata verirse (ornegin veri setinde olmayan pop) GP NULL kalir ve is basina qpadm(prefix) yoluna dusulur.
        GP <- NULL
        if (identical(mode, "allsnps_true") && is.null(AFx) && is.list(gp)) {
          pcs <- do.call(rbind, lapply(jobs, function(jb) gp$pcomb(jb$t, jb$left, right))); tps <- unique(vapply(jobs, function(jb) jb$t, character(1)))
          cat(sprintf("QPS_PASS %d %d\n", N, nrow(unique(pcs)))); cat("QPS_STAGE tek gecis\n")
          GP <- tryCatch(gp$pass(prefix, pcs, tps), error = function(e) { cat(sprintf("QPS_STAGE_ERR single pass: %s\n", gsub("[\r\n]+", " ", conditionMessage(e)))); NULL })
          if (!is.null(GP)) { tv <- GP$tsnp[intersect(tsnp_need, names(GP$tsnp))]
            if (length(tv)) { cat(sprintf("QPS_TSNP_PASS %d %s\n", length(tv), paste(names(tv), collapse = ", "))); for (nm in names(tv)) cat(sprintf("QPS_TSNP %s %s\n", format(tv[[nm]], scientific = FALSE), nm)) } }
        }
        for (k in seq_len(N)) { jb <- jobs[[k]]; t <- jb$t; left <- jb$left; tag <- jb$tag
          cat(sprintf("QPS_TARGET %d %d %s\n", k, N, tag))
          cat("QPS_STAGE qpadm calisiyor\n")
          # rcond / matris uyarilarini YAKALA (warning + message) ve loga bas
          rcbuf <- character(0)
          r <- tryCatch(withCallingHandlers({
            # DIKKAT: allsnps SADECE data bir genotip prefix'i oldugunda gecerlidir.
            # Onceden hesaplanmis f2 dizisi verildiginde qpadm() bu argumani kabul etmez
            # ("The following arguments are not used: 'allsnps'"). Onceden hesaplanmis f2
            # zaten allsnps=FALSE davranisidir; bu yuzden argumani GONDERMIYORUZ.
            if (identical(mode, "allsnps_true")) { if (!is.null(GP)) gp$fit(GP$fd, t, left, right, TRUE) else if (is.null(AFx)) qpadm(prefix, left = left, right = right, target = t, allsnps = TRUE, verbose = TRUE)
                                                   else xfun$qtrue(AFx$afs, AFx$snpfile, t, left, right, 0.05, TRUE, xfun$f4, AFx$zero, xfun$zfix) }   # v6.4 test (M1)
            else qpadm(f2, left = left, right = right, target = t, verbose = TRUE)
          },
            warning = function(w) { m <- conditionMessage(w)
              cat(sprintf("QPS_RCOND [%s] WARNING: %s\n", tag, m)); rcbuf <<- c(rcbuf, m); invokeRestart("muffleWarning") },
            message = function(m2) { m <- conditionMessage(m2)
              if (grepl("rcond|singular|ill-condition", m, ignore.case = TRUE))
                { cat(sprintf("QPS_RCOND [%s] MESSAGE: %s\n", tag, m)); rcbuf <<- c(rcbuf, m) } }
          ), error = function(e) { cat(sprintf("QPS_RCOND [%s] ERROR: %s\n", tag, conditionMessage(e))); simpleError(conditionMessage(e)) })
          if (length(rcbuf) && !inherits(r, "error")) attr(r, "qps_rcond") <- unique(rcbuf)
          out[[jb$key]] <- r
          # v6.2 (K1): sonuc diske (gecici ad -> yeniden adlandirma), sonra isaret
          tryCatch({ tmp <- file.path(resdir, sprintf(".%04d.tmp", k)); saveRDS(r, tmp); file.rename(tmp, file.path(resdir, sprintf("%04d.rds", k))) },
            error = function(e) cat(sprintf("QPS_STAGE_ERR result file: %s\n", conditionMessage(e))))
          cat(sprintf("QPS_DONE %d\n", k))
        }
        # v6.0 (K3): allsnps=TRUE -- onbellekte olmayan (ve basarili) hedeflerin SNP sayisi TEK genotip
        # okumasiyla; otozomlar (qpadm allsnps'in auto_only = TRUE varsayilani). Hata sonucu bozmaz.
        okj <- !vapply(out, inherits, logical(1), "error")
        okt <- intersect(tsnp_need, unique(vapply(jobs[okj], function(j) j$t, character(1))))
        if (!is.null(GP) && length(okt)) { attr(out, "qps_tsnp") <- stats::setNames(as.numeric(GP$tsnp[okt]), okt)   # v6.5: tek geciste sayildi (okuma yok)
        } else if (identical(mode, "allsnps_true") && length(okt)) {
          cat(sprintf("QPS_TSNP_START %d %s\n", length(okt), paste(okt, collapse = ", "))); t0 <- Sys.time()
          v <- if (!is.null(AFx)) { ch <- suppressWarnings(as.numeric(gsub("[a-zA-Z]+", "", AFx$snpfile$CHR))); keep <- !is.na(ch) & ch <= 22   # v6.4 test: sanal matristen
            stats::setNames(vapply(okt, function(tt) as.numeric(sum(!is.na(AFx$afs[keep, tt]))), 0), okt) } else tryCatch({
            # v6.3 test2 (S1): anygeno_to_aftable admixtools'ta disa acik DEGIL (2f6957a ve 2.0.10 NAMESPACE); ad alanindan alinir.
            rdr <- get0("anygeno_to_aftable", envir = asNamespace("admixtools"), inherits = FALSE)
            af <- if (is.function(rdr)) rdr(prefix, pops = okt, adjust_pseudohaploid = FALSE, verbose = TRUE) else if (all(file.exists(paste0(prefix, c(".bed", ".bim", ".fam"))))) plink_to_afs(prefix, pops = okt, adjust_pseudohaploid = FALSE, verbose = TRUE) else packedancestrymap_to_afs(prefix, pops = okt, adjust_pseudohaploid = FALSE, verbose = TRUE)
            ch <- suppressWarnings(as.numeric(gsub("[a-zA-Z]+", "", af$snpfile$CHR))); keep <- !is.na(ch) & ch <= 22
            cm <- af$counts[keep, , drop = FALSE]; r <- colSums(!is.na(cm) & cm > 0); rm(af, cm); invisible(gc()); r[okt]
          }, error = function(e) { cat(sprintf("QPS_TSNP_ERR %s\n", conditionMessage(e))); NULL })
          secs <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
          if (!is.null(v)) for (nm in okt) { x <- unname(v[nm]); if (isTRUE(is.finite(x))) cat(sprintf("QPS_TSNP %s %s\n", format(x, scientific = FALSE), nm)) }
          cat(sprintf("QPS_TSNP_TIME %.1f\n", secs))
          attr(out, "qps_tsnp") <- v; attr(out, "qps_tsnp_secs") <- secs
        }
        out
      },
      # v6.0 (D11): stderr = "2>&1" -- ayni dosyaya iki tutamak stdout satirlarini eziyordu (K1 tablosu, QPS_*).
      args = list(mode = mode, prefix = pfx, f2dir = f2dir, need = need, pops = pops, jobs = jobs, right = right,
                  maxmiss = pa$maxmiss, blgsize = pa$blgsize, adjph = pa$adjph, auto_only = pa$auto_only, msgs = msgs, tsnp_need = tneed, resdir = resdir, pool_pops = ppops,
                  xinfo = if (is.null(xc)) NULL else xc$bg, xfun = if (is.null(xc)) NULL else xs_bg_funs(), xcache = XS_CACHE_DIR,
                  gp = if (identical(mode, "allsnps_true") && is.null(xc)) qps_gp_funs() else NULL),   # v6.5 ADIM 1
      stdout = logf, stderr = "2>&1")
    # Havuz yan dosyasi: v5.5 ust-kume aramasi bu dosyaya bakacak.
    if (need) rv$pool_pending <- list(dir = f2dir, prefix = pfx, pops = ppops, maxmiss = pa$maxmiss, vfam = vkey,
                                      blgsize = pa$blgsize, adjph = pa$adjph, auto_only = pa$auto_only, orig = fr$orig, comp = fr$comp)
  }
  # Gozlemci icindeki bir hata Shiny oturumunu dusurur; sarmalayip bildirime ceviriyoruz.
  safe_run <- function(expr, what = NULL) {
    what <- what %||% tr("op_generic")
    tryCatch(expr, error = function(e) {
      if (inherits(e, "shiny.silent.error")) return(NULL)   # v6.4 test (saha 1): req()'in sessiz hatasi hata degildir
      showNotification(sprintf(tr("msg_op_error"), what, conditionMessage(e)), type = "error", duration = NULL)
      console_add(sprintf("[ERROR] %s: %s", what, conditionMessage(e)))
      NULL })
  }
  observeEvent(input$run_false, safe_run(launch_run("allsnps_false"), "qpAdm (allsnps=FALSE)"))
  observeEvent(input$run_true,  safe_run(launch_run("allsnps_true"),  "qpAdm (allsnps=TRUE)"))

  # ===========================================================================================================
  # v6.3 test: ON TANIMLI MODELLER (.qpadm). Proje belgesi claude/qpAdm_Studio_v6.3_kararlari.md (karar 1, O1-O10).
  # rv$pdm_coll : koleksiyon (meta + models); pdm_res(): her modelin yuklu sete gore cozumu (sample ID -> etiket,
  # sanal kurallar, saglik durumu); pdm_groups(): uyumlu kural kumeleri (O1 tek havuz). rv$pdm_on: Model sekmesinde
  # on tanimli kip (etkin modelin kurallari elle kosulara da uygulanir); rv$pdm_cur: kutulardaki model; rv$pdmq: kuyruk.
  # ===========================================================================================================
  PDM_STATE <- file.path(getwd(), "qps_pdm_queue.rds")
  pdm_ac <- new.env(parent = emptyenv())
  pdm_ext_paths <- function() unlist(lapply(isolate(rv$ext_files) %||% list(), function(f) f$path), use.names = FALSE)
  pdm_anno <- function() {
    a <- pdm_find_anno(isolate(rv$prefix), pdm_ext_paths()); if (!length(a)) return(NULL)
    key <- paste(a[1], file.mtime(a[1])); if (!identical(pdm_ac$key, key)) { pdm_ac$key <- key; pdm_ac$df <- pdm_anno_read(a[1]); pdm_ac$path <- a[1] }
    pdm_ac$df
  }
  pdm_lab_of <- function(lm = rv$labelmap) if (!length(lm)) character(0) else stats::setNames(rep(names(lm), lengths(lm)), unlist(lm, use.names = FALSE))
  pdm_bad_res <- function(msg) list(status = "red", issues = list(list(code = "error", n = NA, what = msg)), rules = SPLIT_EMPTY[, c("SampleID", "VirtualLabel", "OriginalLabel", "Source")],
                                    labels = list(target = character(0), left = character(0), right = character(0)), comp = list(), n = c(target = 0, left = 0, right = 0), pops = NULL)
  pdm_res <- reactive({
    cl <- rv$pdm_coll; if (is.null(cl) || !length(cl$models) || !length(rv$labelmap)) return(list())
    lm <- rv$labelmap; lo <- pdm_lab_of(lm); ids <- names(lo)
    need <- any(vapply(cl$models, function(x) any(nzchar(x$pops$sample_id) & !(x$pops$sample_id %in% ids)), logical(1)))
    an <- if (need) tryCatch(pdm_anno(), error = function(e) NULL) else NULL
    lapply(cl$models, function(x) tryCatch(pdm_resolve(x, ids, lo, an, names(lm)), error = function(e) pdm_bad_res(conditionMessage(e))))
  })
  pdm_groups <- reactive({
    rs <- pdm_res(); if (!length(rs)) return(list())
    ok <- which(vapply(rs, function(r) !identical(r$status, "red"), logical(1))); if (!length(ok)) return(list())
    tryCatch(pdm_group(stats::setNames(rs[ok], as.character(ok)), pdm_lab_of()), error = function(e) list())
  })
  pdm_group_of <- function(i) { for (g in pdm_groups()) if (as.character(i) %in% g$idx) return(g); NULL }
  pdm_rules_of <- function(i) { g <- pdm_group_of(i); if (!is.null(g)) return(g$rules); r <- pdm_res()[[i]]; if (is.null(r)) NULL else r$rules }
  pdm_active_rules <- function() if (!isTRUE(isolate(rv$pdm_on)) || is.null(isolate(rv$pdm_cur))) NULL else pdm_rules_of(isolate(rv$pdm_cur))
  pdm_extra_for <- function(rules) if (is.null(rules) || !nrow(rules)) character(0) else setdiff(unique(rules$VirtualLabel[rules$Source == "qpadm"]), isolate(rv$labels))
  pdm_extra <- function() isolate(rv$pdm_extra) %||% character(0)
  observe({ ex <- if (isTRUE(rv$pdm_on) && !is.null(rv$pdm_cur)) pdm_extra_for(pdm_rules_of(rv$pdm_cur)) else character(0)
    if (!identical(ex, isolate(rv$pdm_extra))) rv$pdm_extra <- ex })
  pdm_err_tr <- function(m) if (startsWith(m %||% "", "pdm_err_")) tr(m) else m
  pdm_iss_tr <- function(z, k = 5) { w <- strsplit(z$what %||% "", ", ", fixed = TRUE)[[1]]
    wt <- paste0(paste(utils::head(w, k), collapse = ", "), if (length(w) > k) sprintf(" (+%d)", length(w) - k) else "")
    key <- paste0("pdm_iss_", z$code)
    switch(z$code, anno = , missing = , dup = sprintf(tr(key), as.integer(z$n), wt), rank = sprintf(tr(key), as.character(z$n), z$what),
           no_left = , no_right = tr(key), sprintf(tr(key), wt)) }
  pdm_st_col <- function(st) switch(st %||% "red", green = "#2e9d4f", yellow = "#d39e00", none = "#8a8f98", "#c0392b")
  pdm_st_sym <- function(st) switch(st %||% "red", green = "\u2713", yellow = "!", none = "\u2013", "\u2715")
  pdm_st_of <- function(rs, i) if (i <= length(rs)) rs[[i]]$status %||% "red" else "none"   # set yuklu degilse "none"
  pdm_guess_ds <- function(prefix) {
    b <- tolower(basename(prefix %||% "")); if (!nzchar(b)) return("")
    v <- regmatches(b, regexpr("v[0-9]+(\\.[0-9a-z]+)*", b)); if (!length(v)) return("")
    v <- sub("\\.(aadr|patch|pub|plink).*$", "", v); v <- sub("_.*$", "", v); if (identical(v, "v66")) v <- "v66.0"; if (identical(v, "v62")) v <- "v62.0"
    pn <- if (grepl("2m", b)) "2M" else if (grepl("_ho|\\.ho|ho_", b)) "HO (1240K+HO)" else if (grepl("1240k", b)) "1240K" else ""
    x <- paste("AADR", v, pn); if (x %in% PDM_DATASETS) x else ""
  }
  pdm_meta_live <- reactiveVal(list())   # dosya bilgisi kutularindaki guncel degerler (rv$pdm_coll'a yazilmaz: modeller yeniden cozulmesin)
  pdm_meta_cur <- function() { m <- rv$pdm_coll$meta %||% list(); l <- pdm_meta_live(); for (k in names(l)) m[[k]] <- l[[k]]; m }
  pdm_ds_note <- function() { ds <- isolate(pdm_meta_cur())$dataset %||% ""; g <- pdm_guess_ds(isolate(rv$prefix))
    if (!nzchar(ds) || is.null(isolate(rv$prefix))) return(NULL)
    vd <- regmatches(ds, regexpr("v[0-9]+(\\.[0-9a-z]+)*", ds)); vg <- regmatches(g, regexpr("v[0-9]+(\\.[0-9a-z]+)*", g))
    if (length(vd) && length(vg) && identical(vd, vg)) return(NULL)
    if (nzchar(g) && identical(ds, g)) return(NULL)
    sprintf(tr("pdm_ds_diff"), ds, basename(isolate(rv$prefix))) }

  # ---- koleksiyona ekleme (dosya / birakma / pano) ----
  pdm_meta_tick <- reactiveVal(0)
  pdm_add_coll <- function(b, src) {
    n0 <- length(isolate(rv$pdm_coll)$models %||% list()); cl0 <- isolate(rv$pdm_coll); if (!is.null(cl0)) cl0$meta <- isolate(pdm_meta_cur())
    m <- pdm_merge(cl0, b); rv$pdm_coll <- m$coll
    if (n0 == 0) { pdm_meta_live(list()); pdm_meta_tick(isolate(pdm_meta_tick()) + 1) }
    showNotification(sprintf(tr("pdm_loaded"), src, m$added, m$skipped), type = if (m$added) "message" else "warning", duration = 8)
    if (m$added) n0 + 1L else NULL
  }
  pdm_after_load <- function(i) {
    if (is.null(i)) return(invisible(NULL))
    if (is.null(isolate(rv$prefix)) || !length(isolate(rv$labelmap))) { showNotification(tr("pdm_need_geno"), type = "warning", duration = 10); return(invisible(NULL)) }
    q <- isolate(rv$pdmq); if (!is.null(q) && q$state %in% c("running", "waiting", "stopped")) return(invisible(NULL))   # kuyruk varken kutulara dokunma
    pdm_load(i); nav_select("main_nav", "model")
  }
  pdm_load_files <- function(paths, names = basename(paths)) {
    first <- NULL
    for (k in seq_along(paths)) { nm <- names[k]
      ex <- tolower(tools::file_ext(nm))   # v6.3 test2 (karar 2): .txt/.tsv/.csv yalniz icerigi model dosyasiysa
      if (!ex %in% c(PDM_EXT, "txt", "tsv", "csv") || (ex != PDM_EXT && !pdm_sniff(paths[k]))) { showNotification(sprintf(tr("pdm_skip_type"), nm), type = "warning", duration = 8); next }
      b <- tryCatch(pdm_read_file(paths[k], nm), error = function(e) e)
      if (inherits(b, "error")) { showNotification(sprintf(tr("pdm_read_fail"), nm, pdm_err_tr(conditionMessage(b))), type = "error", duration = 10); next }
      i <- pdm_add_coll(b, nm); if (is.null(first)) first <- i }
    pdm_after_load(first)
  }
  observeEvent(input$pdm_drop, safe_run({ x <- input$pdm_drop; if (is.null(x) || !nrow(x)) return(); pdm_load_files(x$datapath, x$name) }, tr("pdm_title")))
  observeEvent(input$pdm_win, safe_run(pick_native("pdm", multi = TRUE, cb = function(p) { d <- rv$defx; d$dirs$pdm <- dirname(p[1]); rv$defx <- d; save_defaults(); pdm_load_files(p) }, op = tr("pdm_title")), tr("pdm_title")))
  observeEvent(input$pdm_sf, safe_run({ fp <- shinyFiles::parseFilePaths(volumes, input$pdm_sf); if (!nrow(fp)) return(); pdm_load_files(as.character(fp$datapath), as.character(fp$name)) }, tr("pdm_title")))
  observeEvent(input$pdm_paste, showModal(modalDialog(title = tr("pdm_paste_title"), easyClose = TRUE, size = "l",
    hint(tr("pdm_paste_hint")), textAreaInput("pdm_paste_txt", NULL, rows = 12, width = "100%"),
    footer = tagList(modalButton(tr("ow_cancel")), actionButton("pdm_paste_go", tr("pdm_paste_go"), class = "btn-primary")))))
  observeEvent(input$pdm_paste_go, safe_run({ txt <- input$pdm_paste_txt %||% ""; removeModal()
    b <- tryCatch(pdm_read_text(txt, src = "pdm"), error = function(e) e)
    if (inherits(b, "error")) { showNotification(sprintf(tr("pdm_read_fail"), tr("pdm_paste"), pdm_err_tr(conditionMessage(b))), type = "error", duration = 10); return() }
    pdm_after_load(pdm_add_coll(b, tr("pdm_paste"))) }, tr("pdm_title")))
  observeEvent(input$pdm_starter, safe_run({ first <- NULL   # v6.4 test (O9): baslangic paketi, yapistirma ile ayni okuma yolu
    for (p in PDM_STARTER) {
      b <- tryCatch(pdm_read_text(p$text, src = pdm_src_name(p$file)), error = function(e) e)
      if (inherits(b, "error")) { showNotification(sprintf(tr("pdm_read_fail"), p$file, pdm_err_tr(conditionMessage(b))), type = "error", duration = 10); next }
      i <- pdm_add_coll(b, sprintf("%s: %s", tr("pdm_starter"), p$name)); if (is.null(first)) first <- i }
    pdm_after_load(first) }, tr("pdm_title")))

  # ---- Set Yonetimi: tablo ve islemler ----
  pdm_cell <- function(v, k = 4) { v <- as.character(v); if (!length(v)) return(""); paste0(paste(utils::head(v, k), collapse = ", "), if (length(v) > k) sprintf(" \u2026 (%d)", length(v)) else "") }
  pdm_tbl_df <- function() {
    cl <- rv$pdm_coll; rs <- pdm_res(); if (is.null(cl) || !length(cl$models)) return(NULL)
    st <- vapply(seq_along(cl$models), function(i) pdm_st_of(rs, i), ""); rr <- function(i) if (i <= length(rs)) rs[[i]] else list()
    data.frame(st = sprintf('<span style="color:%s;font-weight:700">%s</span> %s', vapply(st, pdm_st_col, ""), vapply(st, pdm_st_sym, ""), vapply(st, function(s) if (identical(s, "none")) "" else tr(paste0("pdm_st_", s)), "")),
      model = vapply(cl$models, function(x) x$name, ""), allsnps = vapply(cl$models, function(x) x$allsnps %||% "", ""),
      target = vapply(seq_along(cl$models), function(i) { t <- if (i <= length(rs)) rs[[i]]$labels$target else unique(cl$models[[i]]$pops$label[cl$models[[i]]$pops$role == "target"]); if (length(t)) pdm_cell(t) else tr("pdm_tgt_box") }, ""),
      left = vapply(seq_along(cl$models), function(i) pdm_cell(if (i <= length(rs)) rs[[i]]$labels$left else unique(cl$models[[i]]$pops$label[cl$models[[i]]$pops$role == "left"])), ""),
      right = vapply(seq_along(cl$models), function(i) pdm_cell(if (i <= length(rs)) rs[[i]]$labels$right else unique(cl$models[[i]]$pops$label[cl$models[[i]]$pops$role == "right"]), 3), ""),
      note = vapply(seq_along(cl$models), function(i) paste(vapply(rr(i)$issues %||% list(), pdm_iss_tr, "", k = 2), collapse = " | "), ""), stringsAsFactors = FALSE)
  }
  pdm_tbl_tick <- reactiveVal(0)
  output$pdm_tbl <- renderDT({ lang_rv(); pdm_tbl_tick(); df <- pdm_tbl_df()
    if (is.null(df)) return(adv_info_dt(if (is.null(rv$prefix)) tr("pdm_none_geno") else tr("pdm_none")))
    datatable(df, rownames = FALSE, escape = -1, selection = "multiple", fillContainer = FALSE,
      colnames = c(tr("pdm_col_status"), tr("pdm_col_model"), "allsnps", "Target", "Left", "Right", tr("pdm_col_note")),
      editable = list(target = "cell", disable = list(columns = c(0, 3, 4, 5, 6))),
      options = list(dom = "t", paging = FALSE, ordering = FALSE, autoWidth = FALSE))   # gizli sekmede cizilir: kaydirma basligi kaydirir
  })
  observeEvent(input$pdm_tbl_cell_edit, safe_run({ e <- input$pdm_tbl_cell_edit; cl <- rv$pdm_coll; i <- as.integer(e$row); v <- trimws(as.character(e$value))
    if (is.null(cl) || is.na(i) || i < 1 || i > length(cl$models)) return()
    if (identical(as.integer(e$col), 1L)) { if (!nzchar(v)) return(); if (v %in% vapply(cl$models[-i], function(x) x$name, "")) { showNotification(tr("pdm_name_dup"), type = "error"); pdm_tbl_tick(pdm_tbl_tick() + 1); return() }
      cl$models[[i]]$name <- v }
    else if (identical(as.integer(e$col), 2L)) { b <- pdm_bool3(v); if (is.na(b) && nzchar(v)) { showNotification(tr("pdm_edit_bad"), type = "error"); pdm_tbl_tick(pdm_tbl_tick() + 1); return() }; cl$models[[i]]$allsnps <- b }
    rv$pdm_coll <- cl }, tr("pdm_title")))
  pdm_sel <- function() { s <- sort(as.integer(input$pdm_tbl_rows_selected %||% integer(0))); n <- length(isolate(rv$pdm_coll)$models %||% list()); s[s >= 1 & s <= n] }
  pdm_need_sel <- function() { s <- pdm_sel(); if (!length(s)) showNotification(tr("pdm_sel_none"), type = "warning"); s }
  pdm_q_active <- function() { q <- isolate(rv$pdmq); !is.null(q) && q$state %in% c("running", "waiting", "stopped") }
  pdm_move <- function(d) { if (pdm_q_active()) { showNotification(tr("pdm_busy"), type = "warning"); return() }; s <- pdm_need_sel(); if (length(s) != 1) return(); cl <- rv$pdm_coll; j <- s + d; if (j < 1 || j > length(cl$models)) return()
    o <- seq_along(cl$models); o[c(s, j)] <- o[c(j, s)]; cl$models <- cl$models[o]; rv$pdm_coll <- cl
    cu <- rv$pdm_cur; if (!is.null(cu)) rv$pdm_cur <- match(cu, o)
    DT::selectRows(DT::dataTableProxy("pdm_tbl"), j) }
  observeEvent(input$pdm_up, pdm_move(-1)); observeEvent(input$pdm_down, pdm_move(1))
  observeEvent(input$pdm_del, { s <- pdm_need_sel(); if (!length(s)) return(); q <- rv$pdmq
    if (!is.null(q) && q$state %in% c("running", "waiting", "stopped")) { showNotification(tr("pdm_busy"), type = "warning"); return() }
    cl <- rv$pdm_coll; cl$models <- cl$models[-s]; rv$pdm_coll <- if (length(cl$models)) cl else NULL
    cu <- rv$pdm_cur; if (!is.null(cu)) { if (cu %in% s) { rv$pdm_cur <- if (length(cl$models)) 1L else NULL; if (!length(cl$models)) rv$pdm_on <- FALSE } else rv$pdm_cur <- cu - sum(s < cu) } })
  observeEvent(input$pdm_open, { s <- pdm_need_sel(); if (!length(s)) return(); pdm_after_load(s[1]) })
  observeEvent(input$pdm_clear, { n <- length(rv$pdm_coll$models %||% list()); if (!n) return()
    showModal(modalDialog(title = tr("pdm_title"), sprintf(tr("pdm_clear_q"), n), easyClose = TRUE,
      footer = tagList(modalButton(tr("ow_cancel")), actionButton("pdm_clear_go", tr("pdm_clear"), class = "btn-danger")))) })
  observeEvent(input$pdm_clear_go, { removeModal(); q <- rv$pdmq
    if (!is.null(q) && q$state %in% c("running", "waiting", "stopped")) { showNotification(tr("pdm_busy"), type = "warning"); return() }
    rv$pdm_coll <- NULL; rv$pdm_on <- FALSE; rv$pdm_cur <- NULL; rv$pdmq <- NULL; pdm_meta_live(list()) })
  # meta (dosya adi, onerilen veri seti, hazirlayan, aciklama): degerler yalniz yuklemede ve dil degisiminde yeniden yazilir
  output$pdm_meta_ui <- renderUI({ lang_rv(); pdm_meta_tick(); m <- isolate(pdm_meta_cur())
    ds <- m$dataset %||% ""; if (!nzchar(ds)) ds <- pdm_guess_ds(isolate(rv$prefix)); ch <- unique(c(PDM_DATASETS, ds))
    layout_columns(col_widths = c(3, 3, 3, 3),
      textInput("pdm_meta_name", tr("pdm_meta_name"), m$name %||% "", width = "100%"),
      selectizeInput("pdm_meta_ds", tr("pdm_meta_ds"), stats::setNames(ch, ifelse(nzchar(ch), ch, "\u2014")), ds, width = "100%", options = list(create = TRUE)),
      textInput("pdm_meta_author", tr("pdm_meta_author"), m$author %||% "", width = "100%"),
      textInput("pdm_meta_desc", tr("pdm_meta_desc"), m$description %||% "", width = "100%")) })
  for (k in c("name", "ds", "author", "desc")) local({ kk <- k; fld <- switch(kk, ds = "dataset", desc = "description", kk)
    observeEvent(input[[paste0("pdm_meta_", kk)]], { v <- as.character(input[[paste0("pdm_meta_", kk)]] %||% ""); l <- pdm_meta_live()
      if (!identical(l[[fld]], v)) { l[[fld]] <- v; pdm_meta_live(l) } }, ignoreInit = TRUE) })
  output$pdm_ds_ui <- renderUI({ lang_rv(); rv$pdm_coll; rv$prefix; pdm_meta_live(); n <- pdm_ds_note(); if (is.null(n)) NULL else div(class = "small text-warning mb-2", icon("circle-info"), " ", n) })
  pdm_text <- function(ids = NULL) { cl <- rv$pdm_coll; if (is.null(cl)) return(""); cl$meta <- pdm_meta_cur(); pdm_write_text(cl, ids %||% seq_along(cl$models), program = QPS_VERSION) }
  pdm_fname <- function(sel = FALSE) { nm <- trimws(input$pdm_meta_name %||% ""); if (!nzchar(nm)) nm <- "qpadm_models"; paste0(label_fix(nm), if (sel) "_part" else "", PDM_EXT_W) }   # v6.3 test2 (karar 2)
  pdm_write_file <- function(txt, file) { con <- file(file, "wb"); on.exit(close(con)); writeBin(charToRaw(enc2utf8(txt)), con) }
  output$pdm_dl_all <- downloadHandler(filename = function() pdm_fname(), content = function(file) pdm_write_file(pdm_text(), file))
  output$pdm_dl_sel <- downloadHandler(filename = function() pdm_fname(TRUE), content = function(file) { s <- pdm_sel(); pdm_write_file(pdm_text(if (length(s)) s else NULL), file) })
  output$pdm_copy_ui <- renderUI({ lang_rv(); txt <- pdm_text(); n <- length(strsplit(txt, "\n", fixed = TRUE)[[1]])
    tags$button(type = "button", class = "btn btn-sm btn-outline-primary qps-copy-vals", `data-id` = "pdm", `data-vals` = sub("\n$", "", txt), disabled = if (!nzchar(txt)) NA else NULL,
      icon("clipboard"), " ", tr("pdm_copy")) })

  # ---- Model sekmesi: on tanimli kip ----
  pdm_load <- function(i) {
    cl <- isolate(rv$pdm_coll); rs <- pdm_res(); if (is.null(cl) || is.null(i) || i < 1 || i > length(cl$models)) return(invisible(FALSE))
    rv$pdm_cur <- i; rv$pdm_on <- TRUE
    if (isTRUE(isolate(input$seq_on))) update_switch("seq_on", value = FALSE)
    if (isTRUE(isolate(input$split_ind))) update_switch("split_ind", value = FALSE)
    r <- rs[[i]]; rv$pdm_extra <- pdm_extra_for(pdm_rules_of(i))
    if (identical(r$status, "red") && !length(r$labels$left)) return(invisible(TRUE))
    set_sel("left", r$labels$left); set_sel("right", r$labels$right)
    if (length(r$labels$target)) { set_sel("target", r$labels$target); pdm_ac$tgt_auto <- r$labels$target }
    else if (length(pdm_ac$tgt_auto) && setequal(as.character(isolate(input$target) %||% character(0)), pdm_ac$tgt_auto)) { set_sel("target", character(0)); pdm_ac$tgt_auto <- NULL }
    invisible(TRUE)
  }
  # kuyruk etkinken (calisiyor / bekliyor / durduruldu) kutulardaki model kuyrugun isidir: secici kilitli (kural ve ad kariskmasin)
  observeEvent(input$pdm_cur_sel, { i <- as.integer(input$pdm_cur_sel); if (is.na(i) || identical(i, rv$pdm_cur)) return()
    if (pdm_q_active()) { showNotification(tr("pdm_busy"), type = "warning"); updateSelectInput(session, "pdm_cur_sel", selected = rv$pdm_cur); return() }
    pdm_load(i) }, ignoreInit = TRUE)
  observeEvent(input$pdm_prev, { i <- (rv$pdm_cur %||% 1L) - 1L; if (pdm_q_active()) showNotification(tr("pdm_busy"), type = "warning") else if (i >= 1) pdm_load(i) })
  observeEvent(input$pdm_nextm, { i <- (rv$pdm_cur %||% 0L) + 1L; if (pdm_q_active()) showNotification(tr("pdm_busy"), type = "warning") else if (i <= length(rv$pdm_coll$models %||% list())) pdm_load(i) })
  observeEvent(input$pdm_mode, { v <- input$pdm_mode; if (!v %in% c("auto", "step")) return(); rv$pdm_mode <- v
    q <- rv$pdmq; if (!is.null(q) && !identical(q$mode, v)) { q$mode <- v; rv$pdmq <- q } }, ignoreInit = TRUE)
  observeEvent(input$pdm_close, { q <- rv$pdmq; if (!is.null(q) && identical(q$state, "running")) { showNotification(tr("pdm_busy"), type = "warning"); return() }
    rv$pdm_on <- FALSE; rv$pdm_extra <- character(0); if (!is.null(q) && q$state %in% c("waiting", "stopped")) pdm_finish(quiet = TRUE) })
  output$pdm_ui <- renderUI({ lang_rv(); cl <- rv$pdm_coll; rec <- rv$pdm_rec
    recb <- if (!is.null(rec)) div(class = "alert alert-warning py-2 px-3 small mb-2", icon("rotate"), " ", sprintf(tr("pdm_rec_msg"), rec$n_done, rec$n, format(rec$time, "%Y-%m-%d %H:%M")),
      div(class = "d-flex gap-2 flex-wrap mt-1", actionButton("pdm_rec_go", tr("pdm_rec_go"), class = "btn-sm btn-warning", icon = icon("play")),
        actionButton("pdm_rec_load", tr("pdm_rec_load"), class = "btn-sm btn-outline-secondary"), actionButton("pdm_rec_del", tr("pdm_rec_del"), class = "btn-sm btn-outline-danger")))
    if (is.null(cl) || !length(cl$models) || !isTRUE(rv$pdm_on)) return(recb)
    rs <- isolate(pdm_res()); st <- vapply(seq_along(cl$models), function(i) pdm_st_of(rs, i), "")
    ch <- stats::setNames(seq_along(cl$models), sprintf("%s  %d. %s", vapply(st, pdm_st_sym, ""), seq_along(cl$models), vapply(cl$models, function(x) x$name, "")))
    div(class = "border rounded p-2 mb-3", style = "border-color:var(--bs-primary) !important;", recb,
      div(class = "d-flex justify-content-between align-items-center flex-wrap gap-2 mb-1",
        tags$strong(icon("list-check"), " ", tr("pdm_title"), if (nzchar(isolate(pdm_meta_cur())$name %||% "")) paste0(": ", isolate(pdm_meta_cur())$name) else "", sprintf(" (%d)", length(cl$models))),
        actionLink("pdm_close", tr("pdm_close"), icon = icon("xmark"))),
      div(class = "d-flex gap-2 align-items-center flex-wrap",
        actionButton("pdm_prev", NULL, icon = icon("chevron-left"), class = "btn-sm btn-outline-secondary", title = tr("k9_up")),
        div(style = "min-width:240px;flex:1;", selectInput("pdm_cur_sel", NULL, ch, isolate(rv$pdm_cur) %||% 1L, width = "100%", selectize = FALSE)),
        actionButton("pdm_nextm", NULL, icon = icon("chevron-right"), class = "btn-sm btn-outline-secondary", title = tr("k9_down")),
        radioButtons("pdm_mode", NULL, stats::setNames(c("auto", "step"), c(tr("pdm_mode_auto"), tr("pdm_mode_step"))), isolate(rv$pdm_mode) %||% "auto", inline = TRUE)),
      uiOutput("pdm_cur_card"), uiOutput("pdm_q_ui"))
  })
  observeEvent(rv$pdm_cur, { i <- rv$pdm_cur; if (!is.null(i) && !identical(as.integer(isolate(input$pdm_cur_sel)), i)) updateSelectInput(session, "pdm_cur_sel", selected = i) }, ignoreNULL = TRUE)
  output$pdm_cur_card <- renderUI({ lang_rv(); i <- rv$pdm_cur; cl <- rv$pdm_coll; rs <- pdm_res(); if (is.null(i) || is.null(cl) || i > length(rs)) return(NULL)
    r <- rs[[i]]; x <- cl$models[[i]]; g <- pdm_group_of(i)
    tg <- if (length(r$labels$target)) pdm_cell(r$labels$target, 6) else tr("pdm_tgt_box")
    div(class = "small mt-1 mb-1 ps-2", style = sprintf("border-left:4px solid %s;", pdm_st_col(r$status)),
      div(tags$b(sprintf("%s %s", pdm_st_sym(r$status), tr(paste0("pdm_st_", r$status)))), " \u00b7 ", sprintf("Target: %s \u00b7 Left %d \u00b7 Right %d \u00b7 allsnps=%s", tg, length(r$labels$left), length(r$labels$right), x$allsnps %||% "TRUE"),
        if (length(x$params)) paste0(" \u00b7 ", paste(sprintf("%s=%s", names(x$params), unlist(x$params)), collapse = ", "))),
      if (length(r$issues)) tags$ul(class = "mb-1 ps-3", lapply(r$issues, function(z) tags$li(pdm_iss_tr(z)))),
      if ((nq <- sum((r$rules %||% data.frame(Source = character()))$Source == "qpadm")) > 0) div(class = "text-muted", sprintf(tr("pdm_note_rules"), nq)),
      if (!is.null(g) && length(g$idx) > 1) div(class = "text-muted", sprintf(tr("pdm_note_group"), length(g$idx))),
      if (nrow(x$ref %||% data.frame())) div(class = "text-muted", icon("scale-balanced"), " ", sprintf(tr("pdm_ref_has"), length(unique(x$ref$target)))),
      if (!is.null(n <- pdm_ds_note())) div(class = "text-warning", n))
  })
  output$pdm_q_ui <- renderUI({ lang_rv(); q <- rv$pdmq; cl <- rv$pdm_coll; running <- !is.null(rv$proc); md <- rv$pdm_mode %||% "auto"
    jn <- function(k) { j <- q$jobs[[k]]; sprintf("%s (allsnps=%s)", cl$models[[j$i]]$name %||% "?", j$md) }
    ndone <- if (is.null(q)) 0L else sum(vapply(q$jobs, function(j) isTRUE(j$done), logical(1)))
    if (is.null(q) || identical(q$state, "done")) {
      n <- length(cl$models %||% list()); from <- rv$pdm_cur %||% 1L
      tagList(
        if (!is.null(q)) div(class = "small text-success mt-1", icon("check"), " ", sprintf(tr("pdm_q_done"), ndone, length(q$jobs)), " ", actionLink("pdm_show_sum", tr("pdm_show_sum"))),
        div(class = "d-flex gap-2 flex-wrap mt-2",
          if (identical(md, "auto")) actionButton("pdm_run", sprintf(tr("pdm_run_all"), n - from + 1L), class = "btn-sm btn-primary", icon = icon("forward"))
          else actionButton("pdm_run", tr("pdm_run_cur"), class = "btn-sm btn-primary", icon = icon("play"))),
        hint(if (identical(md, "auto")) tr("pdm_run_hint_auto") else tr("pdm_run_hint_step")))
    } else if (identical(q$state, "running")) {
      div(class = "small mt-1 text-primary", icon("spinner", class = "fa-spin"), " ", sprintf(tr("pdm_q_running"), ndone, length(q$jobs), jn(min(q$pos, length(q$jobs)))))
    } else if (identical(q$state, "stopped")) {
      div(class = "mt-1", div(class = "small text-danger", icon("stop"), " ", sprintf(tr("pdm_q_stopped"), jn(q$pos))),
        div(class = "d-flex gap-2 flex-wrap mt-1",
          actionButton("pdm_rerun", tr("pdm_rerun"), class = "btn-sm btn-primary", icon = icon("pen-to-square")),
          actionButton("pdm_resume", tr("pdm_resume"), class = "btn-sm btn-outline-primary", icon = icon("rotate-right")),
          actionButton("pdm_skip", tr("pdm_skip"), class = "btn-sm btn-outline-secondary", icon = icon("forward-step")),
          actionButton("pdm_end", tr("pdm_end"), class = "btn-sm btn-outline-danger", icon = icon("flag-checkered"))))
    } else {   # waiting (sirayla)
      div(class = "mt-1", div(class = "small text-primary", icon("hand-point-right"), " ", sprintf(tr("pdm_q_waiting"), jn(q$pos)), sprintf("  (%d/%d)", ndone, length(q$jobs))),
        div(class = "d-flex gap-2 flex-wrap mt-1",
          actionButton("pdm_rerun", tr("pdm_run_cur"), class = "btn-sm btn-primary", icon = icon("play")),
          actionButton("pdm_skip", tr("pdm_skip"), class = "btn-sm btn-outline-secondary", icon = icon("forward-step")),
          actionButton("pdm_end", tr("pdm_end"), class = "btn-sm btn-outline-danger", icon = icon("flag-checkered"))))
    }
  })

  # ---- kuyruk ----
  pdm_jobs <- function(ids) {
    cl <- isolate(rv$pdm_coll); jobs <- list()
    for (i in ids) { a <- cl$models[[i]]$allsnps %||% NA_character_; v <- if (is.na(a)) "TRUE" else if (identical(a, "BOTH")) c("TRUE", "FALSE") else a
      for (m in v) jobs[[length(jobs) + 1]] <- list(i = i, md = m, done = FALSE, st = "pending", runs = character(0), note = "") }
    jobs
  }
  pdm_start <- function(confirmed = FALSE) {
    cl <- rv$pdm_coll; rs <- pdm_res(); if (is.null(cl) || !length(rs)) return()
    if (is.null(rv$prefix)) { showNotification(tr("pdm_need_geno"), type = "error"); return() }
    if (!is.null(rv$proc)) { showNotification(tr("msg_running"), type = "warning"); return() }
    md <- rv$pdm_mode %||% "auto"; from <- rv$pdm_cur %||% 1L
    ids <- seq.int(from, length(cl$models))   # sirayla kipte de kuyruk secili modelden sona (her model kutulara gelir)
    red <- ids[vapply(rs[ids], function(r) identical(r$status, "red"), logical(1))]; ids <- setdiff(ids, red)
    if (!length(ids)) { showNotification(tr("pdm_nothing"), type = "error", duration = NULL); return() }
    tgt <- as.character(input$target %||% character(0)); if (length(tgt) && length(pdm_ac$tgt_auto) && setequal(tgt, pdm_ac$tgt_auto)) tgt <- character(0)   # dosyadan gelen Target kullanicinin secimi degil
    if (any(vapply(rs[ids], function(r) !length(r$labels$target), logical(1))) && !length(tgt)) { showNotification(tr("pdm_need_target"), type = "error", duration = NULL); return() }
    # onay yalniz bulunamayan birey varsa (karar: eksik sample ID ayri onay); .anno eslemesi / tekrar / ad duzeltme soru sormaz (varsayilan 1, 6, O2)
    warn <- ids[vapply(rs[ids], function(r) any(vapply(r$issues, function(z) z$code %in% c("missing", "right_dropped", "target_dropped"), logical(1))), logical(1))]
    if (!confirmed && identical(md, "auto") && length(warn)) { pdm_confirm(ids, red, warn); return() }   # sirayla kipte notlar kartta; calistir = onay
    if (length(red)) showNotification(sprintf(tr("pdm_conf_red"), length(red), paste(vapply(red, function(i) sprintf("%s (%s)", cl$models[[i]]$name, paste(vapply(rs[[i]]$issues, pdm_iss_tr, ""), collapse = "; ")), ""), collapse = " | ")), type = "warning", duration = 15)
    rv$pdm_sum <- pdm_sum_red(red, tgt)
    rv$pdmq <- list(jobs = pdm_jobs(ids), pos = 1L, mode = md, state = "running", tgt = tgt, t0 = Sys.time(), red = red, inflight = FALSE, prefix = rv$prefix)
    pdm_state_save()
    if (identical(md, "step") && !identical(isolate(rv$pdm_cur), ids[1])) { pdm_load(ids[1]); q <- rv$pdmq; q$state <- "waiting"; rv$pdmq <- q; pdm_state_save()   # secili model kirmiziydi: ilk calisabilen kutulara
      showNotification(sprintf(tr("pdm_next_loaded"), cl$models[[ids[1]]]$name), type = "message", duration = 6); return() }
    pdm_run_job(use_boxes = identical(md, "step"))
  }
  pdm_confirm <- function(ids, red, warn) {
    cl <- rv$pdm_coll; rs <- pdm_res(); nj <- length(pdm_jobs(ids))
    items <- lapply(warn, function(i) tags$li(tags$b(cl$models[[i]]$name), ": ", paste(vapply(rs[[i]]$issues, pdm_iss_tr, ""), collapse = " | ")))
    reds <- lapply(red, function(i) tags$li(tags$b(cl$models[[i]]$name), ": ", paste(vapply(rs[[i]]$issues, pdm_iss_tr, ""), collapse = " | ")))
    showModal(modalDialog(title = tr("pdm_conf_title"), easyClose = FALSE, size = "l",
      p(sprintf(tr("pdm_conf_body"), length(ids), nj)),
      if (length(red)) tagList(p(class = "text-danger mb-1", sprintf(tr("pdm_conf_red"), length(red), "")), tags$ul(class = "small text-danger", reds)),
      if (length(items)) tagList(p(tr("pdm_conf_miss")), tags$ul(class = "small", items)),
      footer = tagList(modalButton(tr("ow_cancel")),
        if (length(warn)) actionButton("pdm_conf_edit", tr("pdm_conf_edit"), class = "btn-outline-secondary", icon = icon("pen-to-square")),
        actionButton("pdm_conf_go", tr("pdm_conf_go"), class = "btn-primary", icon = icon("play")))))
    pdm_ac$pend_warn <- warn
  }
  observeEvent(input$pdm_conf_go, { removeModal(); safe_run(pdm_start(confirmed = TRUE), tr("pdm_title")) })
  # "Elle ekleme" secenegi: ilk uyarili model kutulara gelir, kip "Sirayla" olur (kullanici duzenleyip calistirir).
  observeEvent(input$pdm_conf_edit, { removeModal(); w <- pdm_ac$pend_warn; if (!length(w)) return()
    rv$pdm_mode <- "step"; pdm_load(w[1]); updateRadioButtons(session, "pdm_mode", selected = "step") })
  observeEvent(input$pdm_run, safe_run({ q <- rv$pdmq; if (!is.null(q) && q$state %in% c("running", "waiting", "stopped")) return(); pdm_start() }, tr("pdm_title")))
  pdm_meta_for <- function(i, rules, g = NULL, edited = FALSE) {
    x <- isolate(rv$pdm_coll)$models[[i]]; r <- pdm_res()[[i]]
    list(model = x$name, file = x$src, i = i, status = r$status, iss = r$issues, rules_n = sum(rules$Source == "qpadm"), out_n = sum(rules$Source == "qpadm_out"), notes = character(0),
         group_n = if (is.null(g)) 1L else length(g$idx), ref = x$ref, params = x$params, dataset = isolate(pdm_meta_cur())$dataset %||% "", edited = edited)
  }
  # Kutulara gore elle kosu (on tanimli kip acikken) icin: etkin modelin kurallari + not
  pdm_manual_ov <- function() {
    if (!isTRUE(isolate(rv$pdm_on)) || is.null(i <- isolate(rv$pdm_cur))) return(NULL)
    rl <- pdm_rules_of(i); if (is.null(rl)) return(NULL); g <- pdm_group_of(i)
    list(rules = rl, model = isolate(rv$pdm_coll)$models[[i]]$name, params = isolate(rv$pdm_coll)$models[[i]]$params, pdm = pdm_meta_for(i, rl, g, edited = pdm_boxes_edited(i)), boxes = TRUE, nav = TRUE)
  }
  # kutular modelin cozumunden farkli mi (Sonuclar'da "kutularda duzenlendi" notu yalniz o zaman)
  pdm_boxes_edited <- function(i) { r <- pdm_res()[[i]]; if (is.null(r)) return(TRUE); b <- function(id) as.character(isolate(input[[id]]) %||% character(0))
    !(setequal(b("left"), r$labels$left) && setequal(b("right"), r$labels$right) && (!length(r$labels$target) || setequal(b("target"), r$labels$target))) }
  # kuyrugu guvenle durdur (beklenmeyen hata, set degisimi, mesgul surec): kuyruk "running"de takili kalmaz
  pdm_halt <- function(msg) { q <- isolate(rv$pdmq); if (is.null(q)) return(invisible(NULL))
    q$inflight <- FALSE; q$state <- if (identical(q$mode, "step")) "waiting" else "stopped"; rv$pdmq <- q; pdm_state_save()
    showNotification(msg, type = "error", duration = NULL); console_add(sprintf("[%s] predefined queue halted: %s", format(Sys.time(), "%H:%M:%S"), msg)); invisible(NULL) }
  # kirmizi (calisamayan) modeller ozete gerekcesiyle (O3 / varsayilan 11)
  pdm_sum_red <- function(red, tgt) { if (!length(red)) return(NULL); cl <- isolate(rv$pdm_coll); rs <- pdm_res()
    do.call(rbind, lapply(red, function(i) { x <- cl$models[[i]]; r <- rs[[i]]; tl <- unique(x$pops$label[x$pops$role == "target"]); if (!length(tl)) tl <- tgt; if (!length(tl)) tl <- "\u2014"
      data.frame(model = x$name, allsnps = x$allsnps %||% "TRUE", target = tl, p = NA_real_, chisq = NA_real_, dof = NA_real_, feasible = NA_character_, weights = "", reference = "",
                 notes = paste("not run:", paste(vapply(r$issues, pdm_issue_en, ""), collapse = "; ")), file = x$src, stringsAsFactors = FALSE) })) }
  pdm_run_job <- function(use_boxes = FALSE) tryCatch(pdm_run_job0(use_boxes), error = function(e) pdm_halt(paste(tr("pdm_title"), conditionMessage(e), sep = ": ")))
  pdm_run_job0 <- function(use_boxes = FALSE) {
    q <- isolate(rv$pdmq); if (is.null(q)) return(invisible(NULL)); k <- q$pos
    if (k > length(q$jobs)) { pdm_finish(); return(invisible(NULL)) }
    if (!is.null(isolate(rv$proc))) { showNotification(tr("msg_running"), type = "warning"); if (identical(q$state, "running") && !isTRUE(q$inflight)) pdm_halt(tr("msg_running")); return(invisible(NULL)) }
    if (!identical(isolate(rv$prefix), q$prefix %||% isolate(rv$prefix))) { pdm_halt(tr("pdm_set_changed")); return(invisible(NULL)) }
    jb <- q$jobs[[k]]; i <- jb$i; rs <- pdm_res(); if (i > length(rs)) { pdm_halt(tr("pdm_set_changed")); return(invisible(NULL)) }
    r <- rs[[i]]; x <- isolate(rv$pdm_coll)$models[[i]]
    if (use_boxes && !identical(isolate(rv$pdm_cur), i)) {   # kutularda baska model var: kuyrugun modeli yuklenir, kullanici bakip calistirir
      pdm_load(i); q$state <- if (identical(q$mode, "auto")) "stopped" else "waiting"; q$inflight <- FALSE; rv$pdmq <- q
      showNotification(sprintf(tr("pdm_next_loaded"), x$name), type = "message", duration = 8); return(invisible(NULL)) }
    if (!use_boxes && !identical(isolate(rv$pdm_cur), i)) pdm_load(i)
    notes <- character(0)
    g <- pdm_group_of(i); rules <- if (is.null(g)) r$rules else g$rules
    tg <- if (length(r$labels$target)) r$labels$target else q$tgt
    if (!use_boxes && !length(r$labels$target) && length(tg)) {   # kullanicinin hedefi modelin bireyleriyle cakisiyorsa o hedef atlanir
      lm <- isolate(rv$labelmap); mids <- unique(unlist(r$comp, use.names = FALSE))
      bad <- tg[vapply(tg, function(t) length(intersect(lm[[t]] %||% character(0), c(mids, rules$SampleID))) > 0, logical(1))]
      if (length(bad)) { showNotification(sprintf(tr("pdm_tgt_clash"), x$name, paste(bad, collapse = ", ")), type = "warning", duration = 12); tg <- setdiff(tg, bad)
        notes <- c(notes, sprintf("target(s) skipped (overlap with model samples): %s", paste(bad, collapse = ", "))) } }
    pool <- if (!is.null(g) && identical(jb$md, "FALSE")) unique(c(g$pops, q$tgt)) else NULL
    pm <- pdm_meta_for(i, rules, g, edited = use_boxes && pdm_boxes_edited(i)); pm$pool_n <- length(pool); pm$md <- jb$md
    if (length(x$params)) notes <- c(notes, paste("file parameters:", paste(sprintf("%s=%s", names(x$params), unlist(x$params)), collapse = ", ")))
    pm$notes <- notes
    ov <- c(list(rules = rules, model = x$name, params = x$params, pdm = pm, pool_pops = pool, nav = (k == 1L || use_boxes)),
            if (use_boxes) list(boxes = TRUE) else list(target = tg, left = r$labels$left, right = r$labels$right))
    q$inflight <- TRUE; q$state <- "running"; rv$pdmq <- q
    if (!use_boxes && !length(tg)) launched <- FALSE
    else { safe_run(launch_run(if (identical(jb$md, "TRUE")) "allsnps_true" else "allsnps_false", confirmed = TRUE, ov = ov), "qpAdm")
      launched <- !is.null(isolate(rv$proc)) }
    if (!launched) { q <- isolate(rv$pdmq); q$inflight <- FALSE; q$jobs[[k]]$st <- "failed"; q$jobs[[k]]$done <- FALSE; rv$pdmq <- q
      if (!use_boxes) showNotification(sprintf(tr("pdm_job_fail"), x$name), type = "warning", duration = 10)   # kutulardan: launch_run kendi gerekcesini gosterir
      if (use_boxes) { q$state <- if (identical(q$mode, "auto")) "stopped" else "waiting"; rv$pdmq <- q; return(invisible(NULL)) }
      pdm_advance() }
    invisible(NULL)
  }
  # Is bitti / atlandi: sonraki ise gec (otomatik: kosar; sirayla: kutulara yukler ve bekler)
  pdm_advance <- function() {
    q <- isolate(rv$pdmq); q$pos <- q$pos + 1L; q$inflight <- FALSE
    if (q$pos > length(q$jobs)) { rv$pdmq <- q; pdm_finish(); return(invisible(NULL)) }
    if (identical(q$mode, "auto")) { q$state <- "running"; rv$pdmq <- q; pdm_state_save(); session$sendCustomMessage("qps_input", list(id = "pdm_go", value = q$pos)) }
    else { q$state <- "waiting"; rv$pdmq <- q; pdm_state_save(); i <- q$jobs[[q$pos]]$i
      if (!identical(isolate(rv$pdm_cur), i)) pdm_load(i)
      showNotification(sprintf(tr("pdm_next_loaded"), isolate(rv$pdm_coll)$models[[i]]$name), type = "message", duration = 6) }
    invisible(NULL)
  }
  observeEvent(input$pdm_go, { q <- rv$pdmq; if (is.null(q) || !identical(q$state, "running") || isTRUE(q$inflight)) return()
    if (!is.null(rv$proc)) { pdm_halt(tr("msg_running")); return() }   # baska bir kosu suruyor: kuyruk takilmaz, durur
    pdm_run_job(FALSE) })
  pdm_sum_add <- function(k, q) {
    bid <- k1$bid; if (is.null(bid)) return(invisible(NULL)); b <- isolate(rv$batches)[[bid]]; if (is.null(b)) return(invisible(NULL))
    jb <- q$jobs[[k]]; x <- isolate(rv$pdm_coll)$models[[jb$i]]; pm <- isolate(rv$pending)$pdm %||% list()
    rows <- lapply(b$batch, function(it) {
      w <- if (!is.null(it$res)) as.data.frame(it$res$weights) else data.frame()
      wt <- if (nrow(w)) paste(sprintf("%s: %.4f \u00b1 %.4f", w$left, w$weight, w$se), collapse = "; ") else ""
      cmp <- if (!is.null(it$res)) pdm_ref_compare(x$ref, it$target, jb$md, it$p, w) else NULL
      notes <- c(vapply(pm$iss %||% list(), pdm_issue_en, ""), pm$notes, if ((pm$rules_n %||% 0) > 0) sprintf("%d sample(s) relabelled by sample ID", pm$rules_n), if (isTRUE(pm$super)) "f2 pool built with a wider panel than requested", if (isTRUE(pm$edited)) "edited in the boxes", if (isTRUE((pm$group_n %||% 1) > 1) && identical(jb$md, "FALSE")) sprintf("shared f2 pool (%d models, %d pops)", pm$group_n, pm$pool_n %||% 0L), if (!is.null(it$error)) paste("ERROR:", it$error))
      data.frame(model = x$name, allsnps = jb$md, target = it$target, p = it$p %||% NA_real_, chisq = it$chisq %||% NA_real_, dof = it$dof %||% NA_real_, feasible = as.character(it$feasible %||% NA),
                 weights = wt, reference = pdm_ref_en(cmp), notes = paste(notes, collapse = "; "), file = x$src, stringsAsFactors = FALSE) })
    if (length(rows)) { nw <- do.call(rbind, rows); old <- isolate(rv$pdm_sum); key <- function(d) paste(d$model, d$allsnps, d$target, sep = "\r")
      if (!is.null(old) && nrow(old)) old <- old[!(key(old) %in% key(nw)), , drop = FALSE]   # yeniden kosu (Durdur sonrasi) eski satirin yerine gecer
      rv$pdm_sum <- rbind(old, nw) }
    invisible(NULL)
  }
  # launch_run'dan baslayan bir kuyruk isinin sonu (basari / hata / durdurma). Elle kosular kuyrugu ilerletmez.
  pdm_after_run <- function(st) {
    q <- isolate(rv$pdmq)
    if (identical(st, "stop") && !is.null(q) && identical(q$state, "running") && !isTRUE(q$inflight)) { q$state <- "stopped"; rv$pdmq <- q; pdm_state_save(); return(invisible(NULL)) }
    if (is.null(q) || !isTRUE(q$inflight)) return(invisible(NULL))
    k <- q$pos; q$inflight <- FALSE; q$jobs[[k]]$runs <- c(q$jobs[[k]]$runs, k1$nm[!is.na(k1$nm)])
    tryCatch(pdm_sum_add(k, q), error = function(e) console_add(sprintf("[ERROR] predefined summary: %s", conditionMessage(e))))
    if (identical(st, "stop")) { q$state <- "stopped"; q$jobs[[k]]$st <- "stopped"; rv$pdmq <- q; pdm_state_save(); return(invisible(NULL)) }
    q$jobs[[k]]$st <- if (identical(st, "ok")) "done" else "error"; q$jobs[[k]]$done <- TRUE; rv$pdmq <- q
    tryCatch(pdm_advance(), error = function(e) pdm_halt(paste(tr("pdm_title"), conditionMessage(e), sep = ": ")))
  }
  observeEvent(input$pdm_rerun, safe_run({ q <- rv$pdmq; if (is.null(q) || !q$state %in% c("stopped", "waiting")) return()
    if (!is.null(rv$proc)) { showNotification(tr("msg_running"), type = "warning"); return() }; pdm_run_job(use_boxes = TRUE) }, tr("pdm_title")))
  observeEvent(input$pdm_resume, safe_run({ q <- rv$pdmq; if (is.null(q) || !identical(q$state, "stopped")) return()
    if (!is.null(rv$proc)) { showNotification(tr("msg_running"), type = "warning"); return() }; q$state <- "running"; rv$pdmq <- q; pdm_run_job(FALSE) }, tr("pdm_title")))
  observeEvent(input$pdm_skip, safe_run({ q <- rv$pdmq; if (is.null(q) || !q$state %in% c("stopped", "waiting")) return()
    if (!is.null(rv$proc)) { showNotification(tr("msg_running"), type = "warning"); return() }
    q$jobs[[q$pos]]$st <- "skipped"; rv$pdmq <- q; pdm_advance() }, tr("pdm_title")))
  observeEvent(input$pdm_end, pdm_finish())
  pdm_finish <- function(quiet = FALSE) {
    q <- isolate(rv$pdmq); if (is.null(q)) return(invisible(NULL)); q$state <- "done"; q$inflight <- FALSE; q$t1 <- Sys.time(); rv$pdmq <- q
    pdm_state_clear()
    nd <- sum(vapply(q$jobs, function(j) identical(j$st, "done"), logical(1)))
    if (!quiet) showNotification(sprintf(tr("pdm_done"), nd, length(q$jobs)), type = "message", duration = 10)
    invisible(NULL)
  }
  observeEvent(input$pdm_show_sum, nav_select("main_nav", "results"))

  # ---- O6: cokme / kapanma sonrasi devam (durum dosyasi programin klasorunde) ----
  pdm_state_save <- function() {
    q <- isolate(rv$pdmq); if (is.null(q) || identical(q$state, "done")) return(invisible(NULL))
    rn <- unique(unlist(lapply(q$jobs, function(j) j$runs), use.names = FALSE)); runs <- isolate(rv$runs); rr <- runs[intersect(rn, names(runs))]
    bids <- unique(vapply(rr, function(x) x$batch %||% "", "")); bb <- isolate(rv$batches); bb <- bb[intersect(bids, names(bb))]
    cl <- isolate(rv$pdm_coll); if (!is.null(cl)) cl$meta <- isolate(pdm_meta_cur())
    st <- list(v = 1L, q = q, coll = cl, prefix = isolate(rv$prefix), runs = rr, batches = bb, sum = isolate(rv$pdm_sum), mode = isolate(rv$pdm_mode), time = Sys.time())
    tryCatch({ tmp <- paste0(PDM_STATE, ".tmp"); saveRDS(st, tmp); file.rename(tmp, PDM_STATE) }, error = function(e) console_add(sprintf("[WARN] queue state not saved: %s", conditionMessage(e))))
    invisible(NULL)
  }
  pdm_state_clear <- function() if (file.exists(PDM_STATE)) try(unlink(PDM_STATE), silent = TRUE)
  local({ st <- tryCatch(if (file.exists(PDM_STATE)) readRDS(PDM_STATE) else NULL, error = function(e) NULL)
    if (!is.null(st$q) && !identical(st$q$state, "done"))
      { rc <- list(n_done = sum(vapply(st$q$jobs, function(j) isTRUE(j$done), logical(1))), n = length(st$q$jobs), time = st$time %||% Sys.time()); rv$pdm_rec <- rc
        showNotification(paste(sprintf(tr("pdm_rec_msg"), rc$n_done, rc$n, format(rc$time, "%Y-%m-%d %H:%M")), tr("pdm_rec_where")), type = "warning", duration = 20) } })
  pdm_restore <- function(go) {
    if (!is.null(rv$proc)) { showNotification(tr("msg_running"), type = "warning"); return(invisible(NULL)) }   # afis kalir; kosu bitince yeniden denenir
    st <- tryCatch(readRDS(PDM_STATE), error = function(e) NULL); rv$pdm_rec <- NULL
    if (is.null(st)) { pdm_state_clear(); return(invisible(NULL)) }
    # oturumda ayni adli kayit / toplu kayit varsa geri yuklenenler yeni ad alir (ustune yazilmaz, yanlis kayda baglanmaz)
    bb <- rv$batches; bmap <- character(0)
    for (nm in names(st$batches)) { nn <- nm
      if (!is.null(bb[[nn]]) && !identical(bb[[nn]], st$batches[[nm]])) { n <- suppressWarnings(as.integer(sub("^b", "", names(bb)))); nn <- sprintf("b%03d", max(c(0L, n), na.rm = TRUE) + 1L) }
      bb[[nn]] <- st$batches[[nm]]; bmap[nm] <- nn }
    rv$batches <- bb
    runs <- rv$runs; rmap <- character(0)
    for (nm in names(st$runs)) { x <- st$runs[[nm]]; if (!is.null(x$batch) && x$batch %in% names(bmap)) x$batch <- unname(bmap[x$batch])
      nn <- nm; k <- 2L; while (!is.null(runs[[nn]]) && !identical(runs[[nn]], x)) { nn <- paste0(nm, "_r", k); k <- k + 1L }; runs[[nn]] <- x; rmap[nm] <- nn }
    rv$runs <- runs
    st$q$jobs <- lapply(st$q$jobs, function(j) { j$runs <- unname(ifelse(j$runs %in% names(rmap), rmap[j$runs], j$runs)); j })
    st$runs <- runs[unname(rmap)]
    rv$pdm_sum <- st$sum; rv$pdm_coll <- st$coll; pdm_meta_live(list()); pdm_meta_tick(pdm_meta_tick() + 1); rv$pdm_mode <- st$mode %||% st$q$mode %||% "auto"
    if (!go) { pdm_state_clear(); if (length(st$runs)) rv$graph_pick <- names(st$runs)[length(st$runs)]; return(invisible(NULL)) }
    if (is.null(rv$prefix) || !identical(normalizePath(rv$prefix, mustWork = FALSE), normalizePath(st$prefix %||% "", mustWork = FALSE))) {
      fs <- geno_fileset(st$prefix %||% "")
      if (is.null(fs)) { showNotification(sprintf(tr("pdm_rec_nogeno"), st$prefix %||% "?"), type = "error", duration = NULL); return(invisible(NULL)) }
      set_geno(unname(fs$files[1]), remember = FALSE) }
    q <- st$q; q$inflight <- FALSE; q$state <- "running"; q$prefix <- rv$prefix; rv$pdmq <- q
    session$sendCustomMessage("qps_input", list(id = "pdm_go", value = -q$pos))
  }
  observeEvent(input$pdm_rec_go, safe_run(pdm_restore(TRUE), tr("pdm_title")))
  observeEvent(input$pdm_rec_load, safe_run(pdm_restore(FALSE), tr("pdm_title")))
  observeEvent(input$pdm_rec_del, { rv$pdm_rec <- NULL; pdm_state_clear() })

  # ---- Model > "On tanimli modellere ekle" ----
  pdm_last_runs <- function(left, right) {
    rr <- Filter(function(r) setequal(r$left %||% character(0), left) && setequal(r$right %||% character(0), right), rv$runs)
    if (!length(rr)) return(list()); b <- max(vapply(rr, function(r) r$batch %||% "", "")); Filter(function(r) identical(r$batch %||% "", b), rr)
  }
  observeEvent(input$pdm_add, {
    if (!length(input$left) || !length(input$right)) { showNotification(tr("pdm_add_need"), type = "error"); return() }
    rr <- pdm_last_runs(input$left, input$right); md0 <- if (length(rr)) unique(vapply(rr, function(r) r$meta$mode %||% "TRUE", "")) else "TRUE"
    md0 <- if (length(md0) > 1) "BOTH" else md0
    nm0 <- sprintf("M%02d", length(rv$pdm_coll$models %||% list()) + 1L)
    showModal(modalDialog(title = tr("pdm_add_title"), easyClose = TRUE,
      textInput("pdm_add_name", tr("pdm_add_name"), nm0, width = "100%"),
      if (length(input$target)) checkboxInput("pdm_add_tgt", sprintf(tr("pdm_add_tgt"), pdm_cell(input$target)), FALSE),
      radioButtons("pdm_add_as", "allsnps", c("TRUE", "FALSE", "BOTH"), md0, inline = TRUE),
      if (length(rr)) checkboxInput("pdm_add_ref", sprintf(tr("pdm_add_ref"), length(rr)), FALSE) else div(class = "small text-muted", tr("pdm_add_noref")),
      footer = tagList(modalButton(tr("ow_cancel")), actionButton("pdm_add_go", tr("pdm_add_go"), class = "btn-primary", icon = icon("plus")))))
  })
  observeEvent(input$pdm_add_go, safe_run({
    removeModal(); nm <- trimws(input$pdm_add_name %||% ""); if (!nzchar(nm)) nm <- sprintf("M%02d", length(rv$pdm_coll$models %||% list()) + 1L)
    vf <- rv$vfam; ent <- rv$split_ent %||% SPLIT_EMPTY; cols <- c("SampleID", "VirtualLabel", "OriginalLabel", "Source")
    pr <- pdm_active_rules(); if (!is.null(pr) && nrow(pr)) vf <- split_vfam(vf, pr)
    sel <- unique(c(input$left, input$right, if (isTRUE(input$pdm_add_tgt)) input$target)); e2 <- ent[ent$VirtualLabel %in% sel, , drop = FALSE]
    if (nrow(e2)) vf <- split_vfam(vf, e2[, cols])
    lm2 <- vfam_apply_labels(rv$base_labelmap, vf)
    pa <- panel_args(); as <- input$pdm_add_as %||% "TRUE"
    prm <- list(blgsize = pa$blgsize); if (!identical(as, "TRUE")) prm$maxmiss <- pa$maxmiss
    an <- tryCatch(pdm_anno(), error = function(e) NULL)
    m <- pdm_from_selection(nm, if (isTRUE(input$pdm_add_tgt)) input$target else character(0), input$left, input$right, lm2, as, prm, an)
    if (isTRUE(input$pdm_add_ref)) { rr <- pdm_last_runs(input$left, input$right)
      m$ref <- do.call(rbind, c(list(pdm_empty_ref()), lapply(rr, function(r) { b <- rv$batches[[r$batch %||% ""]]; fd <- b$meta$prefix %||% rv$prefix
        pdm_ref_rows(r$meta$target, r$meta$mode %||% "TRUE", r$meta$p, r$meta$chisq, r$meta$dof, r$meta$feasible, r$res$weights, dataset = basename(rv$prefix %||% ""),
                     pool = if (identical(r$meta$mode, "FALSE")) sprintf("maxmiss=%s", r$meta$maxmiss %||% "?") else "allsnps=TRUE", nsnp = r$snp$used %||% NA_real_) }))) }
    cl <- rv$pdm_coll %||% pdm_new_coll(); cl$meta <- if (is.null(rv$pdm_coll)) cl$meta else pdm_meta_cur(); if (!length(cl$models) && !nzchar(cl$meta$dataset %||% "")) cl$meta$dataset <- pdm_guess_ds(rv$prefix)
    mg <- pdm_merge(cl, list(meta = list(), models = list(m)))
    if (!mg$added) { showNotification(tr("pdm_add_dup"), type = "warning"); return() }
    first <- is.null(rv$pdm_coll); rv$pdm_coll <- mg$coll; if (first) { pdm_meta_live(list()); pdm_meta_tick(pdm_meta_tick() + 1) }
    showNotification(sprintf(tr("pdm_added"), mg$coll$models[[length(mg$coll$models)]]$name, length(mg$coll$models)), type = "message", duration = 10)
  }, tr("pdm_add")))

  # ---- Sonuclar: model notu (O5 referans, varsayilan 11) ve ozet (O10) ----
  output$pdm_note_ui <- renderUI({ lang_rv(); r <- shown_run(); m <- r$meta$pdm; if (is.null(m)) return(NULL)
    cmp <- tryCatch(pdm_ref_compare(m$ref, r$meta$target, r$meta$mode, r$meta$p, r$res$weights), error = function(e) NULL)
    rf <- if (is.null(cmp)) NULL else if (isTRUE(cmp$same)) div(class = "text-success", icon("scale-balanced"), " ", tr("pdm_ref_same"))
      else div(class = "text-warning", icon("scale-balanced"), " ", sprintf(tr("pdm_ref_diff"), if (is.na(cmp$dw)) 0 else 100 * cmp$dw, format(signif(cmp$p_ref, 3)), format(signif(cmp$p_cur, 3))))
    div(class = "small border rounded p-2 mt-2", style = sprintf("border-left:4px solid %s !important;", pdm_st_col(m$status)),
      div(icon("list-check"), " ", tags$b(tr("pdm_note_title")), ": ", m$model, if (nzchar(m$file %||% "")) paste0("  (", m$file, ")") else "", if (isTRUE(m$edited)) paste0(" \u00b7 ", tr("pdm_note_edited")) else ""),
      if (length(m$iss)) tags$ul(class = "mb-1 ps-3", lapply(m$iss, function(z) tags$li(pdm_iss_tr(z)))),
      if ((m$rules_n %||% 0) > 0) div(class = "text-muted", sprintf(tr("pdm_note_rules"), m$rules_n)),
      if (isTRUE((m$group_n %||% 1) > 1) && identical(r$meta$mode, "FALSE")) div(class = "text-muted", sprintf(tr("pdm_note_pool"), m$group_n, m$pool_n %||% 0L)),
      if (isTRUE(m$super)) div(class = "text-muted", tr("panel_super_note")),
      if (length(m$notes)) div(class = "text-muted", paste(m$notes, collapse = " \u00b7 ")),
      rf)
  })
  output$pdm_sum_ui <- renderUI({ lang_rv(); sm <- rv$pdm_sum; if (is.null(sm) || !nrow(sm)) return(NULL)
    card(full_screen = TRUE, card_header(tr("pdm_sum_title")),
      card_body(fillable = FALSE, div(class = "d-flex gap-2 mb-2", downloadButton("dl_pdm_sum", tr("pdm_sum_xlsx"), class = "btn-success btn-sm")), div(style = "overflow-x:auto", DTOutput("pdm_sum_tbl")))) })
  output$pdm_sum_tbl <- renderDT({ sm <- rv$pdm_sum; req(sm, nrow(sm)); col <- paste0(sm$model, " [", sm$allsnps, "]")
    mt <- stats::reshape(data.frame(Target = sm$target, model = col, p = vapply(sm$p, function(v) if (is.na(v)) "\u2014" else format(signif(v, 3)), ""), stringsAsFactors = FALSE),
                         idvar = "Target", timevar = "model", direction = "wide")
    names(mt) <- sub("^p\\.", "", names(mt)); datatable(mt, rownames = FALSE, fillContainer = FALSE, options = list(dom = "t", paging = FALSE, ordering = FALSE, autoWidth = FALSE)) })
  output$dl_pdm_sum <- downloadHandler(filename = function() sprintf("qpadm_predefined_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) write_pdm_excel(rv$pdm_sum, file))

  observeEvent(input$stop, { if (!is.null(rv$proc)) { try(rv$proc$kill(), silent = TRUE); rv$proc <- NULL }
    kept <- tryCatch(k1_partial(stopped = TRUE), error = function(e) 0L)   # v6.2 (K1): bitenler korunur
    rv$done <- FALSE; rv$progress <- 0; rv$progmsg <- tr("msg_stopped"); rv$t_end <- Sys.time()
    console_add(sprintf("[%s] qpAdm stopped by user (%s)%s", format(Sys.time(), "%H:%M:%S"), el_str(rv$t_start, rv$t_end) %||% "-",
                        if (kept > 0) sprintf("; %d finished model(s) kept", kept) else ""))
    showNotification(if (kept > 0) sprintf(tr("k1_kept"), kept, length(k1$jobs)) else tr("msg_stopped"), type = "warning", duration = if (kept > 0) 10 else 5)
    pdm_after_run("stop") })   # v6.3 test

  # Havuz yan dosyasi: extract_f2 bittikten sonra bir kez yazilir.
  # v5.5'teki ust-kume aramasi (S3) bu dosyaya bakacak; admixtools'un kendi
  # cache_metadata.json'i prefix'i KAYDETMEZ ve eski surumlerde hic yazilmaz.
  flush_pool_meta <- function() {
    pp <- rv$pool_pending
    if (is.null(pp) || !pool_ok(pp$dir)) return(invisible(NULL))
    pool_write_meta(pp$dir, pp$prefix, pp$pops, pp$maxmiss, pp$blgsize %||% F2_BLGSIZE, pp$adjph %||% F2_ADJPH, pp$auto_only %||% F2_AUTOONLY, pp$vfam, pp$orig, pp$comp)
    rv$pool_pending <- NULL
    rv$panel_tick <- rv$panel_tick + 1
    invisible(NULL)
  }

  # v6.2 (K1): kosu sonu. Henuz eklenmemis isler (out'tan) eklenir; allsnps=TRUE'da hedef SNP sayisi (bg'de kosu sonunda
  # sayildigi icin) ve f4 tablolari tam logdan yeniden okunup kayitlar tamamlanir; kayit kapatilir. Kosu disinda
  # (sinamalar) dogrudan cagrilirsa isler out'un adlarindan kurulur (hedef basina bir is).
  finalize <- function(out) {
    pend <- rv$pending; now <- Sys.time(); md <- if (identical(pend$mode, "allsnps_true")) "TRUE" else "FALSE"
    if (is.null(k1$jobs) || isTRUE(k1$closed))
      k1_init(lapply(names(out), function(t) list(key = t, t = t, left = pend$left, model = NULL, tag = t)),
              tcache = if (identical(md, "TRUE")) tsnp_cache_read() else list())
    # v6.3 test2: attr(..., exact = TRUE) -- sayim basarisizsa "qps_tsnp" yok ve kismi eslesme "qps_tsnp_secs"i donduruyordu
    raw_lg <- k1_read_log(); tsv <- attr(out, "qps_tsnp", exact = TRUE); tsecs <- attr(out, "qps_tsnp_secs", exact = TRUE); k1$tsv <- tsv; k1$tdone <- TRUE   # v6.3 (S6): sayim bitti (basarisiz da olsa)
    if (identical(md, "TRUE") && is.null(tsv)) { te <- grep("^QPS_TSNP_ERR ", strip_ansi(raw_lg), value = TRUE)   # v6.3 test2 (S1): hata konsola
      if (length(te)) console_add(paste0("ERROR target SNPs: ", sub("^QPS_TSNP_ERR ", "", te[length(te)]))) }
    for (k in which(!k1$seen)) { jb <- k1$jobs[[k]]; r <- out[[jb$key]] %||% simpleError("no result"); fin_add(k, r, raw_lg) }
    if (identical(md, "TRUE")) {
      runs <- rv$runs; bt <- rv$batches[[k1$bid]]; tput <- list(); ch <- FALSE
      for (k in which(!is.na(k1$nm))) { jb <- k1$jobs[[k]]; nm <- k1$nm[k]; si <- k1_snp(k, jb$t, md, raw_lg)
        if (!is.null(runs[[nm]]) && !identical(runs[[nm]]$snp, si)) {
          if (!identical(runs[[nm]]$snp$target, si$target)) console_add(sprintf("SNPs [%s]: %s", jb$tag, snp_line_en(si)))
          runs[[nm]]$snp <- si; ch <- TRUE }
        if (!is.null(bt$batch[[jb$key]])) bt$batch[[jb$key]]$snp <- si
        kk <- pend$tsnp_keys[[jb$t]] %||% NA_character_
        if (!is.na(kk) && is.null(k1$tcache[[kk]]) && is.null(tput[[kk]]) && isTRUE(is.finite(si$target)))
          tput[[kk]] <- list(n = si$target, target = jb$t, time = format(now, "%Y-%m-%d %H:%M:%S"), secs = tsecs)
      }
      if (ch) rv$runs <- runs
      if (!is.null(k1$bid) && !is.null(bt)) rv$batches[[k1$bid]] <- bt
      if (length(tput)) tsnp_cache_put(tput)
    }
    if (!is.null(tsecs)) console_add(sprintf("Target SNP count (allsnps=TRUE, one genotype read): %s", fmt_dur(tsecs)))
    fin_close(raw_lg, stopped = FALSE)
  }

  observe({
    p <- rv$proc; if (is.null(p)) return(); invalidateLater(400)
    isolate({
      txt <- if (!is.null(rv$logf) && file.exists(rv$logf)) tryCatch(readLines(rv$logf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_progress(txt, rv$snp_total)
      rv$progress <- max(rv$progress %||% 0, pr$frac)   # ibre geri gitmesin
      rv$progmsg <- pr$msg
      # v6.0 (K10): kalan sure -- yalniz blok sayaci olan asamada (allsnps=TRUE qpadm blok dongusu).
      # Toplu kosuda her hedefte sayac basa doner; hiz ilk gorulen bloktan olculur.
      if (!is.null(pr$blk)) {
        if (is.null(rv$blk_t0) || pr$blk < (rv$blk_last %||% 0)) { rv$blk_t0 <- Sys.time(); rv$blk_k0 <- pr$blk }
        rv$blk_last <- pr$blk; dk <- pr$blk - (rv$blk_k0 %||% pr$blk)
        rv$eta <- if (dk >= 5 && pr$tot > pr$blk) fmt_dur(as.numeric(difftime(Sys.time(), rv$blk_t0, units = "secs")) / dk * (pr$tot - pr$blk)) else NULL
        rv$eta_key <- if (isTRUE(pr$phase)) "prog_eta_phase" else "prog_eta"   # v6.5: tek gecis -> "bu asama icin kalan"
      } else rv$eta <- NULL
      rcx <- unique(c(txt[grepl("^QPS_RCOND ", txt)], pr$rcond))
      if (length(rcx)) rv$rcond <- unique(c(rv$rcond, rcx))
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (D1/D2)
      tryCatch(k1_poll(txt), error = function(e) console_add(sprintf("[ERROR] partial results: %s", conditionMessage(e))))   # v6.2 (K1)
      if (!p$is_alive()) {
        out <- tryCatch(p$get_result(), error = function(e) {
          tail_log <- if (length(txt)) paste(utils::tail(txt, 6), collapse = "\n") else ""
          msg <- paste0(tr("msg_error_prefix"), conditionMessage(e), if (nzchar(tail_log)) paste0("\n\n", tr("msg_log_tail"), "\n", tail_log) else "")
          showNotification(msg, type = "error", duration = NULL)
          console_add(sprintf("[%s] qpAdm ERROR: %s", format(Sys.time(), "%H:%M:%S"), conditionMessage(e))); NULL })
        rv$proc <- NULL; rv$t_end <- Sys.time(); rv$eta <- NULL
        flush_pool_meta()
        if (!is.null(out)) { opened <- isTRUE(k1$opened); finalize(out); rv$done <- TRUE; rv$progress <- 1; rv$progmsg <- tr("msg_completed")
          nok <- sum(!vapply(out, function(x) inherits(x, "error"), logical(1)))
          console_add(sprintf("[%s] qpAdm finished: %d/%d model(s) OK (%s)", format(Sys.time(), "%H:%M:%S"), nok, length(out), el_str(rv$t_start, rv$t_end) %||% "-"))
          # v6.0 (D3-b): log kosunun kaydinda (RAW); ekranda dokum en altta kalsin
          rv$bg_log <- character(0)
          showNotification(tr("msg_done"), type = "message")
          # v6.2 (K1): Sonuclar ilk sonucla acilmistir; kosu sonu ekrani degistirmez (hic sonuc yoksa hatalar icin acilir)
          if (!opened && !isTRUE(k1$opened)) nav_select("main_nav", "results")
          pdm_after_run("ok") }   # v6.3 test
        else { kept <- tryCatch(k1_partial(stopped = FALSE), error = function(e) 0L)
          rv$done <- FALSE; rv$progress <- 0; rv$progmsg <- tr("prog_error_notif")
          if (kept > 0) showNotification(sprintf(tr("k1_kept_err"), kept), type = "warning", duration = NULL)
          pdm_after_run("error") }
      }
    })
  })

  output$progress_ui <- renderUI({
    running <- !is.null(rv$proc); done <- isTRUE(rv$done); if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.0 (K9): gecen sure saniyede bir
    prog_ui(done, rv$progress, rv$progmsg, el = el_str(rv$t_start, if (running) NULL else rv$t_end), eta = if (running) rv$eta else NULL, eta_key = rv$eta_key %||% "prog_eta")
  })

  # ---- Ozet kutulari (yari yukseklik, feasible renkli) ----
  # v6.0 (D5-b): Sonuclar sekmesinde GOSTERILEN model = rv$graph_pick (tek secici; grafik de onu izler).
  # Kutular, popdrop, right seti ve etiket eslemesi bu kosudan; agirliklar, RAW ve toplu Excel onun
  # toplu kosusundan gelir. Kayit yoksa (eski oturum) son toplu kosuya duser.
  shown_run <- reactive({ k <- rv$graph_pick; if (is.null(k)) NULL else rv$runs[[k]] })
  shown_batch <- reactive({
    r <- shown_run(); b <- if (!is.null(r$batch)) rv$batches[[r$batch]] else NULL
    if (!is.null(b)) return(b)
    if (is.null(rv$batch)) return(NULL)
    pend <- rv$pending %||% list()
    list(batch = rv$batch, right = rv$right, left = rv$left, rcond = rv$rcond, log = rv$bg_log, vfam = rv$vfam, labelmap = rv$labelmap,
         meta = list(mode = if (identical(pend$mode, "allsnps_true")) "TRUE" else "FALSE", maxmiss = pend$maxmiss))
  })
  fmr <- reactive({ r <- shown_run(); req(r); qpadm_fullmodel(r$res, r$left) })

  # ---- v6.1 ADIM 3 (istek 6): toplu kosu tablosu ----
  observeEvent(input$bt_sort, { x <- input$bt_sort; rv$bt_sort <- list(col = as.character(x$col %||% ""), dir = as.character(x$dir %||% "desc")) })
  # v6.2 (K1): kosu surerken / durdurulmus kosuda tablo ustunde not
  k1_note <- function(b) { n <- rv$k1_n
    if (!is.null(n) && isTRUE(n$running) && !is.null(k1$bid) && identical(shown_run()$batch, k1$bid))
      return(div(class = "small fw-bold text-primary mb-1", sprintf(tr("k1_bt_live"), n$done, n$total)))
    if (!is.null(b$meta$stopped)) return(div(class = "small text-warning mb-1", sprintf(tr("k1_bt_stopped"), b$meta$stopped)))
    NULL }
  # v6.5 ADIM 3 (madde 6): tablo kaynagi -- Biriken modellerden secim (rv$bt_sel; en az iki kayit duruyorsa) ya da
  # gosterilen modelin toplu kosusu. PNG, pano ve tablonun Excel'i de bunu alir.
  bt_batch <- reactive({ s <- rv$bt_sel
    if (length(s)) { ks <- intersect(s, names(rv$runs)); if (length(ks) >= 2) return(bt_sel_batch(rv$runs[ks], rv$batches)) }
    shown_batch() })
  bts_note <- function(b) div(class = "small fw-bold text-primary mb-1 d-flex gap-2 align-items-center flex-wrap",
    span(sprintf(tr("bts_note"), b$meta$n)), actionLink("bt_back", tr("bt_back"), icon = icon("arrow-left")))
  output$bt_ui <- renderUI({
    lang_rv(); b <- bt_batch(); f <- if (is.null(b)) NULL else bt_frame(b)
    if (identical(b$kind, "seq")) return(hint(tr("k9_no_table")))   # v6.2 (K9)
    if (is.null(f)) return(hint(tr("bt_none")))
    st <- isolate(rv$bt_sort) %||% list(col = "", dir = "desc"); ord <- bt_order(f, st$col, st$dir); nl <- length(f$left)
    th <- function(lbl, col) tags$th(`data-col` = col, `data-dir` = if (identical(st$col, col)) st$dir else NULL, title = lbl, span(class = "qps-bt-rot", lbl))
    head <- tags$tr(tags$th(class = "qps-bt-t", `data-col` = "target", `data-dir` = if (identical(st$col, "target")) st$dir else NULL, "Target"),
      lapply(seq_len(nl), function(j) th(f$left[j], paste0("L", j))), th("p", "p"), th("chisq", "chisq"), th("feasible", "feasible"))
    rows <- lapply(ord, function(i) tags$tr(
      tags$td(class = "qps-bt-t", `data-v` = f$target[i], title = if (nzchar(f$err[i])) f$err[i] else NULL, f$target[i]),
      lapply(seq_len(nl), function(j) { w <- f$W[i, j]; cl <- bt_color(w, j, nl)
        tags$td(`data-v` = if (is.na(w)) "" else format(w, digits = 15), style = sprintf("background:%s;color:%s;", cl$bg, if (isTRUE(w < 0)) "#c62828" else cl$fg),
          if (is.na(w)) (if (nzchar(f$err[i])) "ERROR" else "\u2014")
          else tagList(div(class = "qps-bt-v", sprintf("%.3f", w)), div(class = "qps-bt-s", sprintf("se %.3f \u00b7 z %.2f", f$S[i, j], f$Z[i, j])))) }),
      tags$td(`data-v` = if (is.na(f$p[i])) "" else format(f$p[i], digits = 15), fmt(f$p[i])),
      tags$td(`data-v` = if (is.na(f$chisq[i])) "" else format(f$chisq[i], digits = 15), fmt(f$chisq[i])),
      tags$td(`data-v` = if (is.na(f$feasible[i])) "" else as.numeric(f$feasible[i]), if (is.na(f$feasible[i])) "NA" else as.character(f$feasible[i]))))
    tagList(hint(tr("bt_hint")), if (identical(b$kind, "sel")) bts_note(b) else k1_note(b), div(class = "qps-bt-wrap", tags$table(class = "qps-bt", id = "qps_bt", tags$thead(head), tags$tbody(rows))),
      tags$script(HTML("setTimeout(window.qpsBtFit, 30);")))
  })
  # kayit klasoru: kartin kendi dugmesi; secilmediyse grafik kartinin klasoru
  shinyDirChoose(input, "bt_dir", roots = volumes, session = session)
  bt_dir_sel <- function() { d <- tryCatch(shinyFiles::parseDirPath(volumes, input$bt_dir), error = function(e) character(0)); if (length(d)) d else png_dir_sel() }
  output$bt_dir_path <- renderText({ lang_rv(); d <- bt_dir_sel(); if (length(d)) paste0(tr("save_folder"), ": ", d) else tr("folder_not_selected") })
  observeEvent(input$bt_png, {
    b <- bt_batch(); f <- if (is.null(b)) NULL else bt_frame(b)
    if (is.null(f)) { showNotification(tr("bt_none"), type = "error"); return() }
    d <- bt_dir_sel(); if (!length(d)) { showNotification(tr("msg_pick_folder"), type = "error"); return() }
    st <- rv$bt_sort %||% list(col = "", dir = "desc"); ord <- bt_order(f, st$col, st$dir); wh <- bt_png_size(f)
    bid <- if (identical(b$kind, "sel")) "sel" else shown_run()$batch %||% "b000"; stamp <- gsub("[^0-9]", "", b$meta$time %||% format(Sys.time(), "%Y%m%d%H%M%S"))
    fn <- file.path(d, sprintf("qpadm_batch_%s_%s.png", bid, stamp))
    tryCatch({ save_png(bt_plot(f, ord), fn, wh[1], wh[2]); showNotification(sprintf(tr("msg_saved_to"), fn), type = "message", duration = 8) },
      error = function(e) showNotification(paste0(tr("msg_png_error"), ": ", conditionMessage(e)), type = "error", duration = NULL))
  })
  # v6.5 ADIM 3 (madde 6): tablodaki modellerin toplu Excel'i (bugunku bicim: Summary / Weights / Popdrop / rcond)
  output$bt_xlsx <- downloadHandler(
    filename = function() sprintf("qpadm_batch_table_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { b <- bt_batch(); if (is.null(b)) { showNotification(tr("bt_none"), type = "error"); return() }
      write_batch_excel(b$batch, b$right, b$left, b$labelmap %||% rv$labelmap, file, rcond_lines = b$rcond %||% character(0), kind = if (identical(b$kind, "seq")) "seq" else "batch") })
  observeEvent(input$bt_back, { rv$bt_sel <- NULL })
  # ---- v6.2 (K5): toplu kosu tablosu panoya (PNG ile ayni gorsel) ----
  clip <- new.env(parent = emptyenv()); clip$cur <- NULL; clip_tick <- reactiveVal(0)
  session$onSessionEnded(function() { d <- clip$cur; if (!is.null(d)) try(d$proc$kill(), silent = TRUE) })
  bt_png_file <- function() {
    b <- bt_batch(); f <- if (is.null(b)) NULL else bt_frame(b); if (is.null(f)) stop(tr(if (identical(b$kind, "seq")) "k9_no_table" else "bt_none"), call. = FALSE)
    st <- rv$bt_sort %||% list(col = "", dir = "desc"); ord <- bt_order(f, st$col, st$dir); wh <- bt_png_size(f)
    fn <- tempfile("qps_bt_", fileext = ".png"); save_png(bt_plot(f, ord), fn, wh[1], wh[2]); fn
  }
  observeEvent(input$bt_clip, {
    srv <- identical(clip_mode(), "server")
    if (srv && !is.null(clip$cur)) { showNotification(tr("bt_clip_busy"), type = "warning", duration = 4); return() }
    fn <- tryCatch(bt_png_file(), error = function(e) e)
    if (inherits(fn, "error")) {
      if (srv) showNotification(sprintf(tr("bt_clip_fail"), conditionMessage(fn)), type = "error", duration = 8)
      else session$sendCustomMessage("qps_clip_img", list(err = conditionMessage(fn)))
      return() }
    if (!srv) { session$sendCustomMessage("qps_clip_img", list(b64 = jsonlite::base64_enc(readBin(fn, "raw", file.size(fn))))); unlink(fn); return() }
    d <- clip_start(fn); if (!is.null(d$proc)) qps_reg(d$proc, "aux")   # v6.4
    if (is.null(d$proc)) { unlink(fn); showNotification(sprintf(tr("bt_clip_fail"), d$err %||% "PowerShell"), type = "error", duration = 8); return() }
    d$file <- fn; clip$cur <- d; clip_tick(isolate(clip_tick()) + 1)
  })
  observe({ clip_tick(); d <- clip$cur; if (is.null(d)) return(); invalidateLater(250)
    if (isTRUE(tryCatch(d$proc$is_alive(), error = function(e) FALSE))) return()
    clip$cur <- NULL; st <- tryCatch(d$proc$get_exit_status(), error = function(e) NA_integer_)
    e <- if (file.exists(d$errf)) trimws(paste(readLines(d$errf, warn = FALSE), collapse = " ")) else ""
    unlink(c(d$file, d$errf))
    if (isTRUE(as.integer(st) == 0L)) showNotification(tr("bt_clip_ok"), type = "message", duration = 4)
    else showNotification(sprintf(tr("bt_clip_fail"), if (nzchar(e)) e else paste("exit", st)), type = "error", duration = 10)
  })
  observeEvent(input$qps_clip_res, { x <- input$qps_clip_res
    if (isTRUE(x$ok)) showNotification(tr("bt_clip_ok"), type = "message", duration = 4)
    else showNotification(sprintf(tr("bt_clip_fail"), if (nzchar(x$err %||% "")) x$err else "?"), type = "error", duration = 10) })
  output$stat_boxes <- renderUI({
    lang_rv(); r <- shown_run(); req(r); f <- fmr()
    box <- function(lbl, val, accent = "qps-b-slate", valcol = NULL, sub = NULL) div(
      class = paste("qps-stat", accent),
      div(class = "lbl", lbl),
      div(class = "val", style = if (is.null(valcol)) NULL else sprintf("color:%s;", valcol), val),
      if (!is.null(sub) && nzchar(sub)) div(class = "sub", sub))
    feas <- f$feasible; is_t <- isTRUE(feas) || identical(as.character(feas), "TRUE")
    facc <- if (all(is.na(feas))) "qps-b-slate" else if (is_t) "qps-b-green" else "qps-b-red"
    fcol <- if (all(is.na(feas))) NULL else if (is_t) "#10b981" else "#ef4444"
    pv <- f$p
    pacc <- if (all(is.na(pv))) "qps-b-slate" else if (isTRUE(pv < 0.01)) "qps-b-red" else if (isTRUE(pv < 0.05)) "qps-b-amber" else "qps-b-green"
    pcol <- if (all(is.na(pv))) NULL else if (isTRUE(pv < 0.01)) "#ef4444" else if (isTRUE(pv < 0.05)) "#f59e0b" else "#10b981"
    div(class = "qps-stats mb-2",
      box(tr("p_value"), if (all(is.na(pv))) "--" else format(pv, digits = 4), pacc, pcol),
      box(tr("dof"), if (all(is.na(f$dof))) "--" else as.character(f$dof), "qps-b-blue", "#60a5fa"),
      box(tr("chisq"), if (all(is.na(f$chisq))) "--" else format(f$chisq, digits = 4), "qps-b-amber", "#fbbf24"),
      box(tr("feasible"), if (all(is.na(feas))) "--" else as.character(feas), facc, fcol),
      box(tr("n_sources"), as.character(NROW(r$res$weights)), "qps-b-slate"),   # v6.0 (K12)
      box(tr("used_snps"), snp_used_str(r$snp), "qps-b-blue", sub = snp_sub(r$snp)),   # v6.0 (K4)
      box(tr("target_snps"), if (isTRUE(r$snp$pending)) tr("tsnp_counting") else fmt_int(r$snp$target), "qps-b-slate"))
  })

  # ---- Agirliklar (tek/toplu, alt alta) ----
  output$weights_ui <- renderUI({
    lang_rv(); b <- shown_batch(); req(b)
    neg <- "color:#ef4444;font-weight:700;"   # v6.0 (K12): negatif agirlik kirmizi
    one <- function(x) {
      tl <- if (is.null(x$model)) x$target else sprintf("%s   |   %s: %s", x$target, x$model, paste(x$left, collapse = ", "))   # v6.2 (K9)
      if (is.null(x$res)) return(div(class = "text-danger mt-2", sprintf("Target %s: %s%s", tl, tr("msg_error_prefix"), x$error %||% "")))
      w <- as.data.frame(x$res$weights)
      rows <- lapply(seq_len(nrow(w)), function(i) tags$tr(
        tags$td(as.character(w$left[i])), tags$td(style = if (isTRUE(w$weight[i] < 0)) neg else NULL, round(w$weight[i], 4)),
        tags$td(round(w$se[i], 4)), tags$td(round(w$z[i], 3))))
      tagList(
        div(class = "fw-bold mt-3", sprintf("Target: %s   |   p = %s   |   feasible = %s   |   %s", tl, fmt(x$p), as.character(x$feasible), snp_hdr(x$snp))),
        tags$table(class = "table table-sm table-striped",
          tags$thead(tags$tr(tags$th("left"), tags$th("weight"), tags$th("se"), tags$th("z"))), tags$tbody(rows)))
    }
    tagList(lapply(b$batch, one))
  })

  output$rightset_ui <- renderUI({
    lang_rv(); r <- shown_run(); right <- r$right %||% rv$right; req(length(right))
    # v6.0 (K13): kullanilan right setini panoya (satir satir; qps_copy yolu)
    card(card_header(div(class = "d-flex justify-content-between align-items-center w-100 gap-2",
        span(tr("right_set_labels")),
        tags$button(type = "button", class = "btn btn-sm btn-outline-primary qps-copy-vals", `data-id` = "res_right",
          `data-vals` = paste(right, collapse = "\n"), icon("copy"), tr("copy_right_set")))),
      div(class = "small", paste(right, collapse = ", "))) })

  output$tbl_popdrop <- renderDT({ r <- shown_run(); req(r)
    d <- as.data.frame(r$res$popdrop)
    if ("feasible" %in% names(d)) d$feasible <- as.character(d$feasible)
    dt <- datatable(d, filter = "top", selection = "none", rownames = FALSE, class = "compact stripe hover",
      options = list(scrollX = TRUE, autoWidth = FALSE, pageLength = 15,
                     columnDefs = list(list(className = "dt-nowrap", targets = "_all"))))
    if ("feasible" %in% names(d))
      dt <- DT::formatStyle(dt, "feasible", fontWeight = "bold",
        color = DT::styleEqual(c("TRUE", "FALSE"), c("#10b981", "#ef4444")))
    if ("p" %in% names(d))
      dt <- DT::formatStyle(dt, "p", fontWeight = "bold",
        color = DT::styleInterval(c(0.01, 0.05), c("#ef4444", "#f59e0b", "#10b981")))
    num <- intersect(c("p", "chisq"), names(d))
    if (length(num)) dt <- DT::formatSignif(dt, columns = num, digits = 4)
    dt
  }, server = FALSE)

  output$samples_ui <- renderUI({
    lang_rv(); b <- shown_batch(); req(b, length(b$right), length(b$left)); m <- b$labelmap %||% rv$labelmap
    tg <- unique(vapply(b$batch, function(x) x$target, character(1)))
    block <- function(title, labs) { if (!length(labs)) return(NULL)
      items <- lapply(labs, function(l) { ids <- m[[l]]
        tags$li(tags$b(l), ": ", if (length(ids)) paste(ids, collapse = ", ") else tags$span(class = "text-danger", tr("not_in_file"))) })
      tagList(div(class = "fw-bold mt-2", title), tags$ul(items)) }
    tagList(block(sprintf("%s (%d)", tr("target_labels_ids"), length(tg)), tg),
            block(sprintf("%s (%d)", tr("left_labels_ids"), length(b$left)), b$left),
            block(sprintf("%s (%d)", tr("right_labels_ids"), length(b$right)), b$right))
  })

  # ---- Toplu Excel ----
  output$dl_batch <- downloadHandler(
    filename = function() sprintf("All_qpAdm_results_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { b <- shown_batch(); if (is.null(b)) { showNotification(tr("msg_run_first"), type = "error"); return() }
      write_batch_excel(b$batch, b$right, b$left, b$labelmap %||% rv$labelmap, file, rcond_lines = b$rcond %||% character(0), kind = b$kind %||% "batch") })

  # ---- Grafik (v5.9: model secici + grafik/model eslesmesi) ----
  # rv$graph_pick: secicideki kosu anahtari (tek dogruluk kaynagi; dil degisiminde
  #   secici bundan yeniden kurulur). rv$graph_key: EKRANDAKI grafigin kosusu.
  #   Bir kez cizildikten sonra grafik secimi izler -> ekrandaki = secili.
  #   PNG her zaman ekrandaki (yoksa secili) kosudan uretilir; adi o kosunun
  #   no/hedef/mod/zamanidir. Eski kod kayit aninda secimi yeniden cozup tekil
  #   secim yoksa son kosuya (rv$res) dusuyordu.
  # lang_rv(): arayuz yeniden kurulunca bu ciktilar da secili dilde yeniden cizilsin
  # (aksi halde istemci onbellekteki eski dil HTML'ini yeniden basar).
  output$graph_run_ui <- renderUI({
    lang_rv(); ch <- run_choices(rv$runs)
    if (!length(ch)) return(hint(tr("no_models_yet")))
    cur <- isolate(rv$graph_pick); sel <- if (!is.null(cur) && cur %in% ch) cur else unname(ch[1])
    selectInput("graph_run", tr("shown_model"), choices = ch, selected = sel, width = "100%")
  })
  observeEvent(input$graph_run, { k <- input$graph_run
    if (length(k) == 1 && nzchar(k) && !is.null(rv$runs[[k]])) rv$graph_pick <- k })
  draw_graph <- function(k) {
    r <- if (is.null(k)) NULL else rv$runs[[k]]
    if (is.null(r)) { rv$graph_key <- NULL; rv$graph_plot <- NULL; return(invisible(FALSE)) }
    p <- tryCatch(make_donut(r$res, r$right, r$snp), error = function(e) {
      showNotification(paste0(tr("msg_error_prefix"), conditionMessage(e)), type = "error", duration = NULL); NULL })
    rv$graph_plot <- p; rv$graph_key <- if (is.null(p)) NULL else k
    invisible(!is.null(p))
  }
  observeEvent(input$make_graph, {
    k <- rv$graph_pick
    if (is.null(k) || is.null(rv$runs[[k]])) { showNotification(tr("msg_run_model_first"), type = "error"); return() }
    draw_graph(k)
  })
  observeEvent(rv$graph_pick, {
    if (!is.null(rv$graph_key) && !identical(rv$graph_pick, rv$graph_key)) draw_graph(rv$graph_pick)
  }, ignoreInit = TRUE)
  output$donut <- renderPlot({ req(rv$graph_plot); rv$graph_plot }, res = 96)
  output$graph_info <- renderUI({
    lang_rv(); k <- rv$graph_key; r <- if (is.null(k)) NULL else rv$runs[[k]]
    if (is.null(r)) return(NULL)
    div(class = "small fw-bold mb-1", sprintf(tr("graph_shown"), run_choice_label(r$meta)))
  })
  png_dir_sel <- function() tryCatch(shinyFiles::parseDirPath(volumes, input$png_dir), error = function(e) character(0))
  png_wh <- function() as.integer(strsplit(input$png_res %||% "1280x800", "x")[[1]])
  output$png_dir_path <- renderText({ lang_rv(); d <- png_dir_sel()
    if (length(d)) paste0(tr("save_folder"), ": ", d) else tr("folder_not_selected") })
  observeEvent(input$save_png, {
    k <- rv$graph_key %||% rv$graph_pick; r <- if (is.null(k)) NULL else rv$runs[[k]]
    if (is.null(r)) { showNotification(tr("msg_run_model_first"), type = "error"); return() }
    d <- png_dir_sel(); if (!length(d)) { showNotification(tr("msg_pick_folder"), type = "error"); return() }
    wh <- png_wh(); fn <- file.path(d, graph_png_name(r$meta))
    tryCatch({ save_png(make_donut(r$res, r$right, r$snp), fn, wh[1], wh[2]); showNotification(sprintf(tr("msg_saved_to"), fn), type = "message", duration = 8) },
      error = function(e) showNotification(paste0(tr("msg_png_error"), ": ", conditionMessage(e)), type = "error", duration = NULL))
  })
  # Coklu secim: her secili model icin ayri PNG (klasor ve cozunurluk grafik bolumunden)
  observeEvent(input$save_png_sel, {
    sel <- input$acc_table_rows_selected
    if (!length(sel)) { showNotification(tr("msg_pick_rows_graph"), type = "error"); return() }
    d <- png_dir_sel(); if (!length(d)) { showNotification(tr("msg_pick_folder"), type = "error"); return() }
    wh <- png_wh(); keys <- names(rv$runs)[sel]; keys <- keys[!is.na(keys)]; nok <- 0L; err <- character(0)
    withProgress(message = tr("save_png_sel"), value = 0, {
      for (k in keys) {
        r <- rv$runs[[k]]
        e <- tryCatch({ save_png(make_donut(r$res, r$right, r$snp), file.path(d, graph_png_name(r$meta)), wh[1], wh[2]); "" }, error = function(e) conditionMessage(e))
        if (nzchar(e)) err <- c(err, paste0(k, ": ", e)) else nok <- nok + 1L
        incProgress(1 / length(keys))
      }
    })
    if (nok) showNotification(sprintf(tr("msg_png_saved_n"), nok, d), type = "message", duration = 10)
    if (length(err)) showNotification(paste0(tr("msg_png_error"), ": ", paste(err, collapse = " | ")), type = "error", duration = NULL)
  })

  # ---- Biriken modeller ----
  acc_df <- reactive({ if (!length(rv$runs)) return(data.frame())
    do.call(rbind, lapply(rv$runs, function(r) with(r$meta, data.frame(
      No = no, Target = if (is.null(r$meta$model)) target else paste0(target, " \u00b7 ", r$meta$model), allsnps = mode, `p-value` = p, feasible = as.character(feasible),
      chisq = chisq, dof = dof, `Used SNPs` = round(r$snp$used %||% NA_real_), `Target SNPs` = as.numeric(r$snp$target %||% NA_real_),
      Saat = time, check.names = FALSE)))) })
  output$acc_table <- renderDT({ d <- acc_df()
    if (!nrow(d)) return(datatable(data.frame(Info = tr("no_models_yet")), colnames = tr("info"), options = list(dom = "t"), rownames = FALSE))
    d$flag <- (d$feasible %in% c("FALSE","F")) | (!is.na(d$`p-value`) & d$`p-value` < 0.01)
    # v6.3 (S6): hedef SNP sayimi suren satirda "sayiliyor"; sutun gosterimde metin (binlik ayracli)
    tp <- vapply(rv$runs, function(r) isTRUE(r$snp$pending), logical(1)); ts <- d$`Target SNPs`
    d$`Target SNPs` <- ifelse(if (length(tp) == nrow(d)) tp else FALSE, tr("tsnp_counting"), ifelse(is.finite(ts), format(round(ts), big.mark = ",", scientific = FALSE, trim = TRUE), ""))
    dt <- datatable(d, filter = "top", selection = "multiple", rownames = FALSE,
      options = list(pageLength = 25, columnDefs = list(list(visible = FALSE, targets = ncol(d) - 1))))
    dt <- DT::formatStyle(dt, "flag", target = "row",
      fontWeight = DT::styleEqual(TRUE, "bold"))
    if ("feasible" %in% names(d))
      dt <- DT::formatStyle(dt, "feasible", fontWeight = "bold",
        color = DT::styleEqual(c("TRUE", "FALSE"), c("#10b981", "#ef4444")))
    if ("p-value" %in% names(d))
      dt <- DT::formatStyle(dt, "p-value", fontWeight = "bold",
        color = DT::styleInterval(c(0.01, 0.05), c("#ef4444", "#f59e0b", "#10b981")))
    if ("Used SNPs" %in% names(d)) dt <- DT::formatCurrency(dt, "Used SNPs", currency = "", digits = 0)
    DT::formatSignif(dt, columns = c("p-value","chisq"), digits = 4)
  }, server = FALSE)
  observeEvent(input$acc_table_rows_selected, {
    sel <- input$acc_table_rows_selected
    if (length(sel) != 1) return()
    k <- names(rv$runs)[sel]
    if (length(k) != 1 || is.na(k)) return()
    rv$graph_pick <- k; updateSelectInput(session, "graph_run", selected = k)
  })
  acc_proxy <- DT::dataTableProxy("acc_table")
  observeEvent(input$sel_all,  DT::selectRows(acc_proxy, seq_len(nrow(acc_df()))))
  observeEvent(input$sel_none, DT::selectRows(acc_proxy, NULL))
  # v6.5 ADIM 3 (madde 6): secimi toplu tabloda goster / referansla ayni setli modelleri sec
  observeEvent(input$acc_bt_show, { sel <- input$acc_table_rows_selected; keys <- names(rv$runs)[sel]; keys <- keys[!is.na(keys)]
    if (!length(keys)) { showNotification(tr("msg_pick_model_first"), type = "error"); return() }
    ck <- bt_sel_check(rv$runs[keys], rv$batches)
    if (!isTRUE(ck$ok)) { showNotification(ck$why, type = "error", duration = 12); return() }
    rv$bt_sel <- keys; showNotification(sprintf(tr("bts_note"), length(keys)), type = "message", duration = 5) })
  observeEvent(input$acc_same_sets, { sel <- input$acc_table_rows_selected; ref <- names(rv$runs)[sel[1]]
    if (!length(sel) || is.na(ref)) { showNotification(tr("bts_pick_ref"), type = "error"); return() }
    idx <- which(vapply(names(rv$runs), function(k) identical(k, ref) || isTRUE(bt_sel_check(rv$runs[c(ref, k)], rv$batches)$ok), logical(1)))
    DT::selectRows(acc_proxy, unname(idx)); showNotification(sprintf(tr("bts_same_n"), length(idx)), type = "message", duration = 6) })
  observeEvent(input$clear_runs, { rv$runs <- list(); rv$batches <- list(); rv$graph_pick <- NULL; rv$graph_key <- NULL; rv$graph_plot <- NULL; rv$bt_sel <- NULL
    showNotification(tr("msg_cleared"), type = "message") })
  output$dl_xlsx <- downloadHandler(
    filename = function() sprintf("qpadm_studio_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { sel <- input$acc_table_rows_selected
      if (!length(sel)) { wb <- openxlsx::createWorkbook(); openxlsx::addWorksheet(wb, "Info")
        openxlsx::writeData(wb, "Info", "Select a model from the list first."); openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
        showNotification(tr("msg_pick_model_first"), type = "error"); return() }
      # v6.3 test2 (S2): her model sayfasi kendi toplu kaydinin etiket eslemesini kullanir (kosuya ozel etiketler dahil)
      rs <- lapply(rv$runs[names(rv$runs)[sel]], function(z) { b <- if (!is.null(z$batch)) rv$batches[[z$batch]] else NULL; if (!is.null(b$labelmap)) z$labelmap <- b$labelmap; z })
      write_qpadm_excel(rs, file, rv$labelmap) })

  # ==========================================================================
  # FST
  # ==========================================================================
  observeEvent(input$fst_run, safe_run({
    if (is.null(rv$prefix)) { showNotification(tr("msg_pick_geno"), type = "error"); return() }
    p1 <- input$fst_pop1; p2 <- input$fst_pop2; if (xs_block(c(p1, p2))) return()   # v6.4 test (T7)
    ic <- ind_check(list(pop1 = p1, pop2 = p2)); if (is.null(ic)) return(); p1 <- ic$roles$pop1; p2 <- ic$roles$pop2   # v6.2 (K3)
    if (!length(p1) || !length(p2)) { showNotification(tr("msg_fst_pick_pops"), type = "error"); return() }
    if (!is.null(rv$fst_proc) && rv$fst_proc$is_alive()) { showNotification(tr("msg_fst_running"), type = "warning"); return() }
    pfx <- run_prefix(ic); if (is.null(pfx)) return()
    logf <- tempfile(fileext = ".log"); rv$fst_logf <- logf; rv$fst_done <- FALSE; rv$fst_prog <- 0; rv$fst_msg <- tr("prog_starting"); rv$fst_res <- NULL
    # v6.0 (D9/K18): ayarlar kosuyla birlikte saklanir; tablo, Excel ve konsol bunlari yazar
    rv$fst_run_params <- list(adjph = isTRUE(input$fst_adjph), autoonly = isTRUE(input$fst_autoonly), maxmiss = input$fst_maxmiss %||% 0,
      blgsize = input$fst_blgsize %||% 0.05, pop1 = p1, pop2 = p2, prefix = pfx, time = format(Sys.time(), "%Y-%m-%d %H:%M:%S"))
    rv$fst_t0 <- Sys.time(); rv$fst_t1 <- NULL
    console_add("", strrep("-", 60), sprintf("[%s] FST started: %d x %d pops", format(Sys.time(), "%H:%M:%S"), length(p1), length(p2)),
      sprintf("  prefix : %s", pfx), paste0("  code: ", fst_code_line(rv$fst_run_params)))
    rv$fst_proc <- qps_r_bg(
      func = function(prefix, pop1, pop2, adjph, autoonly, maxmiss, blgsize) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        res <- fst(prefix, pop1 = pop1, pop2 = pop2, adjust_pseudohaploid = adjph,
                   auto_only = autoonly, maxmiss = maxmiss, blgsize = blgsize, verbose = TRUE)
        res <- as.data.frame(res); res <- res[order(res$est), , drop = FALSE]; rownames(res) <- NULL; res
      },
      args = list(prefix = pfx, pop1 = p1, pop2 = p2, adjph = isTRUE(input$fst_adjph),
                  autoonly = isTRUE(input$fst_autoonly), maxmiss = input$fst_maxmiss %||% 0, blgsize = input$fst_blgsize %||% 0.05),
      stdout = logf, stderr = "2>&1")
  }, "FST"))
  observeEvent(input$fst_stop, { if (!is.null(rv$fst_proc)) { try(rv$fst_proc$kill(), silent = TRUE); rv$fst_proc <- NULL }
    rv$fst_done <- FALSE; rv$fst_prog <- 0; rv$fst_msg <- tr("prog_stopped"); rv$fst_t1 <- Sys.time()
    console_add(sprintf("[%s] FST stopped by user (%s)", format(Sys.time(), "%H:%M:%S"), el_str(rv$fst_t0, rv$fst_t1) %||% "-"))
    showNotification(tr("msg_fst_stopped"), type = "warning") })

  observe({
    p <- rv$fst_proc; if (is.null(p)) return(); invalidateLater(400)
    isolate({
      txt <- if (!is.null(rv$fst_logf) && file.exists(rv$fst_logf)) tryCatch(readLines(rv$fst_logf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_fst_progress(txt); rv$fst_prog <- pr$frac; rv$fst_msg <- pr$msg; rv$fst_eta <- eta_upd("fst", txt)   # v6.4 ADIM 4
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (K18)
      if (!p$is_alive()) {
        out <- tryCatch(p$get_result(), error = function(e) {
          em <- conditionMessage(e)
          # v6.0 (K19): tek ornekli pseudohaploid popda adjust_pseudohaploid = TRUE -> tum bloklar duser
          hint_ph <- if (grepl("No blocks remain", em, fixed = TRUE) && isTRUE(rv$fst_run_params$adjph)) paste0("\n\n", tr("fst_pseudohaploid_hint")) else ""
          showNotification(paste0(tr("msg_fst_error"), ": ", em, hint_ph), type = "error", duration = NULL)
          console_add(sprintf("[%s] FST ERROR: %s", format(Sys.time(), "%H:%M:%S"), em)); NULL })
        rv$fst_proc <- NULL; rv$fst_t1 <- Sys.time()
        if (!is.null(out)) { rv$fst_res <- out; rv$fst_params <- rv$fst_run_params; rv$fst_done <- TRUE; rv$fst_prog <- 1; rv$fst_msg <- tr("msg_completed")
          op <- options(width = 10000)
          console_add(sprintf("[%s] FST finished: %d pair(s) (%s)", format(Sys.time(), "%H:%M:%S"), NROW(out), el_str(rv$fst_t0, rv$fst_t1) %||% "-"),
            "> results", utils::capture.output(print(as.data.frame(out), row.names = FALSE, digits = 4)), "")
          options(op); rv$bg_log <- character(0)
          showNotification(tr("msg_fst_done"), type = "message") }
        else { rv$fst_done <- FALSE; rv$fst_prog <- 0; rv$fst_msg <- tr("msg_fst_error_stop") }
      }
    })
  })

  output$fst_progress_ui <- renderUI({
    running <- !is.null(rv$fst_proc); done <- isTRUE(rv$fst_done); if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.0 (K9)
    prog_ui(done, rv$fst_prog, rv$fst_msg, el = el_str(rv$fst_t0, if (running) NULL else rv$fst_t1), eta = if (running) rv$fst_eta else NULL, eta_key = "prog_eta_phase")
  })
  # v6.0 (D9): tablonun hangi ayarlarla uretildigi + ayarlar sonradan degistiyse uyari
  output$fst_params_ui <- renderUI({
    lang_rv(); pp <- rv$fst_params; req(rv$fst_res, pp)
    cur <- c(isTRUE(input$fst_adjph), isTRUE(input$fst_autoonly), as.numeric(input$fst_maxmiss %||% 0), as.numeric(input$fst_blgsize %||% 0.05))
    was <- c(isTRUE(pp$adjph), isTRUE(pp$autoonly), as.numeric(pp$maxmiss %||% 0), as.numeric(pp$blgsize %||% 0.05))
    tagList(div(class = "small fw-bold mb-1", paste0(tr("fst_settings_used"), ": ", fst_param_str(pp))),
      if (!isTRUE(all.equal(cur, was))) div(class = "alert alert-warning py-1 px-2 small mb-2", tr("fst_stale")))
  })
  output$fst_table <- renderDT({ req(rv$fst_res)
    dt <- datatable(rv$fst_res, rownames = FALSE, class = "compact stripe hover",
      options = list(scrollX = TRUE, autoWidth = FALSE, pageLength = 20))
    DT::formatSignif(dt, columns = intersect(c("est", "se"), names(rv$fst_res)), digits = 4)
  }, server = FALSE)
  output$fst_xlsx <- downloadHandler(
    filename = function() sprintf("fst_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { if (is.null(rv$fst_res)) { showNotification(tr("msg_fst_first"), type = "error"); return() }
      write_fst_excel(rv$fst_res, file, rv$fst_params) })

  # ==========================================================================
  # ROTASYON
  # ==========================================================================
  observeEvent(input$rot_lr_fill, updateSelectizeInput(session, "rot_lr", choices = rv$labels,
    selected = union(input$rot_lr, sel_valid(rv$left_sets[[input$rot_lr_set]])), server = TRUE))
  observeEvent(input$rot_lr_clear, updateSelectizeInput(session, "rot_lr", choices = rv$labels, selected = character(0), server = TRUE))
  observeEvent(input$rot_lr_add, { toks <- parse_pops(input$rot_lr_paste); sv <- sel_check(toks); pres <- sv$ok; miss <- sv$miss
    if (length(pres)) updateSelectizeInput(session, "rot_lr", choices = rv$labels, selected = union(input$rot_lr, pres), server = TRUE)
    showNotification(paste0(sprintf(tr("msg_paste_added"), length(pres)), if (length(miss)) sprintf(tr("msg_paste_missing"), paste(head(miss, 6), collapse = ", ")) else ""),
      type = if (length(miss)) "warning" else "message", duration = 6) })
  observeEvent(input$rot_rf_fill, updateSelectizeInput(session, "rot_rf", choices = rv$labels,
    selected = union(input$rot_rf, sel_valid(rv$right_sets[[input$rot_rf_set]])), server = TRUE))
  observeEvent(input$rot_rf_clear, updateSelectizeInput(session, "rot_rf", choices = rv$labels, selected = character(0), server = TRUE))
  observeEvent(input$rot_rf_add, { toks <- parse_pops(input$rot_rf_paste); sv <- sel_check(toks); pres <- sv$ok; miss <- sv$miss
    if (length(pres)) updateSelectizeInput(session, "rot_rf", choices = rv$labels, selected = union(input$rot_rf, pres), server = TRUE)
    showNotification(paste0(sprintf(tr("msg_paste_added"), length(pres)), if (length(miss)) sprintf(tr("msg_paste_missing"), paste(head(miss, 6), collapse = ", ")) else ""),
      type = if (length(miss)) "warning" else "message", duration = 6) })

  observeEvent(input$rot_run, safe_run({
    if (is.null(rv$prefix)) { showNotification(tr("msg_pick_geno"), type = "error"); return() }
    tg <- input$rot_target; lr <- input$rot_lr; rf <- input$rot_rf
    ic <- ind_check(list(Target = tg, leftright = lr, rightfix = rf)); if (is.null(ic)) return()   # v6.2 (K3)
    tg <- ic$roles$Target; lr <- ic$roles$leftright; rf <- ic$roles$rightfix
    if (!length(tg)) { showNotification(tr("msg_rot_pick_target"), type = "error"); return() }
    if (length(lr) < 2) { showNotification(tr("msg_rot_lr_min2"), type = "error"); return() }
    mn <- as.integer(input$rot_min %||% 1); mx <- as.integer(input$rot_max %||% (length(lr) - 1))
    if (is.na(mn) || is.na(mx) || mn < 1 || mx < mn) { showNotification(tr("msg_rot_size_invalid"), type = "error"); return() }
    if (tg %in% c(lr, rf)) { showNotification(tr("msg_rot_target_in_sets"), type = "error"); return() }
    dupp <- intersect(lr, rf); if (length(dupp)) { showNotification(sprintf(tr("msg_rot_lr_rf_overlap"), paste(dupp, collapse = ", ")), type = "error", duration = NULL); return() }
    if (!is.null(rv$rot_proc) && rv$rot_proc$is_alive()) { showNotification(tr("msg_rot_running"), type = "warning"); return() }
    allsnps <- isTRUE(input$rot_allsnps); pops <- unique(c(lr, rf, tg))
    pfx <- run_prefix(ic); if (is.null(pfx)) return()
    pa <- panel_args()
    cx <- pool_ctx(ic$vfam); rvk <- run_vkey(ic)
    xc <- xs_ctx(pops, ic$vfam); if (isFALSE(xc)) return()   # v6.4 test (adim 1)
    if (!is.null(xc)) { rvk <- paste0(rvk, xc$vsuf); cx$lm <- xc$lm_key }
    fr <- resolve_f2(CACHE_BASE, pfx, pops, pa$maxmiss, pa$blgsize, pa$adjph, pa$auto_only, rvk, active_panel(), cx$orig, cx$lm)
    f2dir <- fr$dir; need <- isTRUE(fr$need) && !pool_ok(f2dir)
    if (need && !allsnps && !pops_disk_ok(pops)) return()
    if (identical(fr$src, "superset") && isTRUE(fr$wider)) showNotification(tr("panel_super_note"), type = "message", duration = 10)
    logf <- tempfile(fileext = ".log"); rv$rot_logf <- logf; rv$rot_done <- FALSE; rv$rot_prog <- 0; rv$rot_msg <- tr("prog_starting"); rv$rot_all <- NULL; rv$rot_target <- tg; rv$rot_plot <- NULL
    rdir <- tempfile("qps_rot_"); dir.create(rdir, recursive = TRUE, showWarnings = FALSE); rk$dir <- rdir; rk$seen <- character(0); rk$buf <- NULL; rk$t <- Sys.time()
    rot_view(NULL)   # v6.2 (K1): yeni kosuda otomatik kurala don
    if (allsnps) showNotification(tr("msg_rot_allsnps_warn"), type = "message", duration = 8)
    rv$rot_t0 <- Sys.time(); rv$rot_t1 <- NULL
    console_add("", strrep("-", 60), sprintf("[%s] rotation started: target = %s, minsize = %d, maxsize = %d, allsnps = %s", format(Sys.time(), "%H:%M:%S"), tg, mn, mx, if (allsnps) "TRUE" else "FALSE"),
      sprintf("  leftright : %s", paste(lr, collapse = ", ")), sprintf("  rightfix  : %s", paste(rf, collapse = ", ")), sprintf("  admixtools: %s%s", qps_adx_str(), qps_adx_note()))   # v6.4 (madde 3)
    if (!is.null(xc)) console_add(xs_console(xc))   # v6.4 test
    msgs <- list(f2_head = tr("err_extract_f2_head"), f2_maxmiss = tr("err_extract_f2_maxmiss"), f2_log = tr("err_extract_f2_log"), f2_precomp = tr("err_f2_precomp"))
    rv$rot_proc <- qps_r_bg(
      func = function(prefix, target, leftright, rightfix, minsize, maxsize, allsnps, maxmiss, need_f2, f2dir, pops, blgsize, adjph, auto_only, msgs, resdir, xinfo = NULL, xfun = NULL, xcache = NULL, gp = NULL) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        models <- rotate_models(leftright, target, rightfix)
        nleft <- lengths(models$left); models <- models[nleft >= minsize & nleft <= maxsize, , drop = FALSE]
        N <- nrow(models); cat(sprintf("QPS_ROT_TOTAL %d\n", N))
        f2 <- NULL
        if (!allsnps) {
          if (need_f2) {
            ok <- tryCatch({ if (is.null(xinfo)) extract_f2(prefix, f2dir, pops = pops, maxmiss = maxmiss, blgsize = blgsize, adjust_pseudohaploid = adjph, auto_only = auto_only, overwrite = TRUE, verbose = TRUE)
                             else xfun$pool(xinfo, f2dir, pops, maxmiss, blgsize, adjph, auto_only, xcache, xfun$aft, xfun$zfix); TRUE },   # v6.4 test
              error = function(e) { cat(sprintf("QPS_STAGE_ERR extract_f2: %s\n", conditionMessage(e))); FALSE })
            if (!ok) stop(paste0(msgs$f2_head, if (isTRUE(maxmiss == 0)) msgs$f2_maxmiss else msgs$f2_log))
            writeLines(format(Sys.time()), file.path(f2dir, ".f2_done"))
          }
          f2 <- tryCatch(f2_from_precomp(f2dir, pops = pops, afprod = TRUE, verbose = FALSE),
            error = function(e) stop(paste0(msgs$f2_precomp, conditionMessage(e))))
        }
        AFx <- NULL   # v6.4 test (adim 2): ek setli allsnps=TRUE rotasyon -- frekans matrisi bir kez
        if (allsnps && !is.null(xinfo)) AFx <- xfun$aft(xinfo, pops, FALSE, xcache, counts = FALSE)
        # v6.5 ADIM 2: ek setsiz allsnps=TRUE rotasyon -- butun modellerin dortluleri tek genotip gecisinde (Right modele gore
        # degisir; birlesim). Gecis hata verirse GP NULL kalir ve model basina qpadm(prefix) yoluna dusulur.
        GP <- NULL
        if (allsnps && is.null(AFx) && is.list(gp) && N > 0) {
          pcs <- do.call(rbind, lapply(seq_len(N), function(i) gp$pcomb(target, models$left[[i]], models$right[[i]])))
          cat(sprintf("QPS_PASS %d %d\n", N, nrow(unique(pcs)))); cat("QPS_STAGE tek gecis\n")
          GP <- tryCatch(gp$pass(prefix, pcs, character(0)), error = function(e) { cat(sprintf("QPS_STAGE_ERR single pass: %s\n", gsub("[\r\n]+", " ", conditionMessage(e)))); NULL })
        }
        get_np <- function(res) {
          pd <- res$popdrop; if (is.null(pd) || !nrow(pd)) return(list(full = NA, nested = numeric(0)))
          w <- nchar(as.character(pd$pat[1])); full_pat <- paste(rep("0", w), collapse = "")
          fp <- pd$p[pd$pat == full_pat]; fp <- if (length(fp)) fp[1] else NA
          nn <- pd$p[pd$pat != full_pat & !grepl("^0+$", pd$pat)]; list(full = fp, nested = nn[is.finite(nn)])
        }
        parse_one <- function(i, res) {
          if (is.null(res) || !is.list(res) || is.null(res$weights)) return(NULL)
          w <- as.data.frame(res$weights)
          if (!("weight" %in% names(w)) && "est" %in% names(w)) names(w)[names(w) == "est"] <- "weight"
          if (!("se" %in% names(w)) && "stderr" %in% names(w)) names(w)[names(w) == "stderr"] <- "se"
          if (!all(c("weight", "se") %in% names(w))) return(NULL)
          np <- get_np(res); low <- w$weight - 2 * w$se; up <- w$weight + 2 * w$se
          data.frame(model_index = i, sources = paste(w$left, collapse = "  +  "),
                     proportions = paste0(round(w$weight * 100, 2), "%", collapse = " + "),
                     se_values = paste(round(w$se * 100, 2), collapse = " / "),
                     p_full = np$full,
                     p_min_nested = if (length(np$nested)) min(np$nested) else NA,
                     p_max_nested = if (length(np$nested)) max(np$nested) else NA,
                     eaf_ok = all(low > 0 & up < 1, na.rm = TRUE),
                     sum_weights = sum(w$weight, na.rm = TRUE), n_src = nrow(w), stringsAsFactors = FALSE)
        }
        rows <- list()
        for (i in seq_len(N)) {
          L <- models$left[[i]]; R <- models$right[[i]]
          cat(sprintf("QPS_ROT %d %d %s\n", i, N, paste(L, collapse = " + ")))   # v6.0 (K11)
          res <- tryCatch({ if (allsnps) { if (!is.null(GP)) gp$fit(GP$fd, target, L, R, FALSE) else if (is.null(AFx)) qpadm(prefix, left = L, right = R, target = target, allsnps = TRUE, verbose = FALSE)
                                           else xfun$qtrue(AFx$afs, AFx$snpfile, target, L, R, 0.05, FALSE, xfun$f4, AFx$zero, xfun$zfix) }
                            else qpadm(f2, left = L, right = R, target = target, verbose = FALSE) },
                          error = function(e) { cat(sprintf("QPS_ROT_ERR %d %s\n", i, gsub("[\r\n]+", " ", conditionMessage(e)))); NULL })   # v6.0 (K7)
          pr <- tryCatch(parse_one(i, res), error = function(e) NULL)
          if (!is.null(pr)) { rows[[length(rows) + 1]] <- pr
            # v6.2 (K1): satir diske (gecici ad -> yeniden adlandirma); arayuz tabloya ekler
            tryCatch({ tmp <- file.path(resdir, sprintf(".%05d.tmp", i)); saveRDS(pr, tmp); file.rename(tmp, file.path(resdir, sprintf("%05d.rds", i))) }, error = function(e) NULL) }
          cat(sprintf("QPS_ROT_DONE %d\n", i))
        }
        if (length(rows)) do.call(rbind, rows) else data.frame()
      },
      args = list(prefix = pfx, target = tg, leftright = lr, rightfix = rf, minsize = mn, maxsize = mx,
                  allsnps = allsnps, maxmiss = pa$maxmiss, need_f2 = need, f2dir = f2dir, pops = pops,
                  blgsize = pa$blgsize, adjph = pa$adjph, auto_only = pa$auto_only, msgs = msgs, resdir = rdir,
                  xinfo = if (is.null(xc)) NULL else xc$bg, xfun = if (is.null(xc)) NULL else xs_bg_funs(), xcache = XS_CACHE_DIR,
                  gp = if (allsnps && is.null(xc)) qps_gp_funs() else NULL),   # v6.5 ADIM 2
      stdout = logf, stderr = "2>&1")
    if (need) rv$pool_pending <- list(dir = f2dir, prefix = pfx, pops = pops, maxmiss = pa$maxmiss, vfam = rvk,
                                      blgsize = pa$blgsize, adjph = pa$adjph, auto_only = pa$auto_only, orig = fr$orig, comp = fr$comp)
  }, tr("op_rotation")))
  # v6.2 (K1): rotasyonda biten modeller. bg her basarili modelin satirini <dir>/<i>.rds'e yazar; gozlemci yeni dosyalari
  # okur, en az 1,5 sn arayla rv$rot_all'a ekler (tablo her eklemede yeniden cizilir). Durdur/hata bitenleri korur.
  rk <- new.env(parent = emptyenv()); rk$dir <- NULL; rk$seen <- character(0); rk$buf <- NULL; rk$t <- Sys.time()
  rot_poll <- function(force = FALSE) {
    d <- rk$dir; if (is.null(d) || !dir.exists(d)) return(invisible(length(rk$seen)))
    fs <- setdiff(list.files(d, "^[0-9]+\\.rds$"), rk$seen)
    if (length(fs)) { nw <- lapply(file.path(d, fs), function(f) tryCatch(readRDS(f), error = function(e) NULL)); okf <- !vapply(nw, is.null, logical(1))
      rk$seen <- c(rk$seen, fs[okf]); rk$buf <- c(rk$buf, nw[okf]) }
    if (length(rk$buf) && (isTRUE(force) || as.numeric(difftime(Sys.time(), rk$t, units = "secs")) >= 1.5)) {
      add <- do.call(rbind, rk$buf); rk$buf <- NULL; rk$t <- Sys.time()
      cur <- isolate(rv$rot_all); x <- if (is.null(cur) || !nrow(cur)) add else rbind(cur, add)
      rv$rot_all <- x[order(x$model_index), , drop = FALSE] }
    invisible(length(rk$seen))
  }
  observeEvent(input$rot_stop, { if (!is.null(rv$rot_proc)) { try(rv$rot_proc$kill(), silent = TRUE); rv$rot_proc <- NULL }
    kept <- tryCatch(rot_poll(force = TRUE), error = function(e) 0L); rk$dir <- NULL
    rv$rot_done <- FALSE; rv$rot_prog <- 0; rv$rot_msg <- tr("prog_stopped"); rv$rot_t1 <- Sys.time()
    console_add(sprintf("[%s] rotation stopped by user (%s)%s", format(Sys.time(), "%H:%M:%S"), el_str(rv$rot_t0, rv$rot_t1) %||% "-",
                        if (kept > 0) sprintf("; %d finished model(s) kept", kept) else ""))
    showNotification(if (kept > 0) sprintf(tr("rot_kept"), kept) else tr("msg_rot_stopped"), type = "warning") })

  observe({
    p <- rv$rot_proc; if (is.null(p)) return(); invalidateLater(500)
    isolate({
      txt <- if (!is.null(rv$rot_logf) && file.exists(rv$rot_logf)) tryCatch(readLines(rv$rot_logf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_rot_progress(txt, rv$snp_total); rv$rot_prog <- pr$frac; rv$rot_msg <- pr$msg; rv$rot_eta <- eta_upd("rot", txt, rv$snp_total)   # v6.4 ADIM 4
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (D1)
      if (p$is_alive()) tryCatch(rot_poll(), error = function(e) NULL)   # v6.2 (K1)
      if (!p$is_alive()) {
        out <- tryCatch(p$get_result(), error = function(e) {
          tail_log <- if (length(txt)) paste(utils::tail(txt, 6), collapse = "\n") else ""
          msg <- paste0(tr("msg_rot_error"), ": ", conditionMessage(e), if (nzchar(tail_log)) paste0("\n\n", tr("msg_log_tail"), "\n", tail_log) else "")
          showNotification(msg, type = "error", duration = NULL)
          console_add(sprintf("[%s] rotation ERROR: %s", format(Sys.time(), "%H:%M:%S"), conditionMessage(e))); NULL })
        rv$rot_proc <- NULL; rv$rot_t1 <- Sys.time()
        flush_pool_meta()
        if (is.null(out)) { kept <- tryCatch(rot_poll(force = TRUE), error = function(e) 0L)
          if (kept > 0) showNotification(sprintf(tr("rot_kept"), kept), type = "warning", duration = NULL) }
        rk$dir <- NULL
        if (!is.null(out)) { rv$rot_all <- out; rv$rot_done <- TRUE; rv$rot_prog <- 1; rv$rot_msg <- tr("msg_completed")
          nerr <- sum(grepl("^QPS_ROT_ERR ", txt))
          console_add(sprintf("[%s] rotation finished: %d model(s) fitted, %d failed to fit (%s)", format(Sys.time(), "%H:%M:%S"), NROW(out), nerr, el_str(rv$rot_t0, rv$rot_t1) %||% "-"))
          showNotification(sprintf(tr("msg_rot_done"), nrow(out)), type = "message") }
        else { rv$rot_done <- FALSE; rv$rot_prog <- 0; rv$rot_msg <- tr("prog_error_notif") }
      }
    })
  })
  output$rot_progress_ui <- renderUI({
    running <- !is.null(rv$rot_proc); done <- isTRUE(rv$rot_done); if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.0 (K9)
    prog_ui(done, rv$rot_prog, rv$rot_msg, el = el_str(rv$rot_t0, if (running) NULL else rv$rot_t1), eta = if (running) rv$rot_eta else NULL, eta_key = "prog_eta_phase")
  })

  rot_valid <- reactive({
    d <- rv$rot_all; if (is.null(d) || !nrow(d)) return(data.frame())
    cols <- c("model_index", "sources", "p_full", "proportions", "se_values", "p_min_nested")
    if (!isTRUE(input$rot_fleg)) { v <- d[order(-d$p_full), , drop = FALSE]; return(v[, cols, drop = FALSE]) }
    pf <- input$rot_pfull %||% 0.01; pn <- input$rot_pnested %||% 0.01
    keep <- rot_keep(d, pf, pn)   # v6.0 (D6-b)
    v <- d[keep, , drop = FALSE]; v <- v[order(-v$p_full), , drop = FALSE]; v[, cols, drop = FALSE]
  })
  rot_failed <- reactive({
    d <- rv$rot_all; if (is.null(d) || !nrow(d)) return(data.frame())
    if (!isTRUE(input$rot_fleg)) return(data.frame())
    pf <- input$rot_pfull %||% 0.01; pn <- input$rot_pnested %||% 0.01
    keep <- rot_keep(d, pf, pn)   # v6.0 (D6-b)
    f <- d[!keep, , drop = FALSE]; if (!nrow(f)) return(data.frame())
    reason <- ifelse(is.na(f$p_full) | f$p_full < pf, tr("fail_p_full"),
              ifelse(!(f$eaf_ok | rot_nsrc(f) == 1), tr("fail_eaf"),
              ifelse(is.na(f$p_max_nested) | f$p_max_nested >= pn, tr("fail_nested"), tr("fail_other"))))
    cbind(f[, c("model_index", "sources", "p_full", "proportions", "se_values", "p_min_nested")], fail_reason = reason)
  })
  # --- Rotasyon sonuclari: TEK tablo + iki dugme (ayni anda yalniz biri) ---
  rot_view <- reactiveVal(NULL)   # "valid" | "failed" | NULL(=otomatik)

  rot_view_eff <- reactive({
    nv <- nrow(rot_valid()); nf <- nrow(rot_failed())
    v <- rot_view()
    # Kullanici secmediyse: gecerli model varsa gecerli, yoksa basarisiz
    if (is.null(v)) return(if (nv > 0) "valid" else "failed")
    # Secilen taraf bossa ve digeri doluysa dolu olana dus
    if (identical(v, "valid")  && nv == 0 && nf > 0) return("failed")
    if (identical(v, "failed") && nf == 0 && nv > 0) return("valid")
    v
  })
  observeEvent(input$rot_show_valid,  rot_view("valid"))
  observeEvent(input$rot_show_failed, rot_view("failed"))
  # v6.2 (K1): otomatik kurala donus kosu basinda (rot_run); tablo bittikce dolarken kullanicinin secimi korunur.

  output$rot_toggle_ui <- renderUI({
    nv <- nrow(rot_valid()); nf <- nrow(rot_failed()); v <- rot_view_eff()
    btn <- function(id, lab, n, kind, active) {
      col <- if (kind == "ok") "#10b981" else "#ef4444"
      actionButton(id,
        tagList(lab, " ", span(class = "qps-cnt", style = sprintf("color:%s;", col), sprintf("(%d)", n))),
        class = paste("btn-sm", if (active) "btn-primary" else "btn-outline-secondary"))
    }
    tagList(
      btn("rot_show_valid",  tr("valid_models"),  nv, "ok",  identical(v, "valid")),
      btn("rot_show_failed", tr("failed_models"), nf, "bad", identical(v, "failed")),
      span(class = "small text-muted ms-2",
           if (identical(v, "valid")) tr("showing_valid") else tr("showing_failed")))
  })

  output$rot_table <- renderDT({
    v <- rot_view_eff()
    d <- if (identical(v, "valid")) rot_valid() else rot_failed()
    if (!nrow(d)) return(datatable(
      data.frame(X = if (identical(v, "valid")) tr("no_valid_model") else tr("no_record")),
      colnames = tr("info"), options = list(dom = "t"), rownames = FALSE))
    cn <- c(model_index = tr("col_model_index"), sources = tr("col_sources"), p_full = "p_full",
            proportions = tr("col_proportions"), se_values = tr("col_se_values"),
            p_min_nested = "p_min_nested", fail_reason = tr("col_fail_reason"))
    dt <- datatable(d, filter = "top", rownames = FALSE, class = "compact stripe hover",
      colnames = unname(ifelse(names(d) %in% names(cn), cn[names(d)], names(d))),
      options = list(scrollX = TRUE, autoWidth = FALSE, pageLength = 15))
    DT::formatSignif(dt, columns = intersect(c("p_full", "p_min_nested"), names(d)), digits = 4)
  }, server = FALSE)

  rot_plot_obj <- eventReactive(input$rot_plot, {
    if (!is.null(rv$rot_proc)) { showNotification(tr("rot_plot_wait"), type = "message", duration = 6); return(NULL) }   # v6.2 (K1)
    v <- rot_valid()
    if (!nrow(v)) { showNotification(tr("msg_rot_no_valid_plot"), type = "error"); return(NULL) }
    tryCatch(make_rotation_plot(v, rv$rot_target %||% input$rot_target %||% "target", input$rot_font %||% "Arial"),
      error = function(e) { showNotification(paste0(tr("msg_plot_error"), ": ", conditionMessage(e)), type = "error", duration = NULL); NULL }) })
  output$rot_plot_out <- renderPlot({ req(rot_plot_obj()); rot_plot_obj() }, res = 96)
  output$rot_dir_path <- renderText({ d <- tryCatch(shinyFiles::parseDirPath(volumes, input$rot_dir), error = function(e) character(0))
    if (length(d)) paste0(tr("save_folder"), ": ", d) else tr("folder_not_selected") })
  observeEvent(input$rot_save_png, {
    if (!is.null(rv$rot_proc)) { showNotification(tr("rot_plot_wait"), type = "message", duration = 6); return() }   # v6.2 (K1)
    v <- rot_valid(); if (!nrow(v)) { showNotification(tr("msg_rot_need_valid"), type = "error"); return() }
    d <- tryCatch(shinyFiles::parseDirPath(volumes, input$rot_dir), error = function(e) character(0))
    if (!length(d)) { showNotification(tr("msg_pick_folder"), type = "error"); return() }
    n <- nrow(v); ph <- max(3.5, min(22, n * 1.4 + 2.5)); tg <- gsub("[^A-Za-z0-9]+", "_", rv$rot_target %||% "target")
    fn <- file.path(d, sprintf("qpadm_rotation_%s_%s.png", tg, format(Sys.time(), "%Y%m%d_%H%M%S")))
    tryCatch({ pl <- make_rotation_plot(v, rv$rot_target %||% "target", input$rot_font %||% "Arial")
      ggplot2::ggsave(fn, pl, width = 18, height = ph, units = "in", dpi = 300, bg = "white")
      showNotification(sprintf(tr("msg_saved_to"), fn), type = "message", duration = 8) },
      error = function(e) showNotification(paste0(tr("msg_png_error"), ": ", conditionMessage(e)), type = "error", duration = NULL))
  })
  output$rot_export <- downloadHandler(
    filename = function() sprintf("qpadm_rotation_%s.%s", format(Sys.time(), "%Y%m%d_%H%M%S"), input$rot_export_fmt %||% "xlsx"),
    content = function(file) { v <- rot_valid(); f <- rot_failed()
      if (identical(input$rot_export_fmt, "csv")) write_rot_csv(v, f, file) else write_rot_excel(v, f, file) })

  # Model sekmesindeki maxmiss ARTIK Panel'den gelir; burada yalnizca gosterilir.
  output$maxmiss_show <- renderText(as.character(input$panel_maxmiss %||% 0))

  # ==========================================================================
  # PANEL (f2 HAVUZU) -- v5.5, S3 "ust kume yeniden kullanimi"
  # ==========================================================================
  panel_args <- function() list(
    maxmiss   = input$panel_maxmiss %||% 0,
    blgsize   = input$panel_blgsize %||% F2_BLGSIZE,
    adjph     = isTRUE(input$panel_adjph),
    auto_only = isTRUE(input$panel_autoonly))

  # Analizlerin kullanacagi aktif panel (duz liste; reaktif okuma YOK).
  active_panel <- function() if (isTRUE(input$panel_use)) rv$panel else NULL

  # Havuz kurulumu: Panel sekmesi ve analiz sekmelerindeki "havuzu hazirla"
  # dugmesi AYNI fonksiyonu kullanir.
  #   set_panel = TRUE  -> kurulan havuz aktif panel olur (Panel kutusu da guncellenir)
  #   resume    = "f2" | "f3" | "f4" | "f4r" | "qg" -> bitince o analiz yeniden tetiklenir
  start_pool_build <- function(pops, set_panel = TRUE, resume = NULL) {
    if (is.null(rv$prefix)) { showNotification(tr("msg_pick_geno"), type = "error"); return(invisible(FALSE)) }
    pops <- unique(pops)
    if (xs_block(pops)) return(invisible(FALSE))   # v6.4 test (T7)
    ic <- ind_check(list(pops = pops)); if (is.null(ic)) return(invisible(FALSE)); pops <- ic$roles$pops   # v6.2 (K3)
    if (length(pops) < 2) { showNotification(tr("panel_need_pops"), type = "error"); return(invisible(FALSE)) }
    if (!pops_disk_ok(pops)) return(invisible(FALSE))
    if (!is.null(rv$panel_proc) && rv$panel_proc$is_alive()) { showNotification(tr("panel_running"), type = "warning"); return(invisible(FALSE)) }
    pa <- panel_args()
    pfx <- run_prefix(ic); if (is.null(pfx)) return(invisible(FALSE))
    vk <- run_vkey(ic); cx <- pool_ctx(ic$vfam); cmp <- pool_comp(cx$lm, pops)
    dir <- f2_cache_dir(CACHE_BASE, pfx, pops, pa$maxmiss, pa$blgsize, pa$adjph, pa$auto_only, vk, orig = cx$orig, comp = cmp)
    # Panel kutusu gercegi yansitsin: kullanici Panel sekmesine gectiginde
    # kurulan havuzun popülasyonlarini gorsun.
    if (set_panel) { updateSelectizeInput(session, "panel_pops", choices = rv$labels, selected = pops, server = TRUE); pop_done(union(pop_done(), "panel_pops")) }
    if (pool_ok(dir)) {
      pool_write_meta(dir, pfx, pops, pa$maxmiss, pa$blgsize, pa$adjph, pa$auto_only, vk, cx$orig, cmp)
      if (set_panel) rv$panel <- pool_read_meta(dir)
      rv$panel_done <- TRUE; rv$panel_prog <- 1
      rv$panel_tick <- rv$panel_tick + 1
      showNotification(tr("panel_exists"), type = "message")
      if (!is.null(resume)) { rv$pool_need <- NULL; k <- paste0("resume_", resume); rv[[k]] <- (rv[[k]] %||% 0) + 1 }
      return(invisible(TRUE))
    }
    logf <- tempfile(fileext = ".log")
    rv$panel_logf <- logf; rv$panel_done <- FALSE; rv$panel_prog <- 0; rv$panel_msg <- tr("prog_starting"); rv$panel_t0 <- Sys.time(); rv$panel_t1 <- NULL
    rv$pool_pending <- list(dir = dir, prefix = pfx, pops = pops, maxmiss = pa$maxmiss, vfam = vk,
                            blgsize = pa$blgsize, adjph = pa$adjph, auto_only = pa$auto_only,
                            set_panel = set_panel, resume = resume, orig = cx$orig, comp = cmp)
    msgs <- list(f2_head = tr("err_extract_f2_head"), f2_maxmiss = tr("err_extract_f2_maxmiss"), f2_log = tr("err_extract_f2_log"))
    console_add("", strrep("-", 60), sprintf("[%s] f2 pool build: %d pops, maxmiss=%s, blgsize=%s",
      format(Sys.time(), "%H:%M:%S"), length(pops), pa$maxmiss, pa$blgsize), sprintf("  dir: %s", dir))
    rv$panel_proc <- qps_r_bg(
      func = function(prefix, dir, pops, maxmiss, blgsize, adjph, auto_only, msgs) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat("QPS_FS_STAGE extract\n")
        ok <- tryCatch({ extract_f2(prefix, dir, pops = pops, maxmiss = maxmiss, blgsize = blgsize,
                                    adjust_pseudohaploid = adjph, auto_only = auto_only,
                                    overwrite = TRUE, verbose = TRUE); TRUE },
          error = function(e) { cat(sprintf("QPS_FS_ERR %s\n", conditionMessage(e))); FALSE })
        if (!ok) stop(paste0(msgs$f2_head, if (isTRUE(maxmiss == 0)) msgs$f2_maxmiss else msgs$f2_log))
        writeLines(format(Sys.time()), file.path(dir, ".f2_done"))
        TRUE
      },
      args = list(prefix = pfx, dir = dir, pops = pops, maxmiss = pa$maxmiss, blgsize = pa$blgsize,
                  adjph = pa$adjph, auto_only = pa$auto_only, msgs = msgs),
      stdout = logf, stderr = "2>&1")
    invisible(TRUE)
  }

  observeEvent(input$panel_build, safe_run(start_pool_build(input$panel_pops %||% character(0), set_panel = TRUE, resume = NULL), tr("panel_title")))

  observeEvent(input$panel_stop, { if (!is.null(rv$panel_proc)) { try(rv$panel_proc$kill(), silent = TRUE); rv$panel_proc <- NULL }
    rv$panel_done <- FALSE; rv$panel_prog <- 0; rv$panel_msg <- tr("prog_stopped"); showNotification(tr("panel_stopped"), type = "warning") })

  observe({
    p <- rv$panel_proc; if (is.null(p)) return(); invalidateLater(600)
    isolate({
      txt <- if (!is.null(rv$panel_logf) && file.exists(rv$panel_logf)) tryCatch(readLines(rv$panel_logf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_fs_progress(txt, rv$snp_total); rv$panel_prog <- max(rv$panel_prog %||% 0, pr$frac); rv$panel_msg <- pr$msg; rv$panel_eta <- eta_upd("panel", txt, rv$snp_total)   # v6.4 ADIM 4
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (D1)
      if (!p$is_alive()) {
        rv$panel_t1 <- Sys.time()
        out <- tryCatch(p$get_result(), error = function(e) {
          tail_log <- if (length(txt)) paste(utils::tail(txt, 6), collapse = "\n") else ""
          console_add(sprintf("[%s] f2 pool build ERROR: %s", format(Sys.time(), "%H:%M:%S"), conditionMessage(e)))
          showNotification(paste0(tr("panel_error"), ": ", conditionMessage(e),
            if (nzchar(tail_log)) paste0("\n\n", tr("msg_log_tail"), "\n", tail_log) else ""), type = "error", duration = NULL); NULL })
        rv$panel_proc <- NULL
        pp <- rv$pool_pending
        if (!is.null(out) && !is.null(pp) && pool_ok(pp$dir)) {
          pool_write_meta(pp$dir, pp$prefix, pp$pops, pp$maxmiss, pp$blgsize, pp$adjph, pp$auto_only, pp$vfam, pp$orig, pp$comp)
          if (!isFALSE(pp$set_panel)) rv$panel <- pool_read_meta(pp$dir)
          rv$pool_pending <- NULL
          if (!is.null(pp$resume)) { rv$pool_need <- NULL; k <- paste0("resume_", pp$resume); rv[[k]] <- (rv[[k]] %||% 0) + 1; showNotification(tr("pool_resumed"), type = "message") }
          rv$panel_done <- TRUE; rv$panel_prog <- 1; rv$panel_msg <- tr("msg_completed")
          st <- pool_stats(pp$dir)
          showNotification(sprintf(tr("panel_built_ok"), length(pp$pops), fs_fmt_n(st$nsnp %||% 0), st$nblock %||% 0), type = "message", duration = 10)
          console_add(sprintf("[%s] f2 pool ready: %d pops, %s SNPs, %s blocks (%s)", format(Sys.time(), "%H:%M:%S"), length(pp$pops), fs_fmt_n(st$nsnp %||% 0), st$nblock %||% 0, el_str(rv$panel_t0, rv$panel_t1) %||% "-"))
        } else { rv$panel_done <- FALSE; rv$panel_prog <- 0; rv$panel_msg <- tr("prog_error_notif") }
        rv$panel_tick <- rv$panel_tick + 1
      }
    })
  })

  output$panel_progress_ui <- renderUI({
    running <- !is.null(rv$panel_proc); done <- isTRUE(rv$panel_done); if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.0 (K9)
    prog_ui(done, rv$panel_prog, rv$panel_msg, el = el_str(rv$panel_t0, if (running) NULL else rv$panel_t1), eta = if (running) rv$panel_eta else NULL, eta_key = "prog_eta_phase")
  })

  output$panel_status_ui <- renderUI({
    pl <- rv$panel
    if (is.null(pl) || !pool_ok(pl$dir %||% "")) return(hint(tr("panel_none")))
    st <- pool_stats(pl$dir)
    kv <- function(k, v) div(class = "qps-kv mb-1", tags$b(paste0(k, ": ")), tags$code(v))
    tagList(
      div(class = "qps-stats my-2",
        div(class = "qps-stat qps-b-green", div(class = "lbl", tr("panel_npops")), div(class = "val", length(pl$pops))),
        div(class = "qps-stat qps-b-green", div(class = "lbl", tr("panel_nsnps")), div(class = "val", fs_fmt_n(st$nsnp %||% 0))),
        div(class = "qps-stat qps-b-amber", div(class = "lbl", tr("panel_nblocks")), div(class = "val", st$nblock %||% 0))),
      kv("maxmiss / blgsize", sprintf("%s / %s", pl$maxmiss, pl$blgsize)),
      kv("adjust_pseudohaploid / auto_only", sprintf("%s / %s", pl$adjph, pl$auto_only)),
      kv(tr("panel_built"), pl$built %||% "-"),
      kv(tr("panel_dir"), pl$dir),
      div(class = "small text-muted mt-2", tr("panel_wide_warn")))
  })

  output$panel_table <- renderDT({
    rv$panel_tick
    ps <- pool_scan(CACHE_BASE)
    if (!length(ps)) return(datatable(data.frame(Info = tr("panel_no_pools")), colnames = tr("info"), options = list(dom = "t"), rownames = FALSE))
    d <- do.call(rbind, lapply(ps, function(m) { st <- pool_stats(m$dir)
      data.frame(NPops = length(m$pops), NSNP = st$nsnp %||% NA, NBlocks = st$nblock %||% NA,
                 maxmiss = m$maxmiss, blgsize = m$blgsize, Built = m$built %||% "", Dir = basename(m$dir), stringsAsFactors = FALSE) }))
    datatable(d, rownames = FALSE, class = "compact stripe hover",
      colnames = c(tr("panel_npops"), tr("panel_nsnps"), tr("panel_nblocks"), "maxmiss", "blgsize", tr("panel_built"), tr("panel_dir")),
      options = list(pageLength = 8, scrollX = TRUE))
  }, server = FALSE)

  # ==========================================================================
  # f-ISTATISTIKLERI (f2 | f3 | f4) -- v5.5
  # ==========================================================================
  # Ortak calistirici. kind: "f2" | "f3" | "f4".
  fs_launch <- function(kind, pops_all, bgfun, bgargs, meta) {
    if (!is.null(rv$fs_proc[[kind]]) && rv$fs_proc[[kind]]$is_alive()) { showNotification(tr("fs_running"), type = "warning"); return(invisible(NULL)) }
    logf <- tempfile(fileext = ".log")
    rv$fs_logf[[kind]] <- logf; rv$fs_res[[kind]] <- NULL
    rv$fs_prog[[kind]] <- 0; rv$fs_msg[[kind]] <- tr("prog_starting"); rv$fs_meta[[kind]] <- meta
    rv$fs_t0[[kind]] <- Sys.time(); rv$fs_t1[[kind]] <- NULL   # v6.1: gecen sure
    console_add("", strrep("-", 60), sprintf("[%s] %s: %d pops", format(Sys.time(), "%H:%M:%S"), kind, length(pops_all)))
    rv$fs_proc[[kind]] <- qps_r_bg(func = bgfun, args = bgargs, stdout = logf, stderr = "2>&1")
    invisible(NULL)
  }

  # Kaynak cozumleme: havuz mu genotip prefix'i mi.
  fs_resolve <- function(pops, use_geno = FALSE, kind = NULL) {
    if (xs_block(pops)) return(NULL)   # v6.4 test (T7)
    ic <- ind_check(list(pops = unique(pops)), block_empty = TRUE); if (is.null(ic)) return(NULL)   # v6.2 (K3)
    pfx <- run_prefix(ic); if (is.null(pfx)) return(NULL)
    if (isTRUE(use_geno)) return(list(data = pfx, need = FALSE, src = "geno", dir = NULL))
    pl <- active_panel()
    pa <- panel_args()
    cx <- pool_ctx(ic$vfam)
    r <- resolve_f2(CACHE_BASE, pfx, pops, pa$maxmiss, pa$blgsize, pa$adjph, pa$auto_only, run_vkey(ic), pl, cx$orig, cx$lm)
    if (isTRUE(r$need)) {
      pl_ok <- !is.null(pl) && pool_ok(pl$dir %||% "")
      miss <- if (pl_ok) setdiff(pops, pl$pops) else pops
      if (!length(miss)) miss <- pops
      if (!is.null(kind)) rv$pool_need <- list(kind = kind, pops = unique(pops), missing = miss)
      showNotification(paste0(tr("pool_need_title"), ". ", sprintf(tr("fs_pops_missing"), paste(miss, collapse = ", "))), type = "warning", duration = 10)
      return(NULL)
    }
    rv$pool_need <- NULL
    if (identical(r$src, "superset") && isTRUE(r$wider)) showNotification(tr("panel_super_note"), type = "message", duration = 10)
    list(data = r$dir, need = FALSE, src = r$src, dir = r$dir)
  }

  # Analiz sekmesi altindaki havuz paneli: aktif havuz satiri; havuz yoksa
  # eksik popülasyonlar + kurulum dugmesi; kurulum suruyorsa ilerleme.
  pool_need_ui <- function(kind) {
    pl <- rv$panel
    st <- if (!is.null(pl) && pool_ok(pl$dir %||% "")) pool_stats(pl$dir) else NULL
    status <- div(class = "small text-muted mt-2",
      if (is.null(st)) tr("pool_status_none") else sprintf(tr("pool_status_line"), length(pl$pops), fs_fmt_n(st$nsnp %||% 0)))
    pp <- rv$pool_pending
    if (!is.null(rv$panel_proc) && identical(pp$resume, kind)) {
      pct <- round((rv$panel_prog %||% 0) * 100)
      return(tagList(status,
        div(class = "alert alert-info py-2 px-3 small mt-2", tr("pool_building")),
        div(class = "qps-prog-bg", div(class = "qps-prog-fill", style = sprintf("width:%d%%;", pct))),
        div(class = "qps-prog-txt", sprintf("%d%%  %s", pct, rv$panel_msg %||% ""))))
    }
    nd <- rv$pool_need
    if (is.null(nd) || !identical(nd$kind, kind)) return(status)
    tagList(status,
      div(class = "alert alert-warning py-2 px-3 small mt-2", tags$b(tr("pool_need_title")), tags$br(),
        sprintf(tr("fs_pops_missing"), paste(nd$missing, collapse = ", "))),
      radioButtons(paste0("pool_mode_", kind), tr("pool_mode"),
        choices = stats::setNames(c("add", "only"), c(tr("pool_mode_add"), tr("pool_mode_only"))), selected = "add"),
      actionButton(paste0("pool_go_", kind), tr("pool_go"), class = "btn-warning w-100", icon = icon("cubes")))
  }
  output$f2_pool_ui  <- renderUI(pool_need_ui("f2"))
  output$f3_pool_ui  <- renderUI(pool_need_ui("f3"))
  output$f4_pool_ui  <- renderUI(pool_need_ui("f4"))
  output$f4r_pool_ui <- renderUI(pool_need_ui("f4r"))
  output$qg_pool_ui  <- renderUI(pool_need_ui("qg"))

  for (k in c("f2", "f3", "f4", "f4r", "qg")) local({
    kk <- k
    observeEvent(input[[paste0("pool_go_", kk)]], safe_run({
      nd <- rv$pool_need; if (is.null(nd) || !identical(nd$kind, kk)) return()
      mode <- input[[paste0("pool_mode_", kk)]] %||% "add"
      pl <- rv$panel
      pops <- if (identical(mode, "add") && !is.null(pl) && pool_ok(pl$dir %||% "")) union(pl$pops, nd$pops) else nd$pops
      start_pool_build(pops, set_panel = identical(mode, "add"), resume = kk)
    }, tr("panel_title")), ignoreInit = TRUE)
  })

  fs_progress_ui <- function(kind) {
    running <- !is.null(rv$fs_proc[[kind]]); done <- !is.null(rv$fs_res[[kind]])
    if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.1 ADIM 3: gecen sure saniyede bir (ortak cubuk prog_ui)
    prog_ui(done, rv$fs_prog[[kind]] %||% 0, rv$fs_msg[[kind]], el = el_str(rv$fs_t0[[kind]], if (running) NULL else rv$fs_t1[[kind]]), eta = if (running) (rv$fs_eta %||% list())[[kind]] else NULL, eta_key = "prog_eta_phase")
  }

  fs_watch <- function(kind) {
    p <- rv$fs_proc[[kind]]; if (is.null(p)) return(); invalidateLater(600)
    isolate({
      lf <- rv$fs_logf[[kind]]
      txt <- if (!is.null(lf) && file.exists(lf)) tryCatch(readLines(lf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_fs_progress(txt, rv$snp_total)
      rv$fs_prog[[kind]] <- max(rv$fs_prog[[kind]] %||% 0, pr$frac); rv$fs_msg[[kind]] <- pr$msg; ee <- rv$fs_eta %||% list(); ee[[kind]] <- eta_upd(paste0("fs_", kind), txt, rv$snp_total); rv$fs_eta <- ee   # v6.4 ADIM 4
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (D1)
      if (!p$is_alive()) {
        out <- tryCatch(p$get_result(), error = function(e) {
          tail_log <- if (length(txt)) paste(utils::tail(txt, 6), collapse = "\n") else ""
          showNotification(paste0(toupper(kind), ": ", conditionMessage(e),
            if (nzchar(tail_log)) paste0("\n\n", tr("msg_log_tail"), "\n", tail_log) else ""), type = "error", duration = NULL); NULL })
        rv$fs_proc[[kind]] <- NULL; rv$fs_t1[[kind]] <- Sys.time()
        if (!is.null(out)) { rv$fs_res[[kind]] <- as.data.frame(out); rv$fs_prog[[kind]] <- 1
          showNotification(sprintf(tr("fs_done"), nrow(out)), type = "message") }
        else { rv$fs_prog[[kind]] <- 0; rv$fs_msg[[kind]] <- tr("prog_error_notif") }
      }
    })
  }

  fs_table <- function(kind) {
    d <- rv$fs_res[[kind]]; req(d)
    dt <- datatable(d, filter = "top", rownames = FALSE, class = "compact stripe hover",
      options = list(scrollX = TRUE, pageLength = 20))
    # v5.8: qpf4ratio "est" degil "alpha", qpf4diff "f4diff" dondurur; payda
    # denetimi den_* sutunlarini ekler. Hepsi biciimlendirme listesinde olmali.
    num <- intersect(c("est", "alpha", "f4diff", "se", "z", "p", "den_est", "den_se", "den_z"), names(d))
    if (length(num)) dt <- DT::formatSignif(dt, columns = num, digits = 4)
    if ("z" %in% names(d)) dt <- DT::formatStyle(dt, "z", fontWeight = DT::styleInterval(c(-3, 3), c("bold", "normal", "bold")))
    if ("den_z" %in% names(d)) dt <- DT::formatStyle(dt, "den_z", color = DT::styleInterval(c(-3, 3), c("", "#ef4444", "")))
    if ("alpha" %in% names(d)) dt <- DT::formatStyle(dt, "alpha", color = DT::styleInterval(c(0, 1), c("#ef4444", "", "#ef4444")))
    if ("den_ok" %in% names(d)) dt <- DT::formatStyle(dt, "den_ok", backgroundColor = DT::styleEqual(c(FALSE), c("#FDE7E9")))
    dt
  }

  fs_dl <- function(kind) downloadHandler(
    filename = function() sprintf("%s_%s.xlsx", kind, format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { d <- rv$fs_res[[kind]]
      if (is.null(d)) { showNotification(tr("fs_first"), type = "error"); return() }
      write_fstat_excel(d, file, kind = kind, meta = rv$fs_meta[[kind]]) })

  # ------------------------------------------------------------------- f2
  output$f2_count_ui <- renderUI({
    n <- fs_ncomb(2, c(length(input$f2_p1 %||% character(0)), length(input$f2_p2 %||% character(0))))
    tagList(hint(sprintf(tr("fs_ncomb"), fs_fmt_n(n))), if (n > FS_MAXCOMB) div(class = "text-danger small", tr("fs_too_many")) else NULL)
  })
  run_f2 <- function() safe_run({
    p1 <- input$f2_p1; p2 <- input$f2_p2
    if (!length(p1) || !length(p2)) { showNotification(tr("msg_fst_pick_pops"), type = "error"); return() }
    if (fs_ncomb(2, c(length(p1), length(p2))) > FS_MAXCOMB) { showNotification(tr("fs_too_many"), type = "error"); return() }
    pops <- unique(c(p1, p2)); r <- fs_resolve(pops, use_geno = FALSE, kind = "f2"); if (is.null(r)) return()
    fs_launch("f2", pops,
      function(data, p1, p2, uniq) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat("QPS_FS_STAGE read\n"); cat("QPS_FS_STAGE compute\n")
        if (is.character(data) && dir.exists(data)) data <- f2_from_precomp(data, pops = unique(c(p1, p2)), afprod = FALSE, apply_corr = TRUE, verbose = FALSE)
        f2(data, pop1 = p1, pop2 = p2, unique_only = uniq, verbose = TRUE)
      },
      list(data = r$data, p1 = p1, p2 = p2, uniq = isTRUE(input$f2_unique)),
      list(statistic = "f2", source = r$src, unique_only = isTRUE(input$f2_unique), pop1 = p1, pop2 = p2))
  }, "f2")
  observeEvent(input$f2_run, run_f2())
  observeEvent(rv$resume_f2, run_f2(), ignoreInit = TRUE)
  observeEvent(input$f2_stop, { if (!is.null(rv$fs_proc[["f2"]])) { try(rv$fs_proc[["f2"]]$kill(), silent = TRUE); rv$fs_proc[["f2"]] <- NULL }
    rv$fs_prog[["f2"]] <- 0; rv$fs_msg[["f2"]] <- tr("prog_stopped"); showNotification(tr("prog_stopped"), type = "warning") })
  observe(fs_watch("f2"))
  output$f2_progress_ui <- renderUI(fs_progress_ui("f2"))
  output$f2_table <- renderDT(fs_table("f2"), server = FALSE)
  output$f2_xlsx <- fs_dl("f2")

  # ------------------------------------------------------------------- f3
  output$f3_mode_note <- renderUI({
    if (identical(input$f3_mode, "admix")) tagList(hint(tr("f3_admix_needs_geno")), div(class = "small text-muted", tr("f3_single_pseudo")))
    else hint(tr("f2_note"))
  })
  # pop1 etiketi moda bagli: karisim f3'te HEDEF, outgroup f3'te OUTGROUP.
  output$f3_p1_label <- renderUI(tags$label(class = "control-label",
    if (identical(input$f3_mode, "admix")) tr("f3_p1_target") else tr("f3_p1_outgroup")))

  output$f3_count_ui <- renderUI({
    n <- fs_ncomb(3, c(length(input$f3_p1 %||% character(0)), length(input$f3_p2 %||% character(0)), length(input$f3_p3 %||% character(0))))
    tagList(hint(sprintf(tr("fs_ncomb"), fs_fmt_n(n))), if (n > FS_MAXCOMB) div(class = "text-danger small", tr("fs_too_many")) else NULL)
  })
  run_f3 <- function() safe_run({
    p1 <- input$f3_p1; p2 <- input$f3_p2; p3 <- input$f3_p3
    if (!length(p1) || !length(p2) || !length(p3)) { showNotification(tr("msg_fst_pick_pops"), type = "error"); return() }
    if (fs_ncomb(3, c(length(p1), length(p2), length(p3))) > FS_MAXCOMB) { showNotification(tr("fs_too_many"), type = "error"); return() }
    admix <- identical(input$f3_mode, "admix")
    pops <- unique(c(p1, p2, p3))
    # KRITIK: karisim f3'u hedefin heterozigotluguna normalize edilir; bu
    # yalnizca GENOTIP dosyasindan hesaplanabilir (qp3pop_geno, outgroupmode=FALSE).
    # Onceden hesaplanmis f2'den okunursa sonuc OUTGROUP f3 olur.
    r <- fs_resolve(pops, use_geno = admix, kind = "f3"); if (is.null(r)) return()
    fs_launch("f3", pops,
      function(data, p1, p2, p3, uniq, admix) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat("QPS_FS_STAGE compute\n")
        if (!admix && is.character(data) && dir.exists(data)) data <- f2_from_precomp(data, pops = unique(c(p1, p2, p3)), afprod = FALSE, apply_corr = TRUE, verbose = FALSE)
        if (admix) qp3pop(data, pop1 = p1, pop2 = p2, pop3 = p3, unique_only = uniq, outgroupmode = FALSE, verbose = TRUE)
        else qp3pop(data, pop1 = p1, pop2 = p2, pop3 = p3, unique_only = uniq, verbose = TRUE)
      },
      list(data = r$data, p1 = p1, p2 = p2, p3 = p3, uniq = isTRUE(input$f3_unique), admix = admix),
      list(statistic = if (admix) "f3 (admixture, outgroupmode=FALSE)" else "f3 (outgroup)",
           source = r$src, unique_only = isTRUE(input$f3_unique), pop1 = p1, pop2 = p2, pop3 = p3))
  }, "f3")
  observeEvent(input$f3_run, run_f3())
  observeEvent(rv$resume_f3, run_f3(), ignoreInit = TRUE)
  observeEvent(input$f3_stop, { if (!is.null(rv$fs_proc[["f3"]])) { try(rv$fs_proc[["f3"]]$kill(), silent = TRUE); rv$fs_proc[["f3"]] <- NULL }
    rv$fs_prog[["f3"]] <- 0; rv$fs_msg[["f3"]] <- tr("prog_stopped"); showNotification(tr("prog_stopped"), type = "warning") })
  observe(fs_watch("f3"))
  output$f3_progress_ui <- renderUI(fs_progress_ui("f3"))
  output$f3_table <- renderDT(fs_table("f3"), server = FALSE)
  output$f3_xlsx <- fs_dl("f3")

  # ------------------------------------------------------------------- f4
  f4_quads <- reactive(parse_quads(input$f4_rows, rv$labels))
  output$f4_count_ui <- renderUI({
    if (identical(input$f4_input, "rows")) {
      q <- f4_quads(); n <- if (is.null(q$df)) 0 else nrow(q$df)
      return(tagList(hint(sprintf(tr("fs_ncomb"), fs_fmt_n(n))),
        if (q$bad > 0) div(class = "text-danger small", sprintf(tr("f4_rows_bad"), q$bad)) else NULL))
    }
    n <- fs_ncomb(4, c(length(input$f4_p1 %||% character(0)), length(input$f4_p2 %||% character(0)),
                       length(input$f4_p3 %||% character(0)), length(input$f4_p4 %||% character(0))))
    tagList(hint(sprintf(tr("fs_ncomb"), fs_fmt_n(n))), if (n > FS_MAXCOMB) div(class = "text-danger small", tr("fs_too_many")) else NULL)
  })
  run_f4 <- function() safe_run({
    rows_mode <- identical(input$f4_input, "rows")
    f4mode <- identical(input$f4_mode, "f4")
    use_geno <- identical(input$f4_src, "geno")
    if (rows_mode) {
      q <- f4_quads()
      if (is.null(q$df) || !nrow(q$df)) { showNotification(tr("msg_paste_fail"), type = "error"); return() }
      pops <- unique(unlist(q$df, use.names = FALSE))
      r <- fs_resolve(pops, use_geno = use_geno, kind = "f4"); if (is.null(r)) return()
      # comb = FALSE: pop1..pop4 esit uzunlukta, her satir TEK istatistik.
      fs_launch("f4", pops,
        function(data, q, f4mode) {
          options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
          cat("QPS_FS_STAGE compute\n")
          if (is.character(data) && dir.exists(data)) data <- f2_from_precomp(data, pops = unique(c(q$pop1, q$pop2, q$pop3, q$pop4)), afprod = TRUE, apply_corr = TRUE, verbose = FALSE)
          qpdstat(data, pop1 = q$pop1, pop2 = q$pop2, pop3 = q$pop3, pop4 = q$pop4, comb = FALSE, f4mode = f4mode, verbose = TRUE)
        },
        list(data = r$data, q = q$df, f4mode = f4mode),
        list(statistic = if (f4mode) "f4" else "D", source = r$src, input = "rows", n_rows = nrow(q$df)))
      return()
    }
    p1 <- input$f4_p1; p2 <- input$f4_p2; p3 <- input$f4_p3; p4 <- input$f4_p4
    if (!length(p1) || !length(p2) || !length(p3) || !length(p4)) { showNotification(tr("msg_fst_pick_pops"), type = "error"); return() }
    if (fs_ncomb(4, c(length(p1), length(p2), length(p3), length(p4))) > FS_MAXCOMB) { showNotification(tr("fs_too_many"), type = "error"); return() }
    pops <- unique(c(p1, p2, p3, p4))
    r <- fs_resolve(pops, use_geno = use_geno, kind = "f4"); if (is.null(r)) return()
    fs_launch("f4", pops,
      function(data, p1, p2, p3, p4, uniq, f4mode) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat("QPS_FS_STAGE compute\n")
        if (is.character(data) && dir.exists(data)) data <- f2_from_precomp(data, pops = unique(c(p1, p2, p3, p4)), afprod = TRUE, apply_corr = TRUE, verbose = FALSE)
        qpdstat(data, pop1 = p1, pop2 = p2, pop3 = p3, pop4 = p4, unique_only = uniq, f4mode = f4mode, verbose = TRUE)
      },
      list(data = r$data, p1 = p1, p2 = p2, p3 = p3, p4 = p4, uniq = isTRUE(input$f4_unique), f4mode = f4mode),
      list(statistic = if (f4mode) "f4" else "D", source = r$src, input = "comb",
           unique_only = isTRUE(input$f4_unique), pop1 = p1, pop2 = p2, pop3 = p3, pop4 = p4))
  }, "f4")
  observeEvent(input$f4_run, run_f4())
  observeEvent(rv$resume_f4, run_f4(), ignoreInit = TRUE)
  observeEvent(input$f4_stop, { if (!is.null(rv$fs_proc[["f4"]])) { try(rv$fs_proc[["f4"]]$kill(), silent = TRUE); rv$fs_proc[["f4"]] <- NULL }
    rv$fs_prog[["f4"]] <- 0; rv$fs_msg[["f4"]] <- tr("prog_stopped"); showNotification(tr("prog_stopped"), type = "warning") })
  observe(fs_watch("f4"))
  output$f4_progress_ui <- renderUI(fs_progress_ui("f4"))
  output$f4_table <- renderDT(fs_table("f4"), server = FALSE)
  output$f4_xlsx <- fs_dl("f4")

  # ------------------------------------------------------------------ f4-ORANI
  # Beslik kaynagi: satir satir (varsayilan) ya da anahtarla acilan kombinasyon.
  f4r_quints <- reactive({
    if (isTRUE(input$f4r_comb)) {
      g <- quints_from_lists(input$f4r_p1, input$f4r_p2, input$f4r_p3, input$f4r_p4, input$f4r_p5)
      return(list(df = g, bad = 0L, dup = 0L))
    }
    parse_quints(input$f4r_rows, rv$labels)
  })

  output$f4r_count_ui <- renderUI({
    q <- f4r_quints(); n <- if (is.null(q$df)) 0L else nrow(q$df)
    items <- list(hint(sprintf(tr("fs_ncomb"), fs_fmt_n(n))))
    if (n > FS_MAXCOMB) items <- c(items, list(div(class = "text-danger small", tr("fs_too_many"))))
    if (isTRUE(q$bad > 0)) items <- c(items, list(div(class = "text-danger small", sprintf(tr("f4r_rows_bad"), q$bad))))
    if (isTRUE(q$dup > 0)) items <- c(items, list(div(class = "small text-muted", sprintf(tr("f4r_dedup"), q$dup))))
    if (n >= 1 && identical(input$f4r_stat, "ratio")) {
      r1 <- q$df[1, ]
      items <- c(items, list(div(class = "small text-muted mt-1", tags$b(paste0(tr("f4r_live"), ": ")),
        tags$code(sprintf("alpha = f4(%s, %s; %s, %s) / f4(%s, %s; %s, %s)",
          r1$pop1, r1$pop2, r1$pop3, r1$pop4, r1$pop1, r1$pop2, r1$pop5, r1$pop4)))))
    }
    if (identical(input$f4r_stat, "diff")) items <- c(items, list(hint(tr("f4r_diff_note"))))
    else items <- c(items, list(hint(tr("f4r_denom_note"))))
    tagList(items)
  })

  output$f4r_notes_ui <- renderUI({
    d <- rv$fs_res[["f4r"]]; if (is.null(d) || !nrow(d)) return(hint(tr("f4r_cols_note")))
    items <- list()
    if ("den_ok" %in% names(d)) { nb <- sum(!d$den_ok, na.rm = TRUE)
      if (nb > 0) items <- c(items, list(div(class = "alert alert-warning py-2 px-3 small",
        icon("triangle-exclamation"), " ", sprintf(tr("f4r_denom_bad"), nb)))) }
    if ("alpha" %in% names(d)) { nr <- sum(!is.na(d$alpha) & (d$alpha < 0 | d$alpha > 1))
      if (nr > 0) items <- c(items, list(div(class = "alert alert-warning py-2 px-3 small",
        icon("triangle-exclamation"), " ", sprintf(tr("f4r_alpha_range"), nr)))) }
    m <- rv$fs_meta[["f4r"]]
    if (!is.null(m) && !is.null(m$nsnp) && is.finite(m$nsnp))
      items <- c(items, list(div(class = "small text-muted", sprintf(tr("f4r_nsnp"), fs_fmt_n(m$nsnp), m$nblock %||% 0))))
    c(items, list(hint(tr("f4r_cols_note")), hint(tr("fs_zcol"))))
  })

  run_f4r <- function() safe_run({
    q <- f4r_quints()
    if (is.null(q$df) || !nrow(q$df)) { showNotification(tr("msg_paste_fail"), type = "error"); return() }
    if (nrow(q$df) > FS_MAXCOMB) { showNotification(tr("fs_too_many"), type = "error"); return() }
    ratio <- identical(input$f4r_stat, "ratio")
    use_geno <- identical(input$f4r_src, "geno")
    pops <- unique(unlist(q$df, use.names = FALSE))
    r <- fs_resolve(pops, use_geno = use_geno, kind = "f4r"); if (is.null(r)) return()
    nsnp <- NA_integer_; nblock <- NA_integer_
    if (!use_geno && !is.null(r$dir)) { st <- pool_stats(r$dir); nsnp <- st$nsnp; nblock <- st$nblock }
    fs_launch("f4r", pops,
      function(data, q, ratio, boot) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        # DIKKAT: qpf4ratio 'pops' icin MATRIS ister. data.frame verilirse
        # is.matrix FALSE doner, t() uygulanir ve ncol != 5 olup hata verir.
        m <- as.matrix(q[, c("pop1", "pop2", "pop3", "pop4", "pop5")])
        # Oran modu: qpf4ratio ve payda qpdstat ikisi de afprod = TRUE kullanir -> tek dizi.
        # Fark modu: qpf4diff afprod = FALSE ve apply_corr = FALSE kullanir.
        if (is.character(data) && dir.exists(data)) data <- f2_from_precomp(data, pops = unique(c(m)), afprod = ratio, apply_corr = ratio, verbose = FALSE)
        if (ratio) {
          cat("QPS_FS_STAGE ratio\n")
          out <- as.data.frame(qpf4ratio(data, m, boot = boot, verbose = TRUE))
          # OTOMATIK PAYDA DENETIMI. qpf4ratio paydanin sifirdan anlamli
          # bicimde farkli olup olmadigini TEST ETMEZ; blok bazinda
          # |f4_den| < 1e-6 olanlari NA'ya cevirmekle yetinir. Payda sifira
          # yakinsa alpha sayi olarak doner ve tamamen anlamsizdir.
          # Payda = f4(1,2;5,4), ayni f2 bloklarindan ucuza gelir.
          cat("QPS_FS_STAGE denom\n")
          den <- as.data.frame(qpdstat(data, pop1 = m[, 1], pop2 = m[, 2], pop3 = m[, 5], pop4 = m[, 4],
                                       comb = FALSE, f4mode = TRUE, verbose = TRUE))
          out$den_est <- den$est; out$den_se <- den$se; out$den_z <- den$z
          out$den_ok <- is.finite(den$z) & abs(den$z) >= 3
          out
        } else {
          cat("QPS_FS_STAGE ratio\n")
          as.data.frame(qpf4diff(data, m, boot = boot, verbose = TRUE))
        }
      },
      list(data = r$data, q = q$df, ratio = ratio, boot = isTRUE(input$f4r_boot)),
      list(statistic = if (ratio) "f4-ratio (alpha)" else "f4-difference", source = r$src,
           input = if (isTRUE(input$f4r_comb)) "combinations" else "rows",
           n_rows = nrow(q$df), dropped_redundant = q$dup, boot = isTRUE(input$f4r_boot),
           denominator_check = ratio, nsnp = nsnp, nblock = nblock,
           formula = if (ratio) "alpha = f4(1,2;3,4) / f4(1,2;5,4)" else "f4(1,2;3,4) - f4(1,2;5,4)"))
  }, "f4-ratio")
  observeEvent(input$f4r_run, run_f4r())
  observeEvent(rv$resume_f4r, run_f4r(), ignoreInit = TRUE)

  observeEvent(input$f4r_stop, { if (!is.null(rv$fs_proc[["f4r"]])) { try(rv$fs_proc[["f4r"]]$kill(), silent = TRUE); rv$fs_proc[["f4r"]] <- NULL }
    rv$fs_prog[["f4r"]] <- 0; rv$fs_msg[["f4r"]] <- tr("prog_stopped"); showNotification(tr("prog_stopped"), type = "warning") })
  observe(fs_watch("f4r"))
  output$f4r_progress_ui <- renderUI(fs_progress_ui("f4r"))
  output$f4r_table <- renderDT(fs_table("f4r"), server = FALSE)
  output$f4r_xlsx <- fs_dl("f4r")

  # ==========================================================================
  # qpGRAPH (v5.6) -- tek graf uyumu
  # ==========================================================================
  qg_parsed <- reactive(parse_edges(input$qg_edges))

  observeEvent(input$qg_example, safe_run({
    labs <- rv$labels %||% character(0)
    seed_pops <- unique(c(input$panel_pops %||% character(0), labs))
    e <- example_graph_edges(seed_pops)
    if (is.null(e)) { showNotification(tr("qg_need_pops"), type = "error"); return() }
    updateTextAreaInput(session, "qg_edges", value = edges_to_text(e))
  }, tr("tab_qpgraph")))

  observeEvent(input$qg_file, safe_run({
    fp <- shinyFiles::parseFilePaths(volumes, input$qg_file)
    if (!nrow(fp)) return()
    path <- as.character(fp$datapath[1])
    e <- tryCatch({
      if (grepl("\\.dot$", path, ignore.case = TRUE)) admixtools::parse_dot(path)
      else admixtools::parse_qpgraph_graphfile(path)
    }, error = function(e) e)
    if (inherits(e, "error")) { showNotification(paste0(tr("qg_import_fail"), ": ", conditionMessage(e)), type = "error", duration = NULL); return() }
    d <- as.data.frame(e, stringsAsFactors = FALSE)
    if (ncol(d) < 2) { showNotification(tr("qg_import_fail"), type = "error"); return() }
    d <- data.frame(from = as.character(d[[1]]), to = as.character(d[[2]]), stringsAsFactors = FALSE)
    d <- d[nzchar(d$from) & nzchar(d$to), , drop = FALSE]
    updateTextAreaInput(session, "qg_edges", value = edges_to_text(d))
    showNotification(sprintf(tr("qg_imported"), nrow(d)), type = "message")
  }, tr("tab_qpgraph")))

  qg_report <- function() {
    p <- qg_parsed()
    if (is.null(p$df)) return(list(chk = NULL, bad = p$bad, missing = character(0)))
    chk <- graph_check(p$df)
    miss <- if (isTRUE(chk$ok)) setdiff(chk$leaves, rv$labels %||% character(0)) else character(0)
    list(chk = chk, bad = p$bad, missing = miss)
  }

  output$qg_check_ui <- renderUI({
    r <- qg_report()
    items <- list()
    if (r$bad > 0) items <- c(items, list(div(class = "text-danger small", sprintf(tr("qg_parse_bad"), r$bad))))
    chk <- r$chk
    if (is.null(chk)) return(tagList(items))
    if (!isTRUE(chk$ok)) return(tagList(items, div(class = "text-danger small mt-1", tr("qg_valid_bad"))))
    items <- c(items, list(div(class = "qps-stats my-2",
      div(class = "qps-stat qps-b-green", div(class = "lbl", tr("qg_leaves")),  div(class = "val", length(chk$leaves))),
      div(class = "qps-stat qps-b-amber", div(class = "lbl", tr("qg_nadmix")),  div(class = "val", chk$nadmix)),
      div(class = "qps-stat qps-b-green", div(class = "lbl", tr("qg_edges")),   div(class = "val", chk$nedge)))))
    if (length(r$missing)) items <- c(items, list(div(class = "text-danger small", sprintf(tr("qg_leaves_missing"), paste(r$missing, collapse = ", ")))))
    tagList(items)
  })

  observeEvent(input$qg_check, {
    r <- qg_report(); chk <- r$chk
    if (is.null(chk) || !isTRUE(chk$ok)) { showNotification(tr("qg_valid_bad"), type = "error", duration = 10); return() }
    if (length(r$missing)) { showNotification(sprintf(tr("qg_leaves_missing"), paste(r$missing, collapse = ", ")), type = "error", duration = 12); return() }
    showNotification(sprintf(tr("qg_valid_ok"), length(chk$leaves), chk$nadmix, chk$nedge), type = "message", duration = 8)
  })

  output$qg_dot <- downloadHandler(
    filename = function() sprintf("qpgraph_%s.dot", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) {
      d <- (rv$qg_fit$edges %||% qg_parsed()$df)
      if (is.null(d) || !NROW(d)) { writeLines("digraph G {}", file); return() }
      d <- as.data.frame(d, stringsAsFactors = FALSE)
      L <- c("digraph G {", "  graph [rankdir=TB];")
      for (i in seq_len(nrow(d))) {
        lab <- if ("weight" %in% names(d) && is.finite(suppressWarnings(as.numeric(d$weight[i]))))
          sprintf(' [label="%.3f"]', as.numeric(d$weight[i])) else ""
        L <- c(L, sprintf('  "%s" -> "%s"%s;', d$from[i], d$to[i], lab))
      }
      writeLines(c(L, "}"), file, useBytes = TRUE)
    })

  run_qg <- function() safe_run({
    if (is.null(rv$prefix)) { showNotification(tr("msg_pick_geno"), type = "error"); return() }
    if (!is.null(rv$qg_proc) && rv$qg_proc$is_alive()) { showNotification(tr("qg_running"), type = "warning"); return() }
    r <- qg_report(); chk <- r$chk
    if (is.null(chk) || !isTRUE(chk$ok)) { showNotification(tr("qg_valid_bad"), type = "error", duration = 10); return() }
    if (length(r$missing)) { showNotification(sprintf(tr("qg_leaves_missing"), paste(r$missing, collapse = ", ")), type = "error", duration = 12); return() }
    ed <- qg_parsed()$df
    use_geno <- identical(input$qg_src, "geno")
    fr <- fs_resolve(chk$leaves, use_geno = use_geno, kind = "qg"); if (is.null(fr)) return()
    sd <- suppressWarnings(as.integer(trimws(input$qg_seed %||% "")))
    if (!is.finite(sd)) sd <- NULL
    logf <- tempfile(fileext = ".log")
    rv$qg_logf <- logf; rv$qg_fit <- NULL; rv$qg_prog <- 0; rv$qg_msg <- tr("prog_starting"); rv$qg_t0 <- Sys.time(); rv$qg_t1 <- NULL
    rv$qg_edges <- ed
    rv$qg_meta <- list(leaves = paste(chk$leaves, collapse = ", "), n_leaves = length(chk$leaves),
      n_admix = chk$nadmix, n_edges = chk$nedge, source = fr$src,
      allsnps = if (use_geno) isTRUE(input$qg_allsnps) else NA,
      numstart = input$qg_numstart %||% 10, seed = if (is.null(sd)) "NOT SET" else sd,
      lsqmode = isTRUE(input$qg_lsqmode), diag_f3 = input$qg_diagf3 %||% 1e-5,
      constrained = isTRUE(input$qg_constrained), return_pvalue = isTRUE(input$qg_pvalue),
      time = format(Sys.time(), "%Y-%m-%d %H:%M:%S"))
    console_add("", strrep("-", 60),
      sprintf("[%s] qpgraph: %d leaves, %d admix, %d edges (source=%s, seed=%s)",
        format(Sys.time(), "%H:%M:%S"), length(chk$leaves), chk$nadmix, chk$nedge, fr$src,
        if (is.null(sd)) "NOT SET" else sd))
    rv$qg_proc <- qps_r_bg(
      func = function(data, edges, use_geno, allsnps, numstart, seed, lsqmode, diag_f3, constrained, want_p) {
        options(cli.width = 10000, width = 10000, cli.num_colors = 1, crayon.enabled = FALSE); Sys.setenv(COLUMNS = "10000", NO_COLOR = "1"); library(admixtools)
        cat("QPS_QG_STAGE read\n")
        g <- as.matrix(edges[, 1:2])
        cat("QPS_QG_STAGE fit\n")
        # DIKKAT (Ders 1'in qpgraph karsiligi): allsnps SADECE data bir genotip
        # prefix'i oldugunda gecerlidir. Onceden hesaplanmis f2 klasoru
        # verildiginde argumani GONDERMIYORUZ.
        # AYRICA: qpgraph() icerde get_f2(..., afprod = FALSE) zorlar; bu yuzden
        # ELDE KURULMUS bir f2 DIZISI degil, KLASOR YOLU geciliyor.
        rc <- character(0)
        fit <- withCallingHandlers({
          if (use_geno)
            qpgraph(data, g, numstart = numstart, seed = seed, lsqmode = lsqmode, diag_f3 = diag_f3,
                    constrained = constrained, return_fstats = TRUE, return_pvalue = want_p,
                    allsnps = allsnps, verbose = TRUE)
          else
            qpgraph(data, g, numstart = numstart, seed = seed, lsqmode = lsqmode, diag_f3 = diag_f3,
                    constrained = constrained, return_fstats = TRUE, return_pvalue = want_p, verbose = TRUE)
        },
          warning = function(w) { m <- conditionMessage(w); cat(sprintf("QPS_RCOND [qpgraph] UYARI: %s\n", m)); rc <<- c(rc, m); invokeRestart("muffleWarning") },
          message = function(m2) { m <- conditionMessage(m2)
            if (grepl("rcond|singular|ill-condition", m, ignore.case = TRUE)) { cat(sprintf("QPS_RCOND [qpgraph] MESAJ: %s\n", m)); rc <<- c(rc, m) } })
        cat("QPS_QG_STAGE fstats\n")
        out <- list(edges = as.data.frame(fit$edges), score = fit$score,
                    worst_residual = fit$worst_residual %||% NA_real_,
                    p.value = fit$p.value %||% NA_real_,
                    f3 = as.data.frame(fit$f3), f4 = if (is.null(fit$f4)) NULL else as.data.frame(fit$f4),
                    rcond = unique(rc))
        out
      },
      args = list(data = fr$data, edges = ed, use_geno = use_geno,
                  allsnps = if (use_geno) isTRUE(input$qg_allsnps) else FALSE,
                  numstart = as.integer(input$qg_numstart %||% 10), seed = sd,
                  lsqmode = isTRUE(input$qg_lsqmode), diag_f3 = input$qg_diagf3 %||% 1e-5,
                  constrained = isTRUE(input$qg_constrained), want_p = isTRUE(input$qg_pvalue)),
      stdout = logf, stderr = "2>&1")
    nav_select("qg_nav", "fit")
  }, tr("tab_qpgraph"))
  observeEvent(input$qg_run, run_qg())
  observeEvent(rv$resume_qg, run_qg(), ignoreInit = TRUE)

  observeEvent(input$qg_stop, { if (!is.null(rv$qg_proc)) { try(rv$qg_proc$kill(), silent = TRUE); rv$qg_proc <- NULL }
    rv$qg_prog <- 0; rv$qg_msg <- tr("prog_stopped"); showNotification(tr("prog_stopped"), type = "warning") })

  observe({
    p <- rv$qg_proc; if (is.null(p)) return(); invalidateLater(600)
    isolate({
      txt <- if (!is.null(rv$qg_logf) && file.exists(rv$qg_logf)) tryCatch(readLines(rv$qg_logf, warn = FALSE), error = function(e) character(0)) else character(0)
      pr <- parse_qg_progress(txt, rv$snp_total); rv$qg_prog <- max(rv$qg_prog %||% 0, pr$frac); rv$qg_msg <- pr$msg; rv$qg_eta <- eta_upd("qg", txt, rv$snp_total)   # v6.4 ADIM 4
      if (length(txt)) rv$bg_log <- utils::tail(log_view(txt), 4000)   # v6.0 (D1)
      rc <- collect_rcond(txt); if (length(rc)) rv$rcond <- unique(c(rv$rcond, rc))
      if (!p$is_alive()) {
        out <- tryCatch(p$get_result(), error = function(e) {
          tail_log <- if (length(txt)) paste(utils::tail(txt, 6), collapse = "\n") else ""
          showNotification(paste0(tr("qg_error"), ": ", conditionMessage(e),
            if (nzchar(tail_log)) paste0("\n\n", tr("msg_log_tail"), "\n", tail_log) else ""), type = "error", duration = NULL); NULL })
        rv$qg_proc <- NULL; rv$qg_t1 <- Sys.time()
        flush_pool_meta()
        if (!is.null(out)) { rv$qg_fit <- out; rv$qg_prog <- 1; rv$qg_msg <- tr("msg_completed")
          showNotification(sprintf(tr("qg_done"), fmt(out$score), fmt(out$worst_residual)), type = "message", duration = 10) }
        else { rv$qg_prog <- 0; rv$qg_msg <- tr("prog_error_notif") }
      }
    })
  })

  output$qg_progress_ui <- renderUI({
    running <- !is.null(rv$qg_proc); done <- !is.null(rv$qg_fit); if (!running && !done) return(NULL)
    if (running) invalidateLater(1000)   # v6.1 ADIM 3: gecen sure (ortak cubuk prog_ui)
    prog_ui(done, rv$qg_prog %||% 0, rv$qg_msg, el = el_str(rv$qg_t0, if (running) NULL else rv$qg_t1), eta = if (running) rv$qg_eta else NULL, eta_key = "prog_eta_phase")
  })

  output$qg_summary_ui <- renderUI({
    f <- rv$qg_fit; if (is.null(f)) return(hint(tr("qg_first")))
    wr <- f$worst_residual
    kls <- if (is.finite(wr) && wr > 3) "qps-b-red" else "qps-b-green"
    stats <- list(
      div(class = "qps-stat qps-b-green", div(class = "lbl", tr("qg_score")), div(class = "val", fmt(f$score))),
      div(class = paste("qps-stat", kls), div(class = "lbl", tr("qg_worst")), div(class = "val", fmt(wr))))
    if (is.finite(f$p.value %||% NA_real_))
      stats <- c(stats, list(div(class = "qps-stat qps-b-amber", div(class = "lbl", tr("qg_pvalue")), div(class = "val", fmt(f$p.value)))))
    m <- rv$qg_meta %||% list()
    tagList(div(class = "qps-stats my-2", stats),
      div(class = "small text-muted", sprintf("seed = %s  |  numstart = %s  |  %s = %s",
        m$seed %||% "-", m$numstart %||% "-", tr("panel_source"), m$source %||% "-")),
      hint(tr("qg_score_note")),
      if (length(f$rcond)) div(class = "alert alert-warning py-2 px-3 small mt-2", icon("triangle-exclamation"), " ",
        sprintf("%s (%d)", tr("rcond_warn_title"), length(f$rcond))) else NULL)
  })

  qg_dt <- function(d, zcol = NULL) {
    if (is.null(d) || !NROW(d)) return(datatable(data.frame(Info = tr("qg_first")), colnames = tr("info"), options = list(dom = "t"), rownames = FALSE))
    d <- as.data.frame(d)
    dt <- datatable(d, filter = "top", rownames = FALSE, class = "compact stripe hover",
      options = list(scrollX = TRUE, pageLength = 20))
    num <- intersect(c("weight", "est", "fit", "diff", "se", "z", "p", "low", "high"), names(d))
    if (length(num)) dt <- DT::formatSignif(dt, columns = num, digits = 4)
    if (!is.null(zcol) && zcol %in% names(d))
      dt <- DT::formatStyle(dt, zcol, fontWeight = DT::styleInterval(c(-3, 3), c("bold", "normal", "bold")),
        color = DT::styleInterval(c(-3, 3), c("#ef4444", "", "#ef4444")))
    dt
  }
  output$qg_edges_table <- renderDT(qg_dt(rv$qg_fit$edges), server = FALSE)
  output$qg_f3_table    <- renderDT(qg_dt(rv$qg_fit$f3, "z"), server = FALSE)
  output$qg_f4_table    <- renderDT({ f <- rv$qg_fit
    d <- if (is.null(f) || is.null(f$f4)) NULL else f$f4[order(-abs(f$f4$z)), , drop = FALSE]
    qg_dt(d, "z") }, server = FALSE)

  output$qg_xlsx <- downloadHandler(
    filename = function() sprintf("qpgraph_%s.xlsx", format(Sys.time(), "%Y%m%d_%H%M%S")),
    content = function(file) { f <- rv$qg_fit
      if (is.null(f)) { showNotification(tr("qg_first"), type = "error"); return() }
      write_qpgraph_excel(f, file, meta = rv$qg_meta) })

  # ------------------------------------------------------------------ grafik
  qg_plot_obj <- eventReactive(input$qg_draw, {
    f <- rv$qg_fit
    if (is.null(f)) { showNotification(tr("qg_first"), type = "error"); return(NULL) }
    tryCatch({
      g <- admixtools::edges_to_igraph(as.data.frame(f$edges))
      ue <- tryCatch(admixtools::unidentifiable_edges(g), error = function(e) NULL)
      if (!is.null(ue) && NROW(ue) > 0) showNotification(sprintf(tr("qg_unident"), NROW(ue)), type = "warning", duration = 10)
      admixtools::plot_graph(as.data.frame(f$edges), hide_weights = isTRUE(input$qg_hide_w),
                             highlight_unidentifiable = isTRUE(input$qg_hl))
    }, error = function(e) { showNotification(paste0(tr("msg_plot_error"), ": ", conditionMessage(e)), type = "error", duration = NULL); NULL })
  })
  output$qg_plot_out <- renderPlot({ req(qg_plot_obj()); qg_plot_obj() }, res = 96)
  output$qg_dir_path <- renderText({ d <- tryCatch(shinyFiles::parseDirPath(volumes, input$qg_dir), error = function(e) character(0))
    if (length(d)) paste0(tr("save_folder"), ": ", d) else tr("folder_not_selected") })
  observeEvent(input$qg_save_png, {
    f <- rv$qg_fit; if (is.null(f)) { showNotification(tr("qg_first"), type = "error"); return() }
    d <- tryCatch(shinyFiles::parseDirPath(volumes, input$qg_dir), error = function(e) character(0))
    if (!length(d)) { showNotification(tr("msg_pick_folder"), type = "error"); return() }
    fn <- file.path(d, sprintf("qpgraph_%s.png", format(Sys.time(), "%Y%m%d_%H%M%S")))
    tryCatch({ pl <- admixtools::plot_graph(as.data.frame(f$edges), hide_weights = isTRUE(input$qg_hide_w),
                                            highlight_unidentifiable = isTRUE(input$qg_hl))
      ggplot2::ggsave(fn, pl, width = 12, height = 9, units = "in", dpi = 300, bg = "white")
      showNotification(sprintf(tr("msg_saved_to"), fn), type = "message", duration = 8) },
      error = function(e) showNotification(paste0(tr("msg_png_error"), ": ", conditionMessage(e)), type = "error", duration = NULL))
  })

  # ==========================================================================
  # qpGRAPH DUZENLEYICI (v5.8) -- plotly tiklama tabanli
  # Duzenleyici YALNIZCA kenar tablosunu (input$qg_edges) degistirir. Grafin
  # denetimi, uyumu ve ice/disa aktarimi mevcut yollardan gecer.
  # plotly YUMUSAK bagimlilik: kurulu degilse uygulama calismaya devam eder,
  # bu alt sekmede kurulum mesaji gorunur.
  # ==========================================================================
  qge_has_plotly <- requireNamespace("plotly", quietly = TRUE)

  qge_apply <- function(newdf) {
    rv$qge_undo <- utils::head(c(list(input$qg_edges %||% ""), rv$qge_undo), 50)
    updateTextAreaInput(session, "qg_edges", value = edges_to_text(newdf))
    rv$qge_sel <- NULL
  }

  qge_run_op <- function(res) {
    if (!isTRUE(res$changed)) { if (nzchar(res$msg)) showNotification(tr(res$msg), type = "warning", duration = 5); return(invisible(FALSE)) }
    qge_apply(res$df); invisible(TRUE)
  }

  output$qge_plot_ui <- renderUI({
    if (!qge_has_plotly) return(div(class = "alert alert-warning small", tr("qge_need_plotly")))
    plotly::plotlyOutput("qge_plot", height = "560px")
  })

  output$qge_status_ui <- renderUI({
    df <- qg_parsed()$df
    if (is.null(df) || !nrow(df)) return(hint(tr("qge_empty")))
    sel <- rv$qge_sel
    if (is.null(sel)) return(div(class = "small text-muted", tr("qge_none_sel")))
    div(class = "small", tags$b(sprintf(tr("qge_selected"), sel)))
  })

  output$qge_check_ui <- renderUI({
    r <- qg_report(); chk <- r$chk
    if (is.null(chk)) return(NULL)
    if (!isTRUE(chk$ok)) return(div(class = "text-danger small mt-2", tr("qg_valid_bad")))
    items <- list(div(class = "small text-muted mt-2", sprintf(tr("qg_valid_ok"), length(chk$leaves), chk$nadmix, chk$nedge)))
    if (length(r$missing)) items <- c(items, list(div(class = "text-danger small", sprintf(tr("qg_leaves_missing"), paste(r$missing, collapse = ", ")))))
    tagList(items)
  })

  if (qge_has_plotly) output$qge_plot <- plotly::renderPlotly({
    df <- qg_parsed()$df
    lay <- qge_layout(df)
    p <- plotly::plot_ly(source = "qgedit")
    if (is.null(lay)) return(plotly::config(plotly::layout(p, xaxis = list(visible = FALSE), yaxis = list(visible = FALSE), paper_bgcolor = "rgba(0,0,0,0)", plot_bgcolor = "rgba(0,0,0,0)"), displayModeBar = FALSE))
    pos <- stats::setNames(seq_len(nrow(lay)), lay$node)
    adm <- df$to %in% lay$node[lay$type == "admix"]
    seg <- function(d) { if (!nrow(d)) return(list(x = numeric(0), y = numeric(0)))
      list(x = as.vector(rbind(lay$x[pos[d$from]], lay$x[pos[d$to]], NA)), y = as.vector(rbind(lay$y[pos[d$from]], lay$y[pos[d$to]], NA))) }
    s1 <- seg(df[!adm, , drop = FALSE]); s2 <- seg(df[adm, , drop = FALSE])
    if (length(s1$x)) p <- plotly::add_trace(p, type = "scatter", mode = "lines", x = s1$x, y = s1$y, line = list(color = "#64748b", width = 2), hoverinfo = "none", showlegend = FALSE)
    if (length(s2$x)) p <- plotly::add_trace(p, type = "scatter", mode = "lines", x = s2$x, y = s2$y, line = list(color = "#f59e0b", width = 2, dash = "dash"), hoverinfo = "none", showlegend = FALSE)
    col <- c(root = "#a78bfa", inner = "#94a3b8", admix = "#f59e0b", leaf = "#10b981")[lay$type]
    sel <- rv$qge_sel   # secim degisince grafik yeniden cizilir, secili dugum kirmizi gorunur
    if (!is.null(sel) && sel %in% lay$node) col[lay$node == sel] <- "#ef4444"
    p <- plotly::add_trace(p, type = "scatter", mode = "markers+text", x = lay$x, y = lay$y, text = lay$node, customdata = lay$node,
      textposition = "bottom center", hoverinfo = "text", marker = list(size = 18, color = unname(col), line = list(color = "#0f172a", width = 1)), showlegend = FALSE)
    p <- plotly::layout(p, xaxis = list(visible = FALSE, zeroline = FALSE), yaxis = list(visible = FALSE, zeroline = FALSE),
      dragmode = FALSE, margin = list(l = 10, r = 10, t = 10, b = 40), paper_bgcolor = "rgba(0,0,0,0)", plot_bgcolor = "rgba(0,0,0,0)",
      font = list(color = "#cbd5e1"))
    p <- plotly::event_register(p, "plotly_click")
    plotly::config(p, displayModeBar = FALSE)
  })

  qge_click <- reactive({ if (!qge_has_plotly) return(NULL); suppressWarnings(plotly::event_data("plotly_click", source = "qgedit")) })

  observeEvent(qge_click(), {
    ev <- qge_click(); if (is.null(ev)) return()
    nd <- as.character(ev$customdata %||% ""); if (!length(nd) || !nzchar(nd[1])) return()
    nd <- nd[1]
    df <- qg_parsed()$df %||% qge_empty()
    mode <- input$qge_mode %||% "insert"
    if (identical(mode, "del_node")) { qge_run_op(qge_del_node(df, nd)); return() }
    sel <- rv$qge_sel
    if (is.null(sel)) { rv$qge_sel <- nd; return() }
    if (identical(sel, nd)) { rv$qge_sel <- NULL; return() }
    res <- switch(mode,
      insert   = qge_insert(df, sel, nd, qge_new_name(df)),
      add      = qge_add(df, sel, nd),
      del_edge = qge_del_edge(df, sel, nd),
      qge_res(df, FALSE, ""))
    rv$qge_sel <- NULL
    qge_run_op(res)
  })

  observeEvent(input$qge_add_leaf, {
    lf <- input$qge_leaf %||% ""
    if (!nzchar(lf)) { showNotification(tr("qge_pick_leaf"), type = "warning"); return() }
    qge_run_op(qge_add_leaf(qg_parsed()$df, rv$qge_sel, lf))
  })

  observeEvent(input$qge_undo, {
    u <- rv$qge_undo
    if (!length(u)) { showNotification(tr("qge_undo_empty"), type = "message"); return() }
    updateTextAreaInput(session, "qg_edges", value = u[[1]])
    rv$qge_undo <- u[-1]; rv$qge_sel <- NULL
  })

  observeEvent(input$qge_clear, { rv$qge_sel <- NULL })

  # ---- Ekran olcegi ----
  output$scale_style <- renderUI({
    z <- switch(input$respreset, "2560x1600 (Legion Go)" = 1.30, "1920x1080" = 1.00, "2560x1440" = 1.10,
      "3840x2160" = 1.50, "1366x768" = .90,
      { w <- input$win_w %||% 1920; d <- input$dpr %||% 1; if (w <= 2600 && d >= 1.4) 1.25 else if (w >= 3000) 1.40 else 1.00 })
    tags$style(HTML(sprintf("html{zoom:%.2f;}", z)))
  })
}

shinyApp(ui, server, options = list(launch.browser = TRUE, port = qps_pick_port()),   # v6.4 test (adim 4): varsayilan tarayicida; v6.4 ADIM 3: 7654 doluysa 7655-7699
         onStart = function() shiny::onStop(function() qps_port_unlink()))   # v6.4: yalniz kendi yazdigi port dosyasi
